public class AIModule : MonoBehaviour
{
	public enum AIdifficulty
	{
		Easy,
		Normal,
		Hard,
		Nightmare
	}

	public EnemyBattler Unit;

	public CharacterTemplate UnitStats;

	public classType AIType;

	public AIdifficulty AIDifficulty;

	private bool ThinkingStarted;

	public float TurnStartDelay = 0.55f;

	public float ThinkingDelay = 0.45f;

	public float ThinkingDelayVariance = 1.7f;

	public float SecondarySkillDelay = 0.5f;

	public bool SkillUsedThisturn;

	private List<GameObject> AvailableTargets = new List<GameObject>();

	private List<Vector3> PreferredMoveLocations = new List<Vector3>();

	public List<int> AIOperating = new List<int>();

	public SortedList<float, GameObject> TargetPriority = new SortedList<float, GameObject>();

	public List<GameObject> TargetChoices = new List<GameObject>();

	public SortedList<float, Skill> SkillPriorityList = new SortedList<float, Skill>();

	public GameObject CurrentTarget;

	private float ReachableRange;

	public int SkillUseChance;

	public float TargetChoiceChance;

	public bool BackedAwayThisTurn;

	public void InitializeAI(int Difficulty = 2, bool Automatic = true, string type = "Warrior")
	{
		UnitStats = Unit.ThisCharacter;
		switch (Difficulty)
		{
		case 1:
			AIDifficulty = AIdifficulty.Easy;
			break;
		case 2:
			AIDifficulty = AIdifficulty.Normal;
			break;
		case 3:
			AIDifficulty = AIdifficulty.Hard;
			break;
		case 4:
			AIDifficulty = AIdifficulty.Nightmare;
			break;
		case 5:
			AIDifficulty = AIdifficulty.Nightmare;
			break;
		}
		DifficultyAdjustments();
		if (Automatic)
		{
			if (UnitStats.DoesThisCharacterHaveABow())
			{
				AIType = classType.Archer;
			}
			else if (UnitStats.PhysicalDamage.GetValue() < UnitStats.MagicDamage.GetValue())
			{
				AIType = classType.Mage;
			}
			else
			{
				AIType = classType.Warrior;
			}
		}
		else
		{
			switch (type)
			{
			case "Warrior":
				AIType = classType.Warrior;
				break;
			case "Mage":
				AIType = classType.Mage;
				break;
			case "Archer":
				AIType = classType.Archer;
				break;
			case "Balanced":
				AIType = classType.Warrior;
				break;
			}
		}
		TypeAdjustments();
	}

	public void DifficultyAdjustments()
	{
		switch (AIDifficulty)
		{
		case AIdifficulty.Easy:
			SkillUseChance = 50;
			TargetChoiceChance = 2f;
			break;
		case AIdifficulty.Normal:
			SkillUseChance = 70;
			TargetChoiceChance = 1.5f;
			TurnStartDelay -= 0.1f;
			break;
		case AIdifficulty.Hard:
			SkillUseChance = 85;
			TargetChoiceChance = 1.25f;
			TurnStartDelay -= 0.2f;
			break;
		case AIdifficulty.Nightmare:
			SkillUseChance = 100;
			TargetChoiceChance = 1f;
			TurnStartDelay -= 0.3f;
			break;
		}
	}

	public void TypeAdjustments()
	{
		if (AIType == classType.Mage)
		{
			SkillUseChance += 30;
		}
		else if (AIType == classType.Archer)
		{
			SkillUseChance = 100;
			TargetChoiceChance = 1f;
		}
	}

	public IEnumerator ThinkAction()
	{
		AIOperating.Add(1);
		if (!ThinkingStarted)
		{
			ThinkingStarted = true;
			if (Unit.RemainingMoves == Unit.maxMoves)
			{
				yield return (object)new WaitForSeconds(TurnStartDelay);
				SkillUsedThisturn = false;
				BackedAwayThisTurn = false;
			}
			else if (SkillUsedThisturn)
			{
				yield return (object)new WaitForSeconds(SecondarySkillDelay);
			}
			yield return (object)new WaitForSeconds(Random.Range(ThinkingDelay / ThinkingDelayVariance, ThinkingDelay * ThinkingDelayVariance));
			ChooseAction();
			ThinkingStarted = false;
			AIOperating.Remove(1);
		}
	}

	public void ChooseAction()
	{
		//IL_0234: Unknown result type (might be due to invalid IL or missing references)
		//IL_0244: Unknown result type (might be due to invalid IL or missing references)
		AIOperating.Add(1);
		if (Unit.RemainingMoves <= 0)
		{
			Unit.CharacterState = EnemyBattler.CharacterStates.ENDTURN;
			return;
		}
		AvailableTargets.Clear();
		PreferredMoveLocations.Clear();
		ReachableRange = Unit.RemainingMoves;
		ReachableRange *= 1.45f;
		TargetScoring();
		TargetChoices.Clear();
		foreach (KeyValuePair<float, GameObject> item in TargetPriority)
		{
			if (item.Key <= TargetPriority.Keys[0] / TargetChoiceChance)
			{
				TargetChoices.Add(item.Value);
			}
		}
		CurrentTarget = TargetChoices[Random.Range(0, TargetChoices.Count)];
		if (Random.Range(0, 100) < SkillUseChance && CreateSkillPriority())
		{
			bool flag = false;
			foreach (Buff buff in Unit.Buffs)
			{
				if ((Object)(object)buff != (Object)null && buff.BuffType == "Amnesia")
				{
					flag = true;
				}
			}
			foreach (Skill value in SkillPriorityList.Values)
			{
				if ((Unit.ThisCharacter.CurrentMP < value.ManaCost || Unit.Cooldowns.ContainsKey(value)) | flag)
				{
					continue;
				}
				new List<GameObject>();
				if (SkillController.instance.CheckSurroundingTiles(value.Range, value.SkillTargets, value.SkillType, AI: true).Contains(CurrentTarget))
				{
					AvailableTargets.Add(CurrentTarget);
				}
				if (AvailableTargets.Count > 0)
				{
					if (AIType == classType.Archer && value.BowSkill && Unit.RemainingMoves > 1 && Vector3.Distance(((Component)this).transform.position, CurrentTarget.transform.position) < 2.9f && BackAwayFromEnemy(CurrentTarget))
					{
						AIOperating.Remove(1);
						return;
					}
					try
					{
						if ((Object)(object)value.CausesBuff != (Object)null && (value.CausesBuff.BuffType == "DelayedDamagePhysical" || value.CausesBuff.BuffType == "DelayedDamageMagic") && CurrentTarget.GetComponent<EnemyBattler>().DoesCharacterHaveBuff(value.CausesBuff))
						{
							AvailableTargets.Clear();
							continue;
						}
					}
					catch (Exception ex)
					{
						Debug.Log((object)ex);
						Debug.Log((object)"<color=yellow>For some reason AI was not able to check for DelayedDamageBuff</color>");
					}
					SkillController.instance.UseSkill(value, CurrentTarget, ((Component)this).gameObject);
					SkillUsedThisturn = true;
					AIOperating.Remove(1);
					return;
				}
				if (value.SkillTargets == SkillTargets.Self && Random.Range(0, 100) < 30 && ((value.SkillType != SkillType.BuffAll && value.SkillType != SkillType.RandomBuffAll) || BattleProcessor.instance.HowManyAlive(Hero: false) >= 3) && ((value.SkillType != SkillType.BuffAll && value.SkillType != SkillType.RandomBuffAll && value.SkillType != SkillType.BerserkBuff && value.SkillType != SkillType.Buff) || !(ProgressManager.instance.CareerSpecialRule == "Contagion")) && ((value.SkillType != SkillType.DebuffAll && value.SkillType != SkillType.RandomDebuffAll) || BattleProcessor.instance.HowManyAlive(Hero: true) >= 3))
				{
					SkillController.instance.UseSkill(value, ((Component)this).gameObject, ((Component)this).gameObject);
					SkillUsedThisturn = true;
					AIOperating.Remove(1);
					return;
				}
			}
		}
		CheckSurroundingTilesForSpecificEnemy(1, CurrentTarget);
		if (AvailableTargets.Count > 0)
		{
			Unit.MeleeAttack(CurrentTarget);
		}
