	public bool CreateSkillPriority()
	{
		SkillPriorityList.Clear();
		if (Unit.ThisCharacter.CharacterSkills.Count == 0)
		{
			return false;
		}
		foreach (Skill characterSkill in Unit.ThisCharacter.CharacterSkills)
		{
			float num = (float)characterSkill.ExtraDamage + (float)characterSkill.SkillNumberVariable + Random.Range(1f, 1.005f);
			if (characterSkill.SkillRarity == Rarity.Epic)
			{
				num *= 1.3f;
			}
			else if (characterSkill.SkillRarity == Rarity.Rare)
			{
				num *= 1.15f;
			}
			if ((Object)(object)CurrentTarget != (Object)null)
			{
				AttackDetails attackDetails = new AttackDetails();
				attackDetails.AttackSkill = characterSkill.name;
				attackDetails.AttackerObject = ((Component)Unit).gameObject;
				attackDetails.TargetObject = CurrentTarget;
				attackDetails.Skill = characterSkill.SkillType;
				attackDetails.ExtraDamage = characterSkill.ExtraDamage;
				attackDetails.SkillNumberVariable = characterSkill.SkillNumberVariable;
				attackDetails.SpecialVariable = characterSkill.SpecialVariable;
				attackDetails.DamageType = characterSkill.DamageType;
				int num2 = BattleProcessor.instance.EstimateDamage(attackDetails);
				if (num2 != 9999)
				{
					num = (float)num2 + Random.Range(1f, 1.005f);
				}
			}
			if (characterSkill.BowSkill && num > 1f)
			{
				num *= 2f;
			}
			if ((Object)(object)characterSkill.CausesBuff != (Object)null)
			{
				num *= 1.2f;
			}
			if (characterSkill.ConsumesTurns == 0)
			{
				num *= 4f;
			}
			if (SkillPriorityList.ContainsKey(num))
			{
				num *= 1.001f;
			}
			num *= -1f;
			try
			{
				SkillPriorityList.Add(num, characterSkill);
			}
			catch (ArgumentException)
			{
				Debug.Log((object)("Key already exists in SkillPriorityList: " + num + " " + characterSkill));
			}
		}
		return true;
	}

