		if (CheerStarted)
		{
			yield break;
		}
		CheerStarted = true;
		AudioManager.instance.StartAudienceSounds();
		for (int i = 0; i < AudienceList.Count; i++)
		{
			Transform value = AudienceList[i];
			int index = Random.Range(i, AudienceList.Count);
			AudienceList[i] = AudienceList[index];
			AudienceList[index] = value;
		}
		foreach (Transform audience in AudienceList)
		{
			((Component)audience).GetComponent<Animator>().SetTrigger("Cheer");
			yield return (object)new WaitForSeconds(0.01f);
		}
		while (CheerLength > 0f)
		{
			CheerLength -= Time.deltaTime;
			yield return null;
		}
		AudioManager.instance.FadeOutAudienceSounds();
		for (int j = 0; j < AudienceList.Count; j++)
		{
			Transform value2 = AudienceList[j];
			int index2 = Random.Range(j, AudienceList.Count);
			AudienceList[j] = AudienceList[index2];
			AudienceList[index2] = value2;
		}
		foreach (Transform audience2 in AudienceList)
		{
			((Component)audience2).GetComponent<Animator>().SetTrigger("StopCheer");
			yield return (object)new WaitForSeconds(0.01f);
		}
		CheerStarted = false;
	}

