	public IEnumerator DelayedSound(string sfxclip, float waittime)
	{
		yield return (object)new WaitForSeconds(waittime);
		AudioEffect(sfxclip);
	}

	public void StopSounds()
	{
		SFXPlayer.Stop();
	}

	public void PlayMusic(string music)
	{
		switch (music)
		{
		case "Event":
			MusicPlayer.clip = EventAmbiance;
			break;
		case "Town":
			MusicPlayer.clip = TownMusic[Random.Range(0, TownMusic.Count)];
			break;
		case "Menu":
			MusicPlayer.clip = MenuMusic[Random.Range(0, MenuMusic.Count)];
			break;
		case "Battle":
			MusicPlayer.clip = BattleMusic[Random.Range(0, BattleMusic.Count)];
			break;
		case "ChampionshipBattle":
			MusicPlayer.clip = Championship;
			break;
		}
		FadeInMusic();
		MusicPlayer.Play();
	}

	public void PauseMusic()
	{
		MusicPlayer.Pause();
	}

	public void UnPauseMusic()
	{
		MusicPlayer.UnPause();
	}

	public void FadeInMusic()
	{
		((MonoBehaviour)this).StartCoroutine(MusicFadingIn());
	}

	public void FadeOutMusic()
	{
		((MonoBehaviour)this).StartCoroutine(MusicFadingOut());
	}

	public void StartAudienceSounds()
	{
		AudienceSounds.Play();
	}

	public void FadeOutAudienceSounds()
	{
		((MonoBehaviour)this).StartCoroutine(AudienceFadingOut());
	}

	public void ChangeAudienceClip(int size)
	{
		switch (size)
		{
		case 1:
			AudienceSounds.clip = AudienceSmall;
			break;
		case 2:
			AudienceSounds.clip = AudienceMedium;
			break;
		case 3:
			AudienceSounds.clip = AudienceBig;
			break;
		}
	}

	public void StopAudienceSounds()
	{
		AudienceSounds.Stop();
	}

	public void StopMusic()
	{
		MusicPlayer.Stop();
	}

	public IEnumerator AudienceFadingOut()
	{
		if (!AudienceFadeOutStarted)
		{
			AudienceFadeOutStarted = true;
			while (AudienceSounds.volume > 0f)
			{
				AudioSource audienceSounds = AudienceSounds;
				audienceSounds.volume -= Time.deltaTime * 0.35f;
				yield return null;
			}
			AudienceSounds.Stop();
			AudienceSounds.volume = SFXvolume;
			AudienceFadeOutStarted = false;
		}
	}

	public IEnumerator MusicFadingOut()
	{
		if (FadeOutStarted)
		{
			yield break;
		}
		FadeOutStarted = true;
		while (MusicPlayer.volume > 0f)
		{
			if (FadeInStarted)
			{
				FadeOutStarted = false;
				yield break;
			}
			AudioSource musicPlayer = MusicPlayer;
			musicPlayer.volume -= Time.deltaTime / 2f;
			yield return null;
		}
		if (FadeInStarted)
		{
			FadeOutStarted = false;
			yield break;
		}
		MusicPlayer.Stop();
		MusicPlayer.volume = Musicvolume;
		FadeOutStarted = false;
	}

	public IEnumerator MusicFadingIn()
	{
		if (FadeInStarted)
		{
			yield break;
		}
		FadeInStarted = true;
		MusicPlayer.volume = 0f;
		while (MusicPlayer.volume < Musicvolume)
		{
			if (FadeOutStarted)
			{
				FadeInStarted = false;
				yield break;
			}
			AudioSource musicPlayer = MusicPlayer;
			musicPlayer.volume += Time.deltaTime / 2f;
			yield return null;
		}
		FadeInStarted = false;
	}

	public void OptionsSetSFXVolume(float vol)
	{
		SFXPlayer.volume = vol;
		AudienceSounds.volume = vol;
		SFXvolume = vol;
	}

	public void OptionsSetMusicVolume(float vol)
	{
		MusicPlayer.volume = vol;
		Musicvolume = vol;
	}

	public void MuteSource(int source)
	{
		switch (source)
		{
		case 1:
			SFXPlayer.volume = 0f;
			break;
		case 2:
			MusicPlayer.volume = 0f;
			break;
		default:
			SFXPlayer.volume = 0f;
			MusicPlayer.volume = 0f;
			break;
		}
	}

	public void UnMuteSource(int source)
	{
		switch (source)
		{
		case 1:
			SFXPlayer.volume = SFXvolume;
			break;
		case 2:
			MusicPlayer.volume = Musicvolume;
			break;
		default:
			SFXPlayer.volume = SFXvolume;
			MusicPlayer.volume = Musicvolume;
			break;
		}
	}
}
