	public void HighlightBar()
	{
		((Behaviour)Outline).enabled = true;
	}

	public void RemoveHighlight()
	{
		((Behaviour)Outline).enabled = false;
	}

	public void UpdateBar()
	{
		//IL_0128: Unknown result type (might be due to invalid IL or missing references)
		//IL_013e: Unknown result type (might be due to invalid IL or missing references)
		//IL_014a: Unknown result type (might be due to invalid IL or missing references)
		//IL_014f: Unknown result type (might be due to invalid IL or missing references)
		//IL_00db: Unknown result type (might be due to invalid IL or missing references)
		//IL_00ee: Unknown result type (might be due to invalid IL or missing references)
		//IL_0100: Unknown result type (might be due to invalid IL or missing references)
		//IL_0105: Unknown result type (might be due to invalid IL or missing references)
		//IL_016a: Unknown result type (might be due to invalid IL or missing references)
		//IL_01cd: Unknown result type (might be due to invalid IL or missing references)
		((TMP_Text)HpText).text = Character.CurrentHP + " / " + Character.HP.GetValue();
		((TMP_Text)MpText).text = Character.CurrentMP + " / " + Mathf.Clamp(Character.MP.GetValue(), 0, int.MaxValue);
		float num = (float)Character.CurrentHP / (float)Character.HP.GetValue();
		if (num < 0f)
		{
			num = 0f;
		}
		if ((double)num > 0.5)
		{
			((Graphic)((Component)HpBar).GetComponent<Image>()).color = Color32.op_Implicit(Color32.Lerp(new Color32((byte)230, (byte)230, (byte)50, byte.MaxValue), new Color32((byte)70, (byte)250, (byte)50, byte.MaxValue), (num - 0.5f) * 2f));
		}
		else
		{
			((Graphic)((Component)HpBar).GetComponent<Image>()).color = Color32.op_Implicit(Color32.Lerp(new Color32(byte.MaxValue, (byte)0, (byte)0, byte.MaxValue), new Color32((byte)230, (byte)230, (byte)50, byte.MaxValue), num * 2f));
		}
		HpBar.localScale = new Vector3(num, 1f, 1f);
		float num2 = ((Character.MP.GetValue() > 0) ? ((float)Character.CurrentMP / (float)Character.MP.GetValue()) : 0f);
		if (num2 < 0f)
		{
			num2 = 0f;
		}
		MpBar.localScale = new Vector3(num2, 1f, 1f);
	}

	public void AddBuffIcon(Buff buff)
	{
		GameObject val = Object.Instantiate<GameObject>(BuffPrefab);
		val.transform.SetParent(BuffPanel, false);
		val.GetComponent<BuffSlot>().ContainsBuff = buff;
		val.GetComponent<Image>().sprite = buff.Icon;
	}

	public void RecheckBuffs()
	{
		//IL_0014: Unknown result type (might be due to invalid IL or missing references)
		//IL_001a: Expected Obj, but got Unknown
		foreach (Transform item in BuffPanel)
		{
			Transform val = item;
			if (!CharacterController.Buffs.Contains(((Component)val).GetComponent<BuffSlot>().ContainsBuff))
			{
				Object.Destroy((Object)(object)((Component)val).gameObject);
			}
		}
	}

	public void CharIsDead(EnemyBattler.DeathState State)
	{
		((Component)StatusIndicator).gameObject.SetActive(true);
		RemoveHighlight();
		CharacterController.RemoveAllBuffs();
		RecheckBuffs();
		if (GlobalVariables.instance.ChallengeDeadIsDead || ChangingVariables.instance.SevereInjuries == 2)
		{
			AddBuffIcon(DeadDebuff);
			return;
		}
		switch (State)
		{
		case EnemyBattler.DeathState.KNOCKOUT:
			AddBuffIcon(KnockoutDebuff);
			break;
		case EnemyBattler.DeathState.COMA:
			AddBuffIcon(ComaDebuff);
			break;
		case EnemyBattler.DeathState.MORTAL:
			AddBuffIcon(MortalDebuff);
			break;
		}
	}

	public void RecheckDeathState()
	{
		if (!GlobalVariables.instance.ChallengeDeadIsDead && ChangingVariables.instance.SevereInjuries != 2)
		{
			int currentHP = Character.CurrentHP;
			EnemyBattler.DeathState deathState = ((currentHP <= -20) ? EnemyBattler.DeathState.MORTAL : ((currentHP <= -10) ? EnemyBattler.DeathState.COMA : EnemyBattler.DeathState.KNOCKOUT));
			if (deathState != CharacterController.DeathType)
			{
				CharacterController.DeathType = deathState;
				CharIsDead(deathState);
			}
		}
	}
}
