	private void Awake()
	{
		if ((Object)(object)instance != (Object)null)
		{
			Debug.LogWarning((object)"More than one instance of BattleProcessor found!");
			Object.Destroy((Object)(object)((Component)this).gameObject);
		}
		else
		{
			instance = this;
			battleStates = PerformAction.WAIT;
		}
	}

	private void Start()
	{
		ChampionshipMatch = false;
		if (ProgressManager.instance.ProgressionLevel > ProgressManager.instance.ProgressionLevelMax || (GlobalVariables.instance.CareerModeActivated && ProgressManager.instance.CurrentTypeOfMatch == 20))
		{
			ChampionshipMatch = true;
		}
		DisableArrowButtons();
		MapManager.instance.StartMap();
		TurnTimer = 1;
		CheckTiles();
		PrepareBoard();
		List<GameObject> list = new List<GameObject>();
		List<GameObject> list2 = new List<GameObject>();
		list.AddRange(GameObject.FindGameObjectsWithTag("Enemy"));
		list2.AddRange(GameObject.FindGameObjectsWithTag("Hero"));
		foreach (GameObject item in list)
		{
			EnemiesInBattle.Add(item.GetComponent<EnemyBattler>());
		}
		foreach (GameObject item2 in list2)
		{
			HerosInBattle.Add(item2.GetComponent<EnemyBattler>());
		}
		SecondMessage = "";
		ThirdMessage = "";
		EnemyStarts = Random.value > 0.5f;
		if (ProgressManager.instance.CareerSpecialRule == "Coordination")
		{
			if (EnemyStarts)
			{
				foreach (EnemyBattler item3 in EnemiesInBattle)
				{
					TurnOrder.Add(item3);
					BattleDurationTimer.Add(item3);
				}
			}
			foreach (EnemyBattler item4 in HerosInBattle)
			{
				TurnOrder.Add(item4);
				BattleDurationTimer.Add(item4);
			}
			if (!EnemyStarts)
			{
				foreach (EnemyBattler item5 in EnemiesInBattle)
				{
					TurnOrder.Add(item5);
					BattleDurationTimer.Add(item5);
				}
			}
		}
		else
		{
			for (int i = 0; i < 4; i++)
			{
				if (i < EnemiesInBattle.Count && EnemyStarts)
				{
					TurnOrder.Add(EnemiesInBattle[i]);
					BattleDurationTimer.Add(EnemiesInBattle[i]);
				}
				if (i < HerosInBattle.Count)
				{
					TurnOrder.Add(HerosInBattle[i]);
					BattleDurationTimer.Add(HerosInBattle[i]);
				}
				if (i < EnemiesInBattle.Count && !EnemyStarts)
				{
					TurnOrder.Add(EnemiesInBattle[i]);
					BattleDurationTimer.Add(EnemiesInBattle[i]);
				}
			}
		}
		TurnColor = "#FFFFFF";
		AreThereDesiresOrDemands();
		if (ProfileManager.instance.LatestGridOutlinesVisible)
		{
			GridOutline.SetActive(true);
		}
		((MonoBehaviour)this).StartCoroutine(StartActivities());
	}

	private void Update()
	{
		if (KeyboardListenerActive && KeyBindingManager.GetKeyDown(KeyAction.submit) && ChatMessageActive)
		{
			CloseChatWindow();
		}
		switch (battleStates)
		{
		case PerformAction.TURNSTART:
			if (CheckRandom(10))
			{
				EmperorAnimator.SetTrigger("IdleHand");
			}
			if ((Object)(object)CurrentCharacter == (Object)(object)BattleDurationTimer[BattleDurationTimer.Count - 1])
			{
				TurnTimer++;
			}
			if (TurnTimer >= 18)
			{
				TurnColor = "#FF5858";
			}
			else if (TurnTimer >= 15)
			{
				TurnColor = "#FF8A28";
			}
			((TMP_Text)TurnTimerText).SetText("<color=" + TurnColor + ">" + LocalizationManager.GetTranslation("UI.BATTLE/UI.BATTLE_turn") + " " + TurnTimer + "/" + FinalTurn + "</color>");
			if (ProgressManager.instance.EmpDemand == "Slow burn" && TurnTimer < 5 && EnemiesKilled > 0)
			{
				isEmperorAnnoyed = true;
			}
			if (ProgressManager.instance.EmpDemand == "Fast match" && TurnTimer > 6)
			{
				isEmperorAnnoyed = true;
			}
			if (ProgressManager.instance.EmpDesire == "Long match" && TurnTimer >= 10)
			{
				CompleteDesire();
			}
			if (ProgressManager.instance.EmpDesire == "Even match" && TurnOrder.Count == 2)
			{
				CompleteDesire();
			}
			if (isEmperorAnnoyed && !DemandPenaltyGiven)
			{
				EmperorSpeaks("<size=32>" + LocalizationManager.GetTranslation("UI.BATTLE/UI.BATTLE_emperormad1a") + "</size>", LocalizationManager.GetTranslation("UI.BATTLE/UI.BATTLE_emperormad1b"));
			}
			else if (!FirstBlood && TurnTimer == 5 && HerosInBattle.Count > 1 && !MinorPenaltyGiven)
			{
				isEmperorMildlyAnnoyed = true;
				MinorPenaltyGiven = true;
				EmperorSpeaks("<size=32>" + LocalizationManager.GetTranslation("UI.BATTLE/UI.BATTLE_emperormad2a") + "</size>", LocalizationManager.GetTranslation("UI.BATTLE/UI.BATTLE_emperormad2b"));
			}
			else if (TurnTimer == WarningTurn && !WarningTurnReached)
			{
				WarningTurnReached = true;
				EmperorSpeaks(LocalizationManager.GetTranslation("UI.BATTLE/UI.BATTLE_emperormad3a"), LocalizationManager.GetTranslation("UI.BATTLE/UI.BATTLE_emperormad3b"));
			}
			else if (TurnTimer > FinalTurn && !FinalTurnReached)
			{
				FinalTurnReached = true;
				EmperorSpeaks("<size=32>" + LocalizationManager.GetTranslation("UI.BATTLE/UI.BATTLE_emperormad4a") + "</size>", LocalizationManager.GetTranslation("UI.BATTLE/UI.BATTLE_emperormad4b"), LocalizationManager.GetTranslation("UI.BATTLE/UI.BATTLE_emperormad4c"));
			}
			else
			{
				battleStates = PerformAction.DEALTURN;
			}
			break;
		case PerformAction.DEALTURN:
		{
			if (GameIsOver)
			{
				battleStates = PerformAction.WAIT;
			}
			UpdateTurnTracker(midturn: false);
			EnemyBattler currentCharacter = TurnOrder[0];
			CurrentCharacter = currentCharacter;
			CurrentCharacter.CharacterState = EnemyBattler.CharacterStates.STARTTURN;
			((MonoBehaviour)this).StartCoroutine(TurnStartCountdown());
			if (UIManager.instance.TooltipSkill.activeSelf && !UIManager.instance.CharTooltip.activeSelf)
			{
				UIManager.instance.CloseAllTooltips();
			}
			TurnOrder.Add(TurnOrder[0]);
			TurnOrder.RemoveAt(0);
			battleStates = PerformAction.WAIT;
			break;
		}
		case PerformAction.TURNEND:
			DamageEstimator.instance.ClearCurrentCharacter();
			if (TurnHasRemainingTasks.Count <= 0)
			{
				battleStates = PerformAction.TURNSTART;
			}
			break;
		case PerformAction.VICTORY:
			GameIsOver = true;
			battleStates = PerformAction.WAIT;
			GameEndActivitiesBeforeStats();
			((MonoBehaviour)this).StartCoroutine(AudienceManager.instance.Cheer(10f));
			foreach (CharacterTemplate item in ProgressManager.instance.Team)
			{
				if ((Object)(object)item != (Object)null)
				{
					item.WinCount++;
				}
			}
			ProgressManager.instance.TotalWins++;
			if (GlobalVariables.instance.EndlessModeActivated && ProgressManager.instance.TotalWins >= 42)
			{
				SteamAchievements.instance.UnlockSteamAchievement("ACH_Endless42Wins");
			}
			else if (GlobalVariables.instance.CareerModeActivated && (ProgressManager.instance.CurrentTypeOfMatch == 19 || ProgressManager.instance.CurrentTypeOfMatch == 2 || ProgressManager.instance.CurrentTypeOfMatch == 20))
			{
				ProgressManager.instance.CareerAddProgressionStar();
			}
			ProgressManager.instance.ProgressionLevelWins++;
			ProgressManager.instance.ProgressionList.Add(item: true);
			ShowEndStats(VictoryOrNot: true);
			break;
		case PerformAction.LOSS:
			GameIsOver = true;
			battleStates = PerformAction.WAIT;
			ProgressManager.instance.ProgressionLevelLosses++;
			ProgressManager.instance.ProgressionList.Add(item: false);
			if (GlobalVariables.instance.CareerModeActivated && (ProgressManager.instance.CurrentTypeOfMatch == 19 || ProgressManager.instance.CurrentTypeOfMatch == 20))
			{
				ProgressManager.instance.NumberOfQualifierLosses++;
			}
			GameEndActivitiesBeforeStats();
			foreach (CharacterTemplate item2 in ProgressManager.instance.Team)
			{
				if ((Object)(object)item2 != (Object)null)
				{
					item2.LossCount++;
				}
			}
			ShowEndStats(VictoryOrNot: false);
			break;
		case PerformAction.GAMEEND:
			battleStates = PerformAction.WAIT;
			UIManager.instance.ToggleExtraStatsInBattle(forceclose: true);
			ProgressManager.instance.ReduceInjuryCountForAll();
			ProgressManager.instance.GoToTown();
			break;
		case PerformAction.WAIT:
			break;
		}
	}

