	public void SetCooldowns()
	{
		foreach (EnemyBattler item in HerosInBattle)
		{
			foreach (Skill characterSkill in item.ThisCharacter.CharacterSkills)
			{
				if (GlobalVariables.instance.RandomizeCDAtStart)
				{
					int value = Random.Range(1, characterSkill.MaxCooldown + 1);
					item.Cooldowns.Add(characterSkill, value);
				}
				else if (characterSkill.MaxCooldown > 1)
				{
					int value2 = Mathf.CeilToInt((float)characterSkill.MaxCooldown / 2f);
					item.Cooldowns.Add(characterSkill, value2);
				}
			}
		}
		foreach (EnemyBattler item2 in EnemiesInBattle)
		{
			foreach (Skill characterSkill2 in item2.ThisCharacter.CharacterSkills)
			{
				if (GlobalVariables.instance.RandomizeCDAtStart)
				{
					int value3 = Random.Range(1, characterSkill2.MaxCooldown + 1);
					item2.Cooldowns.Add(characterSkill2, value3);
				}
				else if (characterSkill2.MaxCooldown > 1)
				{
					int value4 = Mathf.CeilToInt((float)characterSkill2.MaxCooldown / 2f);
					item2.Cooldowns.Add(characterSkill2, value4);
				}
			}
		}
	}

