	public int CheckForDeaths()
	{
		string text = "";
		int num = 0;
		foreach (EnemyBattler item in HerosInBattle)
		{
			if (item.ThisCharacter.CurrentHP <= 0 && ((Component)item).tag == "Hero")
			{
				AudioManager.instance.AudioEffect("Death");
				((MonoBehaviour)this).StartCoroutine(AudienceManager.instance.Cheer(3f));
				TurnOrder.Remove(item);
				BattleDurationTimer.Remove(item);
				((Component)item).tag = "DeadHero";
				num++;
				text = LocalizationManager.GetTranslation("LOG/LOG_knockedout");
				text = text.Replace("<CHAR>", item.ThisCharacter.Charname);
				CombatLog.instance.WriteLog("<color=#FF0000>" + text + "</color>");
				if (item.ThisCharacter.CurrentHP <= -20)
				{
					item.DeathType = EnemyBattler.DeathState.MORTAL;
				}
				else if (item.ThisCharacter.CurrentHP <= -10)
				{
					item.DeathType = EnemyBattler.DeathState.COMA;
				}
				else
				{
					item.DeathType = EnemyBattler.DeathState.KNOCKOUT;
				}
				item.CharacterState = EnemyBattler.CharacterStates.DYING;
				if (ProgressManager.instance.EmpDemand == "Flawless win")
				{
					isEmperorAnnoyed = true;
				}
			}
		}
		foreach (EnemyBattler item2 in EnemiesInBattle)
		{
			if (item2.ThisCharacter.CurrentHP <= 0 && ((Component)item2).tag == "Enemy")
			{
				AudioManager.instance.AudioEffect("Death");
				EnemiesKilled++;
				KillStreak++;
				((MonoBehaviour)this).StartCoroutine(AudienceManager.instance.Cheer(3f));
				TurnOrder.Remove(item2);
				BattleDurationTimer.Remove(item2);
				((Component)item2).tag = "DeadEnemy";
				num++;
				text = LocalizationManager.GetTranslation("LOG/LOG_knockedout");
				text = text.Replace("<CHAR>", item2.ThisCharacter.Charname);
				CombatLog.instance.WriteLog("<color=#FF0000>" + text + "</color>");
				if (item2.ThisCharacter.CurrentHP <= -20)
				{
					item2.DeathType = EnemyBattler.DeathState.MORTAL;
					if (ProgressManager.instance.EmpDemand == "Ordinary hits")
					{
						isEmperorAnnoyed = true;
					}
					if (ProgressManager.instance.EmpDesire == "Overkill")
					{
						CompleteDesire();
					}
					if (item2.ThisCharacter.CurrentHP <= -100)
					{
						SteamAchievements.instance.UnlockSteamAchievement("ACH_Overkill");
					}
				}
				else if (item2.ThisCharacter.CurrentHP <= -10)
				{
					item2.DeathType = EnemyBattler.DeathState.COMA;
					if (ProgressManager.instance.EmpDemand == "Ordinary hits")
					{
						isEmperorAnnoyed = true;
					}
				}
				else
				{
					item2.DeathType = EnemyBattler.DeathState.KNOCKOUT;
					if (ProgressManager.instance.EmpDesire == "Precise knockout" && item2.ThisCharacter.CurrentHP == 0)
					{
						CompleteDesire();
					}
				}
				item2.CharacterState = EnemyBattler.CharacterStates.DYING;
				if (ProgressManager.instance.EmpDesire == "Quick knockout" && TurnTimer <= 3)
				{
					CompleteDesire();
				}
				if (ProgressManager.instance.EmpDesire == "Chain knockouts" && KillStreak >= 2)
				{
					CompleteDesire();
				}
				if (KillStreak >= 3)
				{
					SteamAchievements.instance.UnlockSteamAchievement("ACH_SerialKiller");
				}
			}
			if (item2.ThisCharacter.CurrentHP <= -20 && ProgressManager.instance.EmpDesire == "Overkill")
			{
				CompleteDesire();
			}
		}
		CheckIfGameShouldEnd();
		return num;
	}

	private IEnumerator AttackDelay(AttackDetails attackdetails, float duration = 0.3f)
	{
		if (!attackdelayactive)
		{
			attackdelayactive = true;
			yield return (object)new WaitForSeconds(duration);
			HandleAttack(attackdetails, 2);
			attackdelayactive = false;
		}
	}

	private bool CheckDodge(EnemyBattler Char, bool IsNormal = true)
	{
		string text = "";
		int num = Char.ThisCharacter.DodgeChance.GetValue();
		if (!Object.op_Implicit((Object)(object)Char.AI) && num > 0)
		{
			num += 5;
		}
		else if (Object.op_Implicit((Object)(object)Char.AI) && num > 0)
		{
			num = Mathf.Clamp(num - 5, 1, 55);
		}
		if (num > 0 && CheckRandom(num))
		{
			text = LocalizationManager.GetTranslation("LOG/LOG_dodge");
			text = text.Replace("<CHAR>", Char.ThisCharacter.Charname);
			CombatLog.instance.WriteLog(text);
			if (IsNormal)
			{
				AudioManager.instance.AudioEffect("Dodge");
				((MonoBehaviour)this).StartCoroutine(Char.GotHit("Dodge"));
			}
			else
			{
				AudioManager.instance.AudioEffect("DodgeMagic");
				((MonoBehaviour)this).StartCoroutine(Char.GotHit("DodgeMagic"));
			}
			TurnHasRemainingTasks.Remove(1);
			return true;
		}
		return false;
	}

	private bool CheckCrit(EnemyBattler Char)
	{
		if (ProgressManager.instance.CareerSpecialRule == "Spirit of the Tiger")
		{
			string translation = LocalizationManager.GetTranslation("LOG/LOG_crit");
			CombatLog.instance.WriteLog("<color=#FF0000>" + translation + "</color>");
			((MonoBehaviour)this).StartCoroutine(Char.PlayEffect("Crit"));
			return true;
		}
		int num = Char.ThisCharacter.CritChance.GetValue();
		if (Char.ThisCharacter.AIChar && num > 15 && num < 95)
		{
			num -= 5;
		}
		if (CheckRandom(num))
		{
			string translation2 = LocalizationManager.GetTranslation("LOG/LOG_crit");
			CombatLog.instance.WriteLog("<color=#FF0000>" + translation2 + "</color>");
			((MonoBehaviour)this).StartCoroutine(Char.PlayEffect("Crit"));
			return true;
		}
		return false;
	}

	private bool CheckKnockback(CharacterTemplate Char)
	{
		if (ProgressManager.instance.CareerSpecialRule == "Spirit of the Bear")
		{
			return true;
		}
		if (CheckRandom(Char.KnockbackChance.GetValue()) || (GlobalVariables.instance.ChallengeBurlyEnemies && Object.op_Implicit((Object)(object)Char.BattleUnit.AI)))
		{
			string translation = LocalizationManager.GetTranslation("LOG/LOG_knockback");
			CombatLog.instance.WriteLog("<color=#FF8500>" + translation + "</color>");
			return true;
		}
		return false;
	}

