			}
		}
	}

	private bool CheckIfGameShouldEnd()
	{
		if (GameObject.FindGameObjectsWithTag("Enemy").Length == 0 && !GameIsOver)
		{
			battleStates = PerformAction.VICTORY;
			return true;
		}
		if (GameObject.FindGameObjectsWithTag("Hero").Length == 0 && !GameIsOver)
		{
			battleStates = PerformAction.LOSS;
			return true;
		}
		return false;
	}

