		{
			num = ((ProgressManager.instance.CareerFightRewardType == 1 && RosterManager.instance.IsThereRoom()) ? 1 : ((ProgressManager.instance.CareerFightRewardType == 2 && InventoryManager.instance.IsThereRoom()) ? 2 : ((ProgressManager.instance.CareerFightRewardType != 3 || !InventoryManager.instance.IsThereRoom()) ? 4 : 3)));
