	}

	public void RewardPicked(RewardButton ChosenReward)
	{
		EndRewardPicked = true;
		SpawnedRewards.Remove(ChosenReward);
		AudioManager.instance.AudioEffect("TreasureChosen");
		UIManager.instance.CloseAllTooltips();
		foreach (RewardButton spawnedReward in SpawnedRewards)
		{
			((MonoBehaviour)this).StartCoroutine(spawnedReward.FadeThis());
		}
		((MonoBehaviour)this).StartCoroutine(ShortDelayBetweenEnd());
		Debug.Log((object)"Reward picked");
	}

	public void SkipReward()
	{
		AudioManager.instance.AudioEffect("ButtonClick");
		battleStates = PerformAction.GAMEEND;
	}

	public void EndBattle()
	{
		battleStates = PerformAction.GAMEEND;
	}

