			}
		}
		CheckMeleeDamages(((Component)CurrentCharacter).gameObject, list);
	}

	public void CheckMeleeDamages(GameObject Attacker, List<GameObject> TargetList)
	{
		if (!ProfileManager.instance.ShowDamageEstimates)
		{
			return;
		}
		Dictionary<GameObject, string> dictionary = new Dictionary<GameObject, string>();
		foreach (GameObject Target in TargetList)
		{
			AttackDetails attackDetails = new AttackDetails();
			attackDetails.AttackSkill = "";
			attackDetails.AttackerObject = Attacker;
			attackDetails.TargetObject = Target;
			attackDetails.Skill = SkillType.Melee;
			attackDetails.ExtraDamage = 0;
			attackDetails.SkillNumberVariable = 0;
			attackDetails.DamageType = DamageType.normal;
			dictionary.Add(Target, EstimateDamage(attackDetails).ToString());
		}
		DamageEstimator.instance.ShowEstimateText(dictionary, "damage", CurrentCharacter);
	}

