	public int HowManyAlive(bool Hero)
	{
		int num = 0;
		if (Hero)
		{
			foreach (EnemyBattler item in HerosInBattle)
			{
				if (((Component)item).gameObject.tag != "DeadHero")
				{
					num++;
				}
			}
		}
		else
		{
			foreach (EnemyBattler item2 in EnemiesInBattle)
			{
				if (((Component)item2).gameObject.tag != "DeadEnemy")
				{
					num++;
				}
			}
		}
		return num;
	}

