	private void GameEndActivitiesBeforeStats()
	{
		AudioManager.instance.FadeOutMusic();
		DisableArrowButtons();
		SkillController.instance.ClearSkills();
		UIManager.instance.CloseAllTooltips();
		foreach (EnemyBattler item in TurnOrder)
		{
			CurrentCharacter = item;
			CurrentCharacter.CharacterState = EnemyBattler.CharacterStates.WAIT;
		}
		int num = 0;
		EnemyBattler enemyBattler = null;
		foreach (EnemyBattler item2 in HerosInBattle)
		{
			item2.RemoveAllBuffs();
			if (((Component)item2).tag == "Hero")
			{
				num++;
				enemyBattler = item2;
			}
		}
		if (num == 1 && (Object)(object)enemyBattler != (Object)null && (Object)(object)enemyBattler.ThisCharacter != (Object)null && enemyBattler.ThisCharacter.CurrentHP == 1)
		{
			SteamAchievements.instance.UnlockSteamAchievement("ACH_1unit1hpWin");
		}
		try
		{
			foreach (CharacterTemplate item3 in RosterManager.instance.Roster)
			{
				if ((Object)(object)item3 != (Object)null)
				{
					item3.GamesSatInRoster++;
				}
			}
		}
		catch (Exception)
		{
		}
		CasualEndActivities();
	}

	private void CasualEndActivities()
	{
		foreach (EnemyBattler item in HerosInBattle)
		{
			if (item.CharacterState != EnemyBattler.CharacterStates.DEAD && item.CharacterState != EnemyBattler.CharacterStates.DYING)
			{
				continue;
			}
			int num = 0;
			if (item.DeathType == EnemyBattler.DeathState.MORTAL)
			{
				num = 6;
			}
			else if (item.DeathType == EnemyBattler.DeathState.COMA)
			{
				num = 4;
			}
			else if (item.DeathType == EnemyBattler.DeathState.KNOCKOUT)
			{
				num = 2;
			}
			if (ChangingVariables.instance.SevereInjuries == 1)
			{
				num *= 2;
			}
			if (ChangingVariables.instance.SevereInjuries == 2 || GlobalVariables.instance.ChallengeDeadIsDead)
			{
				num = 20;
			}
			num++;
			bool flag = false;
			foreach (Perk characterPerk in item.ThisCharacter.CharacterPerks)
			{
				if (characterPerk.name == "Healthy")
				{
					num--;
				}
				if (characterPerk.name == "Heroic" || characterPerk.name == "Zealous")
				{
					num += 2;
				}
				if (characterPerk.name == "Survivor")
				{
					flag = true;
				}
			}
			item.ThisCharacter.InjuryCount += num;
			if (flag)
			{
				item.ThisCharacter.InjuryCount = Mathf.Clamp(item.ThisCharacter.InjuryCount, 0, 10);
			}
			UnitsThatReceivedDamageFromBattle.Add(item.ThisCharacter);
		}
		foreach (EnemyBattler item2 in HerosInBattle)
		{
			if (item2.ThisCharacter.InjuryCount > 10)
			{
				HerosThatDiedThisBattle.Add(item2.ThisCharacter);
				ProgressManager.instance.PermanentlyKillUnit(item2.ThisCharacter);
				if (GlobalVariables.instance.ChallengeNoDeaths)
				{
					ProgressManager.instance.ProgressionLevelLosses = ProgressManager.instance.ProgressionLevelMaxLosses;
				}
			}
		}
	}

	private void ShowEndStats(bool VictoryOrNot)
	{
		//IL_081c: Unknown result type (might be due to invalid IL or missing references)
		//IL_0821: Unknown result type (might be due to invalid IL or missing references)
		float num = 1f;
		foreach (EnemyBattler item in HerosInBattle)
		{
			foreach (Perk characterPerk in item.ThisCharacter.CharacterPerks)
			{
				if (characterPerk.name == "Greedy")
				{
					num += 0.1f;
				}
			}
		}
		float num2 = 1f;
		if (ProgressManager.instance.CurrentTypeOfMatch == 4)
		{
			num2 = 1.5f;
			GildedSticker.SetActive(true);
		}
		float num3 = 3f;
		int num4 = Random.Range(30, 52);
		if (GlobalVariables.instance.CareerModeActivated)
		{
			num3 = 2.3f;
			num4 += HerosInBattle.Count * 15;
			num4 += 15;
		}
		int num5 = Mathf.RoundToInt((num3 * (float)AudienceManager.instance.AudienceCount + (float)num4) * num * num2);
		int num6 = 0;
		int num7 = 0;
		int num8 = 0;
		if (GlobalVariables.instance.CareerModeActivated)
		{
			num8 = Mathf.RoundToInt((float)ProgressManager.instance.CareerVictoryBonusGold * num2);
			foreach (CharacterTemplate item2 in ProgressManager.instance.Team)
			{
				if ((Object)(object)item2 != (Object)null)
				{
					num7 -= item2.Wage;
				}
			}
		}
		if (VictoryOrNot)
		{
			Debug.Log((object)"Won battle");
			AudioManager.instance.AudioEffect("Win");
			if (!ChampionshipMatch)
			{
				RewardChest.SetActive(true);
			}
			else
			{
				((Component)LossToTownButton).gameObject.SetActive(true);
			}
			if (ProgressManager.instance.EmpDesire == "Completed")
			{
				BonusGold = Mathf.RoundToInt((float)num5 * 0.3f);
				if (ProgressManager.instance.EmpDemand != "" && ProgressManager.instance.EmpDemand != "NODEMAND")
				{
					SteamAchievements.instance.UnlockSteamAchievement("ACH_DesireDemandCompleted");
				}
			}
			else
			{
				BonusGold = 0;
			}
			if (num8 > 0)
			{
				((TMP_Text)GoldGainVictoryBonusAmount).SetText("+" + num8);
				((Component)GoldGainVictoryBonusAmount).gameObject.SetActive(true);
				GoldGainVictoryBonusTitle.SetActive(true);
			}
			num6 = Mathf.RoundToInt((float)(num5 + BonusGold + num7 + num8));
			ProgressManager.instance.TotalGoldGainedFromBattle += num6;
			Debug.Log((object)("Total Gold: " + num6 + " (Tickets: " + num5 + " | Bonus: " + BonusGold + " | Wages: " + num7 + " | VictoryBonus: " + num8 + " | totalmultiplier: " + num2 + " + " + num + ")"));
			ProgressManager.instance.ChangeGold(num6);
			((TMP_Text)((Component)WinOrLossText).GetComponent<TextMeshProUGUI>()).text = LocalizationManager.GetTranslation("UI.ENDSCREEN/UI.ENDSCREEN_victory");
			foreach (EnemyBattler item3 in HerosInBattle)
			{
				if (!ProgressManager.instance.Team.Contains(item3.ThisCharacter) || (!GlobalVariables.instance.StatgainForDead && ((Component)item3).gameObject.tag != "Hero"))
				{
					continue;
				}
				bool flag = false;
				foreach (Perk characterPerk2 in item3.ThisCharacter.CharacterPerks)
				{
					if (characterPerk2.name == "Savant")
					{
						flag = true;
					}
				}
				CharacterTemplate thisCharacter = item3.ThisCharacter;
				GameObject val = Object.Instantiate<GameObject>(StatGainTextPrefab);
				if (flag)
				{
					if (GlobalVariables.instance.CareerModeActivated && ProgressManager.instance.CurrentTypeOfMatch == 5)
					{
						string text = thisCharacter.GainRandomStat(4);
						((TMP_Text)val.GetComponent<TextMeshProUGUI>()).SetText(thisCharacter.Charname + " " + text + " +4");
					}
					else
					{
						string text = thisCharacter.GainRandomStat(2);
						((TMP_Text)val.GetComponent<TextMeshProUGUI>()).SetText(thisCharacter.Charname + " " + text + " +2");
					}
				}
				else if (GlobalVariables.instance.CareerModeActivated && ProgressManager.instance.CurrentTypeOfMatch == 5)
				{
					string text = thisCharacter.GainRandomStat(2);
					((TMP_Text)val.GetComponent<TextMeshProUGUI>()).SetText(thisCharacter.Charname + " " + text + " +2");
				}
				else
				{
					string text = thisCharacter.GainRandomStat();
					((TMP_Text)val.GetComponent<TextMeshProUGUI>()).SetText(thisCharacter.Charname + " " + text + " +1");
				}
				val.transform.SetParent(SkillGainPanel, false);
				thisCharacter.UpdateSecondaryStats();
			}
		}
		else
		{
			Debug.Log((object)"Lost battle");
			AudioManager.instance.AudioEffect("Lose");
			((TMP_Text)((Component)WinOrLossText).GetComponent<TextMeshProUGUI>()).text = LocalizationManager.GetTranslation("UI.ENDSCREEN/UI.ENDSCREEN_defeat");
			((Component)LossToTownButton).gameObject.SetActive(true);
			num5 = Mathf.RoundToInt((float)(num5 / 2));
			((TMP_Text)((Component)EndGoldGain).GetComponent<TextMeshProUGUI>()).SetText(num5.ToString());
			if (ProgressManager.instance.EmpDesire == "Completed")
			{
				BonusGold = Mathf.RoundToInt((float)num5 * 0.3f);
			}
			else
			{
				BonusGold = 0;
			}
			num6 = Mathf.RoundToInt((float)(num5 + BonusGold + num7));
			ProgressManager.instance.TotalGoldGainedFromBattle += num6;
			Debug.Log((object)("Total Gold: " + num6 + " (Tickets: " + num5 + " | Bonus: " + BonusGold + " | Wages: " + num7 + " | totalmultiplier: " + num2 + " + " + num + ")"));
			ProgressManager.instance.ChangeGold(num6);
		}
		RealizedGoldGain = num5;
		((TMP_Text)GoldGainTicketSalesAmount).SetText("+" + num5);
		if (BonusGold > 0)
		{
			((TMP_Text)GoldGainDesireAmount).SetText("+" + BonusGold);
			((Component)GoldGainDesireAmount).gameObject.SetActive(true);
			GoldGainDesireTitle.SetActive(true);
		}
		if (GlobalVariables.instance.CareerModeActivated)
		{
			((TMP_Text)GoldGainWagesAmount).SetText("<size=6> </size>-<size=6> </size>" + Mathf.Abs(num7));
			((Component)GoldGainWagesAmount).gameObject.SetActive(true);
			GoldGainWagesTitle.SetActive(true);
		}
		RealizedTotalGoldGain = num6;
		if (num6 >= 0)
		{
			((TMP_Text)GoldGainTotalAmount).SetText(num6 + " <sprite=\"GoldInTextBigger\" index=0>");
		}
		else
		{
			((TMP_Text)GoldGainTotalAmount).SetText("<color=#FF7979>" + num6 + " <sprite=\"GoldInTextBigger\" index=0>");
		}
		string text2 = "";
		foreach (CharacterTemplate item4 in HerosThatDiedThisBattle)
		{
			GameObject val2 = Object.Instantiate<GameObject>(StatGainTextPrefab);
			text2 = LocalizationManager.GetTranslation("TOOLTIP/TOOLTIP_punishdead");
			text2 = text2.Replace("<CHAR>", item4.Charname);
			((TMP_Text)val2.GetComponent<TextMeshProUGUI>()).SetText(text2);
			((Graphic)val2.GetComponent<TextMeshProUGUI>()).color = Color32.op_Implicit(new Color32(byte.MaxValue, (byte)0, (byte)0, byte.MaxValue));
			val2.transform.SetParent(SkillGainPanel, false);
		}
		((MonoBehaviour)this).StartCoroutine(FadeInEndStatPanel());
	}

	public void LateDesireCompletionAdjustment()
	{
		int num = Mathf.RoundToInt((float)RealizedGoldGain * 0.3f);
		ProgressManager.instance.ChangeGold(num);
		((TMP_Text)GoldGainDesireAmount).SetText("+" + num);
		((Component)GoldGainDesireAmount).gameObject.SetActive(true);
		GoldGainDesireTitle.SetActive(true);
		Debug.Log((object)("Late desire completion gold granted: " + num));
		RealizedTotalGoldGain += num;
		if (RealizedTotalGoldGain >= 0)
		{
			((TMP_Text)GoldGainTotalAmount).SetText(RealizedTotalGoldGain + " <sprite=\"GoldInTextBigger\" index=0>");
		}
		else
		{
			((TMP_Text)GoldGainTotalAmount).SetText("<color=#FF7979>" + RealizedTotalGoldGain + " <sprite=\"GoldInTextBigger\" index=0>");
		}
	}

	public IEnumerator TurnEndDebugTimer(EnemyBattler CharacterWithAnimationsRemaining)
	{
		if (!TurnEndDebugTimerStarted)
		{
			TurnEndDebugTimerStarted = true;
			yield return (object)new WaitForSeconds(1f);
			if ((Object)(object)CharacterWithAnimationsRemaining == (Object)(object)CurrentCharacter)
			{
				TurnHasRemainingTasks.Clear();
				Debug.Log((object)"TurnEndDebugTimer: Cleared remaining tasks");
			}
			TurnEndDebugTimerStarted = false;
		}
	}

	public IEnumerator FadeInEndStatPanel()
	{
		if (!fadestarted)
		{
			fadestarted = true;
			((Component)EndStatScreenCanvas).gameObject.SetActive(true);
			yield return (object)new WaitForSeconds(1f);
			while (EndStatScreenCanvas.alpha < 1f)
			{
				CanvasGroup endStatScreenCanvas = EndStatScreenCanvas;
				endStatScreenCanvas.alpha += Time.deltaTime * 2f;
				yield return null;
			}
			EndStatScreenCanvas.interactable = true;
			fadestarted = false;
		}
	}

	public IEnumerator StartActivities()
	{
		if (fadestarted)
		{
			yield break;
		}
		fadestarted = true;
		if (!ProfileManager.instance.SkipBattleIntro)
		{
			((MonoBehaviour)this).StartCoroutine(AudienceManager.instance.Cheer(10f));
			while (StartScreenCanvas.alpha < 1f)
			{
				CanvasGroup startScreenCanvas = StartScreenCanvas;
				startScreenCanvas.alpha += Time.deltaTime * 2f;
				yield return null;
			}
			StartScreenCanvas.interactable = true;
			((TMP_Text)TeamAText).SetText("<color=#64E632>" + ProgressManager.instance.HeroTeamName + "</color>");
			((TMP_Text)TeamBText).SetText("<color=#FF4040>" + ProgressManager.instance.EnemyTeamName + "</color>");
			if (EnemyStarts)
			{
				((TMP_Text)InitiativeText).SetText(LocalizationManager.GetTranslation("UI.BATTLE/UI.BATTLE_initiative").Replace("<TEAM>", "<color=#FF4040>" + ProgressManager.instance.EnemyTeamName + "</color>"));
			}
			else
			{
				((TMP_Text)InitiativeText).SetText(LocalizationManager.GetTranslation("UI.BATTLE/UI.BATTLE_initiative").Replace("<TEAM>", "<color=#64E632>" + ProgressManager.instance.HeroTeamName + "</color>"));
			}
			yield return (object)new WaitForSeconds(1f);
			while (StartScreenTeamACanvas.alpha < 1f)
			{
				CanvasGroup startScreenTeamACanvas = StartScreenTeamACanvas;
				startScreenTeamACanvas.alpha += Time.deltaTime * 3f;
				yield return null;
			}
			yield return (object)new WaitForSeconds(1f);
			AudioManager.instance.AudioEffect("BattleStart");
			while (StartScreenVSCanvas.alpha < 1f)
			{
				CanvasGroup startScreenVSCanvas = StartScreenVSCanvas;
				startScreenVSCanvas.alpha += Time.deltaTime * 3f;
				yield return null;
			}
			yield return (object)new WaitForSeconds(1f);
			while (StartScreenTeamBCanvas.alpha < 1f)
			{
				CanvasGroup startScreenTeamBCanvas = StartScreenTeamBCanvas;
				startScreenTeamBCanvas.alpha += Time.deltaTime * 3f;
				yield return null;
			}
			yield return (object)new WaitForSeconds(1f);
			if (EnemyStarts)
			{
				TurnStartAnimation.SetTrigger("Red");
			}
			else
			{
				TurnStartAnimation.SetTrigger("Green");
			}
			InitiativeOrb.alpha = 1f;
			yield return (object)new WaitForSeconds(1.5f);
			while (StartScreenInitiativeCanvas.alpha < 1f)
			{
				CanvasGroup startScreenInitiativeCanvas = StartScreenInitiativeCanvas;
				startScreenInitiativeCanvas.alpha += Time.deltaTime * 3f;
				yield return null;
			}
			yield return (object)new WaitForSeconds(1f);
			while (StartScreenTeamACanvas.alpha > 0f)
			{
				CanvasGroup startScreenTeamACanvas2 = StartScreenTeamACanvas;
				startScreenTeamACanvas2.alpha -= Time.deltaTime * 3f;
				CanvasGroup startScreenTeamBCanvas2 = StartScreenTeamBCanvas;
				startScreenTeamBCanvas2.alpha -= Time.deltaTime * 3f;
				CanvasGroup startScreenVSCanvas2 = StartScreenVSCanvas;
				startScreenVSCanvas2.alpha -= Time.deltaTime * 3f;
				CanvasGroup initiativeOrb = InitiativeOrb;
				initiativeOrb.alpha -= Time.deltaTime * 3f;
				CanvasGroup startScreenInitiativeCanvas2 = StartScreenInitiativeCanvas;
				startScreenInitiativeCanvas2.alpha -= Time.deltaTime * 3f;
				yield return null;
			}
		}
		else
		{
			yield return (object)new WaitForSeconds(0.3f);
			((MonoBehaviour)this).StartCoroutine(AudienceManager.instance.Cheer(2f));
		}
		AudioManager.instance.AudioEffect("BattleStart2");
		((MonoBehaviour)this).StartCoroutine(ScreenShake.instance.ShakeScreen(0.6f, 0.3f));
		FightTextCanvas.alpha = 1f;
		yield return (object)new WaitForSeconds(0.5f);
		while (StartScreenCanvas.alpha > 0f)
		{
			CanvasGroup startScreenCanvas2 = StartScreenCanvas;
			startScreenCanvas2.alpha -= Time.deltaTime * 3f;
			yield return null;
		}
		StartScreenCanvas.interactable = false;
		foreach (EnemyBattler item in TurnOrder)
		{
			((Behaviour)item.Animator).enabled = false;
		}
		yield return (object)new WaitForSeconds(0.1f);
		if (ChampionshipMatch)
		{
			ChatMessage(EnemiesInBattle[0].ThisCharacter.Portrait, LocalizationManager.GetTranslation("TAUNT/TAUNT_champs"));
		}
		else if (CheckRandom(ChangingVariables.instance.TauntChance))
		{
			ChatMessage(EnemiesInBattle[0].ThisCharacter.Portrait);
		}
		else
		{
			battleStates = PerformAction.TURNSTART;
		}
		EnableArrowButtons();
		fadestarted = false;
		if (ChampionshipMatch)
		{
			AudioManager.instance.PlayMusic("ChampionshipBattle");
		}
		else
		{
			AudioManager.instance.PlayMusic("Battle");
		}
	}

	public EnemyBattler GetRandomAliveUnit(bool Enemy)
	{
		int num = 0;
		EnemyBattler enemyBattler;
		do
		{
			if (Enemy)
			{
				enemyBattler = EnemiesInBattle[Random.Range(0, EnemiesInBattle.Count)];
				if (((Component)enemyBattler).tag == "Enemy")
				{
					break;
				}
			}
			else
			{
				enemyBattler = HerosInBattle[Random.Range(0, HerosInBattle.Count)];
				if (((Component)enemyBattler).tag == "Hero")
				{
					break;
				}
			}
			num++;
		}
		while (num < 50);
		return enemyBattler;
	}

	public void ChatMessage(Sprite Portrait, string message = "", string secondmessage = "", string thirdmessage = "")
	{
		UIManager.instance.CloseAllTooltips();
		AudioManager.instance.AudioEffect("Dialogue");
		TogglePauseBattle();
		ActivateKeyboardListener();
		ChatMessageActive = true;
		battleStates = PerformAction.WAIT;
		((Component)ChatWindow).gameObject.SetActive(true);
		((Component)ChatPortrait).GetComponent<Image>().sprite = Portrait;
		if (message == "")
		{
			message = DataTables.instance.GetRandomBeforeBattleTaunt();
		}
		if (secondmessage != "")
		{
			SecondMessage = secondmessage;
		}
		if (thirdmessage != "")
		{
			ThirdMessage = thirdmessage;
		}
		((TMP_Text)((Component)ChatText).GetComponent<TextMeshProUGUI>()).SetText(message);
	}

	public void CloseChatWindow()
	{
		if (SecondMessage != "")
		{
			((TMP_Text)((Component)ChatText).GetComponent<TextMeshProUGUI>()).SetText(SecondMessage);
			SecondMessage = "";
			return;
		}
		if (ThirdMessage != "")
		{
			((TMP_Text)((Component)ChatText).GetComponent<TextMeshProUGUI>()).SetText(ThirdMessage);
			ThirdMessage = "";
			return;
		}
		AudioManager.instance.AudioEffect("DialogueOK");
		((Component)ChatWindow).gameObject.SetActive(false);
		ChatMessageActive = false;
		DisableKeyboardListener();
		battleStates = PerformAction.DEALTURN;
		TogglePauseBattle();
		if (isEmperorSpeaking)
		{
			EmperorStopsSpeaking();
		}
	}

	public void EmperorSpeaks(string message = "", string message2 = "", string message3 = "")
	{
		isEmperorSpeaking = true;
		EmperorAnimator.SetTrigger("StartSpeak");
		((MonoBehaviour)this).StartCoroutine(ScreenShake.instance.ShakeScreen(0.2f, 0.2f));
		ChatMessage(EmperorPortrait, message, message2, message3);
	}

	public EnemyBattler ChooseRandomUnit(bool Hero)
	{
		EnemyBattler enemyBattler = null;
		int num = 0;
		if (Hero)
		{
			do
			{
				num++;
				enemyBattler = HerosInBattle[Random.Range(0, HerosInBattle.Count)];
			}
			while (!(((Component)enemyBattler).tag != "DeadHero") && num <= 30);
		}
		else
		{
			do
			{
				num++;
				enemyBattler = EnemiesInBattle[Random.Range(0, EnemiesInBattle.Count)];
			}
			while (!(((Component)enemyBattler).tag != "DeadEnemy") && num <= 30);
		}
		return enemyBattler;
	}

	public void CauseDemandPenalty(bool minorpenalty = false)
	{
		string text = "";
		int num = 0;
		foreach (EnemyBattler item in HerosInBattle)
		{
			if (((Component)item).tag == "Hero")
			{
				num++;
			}
		}
		int num2 = 0;
		num2 = ((num <= 1) ? Random.Range(1, 4) : Random.Range(1, 7));
		EnemyBattler enemyBattler = ChooseRandomUnit(Hero: true);
		if (minorpenalty)
		{
			num2 = 2;
		}
		else if (ProgressManager.instance.ProgressionLevel == 2 && !GlobalVariables.instance.CareerModeActivated)
		{
			num2 = ((!(Random.value > 0.5f)) ? 5 : 4);
		}
		if (num2 < 4)
		{
			enemyBattler.HitEffectAnimator.SetTrigger("LightningBurst");
			AudioManager.instance.AudioEffect("Debuff1");
		}
		else
		{
			foreach (EnemyBattler item2 in HerosInBattle)
			{
				item2.HitEffectAnimator.SetTrigger("LightningBurst");
				AudioManager.instance.AudioEffect("Debuff1");
			}
		}
		switch (num2)
		{
		case 1:
			enemyBattler.ThisCharacter.InjuryCount += 5;
			text = LocalizationManager.GetTranslation("LOG/LOG_punishteam");
			text = text.Replace("<TEAM>", ProgressManager.instance.HeroTeamName);
			CombatLog.instance.WriteLog("<color=#FF0000>" + text + " " + LocalizationManager.GetTranslation("LOG/LOG_punish1") + "</color>");
			break;
		case 2:
			enemyBattler.TryToAddBuff(EmperorDotSingle, 1000, NoDmg: true);
			text = LocalizationManager.GetTranslation("LOG/LOG_punishteam");
			text = text.Replace("<TEAM>", ProgressManager.instance.HeroTeamName);
			CombatLog.instance.WriteLog("<color=#FF0000>" + text + " " + LocalizationManager.GetTranslation("LOG/LOG_punish2") + "</color>");
			break;
		case 3:
			enemyBattler.TakeDamage(20, DamageType.piercing, ShowInLog: true, "none", "none", forceanimation: false, debuffdamage: false, emperordamage: true);
			text = LocalizationManager.GetTranslation("LOG/LOG_punishteam");
			text = text.Replace("<TEAM>", ProgressManager.instance.HeroTeamName);
			CombatLog.instance.WriteLog("<color=#FF0000>" + text + " " + LocalizationManager.GetTranslation("LOG/LOG_punish3") + "</color>");
			break;
		case 4:
			foreach (EnemyBattler item3 in HerosInBattle)
			{
				item3.ThisCharacter.InjuryCount += 2;
			}
			text = LocalizationManager.GetTranslation("LOG/LOG_punishteam");
			text = text.Replace("<TEAM>", ProgressManager.instance.HeroTeamName);
			CombatLog.instance.WriteLog("<color=#FF0000>" + text + " " + LocalizationManager.GetTranslation("LOG/LOG_punish4") + "</color>");
			break;
		case 5:
			foreach (EnemyBattler item4 in HerosInBattle)
			{
				if (!(((Component)item4).tag == "DeadHero"))
				{
					item4.TryToAddBuff(EmperorDotAll, 1000, NoDmg: true);
				}
			}
			text = LocalizationManager.GetTranslation("LOG/LOG_punishteam");
			text = text.Replace("<TEAM>", ProgressManager.instance.HeroTeamName);
			CombatLog.instance.WriteLog("<color=#FF0000>" + text + " " + LocalizationManager.GetTranslation("LOG/LOG_punish5") + "</color>");
			break;
		case 6:
			foreach (EnemyBattler item5 in HerosInBattle)
			{
				if (!(((Component)item5).tag == "DeadHero"))
				{
					item5.TakeDamage(10, DamageType.piercing, ShowInLog: true, "none", "none", forceanimation: false, debuffdamage: false, emperordamage: true);
				}
			}
			text = LocalizationManager.GetTranslation("LOG/LOG_punishteam");
			text = text.Replace("<TEAM>", ProgressManager.instance.HeroTeamName);
			CombatLog.instance.WriteLog("<color=#FF0000>" + text + " " + LocalizationManager.GetTranslation("LOG/LOG_punish6") + "</color>");
			break;
		}
		if (!minorpenalty)
		{
			ProgressManager.instance.EmpDemand = "Failed";
			AreThereDesiresOrDemands();
		}
	}

	public void AreThereDesiresOrDemands()
	{
		bool flag = false;
		if (ProgressManager.instance.EmpDemand != "Failed" && ProgressManager.instance.EmpDemand != "" && ProgressManager.instance.EmpDemand != "NODEMAND")
		{
			flag = true;
		}
		else if (ProgressManager.instance.EmpDesire != "Completed" && ProgressManager.instance.EmpDesire != "" && ProgressManager.instance.EmpDesire != "NODESIRE")
		{
			flag = true;
		}
		if (GlobalVariables.instance.CareerModeActivated && ProgressManager.instance.CareerSpecialRule != "")
		{
			flag = true;
		}
		if (flag)
		{
			DesireNotification.SetActive(true);
		}
		else
		{
			DesireNotification.SetActive(false);
		}
	}

	public void EmperorStopsSpeaking()
	{
		if (isEmperorAnnoyed && !DemandPenaltyGiven)
		{
			isEmperorAnnoyed = false;
			CauseDemandPenalty();
			DemandPenaltyGiven = true;
		}
		else if (isEmperorMildlyAnnoyed)
		{
			isEmperorMildlyAnnoyed = false;
			CauseDemandPenalty(minorpenalty: true);
		}
		EmperorAnimator.SetTrigger("StopSpeak");
		isEmperorSpeaking = false;
		if (FinalTurnReached)
		{
			battleStates = PerformAction.LOSS;
		}
	}

	public void UpdateTurnTracker(bool midturn)
	{
		int index = 1;
		if (midturn)
		{
