	public void InitializeTeam(int MatchType = 0)
	{
		int num = Mathf.Clamp(ChangingVariables.instance.EnemyTeamSize, 1, 4);
		difficultyModifier = 1f;
		rewardModifier = 1f;
		if (Random.Range(0, 100) < 25 && MatchType < 19)
		{
			difficultyModifier = Random.Range(1f, 1.3f);
			rewardModifier += difficultyModifier - 1f;
		}
		if (Random.Range(0, 100) < 12 && num > 2 && MatchType < 19)
		{
			num--;
			difficultyModifier += Random.Range(0.2f, 0.4f);
			rewardModifier += 0.3f;
			if (ChangingVariables.instance.EnemyTeamRarityPoints >= 12)
			{
				difficultyModifier += 0.2f;
			}
		}
		else if (Random.Range(0, 100) < 12 && num < 4 && MatchType < 19)
		{
			num++;
			rewardModifier += 0.2f;
		}
		switch (MatchType)
		{
		case 19:
			CurrentIntelCost = DefaultIntelCost * (ProgressManager.instance.CurrentCareerRank + 2);
			CurrentSabotageCost = DefaultSabotageCost * (ProgressManager.instance.CurrentCareerRank + 2);
			break;
		case 20:
			RewardSlot.PresetRewardType = 9;
			TeamDetailsVisible = true;
			SabotageAmount = 9;
			((Selectable)SabotageButton).interactable = false;
			((TMP_Text)IntelButtonText).SetText("-");
			break;
		default:
			CurrentIntelCost = DefaultIntelCost * ProgressManager.instance.CurrentCareerRank;
			CurrentSabotageCost = DefaultSabotageCost * ProgressManager.instance.CurrentCareerRank;
			break;
		}
		int num2 = Mathf.CeilToInt((float)ChangingVariables.instance.EnemyTeamRarity * difficultyModifier);
		float statmodifier = ChangingVariables.instance.EnemyTeamStatModifier + (difficultyModifier - 1f) / 2f;
		int num3 = Mathf.CeilToInt((float)ChangingVariables.instance.EnemyTeamRarityPoints * difficultyModifier);
		int num4 = Mathf.CeilToInt((float)ChangingVariables.instance.EnemyItemRarityPoints * difficultyModifier);
		int num5 = 0;
		if (ProgressManager.instance.CurrentCareerRank > 1 && MatchType < 20)
		{
			for (int i = 0; i < num; i++)
			{
				if (Random.Range(0, 100) < GlobalVariables.instance.CareerEnemyBeastChance + ChangingVariables.instance.EnemyTeamBossChance)
				{
					num5++;
					rewardModifier += 0.4f;
				}
			}
		}
		if (MatchType == 20)
		{
			num5 = 2;
		}
		Debug.Log((object)("Creating team with parameters: " + num + " " + num2 + " " + num3 + " " + num4 + " " + num5 + " " + difficultyModifier + " " + rewardModifier));
		EnemyTeam = ProgressManager.instance.CreateCareerEnemyTeam(num, num2, num3, num4, num5, statmodifier);
		TeamName = DataTablesPersisting.instance.GetRandomTeamName();
		if (Random.Range(0, 100) < GlobalVariables.instance.CareerDemandChance || GlobalVariables.instance.ChallengeNeedyEmperor)
		{
			rewardModifier += 0.1f;
			EmperorDemand = DataTables.instance.GetRandomEmperorDemand();
		}
		if (Random.Range(0, 100) < GlobalVariables.instance.CareerDesireChance || GlobalVariables.instance.ChallengeNeedyEmperor)
		{
			rewardModifier -= 0.1f;
			EmperorDesire = DataTables.instance.GetRandomEmperorDesire();
		}
		bool flag = false;
		if (EmperorDemand == "Flawless win" && EmperorDesire == "Even match")
		{
			flag = true;
		}
		else if (EmperorDemand == "Snail pace" && EmperorDesire == "Sprinting")
		{
			flag = true;
		}
		else if (EmperorDemand == "Clean fight" && EmperorDesire == "Carnage")
		{
			flag = true;
		}
		else if (EmperorDemand == "Slow burn" && EmperorDesire == "Quick knockout")
		{
			flag = true;
		}
		else if (EmperorDemand == "Fast match" && EmperorDesire == "Long match")
		{
			flag = true;
		}
		else if (EmperorDemand == "Ordinary hits" && EmperorDesire == "Overkill")
		{
			flag = true;
		}
		else if (EmperorDemand == "Melee knockouts" && EmperorDesire == "Assisted flight")
		{
			flag = true;
		}
		else if (EmperorDemand == "Honest fight" && EmperorDesire == "Ailments")
		{
			flag = true;
		}
		else if (EmperorDemand == "Fair fight" && EmperorDesire == "Enhancements")
		{
			flag = true;
		}
		if (flag)
		{
			EmperorDesire = "";
			rewardModifier += 0.1f;
		}
		if (Random.Range(0, 100) < GlobalVariables.instance.CareerSpecialRuleChance || GlobalVariables.instance.ChallengeNeedyEmperor)
		{
			rewardModifier += 0.05f;
			SpecialRule = DataTables.instance.GetRandomSpecialRule();
		}
		bool flag2 = false;
		if (EmperorDemand == "Honest fight" && SpecialRule == "Afflicted")
		{
			flag2 = true;
		}
		else if (EmperorDemand == "Honest fight" && SpecialRule == "Contagion")
		{
			flag2 = true;
		}
		else if (EmperorDesire == "Sprinting" && SpecialRule == "Sluggishness")
		{
			flag2 = true;
		}
		if (flag2)
		{
			SpecialRule = "";
			rewardModifier -= 0.05f;
		}
		if (ProgressManager.instance.CurrentCareerRank == 1)
		{
			RewardValue = 30;
		}
		else if (ProgressManager.instance.CurrentCareerRank == 2)
		{
			RewardValue = 50;
		}
		else if (ProgressManager.instance.CurrentCareerRank == 3)
		{
			RewardValue = 100;
		}
		else if (ProgressManager.instance.CurrentCareerRank == 4)
		{
			RewardValue = 150;
		}
		else if (ProgressManager.instance.CurrentCareerRank == 5)
		{
			RewardValue = 200;
		}
		if (MatchType == 3)
		{
			RewardValue += 50;
		}
		RewardValue = Mathf.RoundToInt((float)RewardValue * rewardModifier);
		int num6 = Random.Range(0, 100);
		if (num6 < GlobalVariables.instance.CareerRewardCharacterChance && RewardValue >= 55)
		{
			RewardPresetType = 1;
		}
		else if (num6 < GlobalVariables.instance.CareerRewardCharacterChance + GlobalVariables.instance.CareerRewardEquipmentChance)
		{
			RewardPresetType = 2;
		}
		else
		{
			RewardPresetType = 3;
		}
		if (Random.Range(0, 100) < 50)
		{
			RewardPresetType += 3;
		}
		int num7 = RewardPresetType;
		if (num7 > 3)
		{
			num7 -= 3;
			RewardValue = Mathf.RoundToInt((float)RewardValue * 1.15f);
		}
		RewardRarity = 1;
		int num8 = 0;
		switch (num7)
		{
		case 1:
			if (RewardValue >= 230)
			{
				RewardRarity = 5;
				num8 = RewardValue - 230;
			}
			else if (RewardValue >= 160)
			{
				RewardRarity = 4;
				num8 = RewardValue - 160;
			}
			else if (RewardValue >= 115)
			{
				RewardRarity = 3;
				num8 = RewardValue - 115;
			}
			else if (RewardValue >= 90)
			{
				RewardRarity = 2;
				num8 = RewardValue - 90;
			}
			else
			{
				RewardRarity = 1;
				num8 = RewardValue - 65;
			}
			break;
		case 2:
			if (RewardValue >= 210)
			{
				RewardRarity = 5;
				num8 = RewardValue - 210;
			}
			else if (RewardValue >= 130)
			{
				RewardRarity = 4;
				num8 = RewardValue - 130;
			}
			else if (RewardValue >= 65)
			{
				RewardRarity = 3;
				num8 = RewardValue - 65;
			}
			else if (RewardValue >= 40)
			{
				RewardRarity = 2;
				num8 = RewardValue - 40;
			}
			else
			{
				RewardRarity = 1;
				num8 = RewardValue - 15;
			}
			break;
		case 3:
			if (RewardValue >= 180)
			{
				RewardRarity = 5;
				num8 = RewardValue - 180;
			}
			else if (RewardValue >= 90)
			{
				RewardRarity = 3;
				num8 = RewardValue - 90;
			}
			else
			{
				RewardRarity = 1;
				num8 = RewardValue - 30;
			}
			break;
		}
		num8 = Mathf.Clamp(num8, 0, int.MaxValue);
		RewardGold = num8;
		if (MatchType == 20)
		{
			RewardGold = 0;
			RewardPresetType = 9;
		}
		if (RewardPresetType != 1 && RewardPresetType != 2 && RewardPresetType != 3)
		{
			if (RewardPresetType == 4)
			{
				RewardSlot.RewardCharacter = Object.Instantiate<CharacterTemplate>(DataTables.instance.GetRandomCharacter());
				RewardSlot.RewardCharacter.Initialize(RewardRarity);
			}
			else if (RewardPresetType == 5)
			{
				RewardSlot.RewardEquipment = Object.Instantiate<Equipment>(DataTables.instance.GetRandomEquipment());
				RewardSlot.RewardEquipment.Initialize(RewardRarity);
			}
			else if (RewardPresetType == 6)
			{
				int rarity = ((RewardRarity == 5) ? 3 : ((RewardRarity != 3) ? 1 : 2));
				RewardSlot.RewardSkillbook = Object.Instantiate<Spellbook>((Spellbook)DataTables.instance.GetRandomItemNonEquip());
				RewardSlot.RewardSkillbook.Initialize(rarity);
			}
		}
		ProgressManager.instance.ListOfCareerModeTeams.Add(this);
		VisualizeTeam();
		UpdateTeam();
	}

