	public void LoadTeam(int slot, CareerTeamSaveHelper TeamDetails, List<CharacterTemplate> Team)
	{
		EnemyTeam = Team;
		TeamName = TeamDetails.TeamName;
		TeamDetails.TeamName = TeamName;
		SabotageAmount = TeamDetails.SabotageAmount;
		RewardGold = TeamDetails.RewardGold;
		RewardRarity = TeamDetails.RewardRarity;
		RewardPresetType = TeamDetails.RewardPresetType;
		RewardValue = TeamDetails.RewardValue;
		TeamDetailsVisible = TeamDetails.TeamDetailsVisible;
		EmperorDemand = TeamDetails.EmperorDemand;
		EmperorDesire = TeamDetails.EmperorDesire;
		SpecialRule = TeamDetails.SpecialRule;
		CurrentIntelCost = TeamDetails.CurrentIntelCost;
		CurrentSabotageCost = TeamDetails.CurrentSabotageCost;
		switch (slot)
		{
		case 1:
			RewardSlot.RewardEquipment = ES3.Load<Equipment>("CareerTeam1RewardEquipment");
			RewardSlot.RewardCharacter = ES3.Load<CharacterTemplate>("CareerTeam1RewardCharacter");
			RewardSlot.RewardSkillbook = ES3.Load<Spellbook>("CareerTeam1RewardSkillbook");
			break;
		case 2:
			RewardSlot.RewardEquipment = ES3.Load<Equipment>("CareerTeam2RewardEquipment");
			RewardSlot.RewardCharacter = ES3.Load<CharacterTemplate>("CareerTeam2RewardCharacter");
			RewardSlot.RewardSkillbook = ES3.Load<Spellbook>("CareerTeam2RewardSkillbook");
			break;
		case 3:
			RewardSlot.RewardEquipment = ES3.Load<Equipment>("CareerTeam3RewardEquipment");
			RewardSlot.RewardCharacter = ES3.Load<CharacterTemplate>("CareerTeam3RewardCharacter");
			RewardSlot.RewardSkillbook = ES3.Load<Spellbook>("CareerTeam3RewardSkillbook");
			break;
		}
		VisualizeTeam();
		UpdateTeam();
	}

	public void Intel()
	{
		if (TeamDetailsVisible)
		{
			Sabotage();
			return;
		}
		if (ProgressManager.instance.GetGold() < CurrentIntelCost)
		{
			UIManager.instance.ShowErrorMessage(LocalizationManager.GetTranslation("MESSAGE/MESSAGE_nogold"));
			return;
		}
		ProgressManager.instance.ChangeGold(-CurrentIntelCost);
		AudioManager.instance.AudioEffect("Coin");
		TeamDetailsVisible = true;
		UpdateTeam();
		string translation = LocalizationManager.GetTranslation("UI.TOWN/UI.TOWN_career_sabotage");
		((TMP_Text)IntelButtonText).SetText(translation + " <color=#FFE63B>" + CurrentSabotageCost + "<sprite=\"GoldInText\" index=0> \u00a0");
	}

	public void Sabotage()
	{
		if (ProgressManager.instance.GetGold() < CurrentSabotageCost)
		{
			UIManager.instance.ShowErrorMessage(LocalizationManager.GetTranslation("MESSAGE/MESSAGE_nogold"));
			return;
		}
		ProgressManager.instance.ChangeGold(-CurrentSabotageCost);
		int num = 0;
		int num2 = 0;
		while (num <= 0)
		{
			num2++;
			foreach (CharacterTemplate item in EnemyTeam)
			{
				int num3 = 0;
				if (GlobalVariables.instance.CareerSabotageRandomAmount)
				{
					int num4 = Random.Range(0, 100);
					if (num4 < 5)
					{
						num3 = 3;
					}
					else if (num4 < 20)
					{
						num3 = 2;
					}
					else if (num4 < 65)
					{
						num3 = 1;
					}
				}
				else
				{
					num3 = 1;
				}
				item.CauseInjuryInTown(num3);
				num += num3;
			}
			if (num2 > 10)
			{
				break;
			}
		}
		AudioManager.instance.AudioEffect("MinorHit");
		SabotageAmount++;
		CurrentSabotageCost = Mathf.RoundToInt((float)CurrentSabotageCost * 1.2f);
		if (SabotageAmount >= 3)
		{
			((Selectable)SabotageButton).interactable = false;
			((TMP_Text)IntelButtonText).SetText("-");
		}
		else
		{
			string translation = LocalizationManager.GetTranslation("UI.TOWN/UI.TOWN_career_sabotage");
			((TMP_Text)IntelButtonText).SetText(translation + " <color=#FFE63B>" + CurrentSabotageCost + "<sprite=\"GoldInText\" index=0> \u00a0");
		}
		UpdateTeam();
	}

	public void UpdateTeam()
	{
		//IL_001a: Unknown result type (might be due to invalid IL or missing references)
		//IL_0020: Expected Obj, but got Unknown
		List<GameObject> list = new List<GameObject>();
		foreach (Transform item in TeamParent)
		{
			Transform val = item;
			list.Add(((Component)val).gameObject);
		}
		foreach (GameObject item2 in list)
		{
			Object.Destroy((Object)(object)item2);
		}
		if (TeamDetailsVisible)
		{
			foreach (CharacterTemplate item3 in EnemyTeam)
			{
				GameObject val2 = Object.Instantiate<GameObject>(LobbyEnemyTeamSlot);
				val2.transform.SetParent(TeamParent, false);
				val2.GetComponent<EnemyTeamSlot>().Character = item3;
				((Component)val2.transform.Find("Character")).GetComponent<Image>().sprite = item3.Portrait;
				switch (item3.characterRarity)
				{
				case Rarity.Common:
					((Component)val2.transform.Find("Borders")).GetComponent<Image>().sprite = UIManager.instance.BorderCommon;
					break;
				case Rarity.Uncommon:
					((Component)val2.transform.Find("Borders")).GetComponent<Image>().sprite = UIManager.instance.BorderUncommon;
					break;
				case Rarity.Rare:
					((Component)val2.transform.Find("Borders")).GetComponent<Image>().sprite = UIManager.instance.BorderRare;
					break;
				case Rarity.Epic:
					((Component)val2.transform.Find("Borders")).GetComponent<Image>().sprite = UIManager.instance.BorderEpic;
					break;
				case Rarity.Legendary:
					((Component)val2.transform.Find("Borders")).GetComponent<Image>().sprite = UIManager.instance.BorderLegendary;
					break;
				}
				if (item3.InjuryCount > 0)
				{
					((Component)val2.transform.Find("InjuryImage")).gameObject.SetActive(true);
					((TMP_Text)((Component)val2.transform.Find("InjuryImage/InjuryCounter")).GetComponent<TextMeshProUGUI>()).text = item3.InjuryCount.ToString();
				}
				else
				{
					((Component)val2.transform.Find("InjuryImage")).gameObject.SetActive(false);
				}
			}
			return;
		}
		foreach (CharacterTemplate item4 in EnemyTeam)
		{
			if (!((Object)(object)item4 == (Object)null))
			{
				Object.Instantiate<GameObject>(UnknownEnemySlot).transform.SetParent(TeamParent, false);
			}
		}
	}

	public void DoorChosen()
	{
		if (!ProgressManager.instance.CheckFightPreRequisites())
		{
			return;
		}
		ProgressManager.instance.EnemyTeamName = TeamName;
		ProgressManager.instance.CareerSpecialRule = SpecialRule;
		ProgressManager.instance.EmpDemand = EmperorDemand;
		ProgressManager.instance.EmpDesire = EmperorDesire;
		ProgressManager.instance.CareerFightRewardType = RewardPresetType;
		ProgressManager.instance.PresetCareerPrizeRarity = RewardRarity;
		ProgressManager.instance.PresetCareerPrizeCharacter = RewardSlot.RewardCharacter;
		ProgressManager.instance.PresetCareerPrizeEquipment = RewardSlot.RewardEquipment;
		ProgressManager.instance.PresetCareerPrizeBook = RewardSlot.RewardSkillbook;
		ProgressManager.instance.CareerVictoryBonusGold = RewardGold;
		int num = 1;
		foreach (CharacterTemplate item in EnemyTeam)
		{
			List<Equipment> list = new List<Equipment>();
			switch (num)
			{
			case 1:
				foreach (Equipment characterEquip in item.CharacterEquipList)
				{
					list.Add(characterEquip);
				}
				EquipmentManager.instance.CareerTeam1Enemy1Equipment.Clear();
				foreach (Equipment item2 in list)
				{
					EquipmentManager.instance.CareerTeam1Enemy1Equipment.Add(item2);
				}
				break;
			case 2:
				foreach (Equipment characterEquip2 in item.CharacterEquipList)
				{
					list.Add(characterEquip2);
				}
				EquipmentManager.instance.CareerTeam1Enemy2Equipment.Clear();
				foreach (Equipment item3 in list)
				{
					EquipmentManager.instance.CareerTeam1Enemy2Equipment.Add(item3);
				}
				break;
			case 3:
				foreach (Equipment characterEquip3 in item.CharacterEquipList)
				{
					list.Add(characterEquip3);
				}
				EquipmentManager.instance.CareerTeam1Enemy3Equipment.Clear();
				foreach (Equipment item4 in list)
				{
					EquipmentManager.instance.CareerTeam1Enemy3Equipment.Add(item4);
				}
				break;
			case 4:
				foreach (Equipment characterEquip4 in item.CharacterEquipList)
				{
					list.Add(characterEquip4);
				}
				EquipmentManager.instance.CareerTeam1Enemy4Equipment.Clear();
				foreach (Equipment item5 in list)
				{
					EquipmentManager.instance.CareerTeam1Enemy4Equipment.Add(item5);
				}
				break;
			}
			num++;
		}
		SabotageAmount = 99;
		TeamDetailsVisible = true;
		TownManager.instance.GoingIntoBattle = true;
		ProgressManager.instance.CurrentCareerEnemyTeamDetails = SaveTeamDetails();
		ProgressManager.instance.EnemyTeam = EnemyTeam;
		ProgressManager.instance.StartFight();
	}
}
