	{
		((TMP_Text)message).SetText("<color=" + color + ">" + text + "</color>");
	}

	public IEnumerator BecomeVisible()
	{
		canvas.alpha = 0f;
		((Component)this).gameObject.SetActive(true);
		while (canvas.alpha < 1f)
		{
