public class DamageEstimator : MonoBehaviour
{
	public static DamageEstimator instance;

	public GameObject TextPrefab;

	public Dictionary<GameObject, DamageEstimateEntry> DictionaryOfTextEntries;

	public Queue<DamageEstimateEntry> textPool;

	public int poolSize = 10;

	public List<DamageEstimateEntry> CurrentlyVisibleEntries;

	private EnemyBattler EstimatesForCharacter;

	private void Awake()
	{
		if ((Object)(object)instance != (Object)null)
		{
			Object.Destroy((Object)(object)((Component)this).gameObject);
		}
		else
		{
			instance = this;
		}
	}

	private void Start()
	{
		//IL_004e: Unknown result type (might be due to invalid IL or missing references)
		if (ProfileManager.instance.ShowDamageEstimates)
		{
			textPool = new Queue<DamageEstimateEntry>();
			for (int i = 0; i < poolSize; i++)
			{
				GameObject val = Object.Instantiate<GameObject>(TextPrefab);
				val.transform.SetParent(((Component)this).transform);
				val.transform.localScale = new Vector3(1f, 1f, 1f);
				val.SetActive(false);
				textPool.Enqueue(val.GetComponent<DamageEstimateEntry>());
			}
		}
	}

	public void ShowEstimateText(Dictionary<GameObject, string> TargetedUnits, string category, EnemyBattler CharacterWithTurn)
	{
		//IL_0051: Unknown result type (might be due to invalid IL or missing references)
		//IL_0056: Unknown result type (might be due to invalid IL or missing references)
		//IL_00a2: Unknown result type (might be due to invalid IL or missing references)
		//IL_00a3: Unknown result type (might be due to invalid IL or missing references)
		//IL_00ad: Unknown result type (might be due to invalid IL or missing references)
		//IL_00b2: Unknown result type (might be due to invalid IL or missing references)
		//IL_00b7: Unknown result type (might be due to invalid IL or missing references)
		//IL_00bc: Unknown result type (might be due to invalid IL or missing references)
		//IL_00c1: Unknown result type (might be due to invalid IL or missing references)
		if (!ProfileManager.instance.ShowDamageEstimates)
		{
			return;
		}
		if (BattleProcessor.instance.TurnStartActive)
		{
			((MonoBehaviour)this).StartCoroutine(DelayAndQualify(TargetedUnits, category, CharacterWithTurn));
			return;
		}
		EstimatesForCharacter = CharacterWithTurn;
		foreach (KeyValuePair<GameObject, string> TargetedUnit in TargetedUnits)
		{
			Vector3 position = TargetedUnit.Key.transform.position;
			string value = TargetedUnit.Value;
			DamageEstimateEntry damageEstimateEntry = textPool.Dequeue();
			string text = "";
			text = ((!(category == "damage")) ? "#FFFFFF" : "#FF8684");
			damageEstimateEntry.SetText(value, text);
			((Component)damageEstimateEntry).transform.localPosition = Vector2.op_Implicit(GetUnitPositionOnCanvas(Vector2.op_Implicit(position + Vector3.up * 0.8f)));
			CurrentlyVisibleEntries.Add(damageEstimateEntry);
			((MonoBehaviour)this).StartCoroutine(damageEstimateEntry.BecomeVisible());
		}
	}

	private IEnumerator DelayAndQualify(Dictionary<GameObject, string> TargetedUnits, string category, EnemyBattler CharacterWithTurn)
	{
		yield return (object)new WaitForSeconds(1f);
		if (!((Object)(object)CharacterWithTurn != (Object)(object)BattleProcessor.instance.CurrentCharacter) && !((Object)(object)EstimatesForCharacter != (Object)null) && CharacterWithTurn.RemainingMoves > 0)
		{
			ShowEstimateText(TargetedUnits, category, CharacterWithTurn);
		}
	}

	public void ClearEstimates()
	{
		if (!ProfileManager.instance.ShowDamageEstimates)
		{
			return;
		}
		foreach (DamageEstimateEntry currentlyVisibleEntry in CurrentlyVisibleEntries)
		{
			((Component)currentlyVisibleEntry).gameObject.SetActive(false);
			textPool.Enqueue(currentlyVisibleEntry);
		}
		CurrentlyVisibleEntries.Clear();
	}

	public void ClearCurrentCharacter()
	{
		if (ProfileManager.instance.ShowDamageEstimates)
		{
			EstimatesForCharacter = null;
		}
	}

	public Vector2 GetUnitPositionOnCanvas(Vector2 position)
	{
		//IL_0005: Unknown result type (might be due to invalid IL or missing references)
		//IL_0006: Unknown result type (might be due to invalid IL or missing references)
		//IL_000b: Unknown result type (might be due to invalid IL or missing references)
		//IL_0010: Unknown result type (might be due to invalid IL or missing references)
		//IL_0015: Unknown result type (might be due to invalid IL or missing references)
		//IL_0020: Unknown result type (might be due to invalid IL or missing references)
		//IL_002a: Unknown result type (might be due to invalid IL or missing references)
		Vector2 val = Vector2.op_Implicit(Camera.main.WorldToScreenPoint(Vector2.op_Implicit(position)));
		Vector2 result = default(Vector2);
		RectTransformUtility.ScreenPointToLocalPointInRectangle(UIManager.instance.TooltipCanvasRectTransform, val, (Camera)null, ref result);
		return result;
	}
}
