	public void CreateSkillTiers()
	{
		ListOfSkillsLevel1.Clear();
		ListOfSkillsLevel2.Clear();
		ListOfSkillsLevel3.Clear();
		if (ProfileManager.instance.DLC_ContentEnabled)
		{
			foreach (Skill listOfBowSkill in ListOfBowSkills)
			{
				if (listOfBowSkill.SkillRarity == Rarity.Epic)
				{
					ListOfBowSkillsLevel3.Add(listOfBowSkill);
				}
				else if (listOfBowSkill.SkillRarity == Rarity.Rare)
				{
					ListOfBowSkillsLevel2.Add(listOfBowSkill);
				}
				else
				{
					ListOfBowSkillsLevel1.Add(listOfBowSkill);
				}
				if (listOfBowSkill.AIfriendly)
				{
					ListOfAIFriendlyBowSkills.Add(listOfBowSkill);
				}
			}
			foreach (Skill listOfAdditionalDLCSkill in ListOfAdditionalDLCSkills)
			{
				ListOfSkills.Add(listOfAdditionalDLCSkill);
			}
			if (ProfileManager.instance.BloodEnabled)
			{
				foreach (Skill listOfBloodSkill in ListOfBloodSkills)
				{
					ListOfSkills.Add(listOfBloodSkill);
				}
			}
		}
		foreach (Skill listOfSkill in ListOfSkills)
		{
			if (listOfSkill.SkillRarity == Rarity.Epic)
			{
				ListOfSkillsLevel3.Add(listOfSkill);
			}
			else if (listOfSkill.SkillRarity == Rarity.Rare)
			{
				ListOfSkillsLevel2.Add(listOfSkill);
			}
			else
			{
				ListOfSkillsLevel1.Add(listOfSkill);
			}
		}
	}

