	public void LoadEvents()
	{
		ListOfEvents.Clear();
		ListOfSpecialEvents.Clear();
		ListOfContinuationEvents.Clear();
		string[] array = eventdata.text.Split(new char[1] { '\n' });
		for (int i = 1; i < array.Length - 1; i++)
		{
			string[] array2 = array[i].Split(new char[1] { '\t' });
			if (!(array2[0] != ""))
			{
				continue;
			}
			TownEvent townEvent = new TownEvent();
			int.TryParse(array2[1], out townEvent.id);
			if (townEvent.id < 46 || townEvent.id > 999 || ProfileManager.instance.DLC_ContentEnabled)
			{
				townEvent.Title = array2[2];
				townEvent.EventText = array2[3];
				townEvent.Choice1Text = array2[4];
				int.TryParse(array2[5], out townEvent.Choice1SuccessChance);
				townEvent.Choice1SuccessAction = array2[6];
				int.TryParse(array2[7], out townEvent.Choice1SuccessValue);
				townEvent.Choice1SuccessText = array2[8];
				townEvent.Choice1FailAction = array2[9];
				int.TryParse(array2[10], out townEvent.Choice1FailValue);
				townEvent.Choice1FailText = array2[11];
				townEvent.Choice1StaticAction = array2[12];
				int.TryParse(array2[13], out townEvent.Choice1StaticActionValue);
				townEvent.Choice2Text = array2[14];
				int.TryParse(array2[15], out townEvent.Choice2SuccessChance);
				townEvent.Choice2SuccessAction = array2[16];
				int.TryParse(array2[17], out townEvent.Choice2SuccessValue);
				townEvent.Choice2SuccessText = array2[18];
				townEvent.Choice2FailAction = array2[19];
				int.TryParse(array2[20], out townEvent.Choice2FailValue);
				townEvent.Choice2FailText = array2[21];
				townEvent.Choice2StaticAction = array2[22];
				int.TryParse(array2[23], out townEvent.Choice2StaticActionValue);
				townEvent.Choice3Text = array2[24];
				int.TryParse(array2[25], out townEvent.Choice3SuccessChance);
				townEvent.Choice3SuccessAction = array2[26];
				int.TryParse(array2[27], out townEvent.Choice3SuccessValue);
				townEvent.Choice3SuccessText = array2[28];
				townEvent.Choice3FailAction = array2[29];
				int.TryParse(array2[30], out townEvent.Choice3FailValue);
				townEvent.Choice3FailText = array2[31];
				townEvent.Choice3StaticAction = array2[32];
				int.TryParse(array2[33], out townEvent.Choice3StaticActionValue);
				townEvent.Choice4Text = array2[34];
				int.TryParse(array2[35], out townEvent.Choice4SuccessChance);
				townEvent.Choice4SuccessAction = array2[36];
				int.TryParse(array2[37], out townEvent.Choice4SuccessValue);
				townEvent.Choice4SuccessText = array2[38];
				townEvent.Choice4FailAction = array2[39];
				int.TryParse(array2[40], out townEvent.Choice4FailValue);
				townEvent.Choice4FailText = array2[41];
				townEvent.Choice4StaticAction = array2[42];
				int.TryParse(array2[43], out townEvent.Choice4StaticActionValue);
				townEvent.QuestStaticAction = array2[44];
				int.TryParse(array2[45], out townEvent.QuestStaticActionValue);
				if (townEvent.id >= 2000)
				{
					townEvent.EventPicture = ListOfContinuationEventPictures[townEvent.id - 2000];
					ListOfContinuationEvents.Add(townEvent);
				}
				else if (townEvent.id >= 1000)
				{
					townEvent.EventPicture = ListOfSpecialEventPictures[townEvent.id - 1000];
					ListOfSpecialEvents.Add(townEvent);
				}
				else
				{
					townEvent.EventPicture = ListOfEventPictures[townEvent.id];
					ListOfEvents.Add(townEvent);
				}
			}
		}
	}

