public class DataTablesBattle : MonoBehaviour
{
	public static DataTablesBattle instance;

	public List<Buff> ListOfBuffs = new List<Buff>();

	public List<Buff> ListOfDebuffs = new List<Buff>();

	public List<Buff> ListOfDLCBuffs = new List<Buff>();

	public List<Buff> ListOfDLCDebuffs = new List<Buff>();

	private void Awake()
	{
		if ((Object)(object)instance != (Object)null)
		{
			Object.Destroy((Object)(object)((Component)this).gameObject);
		}
		else
		{
			instance = this;
		}
	}

	public void Start()
	{
		if (ProfileManager.instance.DLC_ContentEnabled)
		{
			ExtraDLCAdjustments();
		}
	}

	public void ExtraDLCAdjustments()
	{
		foreach (Buff listOfDLCBuff in ListOfDLCBuffs)
		{
			ListOfBuffs.Add(listOfDLCBuff);
		}
		foreach (Buff listOfDLCDebuff in ListOfDLCDebuffs)
		{
			ListOfDebuffs.Add(listOfDLCDebuff);
		}
	}

	public Buff GetRandomBuff()
	{
		return ListOfBuffs[Random.Range(0, ListOfBuffs.Count)];
	}

	public Buff GetRandomDebuff()
	{
		return ListOfDebuffs[Random.Range(0, ListOfDebuffs.Count)];
	}
}
