public class RosterDragHandler : MonoBehaviour, IDropHandler, IEventSystemHandler
{
	public void OnDrop(PointerEventData eventData)
	{
		if (!Object.op_Implicit((Object)(object)eventData.pointerDrag.GetComponent<DragHandlerCharacter>()))
		{
			return;
		}
		CharacterTemplate character = eventData.pointerDrag.GetComponent<DragHandlerCharacter>().Character;
		if (!RosterManager.instance.Roster.Contains(character))
		{
			if (RosterManager.instance.IsThereRoom())
			{
				eventData.pointerDrag.GetComponent<DragHandlerCharacter>().OnEndDrag(eventData);
				if ((Object)(object)Trainer.instance.Character == (Object)(object)character)
				{
					Trainer.instance.CharacterRemovedByDragging();
				}
				else
				{
					ProgressManager.instance.RemoveFromTeam(character);
				}
				RosterManager.instance.AddToRoster(character);
			}
			else
			{
				UIManager.instance.ShowErrorMessage(LocalizationManager.GetTranslation("MESSAGE/MESSAGE_rosterfull"));
			}
		}
		else
		{
			Debug.Log((object)"Roster: Duplicate character!?");
		}
	}
}
public class TeamDragHandler : MonoBehaviour, IDropHandler, IEventSystemHandler
{
	public void OnDrop(PointerEventData eventData)
	{
		if (!Object.op_Implicit((Object)(object)eventData.pointerDrag.GetComponent<DragHandlerCharacter>()))
		{
			return;
		}
		CharacterTemplate character = eventData.pointerDrag.GetComponent<DragHandlerCharacter>().Character;
		if (!ProgressManager.instance.Team.Contains(character))
		{
			if ((Object)(object)ProgressManager.instance.Team[((Component)this).transform.GetSiblingIndex()] != (Object)null)
			{
				CharacterTemplate characterTemplate = ProgressManager.instance.Team[((Component)this).transform.GetSiblingIndex()];
				if ((Object)(object)Trainer.instance.Character == (Object)(object)character)
				{
					eventData.pointerDrag.GetComponent<DragHandlerCharacter>().OnEndDrag(eventData);
					Trainer.instance.CharacterRemovedByDragging();
					ProgressManager.instance.RemoveFromTeam(characterTemplate);
					ProgressManager.instance.AddToTeam(character, ((Component)this).transform.GetSiblingIndex());
					Trainer.instance.AddCharacterToSeat(characterTemplate);
				}
				else
				{
					eventData.pointerDrag.GetComponent<DragHandlerCharacter>().OnEndDrag(eventData);
					RosterManager.instance.RemoveFromRoster(character);
					RosterManager.instance.AddToRoster(characterTemplate);
					ProgressManager.instance.RemoveFromTeam(characterTemplate);
					ProgressManager.instance.AddToTeam(character, ((Component)this).transform.GetSiblingIndex());
				}
			}
			else
			{
				eventData.pointerDrag.GetComponent<DragHandlerCharacter>().OnEndDrag(eventData);
				if ((Object)(object)Trainer.instance.Character == (Object)(object)character)
				{
					Trainer.instance.CharacterRemovedByDragging();
				}
				else
				{
					RosterManager.instance.RemoveFromRoster(eventData.pointerDrag.GetComponent<DragHandlerCharacter>().Character);
				}
				ProgressManager.instance.AddToTeam(character, ((Component)this).transform.GetSiblingIndex());
			}
		}
		else if ((Object)(object)ProgressManager.instance.Team[((Component)this).transform.GetSiblingIndex()] != (Object)(object)character)
		{
			eventData.pointerDrag.GetComponent<DragHandlerCharacter>().OnEndDrag(eventData);
			ProgressManager.instance.SwitchSlotsWithinTeam(character, ((Component)this).transform.GetSiblingIndex());
		}
	}
}
public class TrainDragHandler : MonoBehaviour, IDropHandler, IEventSystemHandler
{
	public void OnDrop(PointerEventData eventData)
	{
		if (!Object.op_Implicit((Object)(object)eventData.pointerDrag.GetComponent<DragHandlerCharacter>()))
		{
			return;
		}
		CharacterTemplate character = eventData.pointerDrag.GetComponent<DragHandlerCharacter>().Character;
		if ((Object)(object)Trainer.instance.Character == (Object)null)
		{
			eventData.pointerDrag.GetComponent<DragHandlerCharacter>().OnEndDrag(eventData);
			if (ProgressManager.instance.Team.Contains(character))
			{
				ProgressManager.instance.RemoveFromTeam(character);
			}
			else
			{
				RosterManager.instance.RemoveFromRoster(character);
			}
			Trainer.instance.AddCharacterToSeat(character);
			return;
		}
		eventData.pointerDrag.GetComponent<DragHandlerCharacter>().OnEndDrag(eventData);
		if (!((Object)(object)Trainer.instance.Character == (Object)(object)character))
		{
			if (ProgressManager.instance.Team.Contains(character))
			{
				ProgressManager.instance.RemoveFromTeam(character);
				ProgressManager.instance.AddToTeam(Trainer.instance.Character);
				Trainer.instance.AddCharacterToSeat(character);
			}
			else
			{
				RosterManager.instance.RemoveFromRoster(character);
				RosterManager.instance.AddToRoster(Trainer.instance.Character);
				Trainer.instance.AddCharacterToSeat(character);
			}
		}
	}
}
