			if (Controller == UnitController.Player)
			{
				CharacterBattleBar.HighlightBar();
			}
			((Behaviour)Animator).enabled = true;
			if (ProfileManager.instance.TurnIndicatorsEnabled)
			{
				TurnSelectorAnimator.ResetTrigger("Deactivate");
				if (!Object.op_Implicit((Object)(object)AI))
				{
					TurnSelectorAnimator.SetTrigger("Activate");
				}
				else
				{
					TurnSelectorAnimator.SetTrigger("ActivateEnemy");
				}
			}
			maxMoves = ThisCharacter.MaxAP.GetValue();
			RemainingMoves = maxMoves;
			if (ProgressManager.instance.CareerSpecialRule == "Spirit of the Hare")
			{
				RemainingMoves += 2;
			}
			SkillController.instance.CreateSkills(this);
			ActionCooldown = false;
			AttackCooldown = false;
			CharacterState = CharacterStates.BEFOREMOVE;
			break;
		case CharacterStates.BEFOREMOVE:
			if ((float)Mathf.CeilToInt(((Component)this).transform.position.x) - 0.5f != ((Component)this).transform.position.x || (float)Mathf.CeilToInt(((Component)this).transform.position.y) - 0.5f != ((Component)this).transform.position.y)
			{
				Debug.LogError((object)("EB (BeforeMove): UNIT OFF GRID!! " + ThisCharacter.Charname + " " + ((Component)this).transform.position.x + " : " + ((Component)this).transform.position.y));
				SnapToGrid();
			}
			((Component)this).gameObject.GetComponent<Renderer>().sortingOrder = Mathf.Abs(Mathf.RoundToInt(((Component)this).transform.position.y - 0.5f));
			if (Controller == UnitController.AI)
			{
				BattleProcessor.instance.BlockArrows();
			}
			else
			{
				BattleProcessor.instance.CheckArrows();
			}
			UpdateAPCounter();
			CharacterState = CharacterStates.MOVE;
			break;
		case CharacterStates.MOVE:
			WaitForMoveCommand();
			break;
		case CharacterStates.ENDTURN:
			if (BattleProcessor.instance.TurnHasRemainingTasks.Count <= 0)
			{
				if ((float)Mathf.CeilToInt(((Component)this).transform.position.x) - 0.5f != ((Component)this).transform.position.x || (float)Mathf.CeilToInt(((Component)this).transform.position.y) - 0.5f != ((Component)this).transform.position.y)
				{
					Debug.LogError((object)("EB (BeforeMove): UNIT OFF GRID!! " + ThisCharacter.Charname + " " + ((Component)this).transform.position.x + " : " + ((Component)this).transform.position.y));
					SnapToGrid();
				}
				if (!Object.op_Implicit((Object)(object)AI))
				{
					DamageEstimator.instance.ClearEstimates();
				}
				ActionCooldown = true;
				if (!Object.op_Implicit((Object)(object)AI) && !KilledSomethingThisTurn)
				{
					BattleProcessor.instance.KillStreak = 0;
				}
				if (ProgressManager.instance.EmpDemand == "Snail pace" && !Object.op_Implicit((Object)(object)AI) && MovesTaken > 1)
				{
					BattleProcessor.instance.isEmperorAnnoyed = true;
				}
				if (!Object.op_Implicit((Object)(object)AI) && MovesTaken >= 10)
				{
					SteamAchievements.instance.UnlockSteamAchievement("ACH_Bunny");
				}
				UpdateAPCounter();
				DecreaseCooldowns();
				CheckBuffs(StartOfTurn: false);
				((Behaviour)Animator).enabled = false;
				if (Controller == UnitController.Player)
				{
					CharacterBattleBar.RemoveHighlight();
				}
				if (ProfileManager.instance.TurnIndicatorsEnabled)
				{
					TurnSelectorAnimator.SetTrigger("Deactivate");
				}
				if (LogEntryThisTurn)
				{
					CombatLog.instance.SeparateLines();
				}
				BattleProcessor.instance.battleStates = BattleProcessor.PerformAction.TURNEND;
				if (Controller != UnitController.AI)
				{
					SkillController.instance.ClearSkills();
				}
				CharacterState = CharacterStates.WAIT;
			}
			break;
		case CharacterStates.DYING:
			if ((Object)(object)this == (Object)(object)BattleProcessor.instance.CurrentCharacter)
			{
				if (!Object.op_Implicit((Object)(object)AI))
				{
					DamageEstimator.instance.ClearEstimates();
				}
				if (Controller == UnitController.Player)
				{
					CharacterBattleBar.RemoveHighlight();
				}
				if (ProfileManager.instance.TurnIndicatorsEnabled)
				{
					TurnSelectorAnimator.SetTrigger("Deactivate");
				}
				if (Controller != UnitController.AI)
				{
					SkillController.instance.ClearSkills();
				}
			}
			((Component)((Component)this).transform.Find("TeamIndicator")).gameObject.SetActive(false);
			((Behaviour)Animator).enabled = true;
			Animator.SetBool("Death", true);
			CharacterBattleBar.CharIsDead(DeathType);
			((Renderer)((Component)this).GetComponent<SpriteRenderer>()).sortingOrder = -1;
			CharacterState = CharacterStates.DEAD;
			if ((Object)(object)BattleProcessor.instance.CurrentCharacter == (Object)(object)this)
			{
				if (LogEntryThisTurn)
				{
					CombatLog.instance.SeparateLines();
				}
				BattleProcessor.instance.battleStates = BattleProcessor.PerformAction.TURNEND;
			}
			break;
		case CharacterStates.WAIT:
		case CharacterStates.DEAD:
			break;
		}
	}

