	public void ActivateBuff(Buff buff)
	{
		string text = "";
		switch (buff.BuffType)
		{
		case "Protection":
			break;
		case "BuffSTR":
			ThisCharacter.STR.AddBuffModifier(buff.BuffValue);
			ThisCharacter.UpdateSecondaryStats();
			break;
		case "BuffAGI":
			ThisCharacter.AGI.AddBuffModifier(buff.BuffValue);
			ThisCharacter.UpdateSecondaryStats();
			break;
		case "BuffWIS":
			ThisCharacter.WIS.AddBuffModifier(buff.BuffValue);
			ThisCharacter.UpdateSecondaryStats();
			break;
		case "BuffVIT":
			ThisCharacter.VIT.AddBuffModifier(buff.BuffValue);
			ThisCharacter.UpdateSecondaryStats();
			break;
		case "BuffARM":
			ThisCharacter.ARMOR.AddBuffModifier(buff.BuffValue);
			ThisCharacter.UpdateSecondaryStats();
			break;
		case "BuffPDMG":
			ThisCharacter.PhysicalDamage.AddBuffModifier(buff.BuffValue);
			break;
		case "BuffKB":
			ThisCharacter.KnockbackChance.AddBuffModifier(buff.BuffValue);
			break;
		case "BuffCrit":
			ThisCharacter.CritChance.AddBuffModifier(buff.BuffValue);
			break;
		case "BuffDodge":
			ThisCharacter.DodgeChance.AddBuffModifier(buff.BuffValue);
			break;
		case "DodgePenalty":
			ThisCharacter.DodgeChance.AddBuffModifier(-20);
			dodgePenalty += 20;
			break;
		case "BuffAP":
			if (buff.title == "Slowed")
			{
				ThisCharacter.DodgeChance.AddBuffModifier(-10);
			}
			if (ThisCharacter.MaxAP.GetValue() == 1 && buff.BuffValue == -1)
			{
				buff.BuffValue = 0;
			}
			ThisCharacter.MaxAP.AddBuffModifier(buff.BuffValue);
			if ((Object)(object)BattleProcessor.instance.CurrentCharacter == (Object)(object)this)
			{
				RemainingMoves += buff.BuffValue;
				UpdateAPCounter();
			}
			break;
		case "ExhaustAP":
			ThisCharacter.MaxAP.AddBuffModifier((ThisCharacter.MaxAP.GetValue() - 1) * -1);
			ThisCharacter.DodgeChance.AddBuffModifier(-20);
			break;
		case "BuffMP":
			ThisCharacter.MP.AddBuffModifier(buff.BuffValue);
			break;
		case "BuffMDMG":
			ThisCharacter.MagicDamage.AddBuffModifier(buff.BuffValue);
			break;
		case "BuffMRES":
			ThisCharacter.MagicDefense.AddBuffModifier(buff.BuffValue);
			break;
		case "BuffHP":
			ThisCharacter.HP.AddBuffModifier(buff.BuffValue);
			break;
		case "BuffDRES":
			ThisCharacter.DebuffResistance.AddBuffModifier(buff.BuffValue);
			break;
		case "BuffKBRES":
			ThisCharacter.KnockbackResistance.AddBuffModifier(buff.BuffValue);
			break;
		case "BuffDRESPIERCE":
			ThisCharacter.DebuffChance.AddBuffModifier(buff.BuffValue);
			break;
		case "BuffADMG":
			ThisCharacter.ArcheryDamage.AddBuffModifier(buff.BuffValue);
			break;
		case "DoTFire":
			text = LocalizationManager.GetTranslation("LOG/LOG_burning");
			text = text.Replace("<CHAR>", ThisCharacter.Charname);
			CombatLog.instance.WriteLog("<color=red>" + text + "</color>");
			LogEntryThisTurn = true;
			if (ProgressManager.instance.CareerSpecialRule == "Afflicted")
			{
				TakeDamage(Mathf.CeilToInt((float)(ThisCharacter.HP.GetValue() * 2 * buff.BuffValue) / 100f), DamageType.piercing, ShowInLog: true, "None", "None", forceanimation: false, debuffdamage: true);
			}
			else
			{
				TakeDamage(Mathf.CeilToInt((float)(ThisCharacter.HP.GetValue() * buff.BuffValue) / 100f), DamageType.piercing, ShowInLog: true, "None", "None", forceanimation: false, debuffdamage: true);
			}
			if (buff.OnApplyAnimation != "")
			{
				BuffAnimator.SetTrigger(buff.OnApplyAnimation);
			}
			if (buff.OnApplySFX != "")
			{
				AudioManager.instance.AudioEffect(buff.OnApplySFX);
			}
			break;
		case "DoTPoison":
			text = LocalizationManager.GetTranslation("LOG/LOG_poison");
			text = text.Replace("<CHAR>", ThisCharacter.Charname);
			CombatLog.instance.WriteLog("<color=red>" + text + "</color>");
			LogEntryThisTurn = true;
			if (ProgressManager.instance.CareerSpecialRule == "Afflicted")
			{
				TakeDamage(Mathf.CeilToInt((float)(ThisCharacter.HP.GetValue() * 2 * buff.BuffValue) / 100f), DamageType.piercing, ShowInLog: true, "None", "None", forceanimation: false, debuffdamage: true);
			}
			else
			{
				TakeDamage(Mathf.CeilToInt((float)(ThisCharacter.HP.GetValue() * buff.BuffValue) / 100f), DamageType.piercing, ShowInLog: true, "None", "None", forceanimation: false, debuffdamage: true);
			}
			if (buff.OnApplyAnimation != "")
			{
				BuffAnimator.SetTrigger(buff.OnApplyAnimation);
			}
			if (buff.OnApplySFX != "")
			{
				AudioManager.instance.AudioEffect(buff.OnApplySFX);
			}
			break;
		case "DoTDecay":
			text = LocalizationManager.GetTranslation("LOG/LOG_decay");
			text = text.Replace("<CHAR>", ThisCharacter.Charname);
			CombatLog.instance.WriteLog("<color=red>" + text + "</color>");
			LogEntryThisTurn = true;
			if (ProgressManager.instance.CareerSpecialRule == "Afflicted")
			{
				TakeDamage(Mathf.CeilToInt((float)(ThisCharacter.HP.GetValue() * 2 * buff.BuffValue) / 100f), DamageType.piercing, ShowInLog: true, "None", "None", forceanimation: false, debuffdamage: true);
			}
			else
			{
				TakeDamage(Mathf.CeilToInt((float)(ThisCharacter.HP.GetValue() * buff.BuffValue) / 100f), DamageType.piercing, ShowInLog: true, "None", "None", forceanimation: false, debuffdamage: true);
			}
			if (buff.OnApplyAnimation != "")
			{
				BuffAnimator.SetTrigger(buff.OnApplyAnimation);
			}
			if (buff.OnApplySFX != "")
			{
				AudioManager.instance.AudioEffect(buff.OnApplySFX);
			}
			break;
		case "DelayedDamageMagic":
			text = LocalizationManager.GetTranslation("LOG/LOG_impendingdoom");
			text = text.Replace("<CHAR>", ThisCharacter.Charname);
			CombatLog.instance.WriteLog("<color=red>" + text + "</color>");
			LogEntryThisTurn = true;
			if (ProgressManager.instance.CareerSpecialRule == "Afflicted")
			{
				TakeDamage(buff.BuffValue * 2, DamageType.magic, ShowInLog: true, "FireBurst", "DarkExtra1", forceanimation: false, debuffdamage: true);
			}
			else
			{
				TakeDamage(buff.BuffValue, DamageType.magic, ShowInLog: true, "FireBurst", "DarkExtra1", forceanimation: false, debuffdamage: true);
			}
			break;
		case "DelayedDamagePhysical":
			text = LocalizationManager.GetTranslation("LOG/LOG_impendingdoom");
			text = text.Replace("<CHAR>", ThisCharacter.Charname);
			CombatLog.instance.WriteLog("<color=red>" + text + "</color>");
			LogEntryThisTurn = true;
			if (ProgressManager.instance.CareerSpecialRule == "Afflicted")
			{
				TakeDamage(buff.BuffValue * 2, DamageType.normal, ShowInLog: true, "LightningBurst12", "DarkExtra1", forceanimation: false, debuffdamage: true);
			}
			else
			{
				TakeDamage(buff.BuffValue, DamageType.normal, ShowInLog: true, "LightningBurst12", "DarkExtra1", forceanimation: false, debuffdamage: true);
			}
			break;
		}
	}

	public void AddDodgePenalty(Buff dodgepenalty)
	{
		foreach (Buff buff2 in Buffs)
		{
			if (buff2.title == dodgepenalty.title)
			{
				buff2.BuffValue += dodgepenalty.BuffValue;
				ThisCharacter.DodgeChance.AddBuffModifier(dodgepenalty.BuffValue);
				dodgePenalty += 20;
				return;
			}
		}
		Buff buff = Object.Instantiate<Buff>(dodgepenalty);
		Buffs.Add(buff);
		CharacterBattleBar.AddBuffIcon(buff);
		ActivateBuff(buff);
		if (!(ProgressManager.instance.EmpDesire == "Ailments") || !Object.op_Implicit((Object)(object)AI))
		{
			return;
		}
		int num = 0;
		foreach (Buff buff3 in Buffs)
		{
			if (!buff3.IsItBuff)
			{
				num++;
			}
		}
		if (num >= 3)
		{
			BattleProcessor.instance.CompleteDesire();
		}
	}

	public void BuffOnApplyActions(Buff buff, bool buffalreadyonchar = false)
	{
		if (buff.OnApplyText != "")
		{
			LogEntryThisTurn = true;
			string translation = LocalizationManager.GetTranslation("BUFF/BUFF_" + buff.title + "_onapply");
			CombatLog.instance.WriteLog(translation.Replace("<unit>", ThisCharacter.Charname));
		}
		if (buff.OnApplyAnimation != "")
		{
			BuffAnimator.SetTrigger(buff.OnApplyAnimation);
		}
		if (buff.OnApplySFX != "")
		{
			AudioManager.instance.AudioEffect(buff.OnApplySFX);
		}
	}

	public void RemoveBuffEffect(Buff buff)
	{
