		{
		case "Protection":
			break;
		case "DelayedDamageMagic":
			break;
		case "DelayedDamagePhysical":
			break;
		case "BuffSTR":
			ThisCharacter.STR.RemoveBuffModifier(buff.BuffValue);
			ThisCharacter.UpdateSecondaryStats();
			break;
		case "BuffAGI":
			ThisCharacter.AGI.RemoveBuffModifier(buff.BuffValue);
			ThisCharacter.UpdateSecondaryStats();
			break;
		case "BuffWIS":
			ThisCharacter.WIS.RemoveBuffModifier(buff.BuffValue);
