			break;
		case "BuffVIT":
			ThisCharacter.VIT.RemoveBuffModifier(buff.BuffValue);
			ThisCharacter.UpdateSecondaryStats();
			break;
		case "BuffARM":
			ThisCharacter.ARMOR.RemoveBuffModifier(buff.BuffValue);
			ThisCharacter.UpdateSecondaryStats();
			break;
		case "BuffPDMG":
			ThisCharacter.PhysicalDamage.RemoveBuffModifier(buff.BuffValue);
			break;
		case "BuffKB":
			ThisCharacter.KnockbackChance.RemoveBuffModifier(buff.BuffValue);
			break;
		case "BuffCrit":
			ThisCharacter.CritChance.RemoveBuffModifier(buff.BuffValue);
			break;
		case "BuffDodge":
			ThisCharacter.DodgeChance.RemoveBuffModifier(buff.BuffValue);
			break;
		case "DodgePenalty":
		{
			int num = dodgePenalty / 20;
			for (int i = 0; i < num; i++)
			{
				ThisCharacter.DodgeChance.RemoveBuffModifier(-20);
			}
			dodgePenalty = 0;
			break;
		}
		case "BuffAP":
			ThisCharacter.MaxAP.RemoveBuffModifier(buff.BuffValue);
			if (buff.title == "Slowed")
			{
				ThisCharacter.DodgeChance.RemoveBuffModifier(-10);
			}
			break;
		case "ExhaustAP":
			ThisCharacter.MaxAP.RemoveNegativeBuffModifiers();
			ThisCharacter.DodgeChance.RemoveBuffModifier(-20);
			break;
		case "BuffMP":
			ThisCharacter.MP.RemoveBuffModifier(buff.BuffValue);
			break;
		case "BuffMDMG":
			ThisCharacter.MagicDamage.RemoveBuffModifier(buff.BuffValue);
			break;
		case "BuffMRES":
			ThisCharacter.MagicDefense.RemoveBuffModifier(buff.BuffValue);
			break;
		case "BuffHP":
			ThisCharacter.HP.RemoveBuffModifier(buff.BuffValue);
			break;
		case "BuffDRES":
			ThisCharacter.DebuffResistance.RemoveBuffModifier(buff.BuffValue);
			break;
		case "BuffKBRES":
			ThisCharacter.KnockbackResistance.RemoveBuffModifier(buff.BuffValue);
			break;
		case "BuffDRESPIERCE":
			ThisCharacter.DebuffChance.RemoveBuffModifier(buff.BuffValue);
			break;
		case "BuffADMG":
			ThisCharacter.ArcheryDamage.RemoveBuffModifier(buff.BuffValue);
			break;
		}
	}

	public void TryToAddBuff(Buff buff, int initialchance, bool NoDmg = false, bool ApplierIsAI = false)
	{
		//IL_01fc: Unknown result type (might be due to invalid IL or missing references)
		//IL_0163: Unknown result type (might be due to invalid IL or missing references)
		string text = "";
		if (!buff.IsItBuff && Random.Range(0, 100) >= initialchance - ThisCharacter.DebuffResistance.GetValue())
		{
			if (NoDmg)
			{
				((MonoBehaviour)this).StartCoroutine(GotHit("BlockMagic"));
				AudioManager.instance.AudioEffect("BlockMagic");
			}
			text = LocalizationManager.GetTranslation("LOG/LOG_resisteffect");
			text = text.Replace("<CHAR>", ThisCharacter.Charname);
			CombatLog.instance.WriteLog("<color=#725407>" + text + "</color>");
			LogEntryThisTurn = true;
			return;
		}
		foreach (Buff buff3 in Buffs)
		{
			if (buff3.title == buff.title)
			{
				if (buff.BuffType == "DelayedDamageMagic" || buff.BuffType == "DelayedDamagePhysical")
				{
					BuffAnimator.SetTrigger(buff.OnApplyAnimation);
					AudioManager.instance.AudioEffect(buff.OnApplySFX);
				}
				else
				{
					buff3.Duration = Mathf.Clamp(buff3.Duration + buff.Duration, 0, 99);
					BuffOnApplyActions(buff, buffalreadyonchar: true);
					((MonoBehaviour)this).StartCoroutine(FloatingCombatText.instance.NewFloatingText(LocalizationManager.GetTranslation("BUFF/BUFF_" + buff.title), "buff", ((Component)this).transform.position, ((Component)this).gameObject));
				}
				return;
			}
		}
		Buff buff2 = Object.Instantiate<Buff>(buff);
		Buffs.Add(buff2);
		CharacterBattleBar.AddBuffIcon(buff2);
		BuffOnApplyActions(buff2);
		if (buff.Activation == Buff.ActivationType.Once)
		{
			ActivateBuff(buff2);
		}
		((MonoBehaviour)this).StartCoroutine(FloatingCombatText.instance.NewFloatingText(LocalizationManager.GetTranslation("BUFF/BUFF_" + buff2.title), "buff", ((Component)this).transform.position, ((Component)this).gameObject));
		if (ProgressManager.instance.EmpDemand == "Honest fight" && Object.op_Implicit((Object)(object)AI) && !buff.IsItBuff && !ApplierIsAI)
		{
			BattleProcessor.instance.isEmperorAnnoyed = true;
		}
		if (ProgressManager.instance.EmpDemand == "Fair fight" && !Object.op_Implicit((Object)(object)AI) && buff.IsItBuff && !ApplierIsAI)
		{
			BattleProcessor.instance.isEmperorAnnoyed = true;
		}
		if (ProgressManager.instance.EmpDesire == "Enhancements" && !Object.op_Implicit((Object)(object)AI))
		{
			int num = 0;
			foreach (Buff buff4 in Buffs)
			{
				if (buff4.IsItBuff)
				{
					num++;
				}
			}
			if (num >= 3)
			{
				BattleProcessor.instance.CompleteDesire();
			}
		}
		if (!(ProgressManager.instance.EmpDesire == "Ailments") || !Object.op_Implicit((Object)(object)AI))
		{
			return;
		}
		int num2 = 0;
		foreach (Buff buff5 in Buffs)
		{
			if (!buff5.IsItBuff)
			{
				num2++;
			}
		}
		if (num2 >= 3)
		{
			BattleProcessor.instance.CompleteDesire();
		}
	}

	public void CheckBuffs(bool StartOfTurn)
	{
		if (Buffs.Count == 0)
		{
			return;
		}
		List<Buff> list = new List<Buff>();
		foreach (Buff buff in Buffs)
		{
			if ((buff.Activation == Buff.ActivationType.EveryTurn) & StartOfTurn)
			{
				ActivateBuff(buff);
				buff.Duration--;
			}
			else if ((buff.Activation == Buff.ActivationType.UponExpiry) & StartOfTurn)
			{
				buff.Duration--;
			}
			else if (buff.Activation == Buff.ActivationType.Once && !StartOfTurn)
			{
				buff.Duration--;
			}
			if (buff.Duration <= 0)
			{
				if (buff.Activation == Buff.ActivationType.Once && !StartOfTurn)
				{
					RemoveBuffEffect(buff);
					list.Add(buff);
				}
				else if (buff.Activation == Buff.ActivationType.UponExpiry)
				{
					ActivateBuff(buff);
					list.Add(buff);
				}
				else if (buff.Activation == Buff.ActivationType.EveryTurn)
				{
					list.Add(buff);
				}
			}
		}
		if (list.Count > 0)
		{
			foreach (Buff item in list)
			{
				Buffs.Remove(item);
			}
		}
		CharacterBattleBar.RecheckBuffs();
	}

	public int RemoveAllBuffs()
	{
		int num = 0;
		List<Buff> list = new List<Buff>();
		foreach (Buff buff in Buffs)
		{
			list.Add(buff);
			num++;
			if (buff.Activation == Buff.ActivationType.Once)
			{
				RemoveBuffEffect(buff);
			}
		}
		if (list.Count > 0)
		{
			foreach (Buff item in list)
			{
				Buffs.Remove(item);
			}
		}
		return num;
	}

	public bool TryToMove(Vector3 OldPosition, Vector3 NewPosition)
	{
		//IL_0012: Unknown result type (might be due to invalid IL or missing references)
		//IL_0024: Unknown result type (might be due to invalid IL or missing references)
		//IL_0056: Unknown result type (might be due to invalid IL or missing references)
		//IL_0067: Unknown result type (might be due to invalid IL or missing references)
		//IL_007a: Unknown result type (might be due to invalid IL or missing references)
		//IL_008c: Unknown result type (might be due to invalid IL or missing references)
		//IL_00a3: Unknown result type (might be due to invalid IL or missing references)
		//IL_00ad: Unknown result type (might be due to invalid IL or missing references)
		//IL_002c: Unknown result type (might be due to invalid IL or missing references)
		//IL_003e: Unknown result type (might be due to invalid IL or missing references)
		//IL_00c7: Unknown result type (might be due to invalid IL or missing references)
		//IL_00d7: Unknown result type (might be due to invalid IL or missing references)
		//IL_0124: Unknown result type (might be due to invalid IL or missing references)
		if (ActionCooldown || AttackCooldown)
		{
			return false;
		}
		if ((float)Mathf.CeilToInt(NewPosition.x) - 0.5f != NewPosition.x || (float)Mathf.CeilToInt(NewPosition.y) - 0.5f != NewPosition.y)
		{
			Debug.LogError((object)string.Concat("EB (TryToMove): TRYING TO MOVE TO UNAUTHORIZED SPOT. OLD: ", OldPosition, " ||| NEW: ", NewPosition));
			NewPosition = new Vector3((float)Mathf.CeilToInt(NewPosition.x) - 0.5f, (float)Mathf.CeilToInt(NewPosition.y) - 0.5f, 0f);
			Debug.Log((object)("Corrected move location: " + NewPosition));
		}
		if (BattleProcessor.instance.tileWorldLocations.Contains(NewPosition))
		{
			return false;
		}
		OccupiedOrNot = BattleProcessor.instance.IsTileOccupied(NewPosition);
		if ((Object)(object)OccupiedOrNot != (Object)null)
		{
			if (OccupiedOrNot.tag == ((Component)this).tag)
			{
				return false;
			}
			MeleeAttack(OccupiedOrNot);
			return true;
		}
		SkillController.instance.DeactivateTargeting();
		((MonoBehaviour)this).StartCoroutine(Moving(NewPosition));
		if (ProgressManager.instance.CareerSpecialRule == "Sluggishness")
		{
			RemainingMoves = 0;
		}
		else
		{
			RemainingMoves--;
		}
		MovesTaken++;
		if (MovesTaken >= 6 && !Object.op_Implicit((Object)(object)AI) && ProgressManager.instance.EmpDesire == "Sprinting")
		{
			BattleProcessor.instance.CompleteDesire();
		}
		CharacterState = CharacterStates.WAIT;
		return true;
	}

