	public void MeleeAttack(GameObject EnemyInTile)
	{
		if (!ActionCooldown)
		{
			SkillController.instance.DeactivateTargeting();
			LogEntryThisTurn = true;
			BattleProcessor.instance.TurnHasRemainingTasks.Add(1);
			RemainingMoves -= MeleeConsumesMoves;
			AttackDetails attackDetails = new AttackDetails();
			attackDetails.AttackerObject = ((Component)this).gameObject;
			attackDetails.TargetObject = EnemyInTile;
			attackDetails.Skill = SkillType.Melee;
			attackDetails.ShowInLog = 1;
			BattleProcessor.instance.HandleAttack(attackDetails);
			BattleProcessor.instance.TurnHasRemainingTasks.Remove(1);
		}
	}

	public IEnumerator AttackAnimation(AttackDetails Attack)
	{
		if (!AttackStarted)
		{
			ActionCooldown = true;
			BattleProcessor.instance.TurnHasRemainingTasks.Add(1);
			AttackStarted = true;
			Vector3 startpos = ((Component)this).transform.position;
			Vector3 attackpos = (startpos + Attack.TargetObject.transform.position) / 2f;
			while (MoveTowardsSomething(attackpos, attackSpeed))
			{
				yield return null;
			}
			yield return (object)new WaitForSeconds(0.2f);
			while (MoveTowardsSomething(startpos, attackSpeed / 2f))
			{
				yield return null;
			}
			if (RemainingMoves > 0)
			{
				BattleProcessor.instance.CheckArrows();
			}
			AttackStarted = false;
			BattleProcessor.instance.TurnHasRemainingTasks.Remove(1);
			ActionCooldown = false;
		}
	}

	public IEnumerator GotHit(string Type)
	{
		if (!ActionStarted)
		{
			ActionStarted = true;
			HitEffectAnimator.SetTrigger(Type);
			ActionStarted = false;
		}
		yield break;
	}

	public IEnumerator PlayEffect(string Type)
	{
		if (!EffectStarted)
		{
			EffectStarted = true;
			if (Type == "Crit")
			{
				HitEffectAnimator.SetTrigger("Crit");
				AudioManager.instance.AudioEffect("Critical");
			}
			EffectStarted = false;
		}
		yield break;
	}

	public IEnumerator Charge(AttackDetails Attack, bool knockback = false, bool damage = true, float damagescaling = 0f)
	{
		if (ChargeStarted)
		{
			yield break;
		}
		ActionCooldown = true;
		BattleProcessor.instance.TurnHasRemainingTasks.Add(1);
		ChargeStarted = true;
		Vector3 dir = Attack.AttackerObject.transform.position - Attack.TargetObject.transform.position;
		dir.Normalize();
		while (MoveTowardsSomething(Attack.TargetObject.transform.position + dir, chargeSpeed))
		{
			yield return null;
		}
		if (damage)
		{
			AttackDetails attackDetails = new AttackDetails();
			attackDetails.AttackerObject = ((Component)this).gameObject;
			attackDetails.TargetObject = Attack.TargetObject;
			if (knockback)
			{
				if (damagescaling > 0f)
				{
					attackDetails.Skill = SkillType.ChargeKnockbackContScaling;
				}
				else
				{
					attackDetails.Skill = SkillType.ChargeKnockbackCont;
				}
			}
			else if (damagescaling > 0f)
			{
				attackDetails.Skill = SkillType.ChargeContScaling;
			}
			else
			{
				attackDetails.Skill = SkillType.ChargeCont;
			}
			attackDetails.SpecialVariable = damagescaling;
			attackDetails.SkillNumberVariable = Attack.SkillNumberVariable;
			attackDetails.ExtraDamage = Attack.ExtraDamage;
			attackDetails.DamageType = Attack.DamageType;
			attackDetails.ShowInLog = 0;
			BattleProcessor.instance.HandleAttack(attackDetails);
		}
		if (RemainingMoves > 0)
		{
			BattleProcessor.instance.CheckArrows();
		}
		ChargeStarted = false;
		BattleProcessor.instance.TurnHasRemainingTasks.Remove(1);
		ActionCooldown = false;
	}

