			{
				knockbackSpeed = 28f;
			}
			else if (howFar > 4)
			{
				knockbackSpeed = 23f;
			}
			else if (howFar > 2)
			{
				knockbackSpeed = 18f;
			}
			else if (howFar > 1)
			{
				knockbackSpeed = 13f;
			}
			else
			{
				knockbackSpeed = 8f;
			}
			int KBExtraDamage = 0;
			Vector3 startpos = TargetPosition;
			Vector3 dir = AttackerPosition - TargetPosition;
			if (Mathf.Abs(dir.x) > 1f || Math.Abs(dir.y) > 1f)
			{
				dir.Normalize();
			}
			KnockbackCollisionType KnockbackCollision = KnockbackCollisionType.NULL;
			AttackDetails KnockbackCollateralDamage = null;
			AttackDetails KnockbackCollateralDamage2 = null;
			for (int i = 1; i <= howFar; i++)
			{
				if (BattleProcessor.instance.tileWorldLocations.Contains(startpos - dir * (float)i))
				{
					KnockbackCollision = KnockbackCollisionType.WALL;
					KBExtraDamage = howFar - i + 1;
					howFar = i - 1;
					KnockbackCollateralDamage = new AttackDetails
					{
						AttackerObject = ((Component)this).gameObject,
						TargetObject = ((Component)this).gameObject,
						Skill = SkillType.Environmental,
						DamageType = DamageType.collision,
						ExtraDamage = KBExtraDamage * KnockbackDamageModifier,
						ShowInLog = 0,
						HitAnimation = "none"
					};
					break;
				}
				OccupiedOrNot = BattleProcessor.instance.IsTileOccupied(startpos - dir * (float)i);
				if ((Object)(object)OccupiedOrNot != (Object)null)
				{
					KnockbackCollision = KnockbackCollisionType.UNIT;
					KBExtraDamage = howFar - i + 1;
					howFar = i - 1;
					KnockbackCollateralDamage = new AttackDetails
					{
						AttackerObject = ((Component)this).gameObject,
						TargetObject = ((Component)this).gameObject,
						Skill = SkillType.Environmental,
						DamageType = DamageType.collision,
						ExtraDamage = KBExtraDamage * KnockbackDamageModifier,
						ShowInLog = 0,
						HitAnimation = "none"
					};
					KnockbackCollateralDamage2 = new AttackDetails
					{
						AttackerObject = ((Component)this).gameObject,
						TargetObject = OccupiedOrNot,
						Skill = SkillType.Environmental,
						DamageType = DamageType.collision,
						ExtraDamage = KBExtraDamage * KnockbackDamageModifier,
						ShowInLog = 0,
						HitAnimation = "none"
					};
					if (ProgressManager.instance.EmpDesire == "Collateral damage" && Object.op_Implicit((Object)(object)AI))
					{
						BattleProcessor.instance.CompleteDesire();
					}
					break;
				}
			}
			if (howFar > 0)
			{
				AudioManager.instance.AudioEffect("Knockback");
			}
			while (MoveTowardsSomething(startpos - dir * (float)howFar, knockbackSpeed))
			{
				yield return null;
			}
			if (ProgressManager.instance.EmpDesire == "Assisted flight" && Object.op_Implicit((Object)(object)AI) && howFar >= 3)
			{
				BattleProcessor.instance.CompleteDesire();
			}
			if (Object.op_Implicit((Object)(object)AI) & (howFar >= 10))
			{
				SteamAchievements.instance.UnlockSteamAchievement("ACH_BigKB");
			}
			if (KBExtraDamage > 3)
			{
				AudioManager.instance.AudioEffect("ImpactBig");
			}
			else if (KBExtraDamage > 1)
			{
				AudioManager.instance.AudioEffect("ImpactMedium");
			}
			else if (KBExtraDamage > 0)
			{
				AudioManager.instance.AudioEffect("ImpactSmall");
			}
			if (KBExtraDamage > 3)
			{
				((MonoBehaviour)this).StartCoroutine(ScreenShake.instance.ShakeScreen(0.3f, 0.5f));
			}
			else if (KBExtraDamage > 1)
			{
				((MonoBehaviour)this).StartCoroutine(ScreenShake.instance.ShakeScreen(0.2f, 0.3f));
			}
			else if (KBExtraDamage == 1)
			{
				((MonoBehaviour)this).StartCoroutine(ScreenShake.instance.ShakeScreen(0.1f, 0.1f));
			}
			yield return (object)new WaitForSeconds(0.05f);
			switch (KnockbackCollision)
			{
			case KnockbackCollisionType.WALL:
				BattleProcessor.instance.HandleAttack(KnockbackCollateralDamage);
				break;
			case KnockbackCollisionType.UNIT:
				BattleProcessor.instance.HandleAttack(KnockbackCollateralDamage);
				yield return (object)new WaitForSeconds(0.05f);
				BattleProcessor.instance.HandleAttack(KnockbackCollateralDamage2);
				break;
			}
			KnockbackStarted = false;
			BattleProcessor.instance.TurnHasRemainingTasks.Remove(1);
		}
	}

