	public int CountEffects(int AllBuffsDebuffs = 1)
	{
		int num = 0;
		foreach (Buff buff in Buffs)
		{
			switch (AllBuffsDebuffs)
			{
			case 1:
				num++;
				continue;
			case 2:
				if (buff.IsItBuff)
				{
					num++;
					continue;
				}
				break;
			}
			if (AllBuffsDebuffs == 3 && !buff.IsItBuff)
			{
				num++;
			}
		}
		return num;
	}

