	public bool TakeDamage(int damage, DamageType DamageType, bool ShowInLog, string HitMarkerType, string HitSFX, bool forceanimation = false, bool debuffdamage = false, bool emperordamage = false, int piercingtype = 0)
	{
		//IL_0362: Unknown result type (might be due to invalid IL or missing references)
		if (ProgressManager.instance.CareerSpecialRule == "Frailty")
		{
			switch (DamageType)
			{
			case DamageType.magic:
			case DamageType.MagicHalfPiercing:
			case DamageType.MagicPiercing:
				DamageType = DamageType.MagicPiercing;
				break;
			case DamageType.normal:
			case DamageType.NormalHalfPiercing:
			case DamageType.NormalPiercing:
				DamageType = DamageType.NormalPiercing;
				break;
			default:
				DamageType = DamageType.piercing;
				break;
			case DamageType.collision:
			case DamageType.NoDamage:
				break;
			}
		}
		string text = "";
		int num = Mathf.Clamp(damage, 0, int.MaxValue);
		switch (DamageType)
		{
		case DamageType.normal:
			damage -= ThisCharacter.ARMOR.GetValue();
			break;
		case DamageType.magic:
			damage -= ThisCharacter.MagicDefense.GetValue();
			break;
		case DamageType.NormalHalfPiercing:
			damage = ((ThisCharacter.ARMOR.GetValue() <= 0) ? (damage - ThisCharacter.ARMOR.GetValue()) : (damage - ThisCharacter.ARMOR.GetValue() / 2));
			DamageType = DamageType.normal;
			break;
		case DamageType.MagicHalfPiercing:
			damage = ((ThisCharacter.MagicDefense.GetValue() <= 0) ? (damage - ThisCharacter.MagicDefense.GetValue()) : (damage - ThisCharacter.MagicDefense.GetValue() / 2));
			DamageType = DamageType.magic;
			break;
		case DamageType.MagicPiercing:
			if (ThisCharacter.MagicDefense.GetValue() < 0)
			{
				damage -= ThisCharacter.MagicDefense.GetValue();
			}
			DamageType = DamageType.piercing;
			break;
		case DamageType.NormalPiercing:
			if (ThisCharacter.ARMOR.GetValue() < 0)
			{
				damage -= ThisCharacter.ARMOR.GetValue();
			}
			DamageType = DamageType.piercing;
			break;
		case DamageType.NoDamage:
			ShowInLog = false;
			damage = 0;
			num = 0;
			break;
		}
		if (num == 0)
		{
			damage = 0;
		}
		damage = Mathf.Clamp(damage, 0, int.MaxValue);
		int num2 = Mathf.Clamp(num - damage, 0, int.MaxValue);
		if (GlobalVariables.instance.BattlePityDamage && damage == 0 && num > 0 && BattleProcessor.instance.CheckRandom(50))
		{
			damage++;
			DamageType = DamageType.scrape;
		}
		if (GlobalVariables.instance.FirstBlood && !BattleProcessor.instance.FirstBlood && damage > 0 && !debuffdamage && !emperordamage)
		{
			damage = Mathf.RoundToInt((float)damage * 1.2f);
		}
		float num3 = 0f;
		foreach (Buff buff in Buffs)
		{
			if (buff.BuffType == "Protection")
			{
				if (num3 > 0f)
				{
					num3 = ((!((float)buff.BuffValue > num3 * 100f)) ? (num3 * (1f + (float)buff.BuffValue / 100f)) : ((float)buff.BuffValue / 100f * (1f + num3)));
				}
				else
				{
					num3 = (float)buff.BuffValue / 100f;
				}
			}
		}
		if (num3 > 0f)
		{
			num3 = Mathf.Clamp(num3, 0f, 1f);
			damage = Mathf.RoundToInt((float)damage * (1f - num3));
		}
		if (ProgressManager.instance.CareerSpecialRule == "Spirit of the Whale")
		{
			damage = Mathf.RoundToInt((float)damage / 2f);
		}
		if (emperordamage)
		{
			damage = Mathf.Clamp(damage, 0, ThisCharacter.CurrentHP - 1);
		}
		if (damage > 0)
		{
			ThisCharacter.CurrentHP -= damage;
			((MonoBehaviour)this).StartCoroutine(FloatingCombatText.instance.NewFloatingText(damage.ToString(), "damage", ((Component)this).transform.position, ((Component)this).gameObject));
		}
		if (DamageType == DamageType.collision && ProgressManager.instance.EmpDesire == "Mortal collision" && ThisCharacter.CurrentHP <= 0)
		{
			BattleProcessor.instance.CompleteDesire();
		}
		if (ShowInLog)
		{
			switch (DamageType)
			{
			case DamageType.piercing:
			case DamageType.collision:
				text = LocalizationManager.GetTranslation("LOG/LOG_takedamage1");
				text = text.Replace("<CHAR>", ThisCharacter.Charname);
				text = text.Replace("<DAMAGE>", "<color=#ff0000ff>" + damage + "</color>");
				text = text.Replace("<DAMAGETYPE>", LocalizationManager.GetTranslation("LOG/LOG_dmgtype_" + DamageType));
				CombatLog.instance.WriteLog(text);
				break;
			default:
				text = LocalizationManager.GetTranslation("LOG/LOG_takedamage2");
				text = text.Replace("<CHAR>", ThisCharacter.Charname);
				text = text.Replace("<DAMAGE>", "<color=#ff0000ff>" + damage + "</color>");
				text = text.Replace("<DAMAGETYPE>", LocalizationManager.GetTranslation("LOG/LOG_dmgtype_" + DamageType));
				text = text.Replace("<BLOCKED>", num2.ToString());
				CombatLog.instance.WriteLog(text);
				break;
			case DamageType.normal:
				text = LocalizationManager.GetTranslation("LOG/LOG_takedamage3");
				text = text.Replace("<CHAR>", ThisCharacter.Charname);
				text = text.Replace("<DAMAGE>", "<color=#ff0000ff>" + damage + "</color>");
				text = text.Replace("<BLOCKED>", num2.ToString());
				CombatLog.instance.WriteLog(text);
				break;
			}
		}
		if (!(HitMarkerType == "None") && !(HitMarkerType == "none"))
		{
			if (HitMarkerType != "" && HitMarkerType != null && damage > 0)
			{
				((MonoBehaviour)this).StartCoroutine(GotHit(HitMarkerType));
			}
			else if (forceanimation)
			{
				((MonoBehaviour)this).StartCoroutine(GotHit(HitMarkerType));
			}
			else if (!ProfileManager.instance.BloodEnabled && damage > 0)
			{
				((MonoBehaviour)this).StartCoroutine(GotHit("NoBlood"));
			}
			else if (damage > 20)
			{
				((MonoBehaviour)this).StartCoroutine(GotHit("MajorHit"));
			}
			else if (damage > 10)
			{
				((MonoBehaviour)this).StartCoroutine(GotHit("ModerateHit"));
			}
			else if (damage > 0)
			{
				((MonoBehaviour)this).StartCoroutine(GotHit("MinorHit"));
			}
			else if (damage <= 0 && DamageType == DamageType.magic)
			{
				((MonoBehaviour)this).StartCoroutine(GotHit("BlockMagic"));
			}
			else if (damage <= 0)
			{
				((MonoBehaviour)this).StartCoroutine(GotHit("Block"));
			}
		}
		if (!(HitSFX == "None") && !(HitSFX == "none"))
		{
			if ((HitSFX == "Charge") | forceanimation)
			{
				AudioManager.instance.AudioEffect(HitSFX);
			}
			else if (HitSFX != "" && HitSFX != null && damage > 0)
			{
				AudioManager.instance.AudioEffect(HitSFX);
			}
			else if (damage > 20)
			{
				AudioManager.instance.AudioEffect("MajorHit");
			}
			else if (damage > 10)
			{
				AudioManager.instance.AudioEffect("ModerateHit");
			}
			else if (damage > 0)
			{
				AudioManager.instance.AudioEffect("MinorHit");
			}
			else if (damage <= 0 && DamageType == DamageType.magic)
			{
				AudioManager.instance.AudioEffect("BlockMagic");
			}
			else if (damage <= 0)
			{
				AudioManager.instance.AudioEffect("Block");
			}
		}
		if (damage == 0)
		{
			return false;
		}
		UpdateBar();
		if (ProgressManager.instance.EmpDesire == "Close call" && !Object.op_Implicit((Object)(object)AI) && ThisCharacter.CurrentHP >= 1 && ThisCharacter.CurrentHP < 4)
		{
			BattleProcessor.instance.CompleteDesire();
		}
		if (CharacterState == CharacterStates.DEAD)
		{
			CharacterBattleBar.RecheckDeathState();
		}
		return true;
	}

