	public float TestDamageScore(int damage, bool PhysicalOrNot)
	{
		damage = ((!PhysicalOrNot) ? (damage - ThisCharacter.MagicDefense.GetValue()) : (damage - ThisCharacter.ARMOR.GetValue()));
		float num = 0f;
		foreach (Buff buff in Buffs)
		{
			if (buff.BuffType == "Protection")
			{
				if (num > 0f)
				{
					num = ((!((float)buff.BuffValue > num * 100f)) ? (num * (1f + (float)buff.BuffValue / 100f)) : ((float)buff.BuffValue / 100f * (1f + num)));
				}
				else
				{
					num = (float)buff.BuffValue / 100f;
				}
			}
		}
		if (num > 0f)
		{
			num = Mathf.Clamp(num, 0f, 1f);
			damage = Mathf.RoundToInt((float)damage * (1f - num));
		}
		damage = Mathf.Clamp(damage, 0, int.MaxValue);
		float num2 = (float)damage / (float)ThisCharacter.HP.GetValue();
		num2 = Mathf.Clamp(num2, 0f, 1f);
		if (num2 < 0.01f)
		{
			num2 = 0.01f;
		}
		if (ThisCharacter.CurrentHP - damage <= 0)
		{
			num2 *= 1.2f;
		}
		return Mathf.Clamp(num2, 0f, float.MaxValue);
	}

	public void DecreaseCooldowns()
	{
		List<Skill> list = new List<Skill>();
		foreach (Skill characterSkill in ThisCharacter.CharacterSkills)
		{
			if (Cooldowns.ContainsKey(characterSkill))
			{
				Cooldowns[characterSkill]--;
			}
		}
		foreach (KeyValuePair<Skill, int> cooldown in Cooldowns)
		{
			if (cooldown.Value <= 0)
			{
				list.Add(cooldown.Key);
			}
		}
		if (list.Count <= 0)
		{
			return;
		}
		foreach (Skill item in list)
		{
			Cooldowns.Remove(item);
		}
	}

	public void UpdateAPCounter()
	{
		if (Controller == UnitController.Player)
		{
			((TMP_Text)BattleProcessor.instance.APCounter).SetText(Mathf.Clamp(RemainingMoves, 0, 99).ToString());
		}
		else
		{
			((TMP_Text)BattleProcessor.instance.APCounter).SetText("-");
		}
	}

	public void UpdateBar()
	{
		CharacterBattleBar.UpdateBar();
	}
}
