	public void AddGearModifiers(CharacterTemplate Character, List<Equipment> EquippedItems)
	{
		foreach (Equipment EquippedItem in EquippedItems)
		{
			Character.STR.AddGearModifier(EquippedItem.STRmodifier);
			Character.AGI.AddGearModifier(EquippedItem.AGImodifier);
			Character.WIS.AddGearModifier(EquippedItem.WISmodifier);
			Character.VIT.AddGearModifier(EquippedItem.VITmodifier);
			Character.ARMOR.AddGearModifier(EquippedItem.ARMORmodifier);
			Character.PhysicalDamage.AddGearModifier(EquippedItem.PhysicalDamagemodifier);
			Character.KnockbackChance.AddGearModifier(EquippedItem.KnockbackChancemodifier);
			Character.CritChance.AddGearModifier(EquippedItem.CritChancemodifier);
			Character.DodgeChance.AddGearModifier(EquippedItem.DodgeChancemodifier);
			Character.MP.AddGearModifier(EquippedItem.MPmodifier);
			Character.MagicDamage.AddGearModifier(EquippedItem.MagicDamagemodifier);
			Character.MagicDefense.AddGearModifier(EquippedItem.MagicDefensemodifier);
			Character.HP.AddGearModifier(EquippedItem.HPmodifier);
			Character.MaxAP.AddGearModifier(EquippedItem.MaxAPmodifier);
			Character.DebuffResistance.AddGearModifier(EquippedItem.DebuffResistancemodifier);
			try
			{
				Character.ArcheryDamage.AddGearModifier(EquippedItem.ArcheryDamagemodifier);
				Character.KnockbackResistance.AddGearModifier(EquippedItem.KnockbackResistancemodifier);
				Character.DebuffChance.AddGearModifier(EquippedItem.DebuffChancemodifier);
			}
			catch (Exception)
			{
			}
			if ((Object)(object)EquippedItem.givesSkill != (Object)null)
			{
				Character.LearnGearSkill(EquippedItem.givesSkill);
			}
			if ((Object)(object)EquippedItem.givesPerk != (Object)null)
			{
				Character.LearnGearPerk(EquippedItem.givesPerk);
			}
		}
		Character.UpdateSecondaryStats();
	}

