		Character.MagicDefense.ClearGearModifiers();
		Character.HP.ClearGearModifiers();
		Character.MaxAP.ClearGearModifiers();
		Character.DebuffResistance.ClearGearModifiers();
		try
		{
			Character.ArcheryDamage.ClearGearModifiers();
			Character.KnockbackResistance.ClearGearModifiers();
			Character.DebuffChance.ClearGearModifiers();
		}
		catch (Exception)
		{
		}
		Character.ClearGearPerks();
		Character.ClearGearSkills();
		Character.UpdateSecondaryStats();
	}

	public void RecheckEquipListOrder()
	{
		int num = 0;
		foreach (CharacterTemplate item in ProgressManager.instance.Team)
		{
			if ((Object)(object)item != (Object)null)
			{
				item.CharacterEquipList = instance.ListOfHeroEquipLists[num];
			}
			num++;
		}
		num = 0;
		if (GlobalVariables.instance.CareerModeActivated)
		{
			int num2 = 1;
			{
				foreach (CareerModeEnemyTeam listOfCareerModeTeam in ProgressManager.instance.ListOfCareerModeTeams)
				{
					num = 0;
					foreach (CharacterTemplate item2 in listOfCareerModeTeam.EnemyTeam)
					{
						if (!((Object)(object)item2 == (Object)null))
						{
							switch (num2)
							{
							case 1:
								item2.CharacterEquipList = ListOfCareerTeam1EnemyEquipLists[num];
								break;
							case 2:
								item2.CharacterEquipList = ListOfCareerTeam2EnemyEquipLists[num];
								break;
							case 3:
								item2.CharacterEquipList = ListOfCareerTeam3EnemyEquipLists[num];
								break;
							}
							num++;
						}
					}
					num2++;
				}
				return;
			}
		}
		foreach (CharacterTemplate item3 in ProgressManager.instance.EnemyTeam)
		{
			if ((Object)(object)item3 != (Object)null)
			{
				item3.CharacterEquipList = instance.ListOfEnemyEquipLists[num];
			}
			num++;
		}
	}

	public void RecalculateTeamModifiers()
	{
		foreach (CharacterTemplate item in ProgressManager.instance.Team)
		{
			if ((Object)(object)item != (Object)null)
			{
				RemoveGearModifiers(item);
			}
		}
		int num = 0;
		foreach (CharacterTemplate item2 in ProgressManager.instance.Team)
		{
			if ((Object)(object)item2 != (Object)null)
			{
				AddGearModifiers(item2, ListOfHeroEquipLists[num]);
				item2.UpdateHPMP();
			}
			num++;
		}
	}

	public void RecalculateEnemyModifiers()
	{
		if (GlobalVariables.instance.CareerModeActivated)
		{
			foreach (CareerModeEnemyTeam listOfCareerModeTeam in ProgressManager.instance.ListOfCareerModeTeams)
			{
				foreach (CharacterTemplate item in listOfCareerModeTeam.EnemyTeam)
				{
					if ((Object)(object)item != (Object)null)
					{
						RemoveGearModifiers(item);
					}
				}
				int num = 0;
				foreach (CharacterTemplate item2 in listOfCareerModeTeam.EnemyTeam)
				{
					if ((Object)(object)item2 != (Object)null)
					{
						AddGearModifiers(item2, item2.CharacterEquipList);
						item2.UpdateHPMP();
					}
					num++;
				}
			}
			return;
		}
		foreach (CharacterTemplate item3 in ProgressManager.instance.EnemyTeam)
		{
			if ((Object)(object)item3 != (Object)null)
			{
				RemoveGearModifiers(item3);
			}
		}
		int num2 = 0;
		foreach (CharacterTemplate item4 in ProgressManager.instance.EnemyTeam)
		{
			if ((Object)(object)item4 != (Object)null)
			{
				AddGearModifiers(item4, ListOfEnemyEquipLists[num2]);
				item4.UpdateHPMP();
			}
			num2++;
		}
	}

	public void RecheckGear()
	{
		//IL_0054: Unknown result type (might be due to invalid IL or missing references)
		//IL_005a: Expected Obj, but got Unknown
		Hero1Equipment.Clear();
		Hero2Equipment.Clear();
		Hero3Equipment.Clear();
		Hero4Equipment.Clear();
		int num = 0;
		foreach (Transform characterEquipBar in CharacterEquipBars)
		{
			foreach (Transform item2 in characterEquipBar)
			{
				Transform val = item2;
				if (val.childCount > 1)
				{
					Equipment item = ((Component)val.GetChild(1)).GetComponent<ItemDetails>().containeditem as Equipment;
					ListOfHeroEquipLists[num].Add(item);
					((Component)val.GetChild(0)).GetComponent<CanvasGroup>().alpha = 0f;
				}
				else
				{
					((Component)val.GetChild(0)).GetComponent<CanvasGroup>().alpha = 1f;
				}
			}
			num++;
		}
		RecalculateTeamModifiers();
	}

	public void DestroyUnitGear(int index)
	{
		ListOfHeroEquipLists[index].Clear();
	}

	public void RedrawGear()
	{
		//IL_0023: Unknown result type (might be due to invalid IL or missing references)
		//IL_0029: Expected Obj, but got Unknown
		foreach (Transform characterEquipBar in CharacterEquipBars)
		{
			foreach (Transform item in characterEquipBar)
			{
				Transform val = item;
				if (val.childCount > 1)
				{
					Debug.Log((object)"RedrawGear destroyed something - usually this is not needed");
					Object.Destroy((Object)(object)((Component)val.GetChild(1)).gameObject);
				}
			}
		}
		int num = 0;
		foreach (List<Equipment> listOfHeroEquipList in ListOfHeroEquipLists)
		{
			foreach (Equipment item2 in listOfHeroEquipList)
			{
				GameObject val2 = Object.Instantiate<GameObject>(EquipmentTemplate);
				val2.GetComponent<ItemDetails>().containeditem = item2;
				switch (item2.equipSlot)
				{
				case EquipmentSlot.Weapon:
					val2.transform.SetParent(CharacterEquipBars[num].GetChild(0), false);
					break;
				case EquipmentSlot.Chest:
					val2.transform.SetParent(CharacterEquipBars[num].GetChild(1), false);
					break;
				case EquipmentSlot.Accessory:
					val2.transform.SetParent(CharacterEquipBars[num].GetChild(2), false);
					break;
				}
			}
			num++;
		}
		RecalculateTeamModifiers();
	}

	public void AddEnemyGear(int equipbarindex, Equipment equipment, int teamslot = 1)
	{
		if (GlobalVariables.instance.CareerModeActivated)
		{
			switch (teamslot)
			{
			case 1:
				switch (equipbarindex)
				{
				case 1:
					CareerTeam1Enemy1Equipment.Add(equipment);
					break;
				case 2:
					CareerTeam1Enemy2Equipment.Add(equipment);
					break;
				case 3:
					CareerTeam1Enemy3Equipment.Add(equipment);
					break;
				case 4:
					CareerTeam1Enemy4Equipment.Add(equipment);
					break;
				}
				break;
			case 2:
				switch (equipbarindex)
				{
				case 1:
					CareerTeam2Enemy1Equipment.Add(equipment);
					break;
				case 2:
					CareerTeam2Enemy2Equipment.Add(equipment);
					break;
				case 3:
					CareerTeam2Enemy3Equipment.Add(equipment);
					break;
				case 4:
					CareerTeam2Enemy4Equipment.Add(equipment);
					break;
				}
				break;
			case 3:
				switch (equipbarindex)
				{
				case 1:
					CareerTeam3Enemy1Equipment.Add(equipment);
					break;
				case 2:
					CareerTeam3Enemy2Equipment.Add(equipment);
					break;
				case 3:
					CareerTeam3Enemy3Equipment.Add(equipment);
					break;
				case 4:
					CareerTeam3Enemy4Equipment.Add(equipment);
					break;
				}
				break;
			}
		}
		else
		{
			switch (equipbarindex)
			{
			case 1:
				Enemy1Equipment.Add(equipment);
				break;
			case 2:
				Enemy2Equipment.Add(equipment);
				break;
			case 3:
				Enemy3Equipment.Add(equipment);
				break;
			case 4:
				Enemy4Equipment.Add(equipment);
				break;
			}
		}
	}

	public void ClearEnemyGear()
	{
		Enemy1Equipment.Clear();
		Enemy2Equipment.Clear();
		Enemy3Equipment.Clear();
		Enemy4Equipment.Clear();
