public class Eventchoice : MonoBehaviour, ITooltippable, IPointerEnterHandler, IEventSystemHandler, IPointerExitHandler
{
	public int SuccessChance;

	public string ChanceColor;

	public bool FailPossible;

	public bool NotEnoughGold;

	public bool NotEnoughSpace;

	public string GetDescription()
	{
		string text = "";
		string translation = LocalizationManager.GetTranslation("TOOLTIP/TOOLTIP_positivechance");
		text = translation.Replace("<CHANCE>", "<color=#94FFFC>" + SuccessChance + "</color>");
		if (FailPossible)
		{
			int num = Mathf.Clamp(100 - SuccessChance, 0, 100);
			translation = LocalizationManager.GetTranslation("TOOLTIP/TOOLTIP_negativechance");
			text = text + "\n" + translation.Replace("<CHANCE>", "<color=#94FFFC>" + num + "</color>");
		}
		if (NotEnoughGold)
		{
			text = LocalizationManager.GetTranslation("TOOLTIP/TOOLTIP_nogold");
		}
		if (NotEnoughSpace)
		{
			text = LocalizationManager.GetTranslation("TOOLTIP/TOOLTIP_nospace");
		}
		return text;
	}

	public void OnPointerEnter(PointerEventData eventData)
	{
		//IL_002e: Unknown result type (might be due to invalid IL or missing references)
		if (NotEnoughGold || NotEnoughSpace || (SuccessChance > 0 && SuccessChance < 100))
		{
			UIManager.instance.ShowTooltip(((Component)this).transform.position, this);
		}
	}

	public void OnPointerExit(PointerEventData eventData)
	{
		UIManager.instance.HideTooltip();
	}
}
