	public void PrepareEvent()
	{
		if (ProgressManager.instance.CurrentEvent != null)
		{
			NextEvent = ProgressManager.instance.CurrentEvent;
			if (ProgressManager.instance.CurrentEventAffectedCharacter > 99)
			{
				AffectedCharacter = ProgressManager.instance.DeadHeroes[ProgressManager.instance.CurrentEventAffectedCharacter - 1000];
			}
			else if (ProgressManager.instance.CurrentEventAffectedCharacter > 49)
			{
				AffectedCharacter = ProgressManager.instance.EnemyTeam[ProgressManager.instance.CurrentEventAffectedCharacter - 50];
			}
			else if (ProgressManager.instance.CurrentEventAffectedCharacter > 9)
			{
				AffectedCharacter = RosterManager.instance.Roster[ProgressManager.instance.CurrentEventAffectedCharacter - 10];
			}
			else
			{
				AffectedCharacter = ProgressManager.instance.Team[ProgressManager.instance.CurrentEventAffectedCharacter];
			}
		}
		else
		{
			if ((Object)(object)AffectedCharacter == (Object)null)
			{
				if (ProgressManager.instance.GetTeamSize() > 0)
				{
					AffectedCharacter = ProgressManager.instance.GetRandomTeamMember();
				}
				else if (RosterManager.instance.Roster.Count > 0)
				{
					AffectedCharacter = RosterManager.instance.Roster[Random.Range(0, RosterManager.instance.Roster.Count)];
				}
			}
			if (ProgressManager.instance.NextEvent != null)
			{
				NextEvent = ProgressManager.instance.NextEvent;
				ProgressManager.instance.NextEvent = null;
			}
			if (NextEvent == null && ProgressManager.instance.UnlockedSpecialEvents.Count > 0 && Random.Range(0, 100) < ChangingVariables.instance.SpecialQuestActivationChance)
			{
				int num = 0;
				while (true)
				{
					NextEvent = ProgressManager.instance.UnlockedSpecialEvents[Random.Range(0, ProgressManager.instance.UnlockedSpecialEvents.Count)];
					if (CheckUniqueRequirements(NextEvent.Title))
					{
						ProgressManager.instance.UnlockedSpecialEvents.Remove(NextEvent);
						break;
					}
					num++;
					if (num >= 30)
					{
						NextEvent = null;
						break;
					}
				}
			}
			if (NextEvent == null)
			{
				int num2 = 0;
				while (true)
				{
					NextEvent = DataTables.instance.GetRandomEvent();
					if (CheckUniqueRequirements(NextEvent.Title))
					{
						break;
					}
					num2++;
					if (num2 >= 30)
					{
						NextEvent = null;
						break;
					}
				}
			}
		}
		if (ProgressManager.instance.Team.Contains(AffectedCharacter))
		{
			ProgressManager.instance.CurrentEventAffectedCharacter = ProgressManager.instance.Team.IndexOf(AffectedCharacter);
		}
		else if (RosterManager.instance.Roster.Contains(AffectedCharacter))
		{
			ProgressManager.instance.CurrentEventAffectedCharacter = RosterManager.instance.Roster.IndexOf(AffectedCharacter) + 10;
		}
		else if (ProgressManager.instance.EnemyTeam.Contains(AffectedCharacter))
		{
			ProgressManager.instance.CurrentEventAffectedCharacter = ProgressManager.instance.EnemyTeam.IndexOf(AffectedCharacter) + 50;
		}
		else
		{
			ProgressManager.instance.CurrentEventAffectedCharacter = ProgressManager.instance.DeadHeroes.IndexOf(AffectedCharacter) + 1000;
		}
		if (!GlobalVariables.instance.EndlessModeActivated && !GlobalVariables.instance.CareerModeActivated && ProgressManager.instance.CurrentEvent == null && NextEvent.id < 2000)
		{
			ProgressManager.instance.CompletedEvents.Add(NextEvent);
		}
		else if ((GlobalVariables.instance.EndlessModeActivated || GlobalVariables.instance.CareerModeActivated) && (NextEvent.id == 8 || NextEvent.id == 30 || NextEvent.id == 41 || NextEvent.id == 49))
		{
			ProgressManager.instance.CompletedEvents.Add(NextEvent);
		}
		ProgressManager.instance.CurrentEvent = NextEvent;
		Debug.Log((object)("Prepared Event: " + NextEvent.id));
	}

