	public void SetNextEvent(TownEvent Event)
	{
		ProgressManager.instance.NextEvent = Event;
	}

	public void ChooseChoice(int ChoiceNumber)
	{
		if (NextEvent.QuestStaticAction == "RANDOMCHOICE")
		{
			int num;
			if (NextEvent.Choice4SuccessText != "")
			{
				num = 4;
			}
			else
			{
				num = ((!(NextEvent.Choice3SuccessText != "")) ? 2 : 3);
			}
			ChoiceNumber = Random.Range(1, num + 1);
		}
		else if (NextEvent.QuestStaticAction == "RANDOMCHOICEWITHDECLINE" && ChoiceNumber != 2)
		{
			int num2 = ((!(NextEvent.Choice4SuccessText != "")) ? 2 : 3);
			ChoiceNumber = Random.Range(1, num2 + 1);
			if (ChoiceNumber > 1)
			{
				ChoiceNumber++;
			}
		}
		Debug.Log((object)("EventID: " + NextEvent.id + " | Choice: " + ChoiceNumber));
		switch (ChoiceNumber)
		{
		case 1:
			if (Random.Range(0, 100) < NextEvent.Choice1SuccessChance + ProgressManager.instance.EventLuckBonusTotal)
			{
				ChoiceAction = NextEvent.Choice1SuccessAction;
				ChoiceValue = NextEvent.Choice1SuccessValue;
				ChoiceResultText = LocalizationManager.GetTranslation("EVENT/EVENT_" + NextEvent.id + "choice1success");
			}
			else
			{
				ChoiceAction = NextEvent.Choice1FailAction;
				ChoiceValue = NextEvent.Choice1FailValue;
				ChoiceResultText = LocalizationManager.GetTranslation("EVENT/EVENT_" + NextEvent.id + "choice1fail");
			}
			ChoiceStaticAction = NextEvent.Choice1StaticAction;
			ChoiceStaticActionValue = NextEvent.Choice1StaticActionValue;
			break;
		case 2:
			if (Random.Range(0, 100) < NextEvent.Choice2SuccessChance + ProgressManager.instance.EventLuckBonusTotal)
			{
				ChoiceAction = NextEvent.Choice2SuccessAction;
				ChoiceValue = NextEvent.Choice2SuccessValue;
				ChoiceResultText = LocalizationManager.GetTranslation("EVENT/EVENT_" + NextEvent.id + "choice2success");
			}
			else
			{
				ChoiceAction = NextEvent.Choice2FailAction;
				ChoiceValue = NextEvent.Choice2FailValue;
				ChoiceResultText = LocalizationManager.GetTranslation("EVENT/EVENT_" + NextEvent.id + "choice2fail");
			}
			ChoiceStaticAction = NextEvent.Choice2StaticAction;
			ChoiceStaticActionValue = NextEvent.Choice2StaticActionValue;
			break;
		case 3:
			if (Random.Range(0, 100) < NextEvent.Choice3SuccessChance + ProgressManager.instance.EventLuckBonusTotal)
			{
				ChoiceAction = NextEvent.Choice3SuccessAction;
				ChoiceValue = NextEvent.Choice3SuccessValue;
				ChoiceResultText = LocalizationManager.GetTranslation("EVENT/EVENT_" + NextEvent.id + "choice3success");
			}
			else
			{
				ChoiceAction = NextEvent.Choice3FailAction;
				ChoiceValue = NextEvent.Choice3FailValue;
				ChoiceResultText = LocalizationManager.GetTranslation("EVENT/EVENT_" + NextEvent.id + "choice3fail");
			}
			ChoiceStaticAction = NextEvent.Choice3StaticAction;
			ChoiceStaticActionValue = NextEvent.Choice3StaticActionValue;
			break;
		case 4:
			if (Random.Range(0, 100) < NextEvent.Choice4SuccessChance + ProgressManager.instance.EventLuckBonusTotal)
			{
				ChoiceAction = NextEvent.Choice4SuccessAction;
				ChoiceValue = NextEvent.Choice4SuccessValue;
				ChoiceResultText = LocalizationManager.GetTranslation("EVENT/EVENT_" + NextEvent.id + "choice4success");
			}
			else
			{
				ChoiceAction = NextEvent.Choice4FailAction;
				ChoiceValue = NextEvent.Choice4FailValue;
				ChoiceResultText = LocalizationManager.GetTranslation("EVENT/EVENT_" + NextEvent.id + "choice4fail");
			}
			ChoiceStaticAction = NextEvent.Choice4StaticAction;
			ChoiceStaticActionValue = NextEvent.Choice4StaticActionValue;
			break;
		}
		UIManager.instance.CloseAllTooltips();
		DestroyChoices();
		if (ChoiceResultText != null)
		{
			string text = ChoiceResultText.Replace("<Gladiator>", "<color=#5AF1F0><link=Char>" + AffectedCharacter.Charname + "</link></color>");
			((TMP_Text)EventText).SetText(text);
		}
		ProcessAction(ChoiceAction, ChoiceValue);
		if (ChoiceStaticAction != "")
		{
			ProcessAction(ChoiceStaticAction, ChoiceStaticActionValue);
		}
		if (NextEvent.QuestStaticAction != "")
		{
			ProcessAction(NextEvent.QuestStaticAction, NextEvent.QuestStaticActionValue);
		}
		if (ContinuationEvent && !StopEvent)
		{
			NextEvent = DataTables.instance.ListOfContinuationEvents[ChoiceValue - 2000];
			ProgressManager.instance.CurrentEvent = null;
			StartEvent(continuationevent: true);
		}
		else
		{
			CreateLeavebutton();
			((Component)RewardsPanel).gameObject.SetActive(true);
		}
	}

