	public void DestroyChoices()
	{
		//IL_0014: Unknown result type (might be due to invalid IL or missing references)
		foreach (Transform item in ChoicesPanel)
		{
			Object.Destroy((Object)(object)((Component)item).gameObject);
		}
	}

	public void CreateLeavebutton()
	{
		ProgressManager.instance.CurrentEvent = null;
		ProgressManager.instance.CurrentEventAffectedCharacter = 0;
		SaveManager.instance.Save(FullSave: false);
		AudioManager.instance.AudioEffect("EventChoice");
		((Component)LeaveButton).gameObject.SetActive(true);
		Dictionary<GameObject, float> dictionary = new Dictionary<GameObject, float>();
		dictionary.Add(((Component)LeaveButton).gameObject, 1f);
		((MonoBehaviour)this).StartCoroutine(FadeInChoices(dictionary));
	}

