				Object.Destroy((Object)(object)((Component)item).gameObject);
			}
		}
		UIManager.instance.CloseAllTooltips();
		((Component)LeaveButton).gameObject.SetActive(false);
		((Component)RewardsPanel).gameObject.SetActive(false);
		((Component)EventPanel).gameObject.SetActive(false);
		NextEvent = null;
		ContinuationEvent = false;
		AffectedCharacter = null;
		AudioManager.instance.AudioEffect("EventEnd");
		AudioManager.instance.PlayMusic("Town");
	}

	public bool CheckUniqueRequirements(string Title)
	{
		bool result = true;
		if (GlobalVariables.instance.CareerModeActivated)
		{
			switch (Title)
			{
			case "Fan Favorites":
			case "A Far Away Prince":
			case "An Original Coctail":
			case "A Perilous Sleepover":
			case "Dark Reflections":
			case "Shady Services":
			case "Fame With A Price":
			case "Wicked Charms":
			case "Twisted Fate":
			case "A Free Meal?":
				return false;
			}
		}
		switch (Title)
		{
		case "An Unexpected Reunion":
			if (ProgressManager.instance.DeadHeroes.Count <= 0 || (!ProgressManager.instance.IsThereRoomInTeam() && !RosterManager.instance.IsThereRoom()))
			{
				result = false;
			}
			else
			{
				AffectedCharacter = ProgressManager.instance.DeadHeroes[Random.Range(0, ProgressManager.instance.DeadHeroes.Count)];
			}
			break;
		case "Tending To The Broken":
			result = false;
			foreach (CharacterTemplate item in ProgressManager.instance.Team)
			{
				if ((Object)(object)item != (Object)null && item.InjuryCount > 0 && ProgressManager.instance.GetGold() > 99)
				{
					result = true;
				}
			}
			break;
		case "An Original Coctail":
			AffectedCharacter = ProgressManager.instance.EnemyTeam[Random.Range(0, ProgressManager.instance.EnemyTeam.Count)];
			break;
		case "Shady Services":
			if (ProgressManager.instance.EnemyTeam.Count < 2)
			{
				result = false;
			}
			else if (ProgressManager.instance.GetGold() < 70)
			{
				result = false;
			}
			else
			{
				AffectedCharacter = ProgressManager.instance.EnemyTeam[Random.Range(0, ProgressManager.instance.EnemyTeam.Count)];
			}
			break;
		case "Fame With A Price":
			if (ProgressManager.instance.ProgressionLevel < 3)
			{
				result = false;
			}
			break;
		case "Dark Reflections":
			if (ProgressManager.instance.ProgressionLevel < 2)
