				result = false;
			}
			break;
		case "Ancient Words":
			if (ProgressManager.instance.ProgressionLevel < 2)
			{
				result = false;
			}
			break;
		case "The Local Butcher":
			if (ProgressManager.instance.ProgressionLevel < 2)
			{
				result = false;
			}
			break;
		case "Special Prices":
			if (ProgressManager.instance.GetTeamSize() < 2)
			{
				result = false;
			}
			break;
		case "Grim Awakening":
			if (ProgressManager.instance.GetTeamSize() < 2 || GlobalVariables.instance.EndlessModeActivated)
			{
				result = false;
			}
			break;
		case "A Place For The Lost":
			if (ProgressManager.instance.GetTeamSize() < 2)
			{
				result = false;
			}
			break;
		case "Money Talks":
			if (ProgressManager.instance.GetGold() < 600)
			{
				result = false;
			}
			break;
		case "The Bystander Effect":
			if (ProgressManager.instance.GetGold() < 100)
			{
