			}
			break;
		case "Self-Discovery":
			if (ProgressManager.instance.GetGold() < 200)
			{
				result = false;
			}
			break;
		case "The Downtrodden":
			if (ProgressManager.instance.GetGold() < 30)
			{
				result = false;
			}
			break;
		case "A Shifty Bookdealer":
			if (ProgressManager.instance.GetGold() < 80)
			{
				result = false;
			}
			break;
		case "A Far Away Prince":
			if (ProgressManager.instance.GetGold() < 200)
