			}
			break;
		case "Forgotten Deeds":
			if (ProgressManager.instance.GetGold() < 200)
			{
				result = false;
			}
			break;
		case "Raise The Pitchforks!":
			if (ProgressManager.instance.GetGold() < 100)
			{
				result = false;
			}
			break;
		case "A Message From The Top":
		{
			int num = 0;
			while (AffectedCharacter.InjuryCount >= 8)
			{
				if (ProgressManager.instance.GetTeamSize() > 0)
				{
					AffectedCharacter = ProgressManager.instance.GetRandomTeamMember();
				}
				else if (RosterManager.instance.Roster.Count > 0)
				{
					AffectedCharacter = RosterManager.instance.Roster[Random.Range(0, RosterManager.instance.Roster.Count)];
				}
				num++;
				if (num > 20)
				{
					result = false;
					break;
