			}
			break;
		}
		case "Old Alliances":
			if (ProgressManager.instance.EnemyTeam.Count < 2)
			{
				result = false;
			}
			break;
		case "Fan Encounter":
			result = false;
			foreach (CharacterTemplate item2 in ProgressManager.instance.Team)
			{
				if ((Object)(object)item2 == (Object)null)
				{
					break;
				}
				if (item2.Title != "")
				{
					AffectedCharacter = item2;
					result = true;
					break;
				}
			}
			break;
		case "Yearning For Rest":
			result = false;
			if (GlobalVariables.instance.EndlessModeActivated)
			{
				break;
			}
			foreach (CharacterTemplate item3 in ProgressManager.instance.Team)
			{
				if ((Object)(object)item3 != (Object)null && item3.WinCount + item3.LossCount > 5)
				{
					AffectedCharacter = item3;
					result = true;
				}
			}
			break;
		case "Depraved Rituals":
			if (ProgressManager.instance.GetTeamSize() < 3)
			{
				result = false;
			}
			break;
		case "An Everyday Hero":
			result = false;
			foreach (CharacterTemplate item4 in ProgressManager.instance.Team)
			{
				if ((Object)(object)item4 != (Object)null && item4.Title == "")
				{
					AffectedCharacter = item4;
					result = true;
				}
			}
			break;
		case "Wicked Charms":
			if (ProgressManager.instance.GetGold() < 100)
			{
				result = false;
			}
			break;
		}
		return result;
	}

	public IEnumerator FadeInEventBook()
	{
		if (!fade2Started)
		{
			fade2Started = true;
			while (BookCanvas.alpha < 1f)
			{
				CanvasGroup bookCanvas = BookCanvas;
				bookCanvas.alpha += Time.deltaTime * 2f;
				yield return null;
			}
			fade2Started = false;
		}
	}

	public IEnumerator FadeInChoices(Dictionary<GameObject, float> FadeInList, float delay = 0f)
	{
		if (fadeStarted)
		{
			yield break;
		}
		fadeStarted = true;
		yield return (object)new WaitForSeconds(delay);
		foreach (KeyValuePair<GameObject, float> Choice in FadeInList)
		{
			CanvasGroup canvas = Choice.Key.GetComponent<CanvasGroup>();
			while (canvas.alpha < Choice.Value)
			{
				if ((Object)(object)Choice.Key == (Object)(object)((Component)EventText).gameObject)
				{
					canvas.alpha += Time.deltaTime * 1.5f;
				}
				else
				{
					canvas.alpha += Time.deltaTime * 3f;
				}
				yield return null;
			}
		}
		foreach (KeyValuePair<GameObject, float> FadeIn in FadeInList)
		{
			if (Object.op_Implicit((Object)(object)FadeIn.Key.GetComponent<Button>()))
			{
				((Selectable)FadeIn.Key.GetComponent<Button>()).interactable = true;
			}
		}
		fadeStarted = false;
	}
}
