		if (RewardType == "REWARDCHARACTER" || RewardType == "REWARDSPECIALCHARACTER" || RewardType == "REWARDBACKFROMDEAD")
		{
			UIManager.instance.ShowCharacterTooltip(((Component)this).transform.position, RewardCharacter);
		}
		else if (RewardType == "REWARDEQUIPMENT" || RewardType == "REWARDSPECIALEQUIPMENT" || RewardType == "REWARDCURSEDEQUIPMENT" || RewardType == "REWARDSPECIALTRINKET")
		{
			Equipment equipment = (Equipment)RewardItem;
			UIManager.instance.ShowTooltip(((Component)this).transform.position, this, equipment.givesSkill, equipment.givesPerk);
		}
		else if (RewardType == "REWARDITEM")
		{
			Spellbook spellbook = (Spellbook)RewardItem;
			UIManager.instance.ShowTooltip(((Component)this).transform.position, this, spellbook.TeachesSkill, null, book: true);
		}
		else
		{
			UIManager.instance.ShowTooltip(((Component)this).transform.position, this);
		}
	}

	public void OnPointerExit(PointerEventData eventData)
	{
