public class FloatingCombatText : MonoBehaviour
{
	public static FloatingCombatText instance;

	public GameObject TextPrefab;

	public Dictionary<GameObject, FloatingTextEntry> DictionaryOfTextEntries;

	public List<GameObject> EntityList;

	public Queue<FloatingTextEntry> textPool;

	public int poolSize = 10;

	public float DelayTimer;

	private void Awake()
	{
		if ((Object)(object)instance != (Object)null)
		{
			Object.Destroy((Object)(object)((Component)this).gameObject);
		}
		else
		{
			instance = this;
		}
	}

	public void Start()
	{
		//IL_004c: Unknown result type (might be due to invalid IL or missing references)
		textPool = new Queue<FloatingTextEntry>();
		EntityList = new List<GameObject>();
		for (int i = 0; i < poolSize; i++)
		{
			GameObject val = Object.Instantiate<GameObject>(TextPrefab);
			val.transform.SetParent(((Component)this).transform);
			val.transform.localScale = new Vector3(1f, 1f, 1f);
			val.SetActive(false);
			textPool.Enqueue(val.GetComponent<FloatingTextEntry>());
		}
	}

	public IEnumerator NewFloatingText(string text, string category, Vector3 position, GameObject Entity)
	{
		//IL_001c: Unknown result type (might be due to invalid IL or missing references)
		//IL_001d: Unknown result type (might be due to invalid IL or missing references)
		if (!ProfileManager.instance.FloatingCombatText)
		{
			yield break;
		}
		float NewDelayTimer = 0f;
		foreach (GameObject entity in EntityList)
		{
			if ((Object)(object)entity == (Object)(object)Entity)
			{
				NewDelayTimer += 0.5f;
			}
		}
		EntityList.Add(Entity);
		if (NewDelayTimer > 0f)
		{
			while (NewDelayTimer > 0f)
			{
				NewDelayTimer -= Time.deltaTime;
				yield return null;
			}
		}
		FloatingTextEntry floatingTextEntry = textPool.Dequeue();
		int size = 16;
		Vector3 val = Vector3.up * 0.8f;
		bool increaseSize = false;
		string color;
		switch (category)
		{
		case "damage":
			color = "#FF2420";
			increaseSize = true;
			break;
		case "buff":
			color = "#FFCB37";
			size = 14;
			break;
		case "heal":
			color = "#77FF69";
			break;
		case "mana":
			color = "#20A2FF";
			break;
		default:
			color = "#FFFFFF";
			break;
		}
		floatingTextEntry.SetText(text, color, size);
		((Component)floatingTextEntry).transform.localPosition = Vector2.op_Implicit(GetUnitPositionOnCanvas(Vector2.op_Implicit(position + val)));
		((MonoBehaviour)this).StartCoroutine(floatingTextEntry.ShowText(0.8f, increaseSize));
		yield return (object)new WaitForSeconds(0.3f);
		EntityList.Remove(Entity);
	}

	public Vector2 GetUnitPositionOnCanvas(Vector2 position)
	{
		//IL_0005: Unknown result type (might be due to invalid IL or missing references)
		//IL_0006: Unknown result type (might be due to invalid IL or missing references)
		//IL_000b: Unknown result type (might be due to invalid IL or missing references)
		//IL_0010: Unknown result type (might be due to invalid IL or missing references)
		//IL_0015: Unknown result type (might be due to invalid IL or missing references)
		//IL_0020: Unknown result type (might be due to invalid IL or missing references)
		//IL_002a: Unknown result type (might be due to invalid IL or missing references)
		Vector2 val = Vector2.op_Implicit(Camera.main.WorldToScreenPoint(Vector2.op_Implicit(position)));
		Vector2 result = default(Vector2);
		RectTransformUtility.ScreenPointToLocalPointInRectangle(UIManager.instance.TooltipCanvasRectTransform, val, (Camera)null, ref result);
		return result;
	}
}
public class FloatingTextEntry : MonoBehaviour
{
	public TextMeshProUGUI message;

	public CanvasGroup canvas;

	public void SetText(string text, string color, int size = 16)
	{
		((TMP_Text)message).SetText("<color=" + color + "><size=" + size + ">" + text + "</color>");
	}

	public IEnumerator ShowText(float speed, bool increaseSize)
	{
		((Component)this).transform.localScale = new Vector3(1f, 1f, 1f);
		((Component)this).gameObject.SetActive(true);
		canvas.alpha = 1f;
		if (increaseSize)
		{
			while (((Component)this).transform.localScale.x < 1.5f)
			{
				Transform transform = ((Component)this).transform;
				transform.localScale += new Vector3(0.1f, 0.1f, 0.1f);
			}
		}
		while (canvas.alpha > 0f)
		{
			if (increaseSize && ((Component)this).transform.localScale.x > 0.2f)
			{
				Transform transform2 = ((Component)this).transform;
				transform2.localScale -= new Vector3(0.01f, 0.01f, 0.01f);
			}
			CanvasGroup val = canvas;
			val.alpha -= Time.deltaTime * speed;
			Transform transform3 = ((Component)canvas).transform;
			transform3.localPosition += Vector3.up * speed / 2f;
			yield return null;
		}
		((Component)this).gameObject.SetActive(false);
		FloatingCombatText.instance.textPool.Enqueue(this);
	}
}
