public class InventoryManager : MonoBehaviour
{
	public Transform InventoryPanel;

	public List<Item> InventoryList = new List<Item>();

	public GameObject InventorySlot;

	public GameObject ItemTemplate;

	public TextMeshProUGUI InventoryCount;

	public static InventoryManager instance;

	private void Awake()
	{
		if ((Object)(object)instance != (Object)null)
		{
			Object.Destroy((Object)(object)((Component)this).gameObject);
			return;
		}
		instance = this;
		Object.DontDestroyOnLoad((Object)(object)((Component)((Component)this).transform).gameObject);
	}

	private void Start()
	{
		CreateInventory();
		if (SaveManager.instance.LoadActive)
		{
			SaveManager.instance.LoadComponent("InventoryManager");
		}
	}

	public bool IsThereRoom(int slots = 1)
	{
		if (GetInventorySize() + slots <= GlobalVariables.instance.InventoryMaxSize)
		{
			return true;
		}
		return false;
	}

	public void AddToInventory(Item Item)
	{
		//IL_004b: Unknown result type (might be due to invalid IL or missing references)
		//IL_0050: Unknown result type (might be due to invalid IL or missing references)
		int num = 0;
		foreach (Item inventory in InventoryList)
		{
			if ((Object)(object)inventory == (Object)null)
			{
				InventoryList[num] = Item;
				break;
			}
			num++;
		}
		Scene activeScene = SceneManager.GetActiveScene();
		if (activeScene.name == "Town")
		{
			RedrawInventory();
		}
	}

	public Transform GetFirstFreeSlot()
	{
		//IL_0016: Unknown result type (might be due to invalid IL or missing references)
		//IL_001c: Expected Obj, but got Unknown
		Transform result = null;
		foreach (Transform item in InventoryPanel)
		{
			Transform val = item;
			if (val.childCount == 0)
			{
				return val;
			}
		}
		return result;
	}

	public void RefreshInventory()
	{
		//IL_0016: Unknown result type (might be due to invalid IL or missing references)
		//IL_001c: Expected Obj, but got Unknown
		int num = 0;
		foreach (Transform item in InventoryPanel)
		{
			Transform val = item;
			if (val.childCount > 0)
			{
				InventoryList[num] = ((Component)val.GetChild(0)).GetComponent<ItemDetails>().containeditem;
			}
			else
			{
				InventoryList[num] = null;
			}
			num++;
		}
		((TMP_Text)InventoryCount).SetText(GetInventorySize() + " / " + GlobalVariables.instance.InventoryMaxSize);
	}

	public void CreateInventory()
	{
		for (int i = 0; i < GlobalVariables.instance.InventoryMaxSize; i++)
		{
			Object.Instantiate<GameObject>(InventorySlot).transform.SetParent(InventoryPanel, false);
			InventoryList.Add(null);
		}
	}

	public void RedrawInventory()
	{
		//IL_0022: Unknown result type (might be due to invalid IL or missing references)
		if (InventoryList.Count == 0)
		{
			return;
		}
		foreach (Transform item in InventoryPanel)
		{
			Object.Destroy((Object)(object)((Component)item).gameObject);
		}
		if (InventoryList.Count < GlobalVariables.instance.InventoryMaxSize)
		{
			int num = GlobalVariables.instance.InventoryMaxSize - InventoryList.Count;
			for (int i = 0; i < num; i++)
			{
				InventoryList.Add(null);
			}
		}
		foreach (Item inventory in InventoryList)
		{
			GameObject val = Object.Instantiate<GameObject>(InventorySlot);
			val.transform.SetParent(InventoryPanel, false);
			if ((Object)(object)inventory != (Object)null)
			{
				GameObject val2 = Object.Instantiate<GameObject>(ItemTemplate);
				val2.transform.SetParent(val.transform, false);
				val2.GetComponent<ItemDetails>().containeditem = inventory;
			}
		}
		((TMP_Text)InventoryCount).SetText(GetInventorySize() + " / " + GlobalVariables.instance.InventoryMaxSize);
	}

	public int GetInventorySize()
	{
		int num = 0;
		foreach (Item inventory in InventoryList)
		{
			if ((Object)(object)inventory != (Object)null)
			{
				num++;
			}
		}
		return num;
	}

	public bool IsThisInInventory(Item Item)
	{
		foreach (Item inventory in InventoryList)
		{
			if ((Object)(object)Item == (Object)(object)inventory)
			{
				return true;
			}
		}
		return false;
	}

	public bool RemoveFromInventory(Item Item)
	{
		if (InventoryList.Contains(Item))
		{
			InventoryList[InventoryList.IndexOf(Item)] = null;
			((TMP_Text)InventoryCount).SetText(GetInventorySize() + " / " + GlobalVariables.instance.InventoryMaxSize);
			return true;
		}
		return false;
	}
}
public class ItemDetails : MonoBehaviour, ITooltippable, IPointerEnterHandler, IEventSystemHandler, IPointerExitHandler, IPointerClickHandler
{
	public Item containeditem;

	private bool MouseOverThis;

	public string GetDescription()
	{
		return containeditem.GetTooltip();
	}

	private void Start()
	{
		UpdateSprite();
	}

	public virtual void OnPointerClick(PointerEventData eventData)
	{
		//IL_000c: Unknown result type (might be due to invalid IL or missing references)
		//IL_0011: Unknown result type (might be due to invalid IL or missing references)
		//IL_00b9: Unknown result type (might be due to invalid IL or missing references)
		//IL_012e: Unknown result type (might be due to invalid IL or missing references)
		if (eventData.clickCount != 2)
		{
			return;
		}
		Scene activeScene = SceneManager.GetActiveScene();
		if (activeScene.name != "Town" || TownManager.instance.IsThisInShop(containeditem))
		{
			return;
		}
		int num = 0;
		if (((Component)TownManager.instance.SellWindow).gameObject.activeSelf)
		{
			num = (SellWindowManager.instance.IsThisInSellWindow(containeditem) ? 1 : 2);
		}
		else if (((Component)TownManager.instance.Inventory).gameObject.activeSelf)
		{
			num = 1;
		}
		switch (num)
		{
		case 1:
		{
			Transform firstFreeSlot2 = InventoryManager.instance.GetFirstFreeSlot();
			if ((Object)(object)firstFreeSlot2 == (Object)null)
			{
				Debug.Log((object)"full");
				break;
			}
			((Component)this).transform.SetParent(firstFreeSlot2);
			((Component)this).transform.position = firstFreeSlot2.position;
			InventoryManager.instance.RefreshInventory();
			EquipmentManager.instance.RecheckGear();
			if (((Component)TownManager.instance.SellWindow).gameObject.activeSelf)
			{
				SellWindowManager.instance.RefreshSellWindow();
			}
			break;
		}
		case 2:
		{
			Transform firstFreeSlot = SellWindowManager.instance.GetFirstFreeSlot();
			if ((Object)(object)firstFreeSlot == (Object)null)
			{
				Debug.Log((object)"full");
				break;
			}
			((Component)this).transform.SetParent(firstFreeSlot);
			((Component)this).transform.position = firstFreeSlot.position;
			InventoryManager.instance.RefreshInventory();
			EquipmentManager.instance.RecheckGear();
			SellWindowManager.instance.RefreshSellWindow();
			break;
		}
		}
	}

	public void UpdateSprite()
	{
		if ((Object)(object)containeditem != (Object)null)
		{
			((Component)this).GetComponent<Image>().sprite = containeditem.icon;
		}
	}

	public void OnPointerEnter(PointerEventData eventData)
	{
		//IL_00e1: Unknown result type (might be due to invalid IL or missing references)
		//IL_009e: Unknown result type (might be due to invalid IL or missing references)
		//IL_0144: Unknown result type (might be due to invalid IL or missing references)
		//IL_011e: Unknown result type (might be due to invalid IL or missing references)
		if ((Object)(object)containeditem != (Object)null)
		{
			Equipment equipment = null;
			if (((object)containeditem).GetType() == typeof(Equipment))
			{
				equipment = (Equipment)containeditem;
			}
			Spellbook spellbook = null;
			if (((object)containeditem).GetType() == typeof(Spellbook))
			{
				spellbook = (Spellbook)containeditem;
			}
			if (((object)containeditem).GetType() == typeof(Spellbook) && InventoryManager.instance.IsThisInInventory(containeditem))
			{
				UIManager.instance.ShowSpellbookTooltip(((Component)this).transform.position, this, ((Component)this).gameObject, containeditem);
			}
			else if (((object)containeditem).GetType() == typeof(Spellbook))
			{
				UIManager.instance.ShowTooltip(((Component)this).transform.position, this, spellbook.TeachesSkill, null, book: true);
			}
			else if (((object)containeditem).GetType() == typeof(Equipment))
			{
				UIManager.instance.ShowTooltip(((Component)this).transform.position, this, equipment.givesSkill, equipment.givesPerk);
			}
			else
			{
				UIManager.instance.ShowTooltip(((Component)this).transform.position, this);
			}
			MouseOverThis = true;
		}
	}

	public void OnPointerExit(PointerEventData eventData)
	{
		if ((Object)(object)containeditem != (Object)null)
		{
			UIManager.instance.HideTooltip();
			MouseOverThis = false;
		}
	}

	private void OnDestroy()
	{
		if (MouseOverThis && (Object)(object)containeditem != (Object)null)
		{
			UIManager.instance.CloseAllTooltips();
		}
	}
}
