		}
		else
		{
			AudioManager.instance.AudioEffect("ButtonClick");
		}
		SelectMenu.SetActive(!SelectMenu.activeSelf);
	}

	public void UpdateSelectorText()
	{
		switch (LocalizationManager.CurrentLanguageCode)
		{
		case "en":
			((TMP_Text)CurrentLanguageText).font = EN_Font;
			((TMP_Text)CurrentLanguageText).fontSharedMaterial = EN_Material;
			((TMP_Text)CurrentLanguageText).SetText("English");
