			((TMP_Text)CurrentLanguageText).fontSharedMaterial = KR_Material;
			((TMP_Text)CurrentLanguageText).SetText("한국어");
			break;
		case "es-ES":
			((TMP_Text)CurrentLanguageText).font = EN_Font;
			((TMP_Text)CurrentLanguageText).fontSharedMaterial = EN_Material;
			((TMP_Text)CurrentLanguageText).SetText("Español (España)");
			break;
		case "es-US":
			((TMP_Text)CurrentLanguageText).font = EN_Font;
			((TMP_Text)CurrentLanguageText).fontSharedMaterial = EN_Material;
			((TMP_Text)CurrentLanguageText).SetText("Español (Latinoamérica)");
