	public void SelectLanguage()
	{
		UpdateSelectorText();
		UpdateRBPLogo();
		MainMenuScript.instance.RefreshMenuTranslations();
		ToggleSelectMenu();
		MainMenuScript.instance.TeamName.text = "";
	}

	public void UpdateRBPLogo()
	{
		if (LocalizationManager.CurrentLanguageCode == "zh-CN")
		{
			RBPPromoImage.sprite = RBPLogo_sc;
		}
		else
		{
			RBPPromoImage.sprite = RBPLogo;
		}
