	private void Start()
	{
		//IL_013a: Unknown result type (might be due to invalid IL or missing references)
		//IL_0144: Expected Obj, but got Unknown
		//IL_0181: Unknown result type (might be due to invalid IL or missing references)
		//IL_0186: Unknown result type (might be due to invalid IL or missing references)
		//IL_0190: Unknown result type (might be due to invalid IL or missing references)
		//IL_0195: Unknown result type (might be due to invalid IL or missing references)
		if (SteamAchievements.instance.IsDLCActivated())
		{
			ProfileManager.instance.DLC_Installed = true;
			DLC_Activation_logo.SetActive(true);
			DLC_Promo.SetActive(false);
		}
		else
		{
			ProfileManager.instance.DLC_Installed = false;
			DLC_Promo.SetActive(true);
			DLC_Activation_logo.SetActive(false);
		}
		if (SteamManager.GOGVersion)
		{
			CoDDSteamText.SetActive(false);
			CoDDGOGText.SetActive(true);
		}
		AudioManager.instance.PlayMusic("Menu");
		if (ES3.FileExists("Data.es3"))
		{
			((Selectable)ContinueGameButton.GetComponent<Button>()).interactable = true;
			ContinueGameButton.GetComponent<CanvasGroup>().alpha = 1f;
		}
		else
		{
			((Selectable)ContinueGameButton.GetComponent<Button>()).interactable = false;
			ContinueGameButton.GetComponent<CanvasGroup>().alpha = 0.3f;
		}
		Object.Destroy((Object)(object)GameObject.Find("GameManager"));
		Object.Destroy((Object)(object)GameObject.Find("MainMenuCanvas"));
		OptionsMenu.instance.ToggleOptionsButtonVisibility();
		FillHallOfFame();
		SaveManager.instance.StartActions();
		((UnityEventBase)CareerInfoButton.onClick).RemoveAllListeners();
		((UnityEvent)CareerInfoButton.onClick).AddListener((UnityAction)OptionsMenu.instance.ToggleCareerModeInfo);
		if (ProfileManager.instance.YouTubeDeclined)
		{
			YouTubeButton.SetActive(false);
			YouTubeWindow.SetActive(false);
		}
		if (DLC_Promo.activeSelf)
		{
			Transform transform = RBPButton.transform;
			transform.position += Vector3.up * 110f;
		}
		Debug.Log((object)"Main Menu Loaded");
	}

	public void ActivatePresets()
	{
		TeamName.text = ProfileManager.instance.LatestTeamName;
		if (ProfileManager.instance.LatestDifficulty != 2 && ProfileManager.instance.LatestDifficulty != 1)
		{
			ProfileManager.instance.LatestDifficulty = 2;
		}
		EndlessModeToggle.isOn = false;
		if (ProfileManager.instance.LatestChallenge1Active && ProfileManager.instance.TotalGameWins >= 1)
		{
			Challenge1Toggle.isOn = true;
		}
		else
