		if (ProfileManager.instance.LatestChallenge7Active && ProfileManager.instance.TotalGameWins >= 1)
		{
			Challenge7Toggle.isOn = true;
		}
		else
		{
			Challenge7Toggle.isOn = false;
		}
		if (ProfileManager.instance.LatestChallenge8Active && ProfileManager.instance.TotalGameWins >= 1)
		{
			Challenge8Toggle.isOn = true;
		}
		else
		{
			Challenge8Toggle.isOn = false;
		}
		if (ProfileManager.instance.LatestChallenge9Active && ProfileManager.instance.TotalGameWins >= 1)
		{
			Challenge9Toggle.isOn = true;
		}
		else
		{
			Challenge9Toggle.isOn = false;
		}
		if (ProfileManager.instance.LatestChallenge10Active && ProfileManager.instance.TotalGameWins >= 1)
		{
			Challenge10Toggle.isOn = true;
