			Challenge10Toggle.isOn = false;
		}
		GloryLevel = ProfileManager.instance.LatestGloryLevel;
		if (ProfileManager.instance.TotalGameWins >= 2)
		{
			((Component)AdditionalGloryToggle).GetComponent<CanvasGroup>().alpha = 1f;
			((Selectable)AdditionalGloryToggle).interactable = true;
		}
		else
		{
			((Component)AdditionalGloryToggle).GetComponent<CanvasGroup>().alpha = 0.5f;
			((Selectable)AdditionalGloryToggle).interactable = false;
			GloryLevel = 0;
			AdditionalGloryTooltippable.type = "UNLOCKABLE2";
		}
		if (GloryLevel > 0)
		{
			AdditionalGloryToggle.isOn = true;
			AdditionalGlory.SetActive(true);
		}
		else
		{
			AdditionalGloryToggle.isOn = false;
			AdditionalGlory.SetActive(false);
		}
		if (ProfileManager.instance.LatestDifficulty == 1)
		{
			ChooseEasy();
		}
		else
		{
			ChooseNormal();
		}
		if (ProfileManager.instance.TotalGameWins >= 1)
		{
			((Component)ChallengesButton).GetComponent<CanvasGroup>().alpha = 1f;
			((Behaviour)ChallengesButton).enabled = true;
		}
		else
		{
			((Component)ChallengesButton).GetComponent<CanvasGroup>().alpha = 0.5f;
			((Behaviour)ChallengesButton).enabled = false;
			ChallengesTooltippable.type = "UNLOCKABLE1";
		}
		if (ProfileManager.instance.TotalGameWins >= 3)
		{
			((Component)EndlessModeToggle).GetComponent<CanvasGroup>().alpha = 1f;
			((Selectable)EndlessModeToggle).interactable = true;
			EndlessTooltippable.type = "GAMEMODEENDLESS";
			if (ProfileManager.instance.LatestEndlessActive)
			{
				EndlessModeToggle.isOn = true;
			}
		}
		else
		{
			((Component)EndlessModeToggle).GetComponent<CanvasGroup>().alpha = 0.5f;
			((Selectable)EndlessModeToggle).interactable = false;
		}
		if (ProfileManager.instance.TotalGameWins > 0)
		{
			((TMP_Text)TotalWinsText).SetText(LocalizationManager.GetTranslation("UI.NEWGAME/UI.NEWGAME_totalwins") + " <color=white>" + ProfileManager.instance.TotalGameWins + "</color>");
			((Component)TotalWinsText).gameObject.SetActive(true);
		}
		if (ProfileManager.instance.TotalGameWins > 2)
		{
			((TMP_Text)HighestEndlessScoreText).SetText(LocalizationManager.GetTranslation("UI.NEWGAME/UI.NEWGAME_endlessscore") + " <color=white>" + ProfileManager.instance.HighestEndlessScore + "</color>");
			((Component)HighestEndlessScoreText).gameObject.SetActive(true);
		}
		if (ProfileManager.instance.CareerModeWins > 0)
		{
			((TMP_Text)CareerModeWinsText).SetText(LocalizationManager.GetTranslation("UI.NEWGAME/UI.NEWGAME_careerwins") + " <color=white>" + ProfileManager.instance.CareerModeWins + "</color>");
			((Component)CareerModeWinsText).gameObject.SetActive(true);
		}
		CareerModeToggle.isOn = false;
		if (ProfileManager.instance.DLC_Installed)
		{
			((Component)CareerModeToggle).GetComponent<CanvasGroup>().alpha = 1f;
			((Selectable)CareerModeToggle).interactable = true;
			CareerModeTooltippable.type = "GAMEMODECAREER";
			if (ProfileManager.instance.LatestCareerActive)
			{
				CareerModeToggle.isOn = true;
			}
		}
		else
		{
			((Component)CareerModeToggle).GetComponent<CanvasGroup>().alpha = 0.5f;
			((Selectable)CareerModeToggle).interactable = false;
		}
		if (CareerModeToggle.isOn)
		{
			if (AdditionalGloryToggle.isOn)
			{
				AdditionalGlory.SetActive(false);
				AdditionalGloryToggle.isOn = false;
			}
			PrestigeLevelSlider.SetActive(true);
			PrestigeLevel = ProfileManager.instance.LatestPrestigeLevel;
		}
		CheckOptionAvailability();
		AdjustChallengeTrophies();
		UpdateDescriptions();
	}

	public void CheckOptionAvailability()
	{
		if (ProfileManager.instance.DLC_Installed)
		{
			((Selectable)CareerModeToggle).interactable = true;
		}
		if (ProfileManager.instance.TotalGameWins >= 3)
		{
			((Selectable)EndlessModeToggle).interactable = true;
		}
		if (ProfileManager.instance.TotalGameWins >= 2 && DifficultySetting == 2)
		{
			((Selectable)AdditionalGloryToggle).interactable = true;
		}
		else
		{
			((Selectable)AdditionalGloryToggle).interactable = false;
		}
		if (CareerModeToggle.isOn)
		{
			EndlessModeToggle.isOn = false;
			((Selectable)EndlessModeToggle).interactable = false;
			AdditionalGlory.SetActive(false);
			AdditionalGloryToggle.isOn = false;
			((Selectable)AdditionalGloryToggle).interactable = false;
		}
		if (EndlessModeToggle.isOn)
		{
			CareerModeToggle.isOn = false;
			((Selectable)CareerModeToggle).interactable = false;
		}
	}

