	public void AcceptWarning()
	{
		AudioManager.instance.AudioEffect("ButtonClick");
		NewGameWarning.SetActive(false);
		LanguageSelectionButton.SetActive(false);
		NewGameScreen.SetActive(true);
	}

	public void CancelWarning()
	{
		AudioManager.instance.AudioEffect("Back");
		NewGameWarning.SetActive(false);
	}

	public void OpenOptions()
	{
		OptionsMenu.instance.ToggleOptionsWindow();
	}

	public void OpenNewGameMenu()
	{
		AudioManager.instance.AudioEffect("ButtonClick");
		if (ES3.FileExists("Data.es3"))
		{
			NewGameWarning.SetActive(true);
			return;
		}
		NewGameScreen.SetActive(true);
		LanguageSelectionButton.SetActive(false);
		RefreshActiveChallengesText();
	}

	public void CloseNewGameMenu()
	{
		AudioManager.instance.AudioEffect("Back");
		NewGameScreen.SetActive(false);
		LanguageSelectionButton.SetActive(true);
	}

	public void ChooseEasy()
	{
		if (SaveManager.instance.StartupComplete)
		{
			AudioManager.instance.AudioEffect("ButtonClick");
		}
		DifficultySetting = 1;
		GlobalVariables.instance.ChosenGameDifficulty = 1;
		UpdateDescriptions();
		((Selectable)EasyButton).interactable = false;
		((Selectable)NormalButton).interactable = true;
		if (ChallengesMenu.activeSelf)
		{
			ChallengesMenu.SetActive(false);
		}
		AdjustChallengeTrophies();
		if (AdditionalGlory.activeSelf)
		{
			AdditionalGloryToggle.isOn = false;
			ToggleAdditionalGlory(toggle: false);
		}
		if (ProfileManager.instance.TotalGameWins >= 2)
		{
			AdditionalGloryTooltippable.type = "GAMEMODEADDITIONALGLORYEASY";
			((Component)AdditionalGloryToggle).GetComponent<CanvasGroup>().alpha = 0.5f;
			((Selectable)AdditionalGloryToggle).interactable = false;
		}
		if (CareerModeToggle.isOn)
		{
			AdditionalGlory.SetActive(false);
			AdditionalGloryToggle.isOn = false;
			((Selectable)AdditionalGloryToggle).interactable = false;
		}
	}

	public void ChooseNormal()
	{
		if (SaveManager.instance.StartupComplete)
		{
			AudioManager.instance.AudioEffect("ButtonClick");
		}
		DifficultySetting = 2;
		GlobalVariables.instance.ChosenGameDifficulty = 2;
		UpdateDescriptions();
		((Selectable)EasyButton).interactable = true;
		((Selectable)NormalButton).interactable = false;
		if (ChallengesMenu.activeSelf)
		{
			ChallengesMenu.SetActive(false);
		}
		AdjustChallengeTrophies();
		if (ProfileManager.instance.TotalGameWins >= 2)
		{
			AdditionalGloryTooltippable.type = "GAMEMODEADDITIONALGLORY";
			((Component)AdditionalGloryToggle).GetComponent<CanvasGroup>().alpha = 1f;
			((Selectable)AdditionalGloryToggle).interactable = true;
		}
		if (CareerModeToggle.isOn)
		{
			AdditionalGlory.SetActive(false);
			AdditionalGloryToggle.isOn = false;
			((Selectable)AdditionalGloryToggle).interactable = false;
		}
	}

	public void StartGame()
	{
		AudioManager.instance.AudioEffect("ButtonClick");
		SetName();
		if (ProfileManager.instance.GamesPlayed == 0 && !FirstGameMessageShown)
		{
			ShowFirstGameMessage();
			return;
		}
		PregameChecks();
		ProfileManager.instance.LatestTeamName = ChangingVariables.instance.HeroTeamNameTemp;
		ProfileManager.instance.LatestDifficulty = GlobalVariables.instance.ChosenGameDifficulty;
		ProfileManager.instance.LatestGloryLevel = GlobalVariables.instance.GloryLevel;
		ProfileManager.instance.LatestEndlessActive = GlobalVariables.instance.EndlessModeActivated;
		ProfileManager.instance.LatestCareerActive = GlobalVariables.instance.CareerModeActivated;
		ProfileManager.instance.LatestPrestigeLevel = GlobalVariables.instance.CareerPrestigeLevel;
		OptionsMenu.instance.ToggleOptionsButtonVisibility();
		SaveManager.instance.DeleteSave();
		ProfileManager.instance.GamesPlayed++;
		SaveManager.instance.SaveProfile();
		SaveManager.instance.SavePreferences();
		SceneManager.LoadScene("Town", (LoadSceneMode)0);
	}

