	public void FillHallOfFame()
	{
		//IL_020c: Unknown result type (might be due to invalid IL or missing references)
		if (!ES3.FileExists("Profile.es3"))
		{
			return;
		}
		try
		{
			List<List<string>> list = new List<List<string>>();
			if (ES3.KeyExists("HighScore1", "Profile.es3"))
			{
				List<string> item = ES3.Load<List<string>>("HighScore1", "Profile.es3");
				list.Add(item);
			}
			if (ES3.KeyExists("HighScore2", "Profile.es3"))
			{
				List<string> item2 = ES3.Load<List<string>>("HighScore2", "Profile.es3");
				list.Add(item2);
			}
			if (ES3.KeyExists("HighScore3", "Profile.es3"))
			{
				List<string> item3 = ES3.Load<List<string>>("HighScore3", "Profile.es3");
				list.Add(item3);
			}
			if (list.Count > 0)
			{
				HallOfFameEmptyText.SetActive(false);
			}
			List<int> list2 = new List<int>();
			List<HallOfFameEntry> list3 = new List<HallOfFameEntry>();
			foreach (List<string> item4 in list)
			{
				list3.Add(CreateHallOfFameEntry(item4, Endless: false));
				int result = 0;
				int.TryParse(item4[0], out result);
				list2.Add(result);
			}
			int num = 0;
			int num2 = 0;
			if (list2.Count >= 2 && list2[0] < list2[1])
			{
				num++;
			}
			if (list2.Count == 3)
			{
				if (list2[0] < list2[2])
				{
					num2++;
				}
				if (list2[1] < list2[2])
				{
					num2++;
				}
			}
			if (num == 1 && num2 == 2)
			{
				((Component)list3[0]).transform.SetAsLastSibling();
				((Component)list3[2]).transform.SetAsFirstSibling();
			}
			else if (num == 1 && num2 == 1)
			{
				((Component)list3[0]).transform.SetAsLastSibling();
			}
			else if (num == 1)
			{
				((Component)list3[1]).transform.SetAsFirstSibling();
			}
			else
			{
				switch (num2)
				{
				case 1:
					((Component)list3[1]).transform.SetAsLastSibling();
					break;
				case 2:
					((Component)list3[2]).transform.SetAsFirstSibling();
					break;
				}
			}
			int num3 = 1;
			foreach (Transform item5 in HallOfFameEntryParent.transform)
			{
				((TMP_Text)((Component)item5).GetComponent<HallOfFameEntry>().Rank).SetText("#" + num3);
				num3++;
			}
			if (ES3.KeyExists("HighScoreEndless", "Profile.es3"))
			{
				List<string> list4 = ES3.Load<List<string>>("HighScoreEndless", "Profile.es3");
				CreateHallOfFameEntry(list4, Endless: true);
				if (HallOfFameEmptyText.activeSelf)
				{
					HallOfFameEmptyText.SetActive(false);
				}
			}
			else if (list.Count == 3)
			{
				HallOfFameReservedText.SetActive(true);
			}
		}
		catch (Exception ex)
		{
			Debug.Log((object)("EXCEPTION MainMenuScript:FillHallOfFame: " + ex.StackTrace + " ||| MESSAGE: ||| " + ex.Message));
		}
	}

	public HallOfFameEntry CreateHallOfFameEntry(List<string> list, bool Endless)
	{
		GameObject val = Object.Instantiate<GameObject>(HallOfFameEntryPrefab);
		val.transform.SetParent(HallOfFameEntryParent.transform, false);
		HallOfFameEntry component = val.GetComponent<HallOfFameEntry>();
		((TMP_Text)component.Score).SetText(list[0]);
		((TMP_Text)component.TeamName).SetText(list[1]);
		if (Endless)
		{
			((TMP_Text)component.ScoreTitle).SetText(LocalizationManager.GetTranslation("UI.HALLOFFAME/UI.HALLOFFAME_wins"));
			((TMP_Text)component.Rank).SetText("∞");
		}
		int num = (list.Count - 2) / 2;
		for (int i = 0; i < num; i++)
		{
			GameObject val2 = Object.Instantiate<GameObject>(component.HallOfFameUnityPrefab);
			val2.transform.SetParent(component.UnitPanel.transform, false);
			component.SetCharDetails(list[i * 2 + 2], list[i * 2 + 3], val2.GetComponent<HallOfFameUnit>());
		}
		return component;
	}

