	public void ContinueGame()
	{
		AudioManager.instance.AudioEffect("ButtonClick");
		try
		{
			if (ProfileManager.instance.DLC_Installed && ES3.KeyExists("DLCSAVE") && ES3.Load<bool>("DLCSAVE") && !ProfileManager.instance.DLC_ContentEnabled)
			{
				ProfileManager.instance.DLC_ContentEnabled = true;
				OptionsMenu.instance.DLCContentToggle.isOn = true;
			}
		}
		catch
		{
			Debug.Log((object)"ContinueGame Save version verification failed, #1");
		}
		try
		{
			if (!ProfileManager.instance.DLC_Installed && ES3.KeyExists("DLCSAVE") && ES3.Load<bool>("DLCSAVE"))
			{
				UIManager.instance.ShowErrorMessage(LocalizationManager.GetTranslation("UI.MAINMENU/UI.MAINMENU_dlcrequired"), 0.3f);
				return;
			}
		}
		catch
		{
			Debug.Log((object)"ContinueGame Save version verification failed, #2");
		}
		try
		{
			if (!ES3.KeyExists("GameVersionNumber") && ProfileManager.instance.DLC_ContentEnabled)
			{
				UIManager.instance.ShowErrorMessage(LocalizationManager.GetTranslation("UI.MAINMENU/UI.MAINMENU_dlccontinueold"), 0.3f);
				return;
			}
			if (ES3.Load<int>("GameVersionNumber") < 17 && ProfileManager.instance.DLC_ContentEnabled)
			{
				UIManager.instance.ShowErrorMessage(LocalizationManager.GetTranslation("UI.MAINMENU/UI.MAINMENU_dlccontinueold"), 0.3f);
				return;
			}
		}
		catch
		{
			Debug.Log((object)"ContinueGame Save version verification failed, #3");
		}
		OptionsMenu.instance.ToggleOptionsButtonVisibility();
		SaveManager.instance.Load();
	}

