	public void ToggleCareerMode(bool toggle)
	{
		if (toggle)
		{
			if (SaveManager.instance.StartupComplete)
			{
				AudioManager.instance.AudioEffect("Toggle");
			}
			PrestigeLevel = ProfileManager.instance.LatestPrestigeLevel;
			if (PrestigeLevel == 0)
			{
				PrestigeLevel = 1;
			}
			PrestigeLevelSlider.SetActive(true);
			UpdateDescriptions();
		}
		else
		{
			AudioManager.instance.AudioEffect("ToggleOff");
			PrestigeLevelSlider.SetActive(false);
		}
		CheckOptionAvailability();
	}

