	public void PregameChecks()
	{
		if (DifficultySetting == 1)
		{
			GlobalVariables.instance.ChosenGameDifficulty = 1;
		}
		else
		{
			GlobalVariables.instance.ChosenGameDifficulty = 2;
		}
		if (AdditionalGlory.activeSelf)
		{
			GlobalVariables.instance.GloryLevel = GloryLevel;
		}
		else
		{
			GlobalVariables.instance.GloryLevel = 0;
		}
		if (EndlessModeToggle.isOn)
		{
			GlobalVariables.instance.EndlessModeActivated = true;
		}
		else
		{
			GlobalVariables.instance.EndlessModeActivated = false;
		}
		if (Challenge1Toggle.isOn)
		{
			GlobalVariables.instance.ChallengeDeadIsDead = true;
		}
		else
		{
			GlobalVariables.instance.ChallengeDeadIsDead = false;
		}
		if (Challenge2Toggle.isOn)
		{
			GlobalVariables.instance.ChallengeNeedyEmperor = true;
