public class MapManager : MonoBehaviour
{
	public static MapManager instance;

	public Tilemap BaseLayer;

	public Tilemap CollideLayer;

	public Tilemap ItemLayer;

	public Tilemap BlockingLayer;

	public Transform MiscObjectsParent;

	public GameObject BannerPrefab;

	public GameObject TorchPrefab;

	public ES3Settings settings;

	public Dictionary<Vector3Int, TileBase> LayerDictionary = new Dictionary<Vector3Int, TileBase>();

	private Dictionary<Vector3, string> MiscObjects;

	private void Awake()
	{
		if ((Object)(object)instance != (Object)null)
		{
			Object.Destroy((Object)(object)((Component)this).gameObject);
		}
		else
		{
			instance = this;
		}
	}

	public void ClearLayer(int Layer)
	{
		switch (Layer)
		{
		case 1:
			BaseLayer.ClearAllTiles();
			break;
		case 2:
			ItemLayer.ClearAllTiles();
			break;
		case 3:
			CollideLayer.ClearAllTiles();
			break;
		case 4:
			BlockingLayer.ClearAllTiles();
			break;
		case 5:
			BaseLayer.ClearAllTiles();
			ItemLayer.ClearAllTiles();
			CollideLayer.ClearAllTiles();
			BlockingLayer.ClearAllTiles();
			break;
		}
	}

	public void SaveCurrentMap()
	{
		if (settings == null)
		{
			settings = new ES3Settings();
		}
		settings.location = ES3.Location.File;
		int num = CountMaps(save: true);
		string filePath = string.Concat("Map" + num, ".bytes");
		ES3.Save<Dictionary<Vector3Int, TileBase>>("Base", StoreLayer(BaseLayer), filePath, settings);
		ES3.Save<Dictionary<Vector3Int, TileBase>>("Item", StoreLayer(ItemLayer), filePath, settings);
		ES3.Save<Dictionary<Vector3Int, TileBase>>("Collide", StoreLayer(CollideLayer), filePath, settings);
		ES3.Save<Dictionary<Vector3Int, TileBase>>("Block", StoreLayer(BlockingLayer), filePath, settings);
		ES3.Save<Dictionary<Vector3, string>>("MiscObjects", SaveMiscObjects(), filePath, settings);
		Debug.Log((object)("Map saved to slot: " + num));
	}

	public int CountMaps(bool save)
	{
		int i;
		for (i = 0; ES3.FileExists("Map" + i + ".bytes", settings); i++)
		{
		}
		Debug.Log((object)("Total maps found: " + i));
		return i;
	}

	public void LoadMap(int counter, bool random)
	{
		if (settings == null)
		{
			settings = new ES3Settings();
		}
		settings.location = ES3.Location.Resources;
		if (random)
		{
			counter = Random.Range(0, CountMaps(save: false));
		}
		string filePath = "Map" + counter + ".bytes";
		LayerDictionary = ES3.Load<Dictionary<Vector3Int, TileBase>>("Base", filePath, settings);
		PrintLayer(LayerDictionary, BaseLayer);
		LayerDictionary = ES3.Load<Dictionary<Vector3Int, TileBase>>("Item", filePath, settings);
		PrintLayer(LayerDictionary, ItemLayer);
		LayerDictionary = ES3.Load<Dictionary<Vector3Int, TileBase>>("Collide", filePath, settings);
		PrintLayer(LayerDictionary, CollideLayer);
		LayerDictionary = ES3.Load<Dictionary<Vector3Int, TileBase>>("Block", filePath, settings);
		PrintLayer(LayerDictionary, BlockingLayer);
		PrintMiscObjects(ES3.Load<Dictionary<Vector3, string>>("MiscObjects", filePath, settings));
		Debug.Log((object)(counter + " map loaded!"));
	}

	public void StartMap()
	{
		if (!ChangingVariables.instance.DebugMode)
		{
			LoadMap(0, random: true);
		}
	}

	public void PrintLayer(Dictionary<Vector3Int, TileBase> Tiles, Tilemap Layer)
	{
		//IL_001a: Unknown result type (might be due to invalid IL or missing references)
		Layer.ClearAllTiles();
		foreach (KeyValuePair<Vector3Int, TileBase> Tile in Tiles)
		{
			Layer.SetTile(Tile.Key, Tile.Value);
		}
	}

	public void PrintMiscObjects(Dictionary<Vector3, string> MiscObjectsDict)
	{
		//IL_0014: Unknown result type (might be due to invalid IL or missing references)
		//IL_009d: Unknown result type (might be due to invalid IL or missing references)
		//IL_00cd: Unknown result type (might be due to invalid IL or missing references)
		foreach (Transform item in MiscObjectsParent)
		{
			Object.Destroy((Object)(object)((Component)item).gameObject);
		}
		foreach (KeyValuePair<Vector3, string> item2 in MiscObjectsDict)
		{
			string value = item2.Value;
			if (!(value == "MiscObjects/Banner"))
			{
				if (value == "MiscObjects/Torch")
				{
					GameObject val = Object.Instantiate<GameObject>(TorchPrefab);
					val.transform.SetParent(MiscObjectsParent, true);
					val.transform.position = item2.Key;
				}
			}
			else
			{
				GameObject val2 = Object.Instantiate<GameObject>(BannerPrefab);
				val2.transform.SetParent(MiscObjectsParent, true);
				val2.transform.position = item2.Key;
			}
		}
	}

	public Dictionary<Vector3Int, TileBase> StoreLayer(Tilemap tilemap)
	{
		//IL_000c: Unknown result type (might be due to invalid IL or missing references)
		//IL_0011: Unknown result type (might be due to invalid IL or missing references)
		//IL_0014: Unknown result type (might be due to invalid IL or missing references)
		//IL_0019: Unknown result type (might be due to invalid IL or missing references)
		//IL_001c: Unknown result type (might be due to invalid IL or missing references)
		//IL_0021: Unknown result type (might be due to invalid IL or missing references)
		//IL_0026: Unknown result type (might be due to invalid IL or missing references)
		//IL_002b: Unknown result type (might be due to invalid IL or missing references)
		//IL_0043: Unknown result type (might be due to invalid IL or missing references)
		//IL_0049: Unknown result type (might be due to invalid IL or missing references)
		//IL_0058: Unknown result type (might be due to invalid IL or missing references)
		LayerDictionary = new Dictionary<Vector3Int, TileBase>();
		BoundsInt cellBounds = tilemap.cellBounds;
		PositionEnumerator allPositionsWithin = cellBounds.allPositionsWithin;
		PositionEnumerator enumerator = allPositionsWithin.GetEnumerator();
		try
		{
			while (enumerator.MoveNext())
			{
				Vector3Int current = enumerator.Current;
				Vector3Int val = new Vector3Int(current.x, current.y, current.z);
				TileBase tile = tilemap.GetTile(val);
				LayerDictionary.Add(val, tile);
			}
		}
		finally
		{
			((IDisposable)enumerator/*cast due to constrained. prefix*/).Dispose();
		}
		return LayerDictionary;
	}

	public Dictionary<Vector3, string> SaveMiscObjects()
	{
		//IL_001f: Unknown result type (might be due to invalid IL or missing references)
		//IL_0025: Expected Obj, but got Unknown
		//IL_003f: Unknown result type (might be due to invalid IL or missing references)
		//IL_0063: Unknown result type (might be due to invalid IL or missing references)
		MiscObjects = new Dictionary<Vector3, string>();
		foreach (Transform item in MiscObjectsParent)
		{
			Transform val = item;
			Debug.Log((object)string.Concat(((Component)val).tag, " ", val.position, " stored."));
			MiscObjects.Add(val.position, ((Component)val).tag);
		}
		return MiscObjects;
	}
