public class BattleStateMachine : MonoBehaviour
{
	public enum PerformAction
	{
		WAIT,
		TAKEACTION,
		PERFORMACTION
	}

	public enum HeroGUI
	{
		ACTIVE,
		WAITING,
		INPUT1,
		INPUT2,
		DONE
	}

	public PerformAction battleStates;

	public List<HandleTurn> PerformList = new List<HandleTurn>();

	public List<GameObject> HerosInBattle = new List<GameObject>();

	public List<GameObject> EnemiesInBattle = new List<GameObject>();

	public HeroGUI HeroInput;

	public List<GameObject> HerosToManage = new List<GameObject>();

	private HandleTurn HeroChoice;

	public GameObject enemyButton;

	public Transform Spacer;

	public GameObject AttackPanel;

	public GameObject EnemySelectPanel;

	private void Start()
	{
		battleStates = PerformAction.WAIT;
		EnemiesInBattle.AddRange(GameObject.FindGameObjectsWithTag("Enemy"));
		HerosInBattle.AddRange(GameObject.FindGameObjectsWithTag("Hero"));
		HeroInput = HeroGUI.ACTIVE;
		AttackPanel.SetActive(false);
		EnemySelectPanel.SetActive(false);
		EnemyButtons();
	}

	private void Update()
	{
		switch (battleStates)
		{
		case PerformAction.WAIT:
			if (PerformList.Count > 0)
			{
				battleStates = PerformAction.TAKEACTION;
			}
			break;
		case PerformAction.TAKEACTION:
		{
			GameObject val = GameObject.Find(PerformList[0].Attacker);
			if (PerformList[0].Type == "Enemy")
			{
				EnemyStateMachine component = val.GetComponent<EnemyStateMachine>();
				component.HeroToAttack = PerformList[0].AttackersTarget;
				component.currentState = EnemyStateMachine.TurnState.ACTION;
			}
			_ = PerformList[0].Type == "Hero";
			battleStates = PerformAction.PERFORMACTION;
			break;
		}
		}
		switch (HeroInput)
		{
		case HeroGUI.ACTIVE:
			if (HerosToManage.Count > 0)
			{
				((Component)HerosToManage[0].transform.Find("Selector")).gameObject.SetActive(true);
				AttackPanel.SetActive(true);
				HeroInput = HeroGUI.WAITING;
				HeroChoice = new HandleTurn();
			}
			break;
		case HeroGUI.WAITING:
		case HeroGUI.INPUT1:
		case HeroGUI.INPUT2:
		case HeroGUI.DONE:
			break;
		}
	}

	public void CollectActions(HandleTurn input)
	{
		PerformList.Add(input);
	}

	private void EnemyButtons()
	{
		foreach (GameObject item in EnemiesInBattle)
		{
			GameObject val = Object.Instantiate<GameObject>(enemyButton);
			EnemySelectButton component = val.GetComponent<EnemySelectButton>();
			EnemyStateMachine component2 = item.GetComponent<EnemyStateMachine>();
			((Component)val.transform.Find("Text")).gameObject.GetComponent<Text>().text = component2.enemy.name;
			component.EnemyPrefab = item;
			val.transform.SetParent(Spacer, false);
		}
	}

	public void Input1()
	{
		HeroChoice.Attacker = ((Object)HerosToManage[0]).name;
	}
}
