public class HeroStateMachine : MonoBehaviour
{
	public enum TurnState
	{
		PROCESSING,
		ADDTOLIST,
		WAITING,
		SELECTING,
		ACTION,
		DEAD
	}

	private BattleStateMachine BSM;

	public BaseHero hero;

	public TurnState currentState;

	private float CurrentCooldown;

	private float MaxCooldown = 5f;

	public Image ProgressBar;

	public GameObject Selector;

	private void Start()
	{
		CurrentCooldown = Random.Range(0f, 2.5f);
		Selector.SetActive(false);
		currentState = TurnState.PROCESSING;
		BSM = GameObject.Find("BattleManager").GetComponent<BattleStateMachine>();
	}

	private void Update()
	{
		switch (currentState)
		{
		case TurnState.PROCESSING:
			UpgradeProgressBar();
			break;
		case TurnState.ADDTOLIST:
			BSM.HerosToManage.Add(((Component)this).gameObject);
			currentState = TurnState.WAITING;
			break;
		case TurnState.WAITING:
		case TurnState.SELECTING:
		case TurnState.ACTION:
		case TurnState.DEAD:
			break;
		}
	}

	private void UpgradeProgressBar()
	{
		//IL_0046: Unknown result type (might be due to invalid IL or missing references)
		//IL_005b: Unknown result type (might be due to invalid IL or missing references)
		//IL_0065: Unknown result type (might be due to invalid IL or missing references)
		CurrentCooldown += Time.deltaTime;
		float num = CurrentCooldown / MaxCooldown;
		((Component)ProgressBar).transform.localScale = new Vector3(Mathf.Clamp(num, 0f, 1f), ((Component)ProgressBar).transform.localScale.y, ((Component)ProgressBar).transform.localScale.z);
		if (CurrentCooldown >= MaxCooldown)
		{
			currentState = TurnState.ADDTOLIST;
		}
	}
}
