public class TileMove : MonoBehaviour
{
	private float moveSpeed = 5f;

	private float gridSize = 1f;

	private bool allowDiagonals = true;

	private bool correctDiagonalSpeed;

	private Vector2 input;

	private bool isMoving;

	private Vector3 startPosition;

	private Vector3 endPosition;

	private float t;

	private float factor;

	public void Update()
	{
		//IL_0020: Unknown result type (might be due to invalid IL or missing references)
		//IL_0025: Unknown result type (might be due to invalid IL or missing references)
		//IL_0077: Unknown result type (might be due to invalid IL or missing references)
		//IL_007c: Unknown result type (might be due to invalid IL or missing references)
		if (isMoving)
		{
			return;
		}
		input = new Vector2(Input.GetAxis("Horizontal"), Input.GetAxis("Vertical"));
		if (!allowDiagonals)
		{
			if (Mathf.Abs(input.x) > Mathf.Abs(input.y))
			{
				input.y = 0f;
			}
			else
			{
				input.x = 0f;
			}
		}
		if (input != Vector2.zero)
		{
			((MonoBehaviour)this).StartCoroutine(move(((Component)this).transform));
		}
	}

	public IEnumerator move(Transform transform)
	{
		isMoving = true;
		startPosition = transform.position;
		t = 0f;
		endPosition = new Vector3(startPosition.x + (float)Math.Sign(input.x) * gridSize, startPosition.y + (float)Math.Sign(input.y) * gridSize, startPosition.z);
		if (allowDiagonals && correctDiagonalSpeed && input.x != 0f && input.y != 0f)
		{
			factor = 0.7071f;
		}
		else
		{
			factor = 1f;
		}
		while (t < 1f)
		{
			t += Time.deltaTime * (moveSpeed / gridSize) * factor;
			transform.position = Vector3.Lerp(startPosition, endPosition, t);
			yield return null;
		}
		isMoving = false;
		yield return 0;
	}
}
