	public IEnumerator FadeFromBlack(float delay, float speed, string scene)
	{
		if (!FadeFromBlackStarted)
		{
			FadeFromBlackStarted = true;
			FadeFromBlackCanvas.alpha = 1f;
			((Component)FadeFromBlackCanvas).gameObject.SetActive(true);
			yield return (object)new WaitForSeconds(delay);
			if (scene == "EnterTown")
			{
				AudioManager.instance.AudioEffect("EnterTown");
				AudioManager.instance.PlayMusic("Town");
			}
			while (FadeFromBlackCanvas.alpha > 0f)
			{
				CanvasGroup fadeFromBlackCanvas = FadeFromBlackCanvas;
				fadeFromBlackCanvas.alpha -= Time.deltaTime * speed;
				yield return null;
			}
			((Component)FadeFromBlackCanvas).gameObject.SetActive(false);
			FadeFromBlackStarted = false;
		}
	}
}
