	private void Start()
	{
	}

	public void StartNewGame()
	{
		AudioManager.instance.PlayMusic("Town");
		HeroTeamName = ChangingVariables.instance.HeroTeamNameTemp;
		if (HeroTeamName == "")
		{
			HeroTeamName = DataTablesPersisting.instance.GetRandomTeamName();
		}
		ProgressionLevel = 1;
		ProgressionLevelMax = 5;
		ProgressionLevelWins = 0;
		ProgressionLevelLosses = 0;
		ProgressionLevelMaxLosses = 2;
		ProgressionLevelFightsRequired = 3;
		Gold = 300;
		ChangingVariables.instance.SevereInjuries = 0;
		if (GlobalVariables.instance.EndlessModeActivated)
		{
			ProgressionLevelMaxLosses = 1;
			ProgressionLevelMax = 999;
		}
		else if (GlobalVariables.instance.CareerModeActivated)
		{
			if (GlobalVariables.instance.CareerPrestigeLevel >= 3)
			{
				CareerStarsRequiredToProgress = 3;
				CareerStarsRequiredToKeepRank = 2;
			}
			if (GlobalVariables.instance.CareerPrestigeLevel >= 7)
			{
				NumberOfNormalMatches = 10;
			}
			CurrentCareerRank = 1;
			ProgressionLevelMaxLosses = 9999;
			CreateCareerFightList();
		}
		if (GlobalVariables.instance.ChallengeNoLosses)
		{
			ProgressionLevelMaxLosses = 1;
		}
		if (GlobalVariables.instance.ChosenGameDifficulty == 1)
		{
			difficultyLevel = 2;
		}
		else if (GlobalVariables.instance.ChosenGameDifficulty == 2)
		{
			difficultyLevel = 3;
		}
		else
		{
			difficultyLevel = 3;
		}
		SetDifficulty(difficultyLevel);
	}

	public void ChangeGold(int amount)
	{
		//IL_002a: Unknown result type (might be due to invalid IL or missing references)
		//IL_002f: Unknown result type (might be due to invalid IL or missing references)
		Gold += amount;
		if (Gold < 0 && !GlobalVariables.instance.CareerModeActivated)
		{
			Gold = 0;
		}
		Scene activeScene = SceneManager.GetActiveScene();
		if (activeScene.name == "Town")
		{
			TownManager.instance.UpdateGold();
		}
	}

	public int GetGold()
	{
		return Gold;
	}

	public bool CanAfford(int cost)
	{
		if (GetGold() - cost >= 0)
		{
			return true;
		}
		return false;
	}

	public void CheckProgressionStatus()
	{
		if (GlobalVariables.instance.CareerModeActivated)
		{
			if (GlobalVariables.instance.CareerPrestigeLevel >= 3)
			{
				CareerStarsRequiredToProgress = 3;
				CareerStarsRequiredToKeepRank = 2;
			}
			if (GlobalVariables.instance.CareerPrestigeLevel >= 7)
			{
				NumberOfNormalMatches = 10;
			}
			if (ProgressionLevelLosses >= ProgressionLevelMaxLosses)
			{
				LoseGame();
				return;
			}
			if (CurrentCareerRank == 5 && NumberOfQualifierLosses == 1 && NumberOfCareerProgressionStars == 0)
			{
				RemoveChampionshipMatchFromCareerNextFights();
			}
			if (NumberOfCareerProgressionStars + NumberOfQualifierLosses >= NumberOfQualifierMatches || (CurrentCareerRank == 5 && NumberOfQualifierLosses > 0 && NumberOfQualifierLosses + NumberOfCareerProgressionStars >= NumberOfQualifierMatches - 1))
			{
				if (CareerAnimateStatus == 0)
				{
					CareerAnimateStarAmount = NumberOfCareerProgressionStars;
				}
				if (NumberOfCareerProgressionStars >= CareerStarsRequiredToProgress)
				{
					if (CurrentCareerRank == 5)
					{
						if (NumberOfCareerProgressionStars >= NumberOfQualifierMatches)
						{
							CareerPromoteLevel();
						}
						else
						{
							CareerAnimateStatus += 30;
							TownManager.instance.NewRewards.Add("StayAtRank", CareerGetRankNotificationIcon(3));
						}
					}
					else
					{
						CareerPromoteLevel();
					}
				}
				else if (NumberOfCareerProgressionStars >= CareerStarsRequiredToKeepRank)
				{
					CareerAnimateStatus += 30;
					TownManager.instance.NewRewards.Add("StayAtRank", CareerGetRankNotificationIcon(3));
				}
				else
				{
					CareerDemoteLevel();
				}
				if (CurrentCareerRank > HighestCareerRank)
				{
					WinGame();
					return;
				}
				if (NumberOfCareerProgressionStars >= NumberOfQualifierMatches)
				{
					CreateCareerFightList(guaranteedSpecial: true);
				}
				else
				{
					CreateCareerFightList();
				}
				NumberOfCareerProgressionStars = 0;
				NumberOfQualifierLosses = 0;
			}
			difficultyLevel = GlobalVariables.instance.ChosenGameDifficulty + CurrentCareerRank;
			if (CareerNextFights[0] == 19)
			{
				difficultyLevel++;
			}
			else if (CareerNextFights[0] == 20)
			{
				difficultyLevel += 2;
			}
			if (GlobalVariables.instance.CareerPrestigeLevel >= 6 && (CareerNextFights[0] == 19 || CareerNextFights[0] == 20))
			{
				difficultyLevel++;
			}
			SetDifficulty(difficultyLevel);
			ProgressionLevel = CurrentCareerRank;
			return;
		}
		if (ProgressionLevelLosses >= ProgressionLevelMaxLosses)
		{
			LoseGame();
			return;
		}
		if (ProgressionLevelWins + ProgressionLevelLosses >= ProgressionLevelFightsRequired)
		{
			ProgressionLevel++;
			ProgressionLevelLosses = 0;
			ProgressionLevelWins = 0;
			difficultyLevel++;
			SetDifficulty(difficultyLevel);
			if (ProgressionLevel == 2 && !GlobalVariables.instance.EndlessModeActivated)
			{
				TownManager.instance.NewRewards.Add(LocalizationManager.GetTranslation("UI.TOWN/UI.TOWN_levelup"), LevelUp2);
			}
			else if (ProgressionLevel == 3 && !GlobalVariables.instance.EndlessModeActivated)
			{
				TownManager.instance.NewRewards.Add(LocalizationManager.GetTranslation("UI.TOWN/UI.TOWN_levelup"), LevelUp3);
				ChangeGold(200);
				TownManager.instance.StoredInfoText = LocalizationManager.GetTranslation("UI.TOWN/UI.TOWN_managermsg2");
				((MonoBehaviour)this).StartCoroutine(TownManager.instance.ShowInfo());
			}
			else if (ProgressionLevel == 4 && !GlobalVariables.instance.EndlessModeActivated)
			{
				TownManager.instance.NewRewards.Add(LocalizationManager.GetTranslation("UI.TOWN/UI.TOWN_levelup"), LevelUp4);
				NextEvent = DataTables.instance.GetSpecificSpecialEvent(1004);
			}
			else if (ProgressionLevel == 5 && !GlobalVariables.instance.EndlessModeActivated)
			{
				TownManager.instance.NewRewards.Add(LocalizationManager.GetTranslation("UI.TOWN/UI.TOWN_levelup"), LevelUp5);
				ChangeGold(400);
				TownManager.instance.StoredInfoText = LocalizationManager.GetTranslation("UI.TOWN/UI.TOWN_managermsg3");
				((MonoBehaviour)this).StartCoroutine(TownManager.instance.ShowInfo());
			}
			else if (ProgressionLevel == 6 && !GlobalVariables.instance.EndlessModeActivated)
			{
				NextEvent = DataTables.instance.GetSpecificSpecialEvent(1008);
			}
		}
		if (GlobalVariables.instance.EndlessModeActivated)
		{
			if (ProgressionLevel >= 12)
			{
				ProgressionLevelFightsRequired = 1;
			}
			else if (ProgressionLevel >= 4)
			{
				ProgressionLevelFightsRequired = 2;
			}
		}
		else if (ProgressionLevel > ProgressionLevelMax && ProgressionLevelWins == 0 && ProgressionLevelLosses == 0)
		{
			difficultyLevel++;
			SetDifficulty(difficultyLevel);
		}
		else if (ProgressionLevel > ProgressionLevelMax && ProgressionLevelWins > 0)
		{
			WinGame();
		}
		else if (ProgressionLevel > ProgressionLevelMax)
		{
			LoseGame();
		}
	}

