			break;
		default:
		{
			float num = 0.05f;
			if (level >= 20)
			{
				num = (float)level / 1000f + 0.04f;
			}
			ChangingVariables.instance.EnemyDifficulty = 4;
			ChangingVariables.instance.EnemyTeamSize = 4;
