	public void GloryLevelAdjustment()
	{
		if (GlobalVariables.instance.CareerModeActivated)
		{
			ChangingVariables.instance.CareerWageModifier = 0f;
			_ = GlobalVariables.instance.CareerPrestigeLevel;
			_ = 1;
			if (GlobalVariables.instance.CareerPrestigeLevel >= 2)
			{
				ChangingVariables.instance.EnemyTeamRarity++;
				ChangingVariables.instance.EnemyDifficulty = 5;
			}
			if (GlobalVariables.instance.CareerPrestigeLevel >= 3)
			{
				CareerStarsRequiredToProgress = 3;
				CareerStarsRequiredToKeepRank = 2;
			}
			if (GlobalVariables.instance.CareerPrestigeLevel >= 4)
			{
				ChangingVariables.instance.CareerWageModifier = 0.5f;
			}
			if (GlobalVariables.instance.CareerPrestigeLevel >= 5)
			{
				ChangingVariables.instance.EnemyTeamRarity++;
				ChangingVariables.instance.EnemyItemRarityPoints += 2;
			}
			_ = GlobalVariables.instance.CareerPrestigeLevel;
			_ = 6;
			if (GlobalVariables.instance.CareerPrestigeLevel >= 7)
			{
				ChangingVariables.instance.EnemyTeamStatModifier += 0.1f;
				NumberOfNormalMatches = 10;
			}
			if (GlobalVariables.instance.CareerPrestigeLevel >= 8)
			{
				ChangingVariables.instance.SevereInjuries = 1;
			}
			if (GlobalVariables.instance.CareerPrestigeLevel >= 9)
			{
				ChangingVariables.instance.EnemyTeamRarity++;
				ChangingVariables.instance.EnemyItemRarityPoints += 3;
			}
			if (GlobalVariables.instance.CareerPrestigeLevel >= 10)
			{
				ChangingVariables.instance.SevereInjuries = 2;
			}
			if (GlobalVariables.instance.CareerPrestigeLevel >= 11)
			{
				ChangingVariables.instance.EnemyTeamStatModifier += 0.1f * (float)(GlobalVariables.instance.CareerPrestigeLevel - 10);
				ChangingVariables.instance.EnemyItemRarityPoints += GlobalVariables.instance.CareerPrestigeLevel - 10;
			}
			return;
		}
		if (GlobalVariables.instance.GloryLevel >= 1)
		{
			ChangingVariables.instance.SevereInjuries = 1;
		}
		if (GlobalVariables.instance.GloryLevel >= 2)
		{
			ChangingVariables.instance.EnemyDifficulty = 5;
		}
		if (GlobalVariables.instance.GloryLevel >= 3)
		{
			ChangingVariables.instance.EnemyTeamRarity++;
			ChangingVariables.instance.EnemyItemRarityPoints += 2;
		}
		if (GlobalVariables.instance.GloryLevel >= 4)
		{
			ChangingVariables.instance.EnemyTeamBossChance += 5;
		}
		if (GlobalVariables.instance.GloryLevel >= 5 && !GlobalVariables.instance.EndlessModeActivated)
		{
			ProgressionLevelFightsRequired = 4;
		}
		if (GlobalVariables.instance.GloryLevel >= 6)
		{
			ChangingVariables.instance.SevereInjuries = 2;
		}
		if (GlobalVariables.instance.GloryLevel >= 7)
		{
			ChangingVariables.instance.EnemyTeamStatModifier += 0.1f;
		}
		if (GlobalVariables.instance.GloryLevel >= 8)
		{
			ChangingVariables.instance.EnemyTeamRarity++;
			ChangingVariables.instance.EnemyItemRarityPoints += 2;
		}
		if (GlobalVariables.instance.GloryLevel >= 9)
		{
			ChangingVariables.instance.EnemyTeamBossChance += 5;
		}
		if (GlobalVariables.instance.GloryLevel >= 10 && !GlobalVariables.instance.EndlessModeActivated)
		{
			ProgressionLevelFightsRequired = 5;
		}
		if (GlobalVariables.instance.GloryLevel >= 11)
		{
			ChangingVariables.instance.EnemyTeamSize++;
		}
		if (GlobalVariables.instance.GloryLevel >= 12)
		{
			ChangingVariables.instance.EnemyTeamStatModifier += 0.1f;
		}
		if (GlobalVariables.instance.GloryLevel >= 13)
		{
			ChangingVariables.instance.EnemyTeamRarity++;
			ChangingVariables.instance.EnemyItemRarityPoints += 2;
		}
		if (GlobalVariables.instance.GloryLevel >= 14)
		{
			ChangingVariables.instance.EnemyTeamBossChance += 5;
		}
		if (GlobalVariables.instance.GloryLevel >= 15)
		{
			ChangingVariables.instance.EnemyTeamSize++;
		}
		if (GlobalVariables.instance.GloryLevel >= 16 && ProgressionLevel >= 2)
		{
			ChangingVariables.instance.EnemyTeamStatModifier += 0.1f * (float)(GlobalVariables.instance.GloryLevel - 15);
			ChangingVariables.instance.EnemyTeamBossChance += 3 * (GlobalVariables.instance.GloryLevel - 15);
		}
	}

	public void LoseGame()
	{
		GameHasEnded = true;
		TownManager.instance.ShowGameEnd(Victory: false);
		SaveManager.instance.DeleteSave();
		if (GlobalVariables.instance.EndlessModeActivated && TotalWins > ProfileManager.instance.HighestEndlessScore)
		{
			ProfileManager.instance.HighestEndlessScore = TotalWins;
			SubmitFinalScore();
			SaveManager.instance.SaveProfile();
		}
	}

	public void WinGame()
	{
		ProfileManager.instance.TotalGameWins++;
		GameHasEnded = true;
		if (GlobalVariables.instance.CareerModeActivated)
		{
			ProfileManager.instance.CareerModeWins++;
		}
		SteamAchievements.instance.UnlockSteamAchievement("ACH_Win1");
		if (ProfileManager.instance.TotalGameWins >= 5)
		{
			SteamAchievements.instance.UnlockSteamAchievement("ACH_Win5");
		}
		if (ProfileManager.instance.TotalGameWins >= 10)
		{
			SteamAchievements.instance.UnlockSteamAchievement("ACH_Win10");
		}
		if (ProfileManager.instance.TotalGameWins >= 50)
		{
			SteamAchievements.instance.UnlockSteamAchievement("ACH_Win50");
		}
		if (!ProgressionList.Contains(item: false))
		{
			SteamAchievements.instance.UnlockSteamAchievement("ACH_WinAllMatches");
		}
		if (DeadHeroes.Count == 0)
		{
			SteamAchievements.instance.UnlockSteamAchievement("ACH_EmptyGraveyard");
		}
		else if (DeadHeroes.Count >= 10)
		{
			SteamAchievements.instance.UnlockSteamAchievement("ACH_FullGraveyard");
		}
		if (!GlobalVariables.instance.CareerModeActivated)
		{
			SubmitFinalScore();
		}
		if (GlobalVariables.instance.GloryLevel == ProfileManager.instance.GloryLevelUnlocked)
		{
			ProfileManager.instance.IncreaseGloryUnlockLevel();
		}
		if (GlobalVariables.instance.CareerModeActivated && GlobalVariables.instance.CareerPrestigeLevel == ProfileManager.instance.PrestigeLevelUnlocked)
		{
			ProfileManager.instance.IncreasePrestigeUnlockLevel();
		}
		if (GlobalVariables.instance.ChosenGameDifficulty == 1)
		{
			if (GlobalVariables.instance.ChallengeDeadIsDead)
			{
				ProfileManager.instance.ChallengeCompletedDeadisDeadEasy = true;
			}
			if (GlobalVariables.instance.ChallengeLongTournament && !GlobalVariables.instance.CareerModeActivated)
			{
				ProfileManager.instance.ChallengeCompletedLongtournamentEasy = true;
			}
			if (GlobalVariables.instance.ChallengeBurlyEnemies)
			{
				ProfileManager.instance.ChallengeCompletedBurlyenemiesEasy = true;
			}
			if (GlobalVariables.instance.ChallengeNeedyEmperor)
			{
				ProfileManager.instance.ChallengeCompletedNeedyEmperorEasy = true;
			}
			if (GlobalVariables.instance.ChallengeRandomSkills)
			{
				ProfileManager.instance.ChallengeCompletedRandomskillsEasy = true;
			}
			if (GlobalVariables.instance.ChallengeSmallTeam)
			{
				ProfileManager.instance.ChallengeCompletedSmallteamEasy = true;
			}
			if (GlobalVariables.instance.ChallengeNoDeaths)
			{
				ProfileManager.instance.ChallengeCompletedNodeathsEasy = true;
			}
			if (GlobalVariables.instance.ChallengeNoLosses)
			{
				ProfileManager.instance.ChallengeCompletedNolossesEasy = true;
			}
			if (GlobalVariables.instance.ChallengeLoneSurvivor)
			{
				ProfileManager.instance.ChallengeCompletedLoneSurvivorEasy = true;
			}
			if (GlobalVariables.instance.ChallengeBeastMode)
			{
				ProfileManager.instance.ChallengeCompletedBeastModeEasy = true;
			}
			if (ProfileManager.instance.GetCompletedChallengesAmount(Normal: false) == 8)
			{
				SteamAchievements.instance.UnlockSteamAchievement("ACH_RelaxedChallengesCompleted");
			}
		}
		else
		{
			if (GlobalVariables.instance.ChallengeDeadIsDead)
			{
				ProfileManager.instance.ChallengeCompletedDeadisDead = true;
			}
			if (GlobalVariables.instance.ChallengeLongTournament && !GlobalVariables.instance.CareerModeActivated)
			{
				ProfileManager.instance.ChallengeCompletedLongtournament = true;
			}
			if (GlobalVariables.instance.ChallengeBurlyEnemies)
			{
				ProfileManager.instance.ChallengeCompletedBurlyenemies = true;
			}
			if (GlobalVariables.instance.ChallengeNeedyEmperor)
			{
				ProfileManager.instance.ChallengeCompletedNeedyEmperor = true;
			}
			if (GlobalVariables.instance.ChallengeRandomSkills)
			{
				ProfileManager.instance.ChallengeCompletedRandomskills = true;
			}
			if (GlobalVariables.instance.ChallengeSmallTeam)
			{
				ProfileManager.instance.ChallengeCompletedSmallteam = true;
			}
			if (GlobalVariables.instance.ChallengeNoDeaths)
			{
				ProfileManager.instance.ChallengeCompletedNodeaths = true;
			}
			if (GlobalVariables.instance.ChallengeNoLosses)
			{
				ProfileManager.instance.ChallengeCompletedNolosses = true;
			}
			if (GlobalVariables.instance.ChallengeLoneSurvivor)
			{
				ProfileManager.instance.ChallengeCompletedLoneSurvivor = true;
			}
			if (GlobalVariables.instance.ChallengeBeastMode)
			{
				ProfileManager.instance.ChallengeCompletedBeastMode = true;
			}
			if (ProfileManager.instance.GetCompletedChallengesAmount(Normal: true) == 8)
			{
				SteamAchievements.instance.UnlockSteamAchievement("ACH_NormalChallengesCompleted");
			}
		}
		((MonoBehaviour)this).StartCoroutine(TownManager.instance.VictoryAnimation());
		SaveManager.instance.DeleteSave();
		SaveManager.instance.SaveProfile();
	}

	public void FillTeamSlots()
	{
		int num = GlobalVariables.instance.TeamLimit - Team.Count;
		for (int i = 0; i < num; i++)
		{
			Team.Add(null);
		}
	}

	public bool IsThereRoomInTeam()
	{
		if (GetTeamSize() < GlobalVariables.instance.TeamLimit)
		{
			return true;
		}
		return false;
	}

	public int GetTeamSize()
	{
		int num = 0;
		foreach (CharacterTemplate item in Team)
		{
			if ((Object)(object)item != (Object)null)
			{
				num++;
			}
		}
		return num;
	}

	public void AddToTeam(CharacterTemplate Character, int spot = 0)
	{
		//IL_00b1: Unknown result type (might be due to invalid IL or missing references)
		//IL_00b6: Unknown result type (might be due to invalid IL or missing references)
		if (spot != 0)
		{
			if ((Object)(object)Team[spot] != (Object)null)
			{
				Debug.Log((object)"!!!This shouldn't happen: Team slot was already filled and now replaced. This is checked elsewhere (TeamDragHandler)");
			}
			Team[spot] = Character;
		}
		else
		{
			foreach (CharacterTemplate item in Team)
			{
				if ((Object)(object)item == (Object)null)
				{
					Team[spot] = Character;
					break;
				}
				spot++;
			}
		}
		EquipmentManager.instance.AddGearModifiers(Character, EquipmentManager.instance.ListOfHeroEquipLists[spot]);
		Character.CharacterEquipList = EquipmentManager.instance.ListOfHeroEquipLists[spot];
		Character.UpdateHPMP();
		Scene activeScene = SceneManager.GetActiveScene();
		if (activeScene.name == "Town")
		{
			TownManager.instance.RedrawTeamBars();
		}
	}

	public void RemoveFromTeam(CharacterTemplate Character)
	{
		//IL_005c: Unknown result type (might be due to invalid IL or missing references)
		//IL_0061: Unknown result type (might be due to invalid IL or missing references)
		int num = 0;
		using (List<CharacterTemplate>.Enumerator enumerator = Team.GetEnumerator())
		{
			while (enumerator.MoveNext() && !((Object)(object)enumerator.Current == (Object)(object)Character))
			{
				num++;
			}
		}
		Team[num] = null;
		EquipmentManager.instance.RemoveGearModifiers(Character);
		Character.UpdateHPMP();
		Scene activeScene = SceneManager.GetActiveScene();
		if (activeScene.name == "Town")
		{
			TownManager.instance.RedrawTeamBars();
		}
		Character.CharacterEquipList = null;
	}

	public void SwitchSlotsWithinTeam(CharacterTemplate DraggedCharacter, int movingtoslotindex)
	{
		//IL_0088: Unknown result type (might be due to invalid IL or missing references)
		//IL_008d: Unknown result type (might be due to invalid IL or missing references)
		int num = 0;
		using (List<CharacterTemplate>.Enumerator enumerator = Team.GetEnumerator())
		{
			while (enumerator.MoveNext() && !((Object)(object)enumerator.Current == (Object)(object)DraggedCharacter))
			{
				num++;
			}
		}
		if ((Object)(object)Team[movingtoslotindex] != (Object)null)
		{
			CharacterTemplate value = Team[movingtoslotindex];
			Team[num] = value;
		}
		else
		{
			Team[num] = null;
		}
		Team[movingtoslotindex] = DraggedCharacter;
		Scene activeScene = SceneManager.GetActiveScene();
		if (activeScene.name == "Town")
		{
			TownManager.instance.RedrawTeamBars();
		}
		EquipmentManager.instance.RecheckEquipListOrder();
		EquipmentManager.instance.RecalculateTeamModifiers();
	}

	public CharacterTemplate GetRandomTeamMember()
	{
		if (GetTeamSize() == 0)
		{
			return null;
		}
		List<CharacterTemplate> list = new List<CharacterTemplate>();
		foreach (CharacterTemplate item in Team)
		{
			if ((Object)(object)item != (Object)null)
			{
				list.Add(item);
			}
		}
		return list[Random.Range(0, list.Count)];
	}

