	public float CalculateAudienceExcitedness()
	{
		float num = 0f;
		foreach (CharacterTemplate item in Team)
		{
			if ((Object)(object)item != (Object)null)
			{
				num += item.EstimateCharacterQuality();
			}
		}
		foreach (CharacterTemplate item2 in EnemyTeam)
		{
			if ((Object)(object)item2 != (Object)null)
			{
				num += item2.EstimateCharacterQuality();
			}
		}
		num *= 5f;
		if (ProgressionLevel == 1)
		{
			num *= 0.65f;
		}
		else if (ProgressionLevel == 2)
		{
			num *= 0.7f;
		}
		else if (ProgressionLevel == 3)
		{
			num *= 0.75f;
		}
		else if (ProgressionLevel == 4)
		{
			num *= 0.85f;
		}
		else if (ProgressionLevel == 5)
		{
			num *= 0.95f;
		}
		else if (ProgressionLevel >= 5 && GlobalVariables.instance.EndlessModeActivated)
		{
			num *= 1f;
		}
		else if (ProgressionLevel >= 5)
		{
			num *= 1.2f;
		}
		return num;
	}

	public bool CheckFightPreRequisites()
	{
		if (GetTeamSize() <= 0)
		{
			UIManager.instance.ShowErrorMessage(LocalizationManager.GetTranslation("MESSAGE/MESSAGE_1unit"), 0.6f);
			return false;
		}
		if (GlobalVariables.instance.NoDuplicateRaceInTeam)
		{
			List<CharacterRace> list = new List<CharacterRace>();
			foreach (CharacterTemplate item in Team)
			{
				if ((Object)(object)item != (Object)null)
				{
					if (list.Contains(item.Race))
					{
						UIManager.instance.ShowErrorMessage(LocalizationManager.GetTranslation("MESSAGE/MESSAGE_racelimit"), 0.6f);
						return false;
					}
					list.Add(item.Race);
				}
			}
		}
		if (GlobalVariables.instance.ChallengeSmallTeam && GetTeamSize() > 3)
		{
			UIManager.instance.ShowErrorMessage(LocalizationManager.GetTranslation("MESSAGE/MESSAGE_3unit"), 0.6f);
			return false;
		}
		if (GlobalVariables.instance.ChallengeLoneSurvivor && GetTeamSize() > 1)
		{
			UIManager.instance.ShowErrorMessage(LocalizationManager.GetTranslation("MESSAGE/MESSAGE_only1unit"), 0.6f);
			return false;
		}
		if (GlobalVariables.instance.CareerModeActivated && TownManager.instance.TotalWages > Gold)
		{
			if (LendingStatus == 0)
			{
				TownManager.instance.LendMoneyForMatch();
				return false;
			}
			if (LendingStatus != 1 && LendingStatus == 2)
			{
				TownManager.instance.LendMoneyForMatch();
				return false;
			}
		}
		return true;
	}

	public void StartFight()
	{
		if (!CheckFightPreRequisites())
		{
			return;
		}
		AudioManager.instance.FadeOutMusic();
		SaveManager.instance.Save();
		foreach (CharacterTemplate item in Team)
		{
			if ((Object)(object)item == (Object)null)
			{
				continue;
			}
			if (GlobalVariables.instance.ChallengeRandomSkills)
			{
				item.RandomizeSkills();
				continue;
			}
			foreach (Perk characterPerk in item.CharacterPerks)
			{
				if (characterPerk.name == "Amnesiac")
				{
					item.RandomizeSkills();
				}
			}
		}
		foreach (CharacterTemplate item2 in EnemyTeam)
		{
			if ((Object)(object)item2 == (Object)null)
			{
				continue;
			}
			foreach (Perk characterPerk2 in item2.CharacterPerks)
			{
				if (characterPerk2.name == "Amnesiac")
				{
					Debug.Log((object)"<color=red>!!!Enemy has Amnesiac!!!");
				}
			}
		}
		EquipmentManager.instance.RecalculateTeamModifiers();
		EquipmentManager.instance.RecalculateEnemyModifiers();
		if (GlobalVariables.instance.CareerModeActivated)
		{
			CurrentTypeOfMatch = CareerNextFights[0];
			CareerModeCheckNextMatches();
			ListOfCareerModeTeams.Clear();
			if (LendingStatus != 1 || TownManager.instance.TotalWages <= Gold)
			{
				LendingStatus = 0;
			}
		}
		AudioManager.instance.AudioEffect("ButtonClickSpecial");
		UIManager.instance.CloseAllTooltips();
		SceneManager.LoadScene("GladGBattle", (LoadSceneMode)0);
	}

	public void PermanentlyKillUnit(CharacterTemplate Unit, bool DestroyGear = false, bool Retired = false)
	{
		//IL_0037: Unknown result type (might be due to invalid IL or missing references)
		//IL_003c: Unknown result type (might be due to invalid IL or missing references)
		if (Team.Contains(Unit))
		{
			Debug.Log((object)("Killed: " + Unit));
			if (DestroyGear)
			{
				EquipmentManager.instance.DestroyUnitGear(Team.IndexOf(Unit));
				Scene activeScene = SceneManager.GetActiveScene();
				if (activeScene.name == "Town")
				{
					EquipmentManager.instance.RedrawGear();
				}
			}
			RemoveFromTeam(Unit);
		}
		if (RosterManager.instance.Roster.Contains(Unit))
		{
			Debug.Log((object)("Killed: " + Unit));
			RosterManager.instance.RemoveFromRoster(Unit);
		}
		if (Retired)
		{
			if (GlobalVariables.instance.RetireGivesMoney > 0f)
			{
				ChangeGold(Mathf.RoundToInt((float)Unit.characterValue * GlobalVariables.instance.RetireGivesMoney));
			}
		}
		else
		{
			DeadHeroes.Add(Unit);
		}
	}

	public List<int> CreateRarityList(int Amount, int TotalRarity, int variance, bool item = false)
	{
		if (TotalRarity < 0)
		{
			TotalRarity = 0;
		}
		if (variance > TotalRarity)
		{
			variance = TotalRarity;
		}
		List<int> list = new List<int>();
		int num = -999;
		int num2 = 0;
		int num3 = 1;
		int num4 = 1;
		if (item)
		{
			num3 = 0;
			num4 = 2;
			if ((float)TotalRarity / (float)Amount >= 5f)
			{
				TotalRarity = Amount * 5;
				num4 = 0;
			}
			else if ((float)TotalRarity / (float)Amount > 4.3f)
			{
				num4 = 1;
			}
		}
		else if ((float)TotalRarity / (float)Amount > 5f)
		{
			TotalRarity = Amount * 5;
		}
		int num5 = Mathf.RoundToInt((float)TotalRarity / (float)Amount);
		while (num < TotalRarity - variance || num > TotalRarity)
		{
			num = 0;
			list.Clear();
			for (int i = 0; i < Amount; i++)
			{
				int num6 = Random.Range(Mathf.Clamp(num5 - num4, num3, 5), Mathf.Clamp(num5 + 2, num3, 6));
				num += num6;
				list.Add(num6);
			}
			num2++;
			if (num2 <= 30)
			{
				continue;
			}
			Debug.Log((object)("CreateRarityList: Unable to find a solution, defaulting " + TotalRarity + ", " + Amount + ", " + variance + ", " + num + ", " + list.Count));
			list.Clear();
			num = 0;
			for (int j = 0; j < Amount; j++)
			{
				if (num > TotalRarity)
				{
					if (item)
					{
						list.Add(0);
					}
					else
					{
						list.Add(1);
					}
				}
				else
				{
					list.Add(num5);
					num += num5;
				}
			}
			break;
		}
		string text = "";
		foreach (int item2 in list)
		{
			text = text + item2 + ", ";
		}
		return list;
	}

	public void CreateEnemyTeam(int initRarity = 0, int unitRarityPoints = 12, int itemRarityPoints = 36)
	{
		EnemyTeam.Clear();
		EquipmentManager.instance.ClearEnemyGear();
		EnemyTeamName = DataTablesPersisting.instance.GetRandomTeamName();
		List<CharacterRace> list = new List<CharacterRace>();
		int num = Mathf.Clamp(ChangingVariables.instance.EnemyTeamSize, 1, 4);
		if (ProgressionList.Count == 0)
		{
			unitRarityPoints /= num;
			itemRarityPoints /= num;
			num = 1;
		}
		float num2 = ChangingVariables.instance.EnemyTeamStatModifier;
		int num3 = ChangingVariables.instance.EnemyTeamBossChance;
		if (GlobalVariables.instance.GloryLevel >= 4 && !GlobalVariables.instance.EndlessModeActivated)
		{
			int num4 = 1;
			if (GlobalVariables.instance.GloryLevel >= 17)
			{
				num4 = 4;
			}
			else if (GlobalVariables.instance.GloryLevel >= 14)
			{
				num4 = 3;
			}
			else if (GlobalVariables.instance.GloryLevel >= 9)
			{
				num4 = 2;
			}
			if (ProgressionLevel == 1)
			{
				num2 -= 0.05f * (float)num4;
				num3 -= 5 * num4;
			}
			else if (ProgressionLevel == 2)
			{
				num2 -= 0.03f * (float)num4;
				num3 -= 3 * num4;
			}
			else if (ProgressionLevel != 3)
			{
				if (ProgressionLevel == 4)
				{
					num2 += 0.03f * (float)num4;
					num3 += 3 * num4;
				}
				else if (ProgressionLevel == 5)
				{
					num2 += 0.05f * (float)num4;
					num3 += 4 * num4;
				}
				else if (ProgressionLevel == 6)
				{
					num2 += 0.05f * (float)num4;
					num3 += 5 * num4;
				}
			}
		}
		int num5 = 0;
		List<int> list2 = CreateRarityList(num, unitRarityPoints, 2);
		bool flag = false;
		foreach (int item in list2)
		{
			int num6 = Random.Range(0, 100);
			CharacterTemplate characterTemplate;
			do
			{
				if (ProgressionLevel > ProgressionLevelMax && ProgressionLevelWins == 0 && num5 == 0)
				{
					characterTemplate = Object.Instantiate<CharacterTemplate>(DataTables.instance.GetRandomBoss());
					continue;
				}
				if (num6 < num3)
				{
					characterTemplate = Object.Instantiate<CharacterTemplate>(DataTables.instance.GetRandomBoss());
					continue;
				}
				if (!GlobalVariables.instance.ChallengeBeastMode || flag)
				{
					characterTemplate = ((!GlobalVariables.instance.ChallengeBeastMode || Random.Range(0, 100) >= 15) ? Object.Instantiate<CharacterTemplate>(DataTables.instance.GetRandomCharacter()) : Object.Instantiate<CharacterTemplate>(DataTables.instance.GetRandomBoss()));
					continue;
				}
				characterTemplate = Object.Instantiate<CharacterTemplate>(DataTables.instance.GetRandomBoss());
				flag = true;
			}
			while (GlobalVariables.instance.NoDuplicateRaceInTeam && list.Contains(characterTemplate.Race));
			list.Add(characterTemplate.Race);
			characterTemplate.Initialize(item, AI: true, 0, 5, num2);
			EnemyTeam.Add(characterTemplate);
			characterTemplate.CharacterEquipList = EquipmentManager.instance.ListOfEnemyEquipLists[num5];
			num5++;
		}
		SkillUpEnemyTeam(EnemyTeam, initRarity);
		PerkUpEnemyTeam(EnemyTeam, initRarity);
		DressUpEnemyTeam(EnemyTeam, itemRarityPoints);
		EquipmentManager.instance.RecalculateEnemyModifiers();
		foreach (CharacterTemplate item2 in EnemyTeam)
		{
			if (item2.DoesThisCharacterHaveABow())
			{
				AIArcherAdjustments(item2, initRarity);
			}
			item2.CreateListOfCharacterPerks();
			item2.CreateListOfCharacterSkills();
		}
	}

	public void DressUpEnemyTeam(List<CharacterTemplate> ThisTeam, int rarityPoints, int teamslot = 1)
	{
		int num = 1;
		List<int> list = CreateRarityList(3 * ThisTeam.Count, rarityPoints, 4, item: true);
		int num2 = 0;
		foreach (CharacterTemplate item in ThisTeam)
		{
			if (list[num2] > 0)
			{
				DressUpCharacter(item, num, EquipmentSlot.Weapon, item.RaceMainType, list[num2], teamslot);
			}
			num2++;
			if (list[num2] > 0)
			{
				DressUpCharacter(item, num, EquipmentSlot.Chest, item.RaceMainType, list[num2], teamslot);
			}
			num2++;
			if (list[num2] > 0)
			{
				DressUpCharacter(item, num, EquipmentSlot.Accessory, item.RaceMainType, list[num2], teamslot);
			}
			num2++;
			num++;
		}
	}

	public void DressUpCharacter(CharacterTemplate EnemyChar, int Enemyindex, EquipmentSlot slot, classType type = classType.Balanced, int rarity = 3, int teamslot = 1)
	{
		bool exactMatch = false;
		if (Random.Range(0, 100) < difficultyLevel * 5)
		{
			type = ((EnemyChar.STR.GetValue() < EnemyChar.WIS.GetValue()) ? classType.Mage : classType.Warrior);
			exactMatch = true;
		}
		int bowchance = 0;
		if (ProfileManager.instance.DLC_ContentEnabled && slot == EquipmentSlot.Weapon && EnemyChar.AGI.GetValue() > EnemyChar.STR.GetValue() && EnemyChar.AGI.GetValue() > EnemyChar.WIS.GetValue())
		{
			bowchance = ChangingVariables.instance.AIArcherChance;
		}
		Equipment equipment = Object.Instantiate<Equipment>(DataTables.instance.GetRandomEquipment(slot, type, exactMatch, bowchance));
		equipment.Initialize(rarity);
		equipment = EnsureAIhasAIfriendlyequipment(equipment, type);
		EquipmentManager.instance.AddEnemyGear(Enemyindex, equipment, teamslot);
	}

	public Equipment EnsureAIhasAIfriendlyequipment(Equipment equipment, classType type)
	{
		if (equipment.Bow)
		{
			equipment.givesSkill = DataTables.instance.GetRandomBowSkill(0, AI: true);
		}
		else if ((Object)(object)equipment.givesSkill != (Object)null && !equipment.givesSkill.AIfriendly)
		{
			equipment.givesSkill = DataTables.instance.GetRandomSkill(0, 0, AI: true, type);
		}
		return equipment;
	}

	public void AIArcherAdjustments(CharacterTemplate Enemy, int rarityboost)
	{
		try
		{
			Enemy.CharacterEquipList[0].ArcheryDamagemodifier += rarityboost;
		}
		catch
		{
			Debug.Log((object)"Not able to adjust enemy archer bow");
		}
		try
		{
			if (Enemy.CharacterEquipList.Count >= 2)
			{
				Enemy.CharacterEquipList[1].ArcherizeEquipment();
			}
			if (Enemy.CharacterEquipList.Count >= 3)
			{
				Enemy.CharacterEquipList[2].ArcherizeEquipment();
			}
		}
		catch
		{
			Debug.Log((object)"Not able to adjust enemy archer equipment");
		}
		List<Skill> list = new List<Skill>();
		list.Add(Enemy.CharacterEquipList[0].givesSkill);
		int num = 60;
		for (int i = 1; i < 5; i++)
		{
			if ((i == 1 && (Object)(object)Enemy.Skill1 == (Object)null) || (i == 2 && (Object)(object)Enemy.Skill2 == (Object)null) || (i == 3 && (Object)(object)Enemy.Skill3 == (Object)null) || (i == 4 && (Object)(object)Enemy.Skill4 == (Object)null))
			{
				continue;
			}
			if (i == 4 && (Object)(object)Enemy.Skill4 != (Object)null)
			{
				Enemy.Skill4 = null;
			}
			else
			{
				if (list.Count >= 4)
				{
					continue;
				}
				int num2 = 0;
				while (true)
				{
					Skill skill = null;
					if (Random.Range(0, 100) >= num)
					{
						break;
					}
					skill = DataTables.instance.GetRandomBowSkill(0, AI: true);
					if (!list.Contains(skill))
					{
						switch (i)
						{
						case 1:
							Enemy.Skill1 = skill;
							break;
						case 2:
							Enemy.Skill2 = skill;
							break;
						case 3:
							Enemy.Skill3 = skill;
							break;
						case 4:
							Enemy.Skill4 = skill;
							break;
						}
						list.Add(skill);
						break;
					}
					num2++;
					if (num2 >= 30)
					{
						Debug.Log((object)"AI Archer adjustments loop counter went over 30");
						break;
					}
				}
			}
		}
	}

	public void PerkUpEnemyTeam(List<CharacterTemplate> ThisTeam, int level = 0)
	{
		int num = level * 6;
		foreach (CharacterTemplate item in ThisTeam)
		{
			int num2 = Random.Range(0, 100);
			int num3 = item.HowManyPerks();
			int num4 = ((num2 < 5 + num && level > 2) ? Mathf.Clamp(2, 0, 4 - num3) : ((num2 < 15 + num) ? Mathf.Clamp(1, 0, 4 - num3) : 0));
			for (int i = 0; i < num4; i++)
			{
				PerkUpEnemyCharacter(item, level);
			}
		}
	}

	public void PerkUpEnemyCharacter(CharacterTemplate Character, int level = 0)
	{
		int num = 0;
		do
		{
			Perk randomPerk = DataTables.instance.GetRandomPerk(level * 5, 0, PreventAmnesiac: true);
			if (!Character.DoesCharHavePerk(randomPerk))
			{
				Character.LearnPerk(randomPerk);
				break;
			}
			num++;
		}
		while (num != 50);
	}

	public void SkillUpEnemyTeam(List<CharacterTemplate> ThisTeam, int level = 0)
	{
		int num = level * 6;
		foreach (CharacterTemplate item in ThisTeam)
		{
			item.CreateListOfCharacterSkills();
			int num2 = Random.Range(0, 100);
			int num3 = item.HowManySkills();
			int num4;
			if (num2 < num)
			{
				num4 = Mathf.Clamp(3, 0, 4 - num3);
			}
			else
			{
				num4 = ((num2 < 10 + num) ? Mathf.Clamp(2, 0, 4 - num3) : ((num2 < 30 + num) ? Mathf.Clamp(1, 0, 4 - num3) : 0));
			}
			if (level < 3)
			{
				num4 = Mathf.Clamp(num4, 0, 3 - num3);
			}
			for (int i = 0; i < num4; i++)
			{
				SkillUpEnemyCharacter(item, level);
			}
		}
	}

	public void SkillUpEnemyCharacter(CharacterTemplate Character, int level = 0)
	{
		bool flag = false;
		classType type = Character.RaceMainType;
		if (Random.Range(0, 100) < difficultyLevel * 5)
		{
			type = ((Character.STR.GetValue() < Character.WIS.GetValue()) ? classType.Mage : classType.Warrior);
			flag = true;
		}
		int num = 0;
		do
		{
			if (num == 3)
			{
				level = 0;
			}
			bool epicsPossible = true;
			if (ProgressionLevel == 1 || ProgressionLevel == 2)
			{
				epicsPossible = false;
			}
			Skill randomSkill = DataTables.instance.GetRandomSkill(level * 4, 0, AI: true, type, epicsPossible, flag, flag);
			if (!Character.DoesCharHaveSkill(randomSkill))
			{
				Character.LearnSkill(randomSkill);
				return;
			}
			num++;
		}
		while (num != 50);
		Debug.Log((object)"!!!ProgressManager SkillUp counter over limit!!!");
	}

	public List<CharacterTemplate> CreateCareerEnemyTeam(int TeamSize, int initRarity = 0, int unitRarityPoints = 12, int itemRarityPoints = 36, int beastamount = 0, float statmodifier = 0f)
	{
		List<CharacterTemplate> list = new List<CharacterTemplate>();
		List<CharacterRace> list2 = new List<CharacterRace>();
		int num = 0;
		int num2 = ListOfCareerModeTeams.Count + 1;
		foreach (int item in CreateRarityList(TeamSize, unitRarityPoints, 2))
		{
			Random.Range(0, 100);
			CharacterTemplate characterTemplate;
			do
			{
				characterTemplate = ((beastamount <= 0) ? Object.Instantiate<CharacterTemplate>(DataTables.instance.GetRandomCharacter()) : Object.Instantiate<CharacterTemplate>(DataTables.instance.GetRandomBoss()));
			}
			while (GlobalVariables.instance.NoDuplicateRaceInTeam && list2.Contains(characterTemplate.Race));
			beastamount--;
			list2.Add(characterTemplate.Race);
			characterTemplate.Initialize(item, AI: true, 0, 5, statmodifier);
			list.Add(characterTemplate);
			if (num2 == 1)
			{
				characterTemplate.CharacterEquipList = EquipmentManager.instance.ListOfCareerTeam1EnemyEquipLists[num];
			}
			if (num2 == 2)
			{
				characterTemplate.CharacterEquipList = EquipmentManager.instance.ListOfCareerTeam2EnemyEquipLists[num];
			}
			if (num2 == 3)
			{
				characterTemplate.CharacterEquipList = EquipmentManager.instance.ListOfCareerTeam3EnemyEquipLists[num];
			}
			num++;
		}
		SkillUpEnemyTeam(list, initRarity);
		PerkUpEnemyTeam(list, initRarity);
		DressUpEnemyTeam(list, itemRarityPoints, num2);
		foreach (CharacterTemplate item2 in list)
		{
			if (item2.DoesThisCharacterHaveABow())
			{
				AIArcherAdjustments(item2, initRarity);
			}
			item2.CreateListOfCharacterPerks();
			item2.CreateListOfCharacterSkills();
		}
		return list;
	}

