			}
			else
			{
				string term2 = "DESIRE/DESIRE_" + EmpDesire;
				((TMP_Text)TownManager.instance.EmperorDesire).SetText(LocalizationManager.GetTranslation(term2));
			}
			TownManager.instance.EmperorDesireTooltip.type = EmpDesire;
		}
		else
		{
			EmpDesire = "NODESIRE";
			((TMP_Text)TownManager.instance.EmperorDesire).SetText("---");
			TownManager.instance.EmperorDesireTooltip.type = EmpDesire;
		}
		if (!FirstTimeDemands && ProfileManager.instance.TotalGameWins == 0 && (EmpDemand != "NODEMAND" || EmpDesire != "NODESIRE"))
		{
			TownManager.instance.ShowDemandNotification = true;
			FirstTimeDemands = true;
		}
	}

	public void ReduceInjuryCountForAll()
	{
		foreach (CharacterTemplate item in Team)
		{
			if (!((Object)(object)item != (Object)null) || item.InjuryCount <= 0)
			{
				continue;
			}
			item.InjuryCount--;
			foreach (Perk characterPerk in item.CharacterPerks)
			{
				bool flag = false;
				try
				{
					if (BattleProcessor.instance.UnitsThatReceivedDamageFromBattle.Contains(item))
					{
						flag = true;
					}
				}
				catch
				{
					Debug.Log((object)"For some reason couldn't check if unit received damage in battle");
				}
				if (characterPerk.name == "Persistent" && !flag)
				{
					item.InjuryCount -= 2;
					item.InjuryCount = Mathf.Clamp(item.InjuryCount, 0, 9);
				}
			}
		}
		foreach (CharacterTemplate item2 in RosterManager.instance.Roster)
		{
			if (item2.InjuryCount <= 0)
			{
				continue;
			}
			item2.InjuryCount--;
			foreach (Perk characterPerk2 in item2.CharacterPerks)
			{
				if (characterPerk2.name == "Persistent")
				{
					item2.InjuryCount -= 2;
					item2.InjuryCount = Mathf.Clamp(item2.InjuryCount, 0, 9);
				}
			}
		}
	}

	public void CreateCareerFightList(bool guaranteedSpecial = false)
	{
		CareerNextFights.Clear();
		for (int i = 0; i < NumberOfNormalMatches; i++)
		{
			if (guaranteedSpecial && i == 0)
			{
				CareerNextFights.Add(GetRandomCareerFight(guaranteedSpecial));
			}
			else
			{
				CareerNextFights.Add(GetRandomCareerFight());
			}
		}
		for (int j = 0; j < NumberOfQualifierMatches; j++)
		{
			if (CurrentCareerRank == 5 && j == NumberOfQualifierMatches - 1)
			{
				CareerNextFights.Add(20);
			}
			else
			{
				CareerNextFights.Add(19);
			}
		}
		CareerNextFights.Add(1);
		CareerNextFights.Add(1);
		CareerNextFights.Add(1);
		CareerNextFights.Add(1);
		CareerNextFights.Add(1);
	}

	public void RemoveChampionshipMatchFromCareerNextFights()
	{
		int index = CareerNextFights.IndexOf(20);
		CareerNextFights[index] = 1;
	}

	public int GetRandomCareerFight(bool guaranteedSpecial = false)
	{
		int num = 0;
		if (guaranteedSpecial)
		{
			num = Random.Range(2, 6);
		}
		else
		{
			int num2 = Random.Range(0, 100);
			if (num2 < 4)
			{
				num = 2;
			}
			else if (num2 < 8)
			{
				num = 3;
			}
			else if (num2 < 12)
			{
				num = 4;
			}
			else if (num2 < 16)
			{
				num = 5;
			}
		}
		if (num == 2 && CurrentCareerRank == 5)
		{
			num = Random.Range(3, 6);
		}
		if (TotalWins == 0)
		{
			num = 0;
		}
		return num;
	}

	public void CareerModeCheckNextMatches()
	{
		CareerNextFights.RemoveAt(0);
	}

	public void CareerAddProgressionStar()
	{
		NumberOfCareerProgressionStars++;
		CareerAnimateStatus = NumberOfCareerProgressionStars;
	}

	public void CareerDemoteLevel()
	{
		if (CurrentCareerRank > 1)
		{
			CurrentCareerRank--;
			CareerAnimateStatus += 10;
			TownManager.instance.NewRewards.Add("Demotion", CareerGetRankNotificationIcon(1));
		}
		else
		{
			CareerAnimateStatus += 30;
			TownManager.instance.NewRewards.Add("StayAtRank", CareerGetRankNotificationIcon(3));
		}
	}

	public void CareerPromoteLevel()
	{
		CurrentCareerRank++;
		CareerAnimateStatus += 20;
		if (CurrentCareerRank < 6)
		{
			TownManager.instance.NewRewards.Add(LocalizationManager.GetTranslation("UI.TOWN/UI.TOWN_careerpromotion"), CareerGetRankNotificationIcon(2));
			IncreaseCareerWages();
		}
	}

	public void IncreaseCareerWages()
	{
		foreach (CharacterTemplate item in Team)
		{
			if ((Object)(object)item != (Object)null)
			{
				item.WageIncrease();
			}
		}
		foreach (CharacterTemplate item2 in RosterManager.instance.Roster)
		{
			if ((Object)(object)item2 != (Object)null)
			{
				item2.WageIncrease();
			}
		}
		TownManager.instance.InfoWindowPicture.sprite = TownManager.instance.GoblinAccountant;
		TownManager.instance.StoredInfoText = LocalizationManager.GetTranslation("UI.TOWN/UI.TOWN_accountantmsg1");
		((MonoBehaviour)this).StartCoroutine(TownManager.instance.ShowInfo(1));
	}

	public Sprite CareerGetRankNotificationIcon(int status)
	{
		Sprite result = null;
		switch (status)
		{
		case 1:
			switch (CurrentCareerRank)
			{
			case 1:
				result = Demotion1;
				break;
			case 2:
				result = Demotion2;
				break;
			case 3:
				result = Demotion3;
				break;
			case 4:
				result = Demotion4;
				break;
			}
			break;
		case 2:
			switch (CurrentCareerRank)
			{
			case 2:
				result = LevelUp2;
				break;
			case 3:
				result = LevelUp3;
				break;
			case 4:
				result = LevelUp4;
				break;
			case 5:
				result = LevelUp5;
				break;
			}
			break;
		default:
			switch (CurrentCareerRank)
			{
			case 1:
				result = StayAtRank1;
				break;
			case 2:
				result = StayAtRank2;
				break;
			case 3:
				result = StayAtRank3;
				break;
			case 4:
				result = StayAtRank4;
				break;
			case 5:
				result = StayAtRank5;
				break;
			}
			break;
		}
		return result;
	}

	public void ReCheckLuckBonus()
	{
		EventLuckBonusFromPerks = 0;
		foreach (CharacterTemplate item in Team)
		{
			if (!((Object)(object)item != (Object)null))
			{
				continue;
			}
			foreach (Perk characterPerk in item.CharacterPerks)
			{
				if (characterPerk.PrimaryEffect == "Luck")
				{
					EventLuckBonusFromPerks += characterPerk.PrimaryEffectValue;
				}
				if (characterPerk.SecondaryEffect == "Luck")
				{
					EventLuckBonusFromPerks += characterPerk.SecondaryEffectValue;
				}
			}
		}
		EventLuckBonusTotal = EventLuckBonusFromPerks + EventLuckBonusDefault;
	}

	public void SubmitFinalScore()
	{
		int num = CalculateFinalScore(GlobalVariables.instance.EndlessModeActivated);
		List<string> list = new List<string>();
		list.Add(num.ToString());
		list.Add(HeroTeamName);
		foreach (CharacterTemplate item in Team)
		{
			if ((Object)(object)item != (Object)null)
			{
				list.Add(item.Charname);
				list.Add(item.Race.ToString());
			}
		}
		SaveManager.instance.SaveFinalScore(list, GlobalVariables.instance.EndlessModeActivated);
	}

	public int CalculateFinalScore(bool Endless)
	{
		int num = 0;
		if (Endless)
		{
			num = TotalWins;
			if (num >= 42)
			{
				SteamAchievements.instance.UnlockSteamAchievement("ACH_Endless42Wins");
			}
		}
		else
		{
			num += GetGold() / 100;
			foreach (bool progression in ProgressionList)
			{
				if (progression)
				{
					num += 10;
				}
			}
			foreach (CharacterTemplate item in Team)
			{
				if ((Object)(object)item == (Object)null)
				{
					break;
				}
				num += item.KillCount;
			}
			foreach (Item inventory in InventoryManager.instance.InventoryList)
			{
				if ((Object)(object)inventory != (Object)null && inventory.itemRarity == Rarity.Legendary)
				{
					num += 2;
				}
			}
			foreach (Equipment item2 in EquipmentManager.instance.Hero1Equipment)
			{
				if ((Object)(object)item2 != (Object)null && item2.itemRarity == Rarity.Legendary)
				{
					num += 2;
				}
			}
			foreach (Equipment item3 in EquipmentManager.instance.Hero2Equipment)
			{
				if ((Object)(object)item3 != (Object)null && item3.itemRarity == Rarity.Legendary)
				{
					num += 2;
				}
			}
			foreach (Equipment item4 in EquipmentManager.instance.Hero3Equipment)
			{
				if ((Object)(object)item4 != (Object)null && item4.itemRarity == Rarity.Legendary)
				{
					num += 2;
				}
			}
			foreach (Equipment item5 in EquipmentManager.instance.Hero4Equipment)
			{
				if ((Object)(object)item5 != (Object)null && item5.itemRarity == Rarity.Legendary)
				{
					num += 2;
				}
			}
			foreach (CharacterTemplate item6 in RosterManager.instance.Roster)
			{
				if ((Object)(object)item6 != (Object)null)
				{
					num += 2;
				}
			}
			foreach (CharacterTemplate deadHero in DeadHeroes)
			{
				if ((Object)(object)deadHero != (Object)null)
				{
					num -= 2;
				}
			}
			num = ((GlobalVariables.instance.ChosenGameDifficulty != 1) ? (num * 8) : (num * 6));
			int num2 = 0;
			if (GlobalVariables.instance.ChallengeSmallTeam && GlobalVariables.instance.ChallengeLoneSurvivor)
			{
				num2 = -1;
			}
			float num3 = 1f + (float)(GlobalVariables.instance.CountChallenges() + num2) * 0.1f + (float)GlobalVariables.instance.GloryLevel * 0.1f;
			num = Mathf.RoundToInt((float)num * num3);
		}
		Debug.Log((object)("Final score: " + num));
		return num;
	}

	public void TestDebug(int debugslot)
	{
		switch (debugslot)
		{
		case 1:
			if (KeyBindingManager.keyDict.ContainsKey(KeyAction.togglegrid))
			{
				Debug.Log((object)"Yay");
			}
			if (KeyBindingManager.keyDict.ContainsKey(KeyAction.left))
			{
				Debug.Log((object)"As expected");
			}
			break;
		case 2:
			if (!KeyBindingManager.keyDict.ContainsKey(KeyAction.togglegrid))
			{
				KeyBindingManager.keyDict.Add(KeyAction.togglegrid, (KeyCode)116);
				ES3.Save<Dictionary<KeyAction, KeyCode>>("keyDict", KeyBindingManager.keyDict, "Preferences.es3");
			}
			break;
		}
	}
}
