				if ((Object)(object)item2.Key == (Object)(object)kb || (Object)(object)item2.Key == (Object)(object)crit || (Object)(object)item2.Key == (Object)(object)dodge || (Object)(object)item2.Key == (Object)(object)debuffresistance)
				{
					text2 += "%";
				}
				((TMP_Text)item2.Key).SetText(text2);
				if (item2.Value.DoesItHaveModifiers() == 1)
				{
					((Graphic)item2.Key).color = Color32.op_Implicit(new Color32((byte)0, byte.MaxValue, (byte)0, byte.MaxValue));
				}
				else if (item2.Value.DoesItHaveModifiers() == -1)
				{
					((Graphic)item2.Key).color = Color32.op_Implicit(new Color32(byte.MaxValue, (byte)75, (byte)75, byte.MaxValue));
				}
				else
				{
					((Graphic)item2.Key).color = Color32.op_Implicit(new Color32(byte.MaxValue, byte.MaxValue, byte.MaxValue, byte.MaxValue));
				}
			}
			catch
			{
				((Graphic)item2.Key).color = Color32.op_Implicit(new Color32(byte.MaxValue, byte.MaxValue, byte.MaxValue, byte.MaxValue));
				((TMP_Text)item2.Key).SetText("-");
			}
		}
		foreach (Transform item3 in SkillPanel)
		{
			Object.Destroy((Object)(object)((Component)item3).gameObject);
		}
		foreach (Skill characterSkill in Character.CharacterSkills)
		{
			if ((Object)(object)characterSkill != (Object)null)
			{
				GameObject val = Object.Instantiate<GameObject>(SkillSlotPrefab);
				val.transform.SetParent(SkillPanel, false);
				val.GetComponentInChildren<SkillButton>().skill = characterSkill;
			}
		}
		((TMP_Text)SkillsText).SetText(LocalizationManager.GetTranslation("TOOLTIP/TOOLTIP_character_skills") + " " + Character.HowManySkills() + " / 4");
		foreach (Transform item4 in PerkPanel)
		{
			Object.Destroy((Object)(object)((Component)item4).gameObject);
		}
		foreach (Perk characterPerk in Character.CharacterPerks)
		{
			if ((Object)(object)characterPerk != (Object)null)
			{
				GameObject val2 = Object.Instantiate<GameObject>(PerkPrefab);
				val2.transform.SetParent(PerkPanel, false);
				val2.GetComponent<PerkSlot>().ContainsPerk = characterPerk;
				val2.GetComponent<Image>().sprite = characterPerk.icon;
			}
		}
		((Component)ShowcaseWindow).gameObject.SetActive(true);
	}

	public void ClearInfo()
	{
		if ((Object)(object)ChosenSlot != (Object)null)
		{
			ChosenSlot.UnDimThis();
		}
		((Component)ShowcaseWindow).gameObject.SetActive(false);
	}

	public void Recruitchosen()
	{
		if ((Object)(object)ChosenSlot != (Object)null)
		{
			if (ChosenSlot.RecruitCharacter())
			{
				((Component)ShowcaseWindow).gameObject.SetActive(false);
				ChosenSlot = null;
			}
			else
			{
				Debug.Log((object)"Recruit was not successful");
			}
		}
		else
		{
			Debug.Log((object)"No slot chosen");
		}
	}
}
