public class RewardButton : MonoBehaviour, ITooltippable, IPointerEnterHandler, IEventSystemHandler, IPointerExitHandler
{
	public Sprite GoldSprite;

	private CharacterTemplate RewardCharacter;

	private Equipment RewardEquipment;

	private Item RewardItem;

	private int RewardGoldAmount;

	private RewardType rewardType;

	public GameObject RewardSlot;

	public CanvasGroup FadeCanvas;

	private void Start()
	{
	}

	public void InitializeReward(int rarityBonus = 0, int presetrarity = 0, int preset = 0)
	{
		if (preset > 0)
		{
			switch (preset)
			{
			case 1:
				rewardType = RewardType.Character;
				RewardCharacter = Object.Instantiate<CharacterTemplate>(DataTables.instance.GetRandomCharacter());
				RewardCharacter.Initialize(presetrarity, AI: false, rarityBonus / 2);
				RewardSlot.GetComponent<Image>().sprite = RewardCharacter.Sprite;
				((Component)this).GetComponent<GlowEffect>().InitializeGlow(RewardCharacter.characterRarity);
				break;
			case 2:
				rewardType = RewardType.Equipment;
				RewardEquipment = Object.Instantiate<Equipment>(DataTables.instance.GetRandomEquipment());
				RewardEquipment.Initialize(presetrarity, rarityBonus / 2);
				RewardSlot.GetComponent<Image>().sprite = RewardEquipment.icon;
				((Component)this).GetComponent<GlowEffect>().InitializeGlow(RewardEquipment.itemRarity);
				break;
			case 3:
				switch (presetrarity)
				{
				case 5:
					presetrarity = 3;
					break;
				case 4:
					presetrarity = 2;
					break;
				case 3:
					presetrarity = 2;
					break;
				case 2:
					presetrarity = 1;
					break;
				}
				rewardType = RewardType.Item;
				RewardItem = Object.Instantiate<Item>(DataTables.instance.GetRandomItemNonEquip());
				RewardItem.Initialize(presetrarity, rarityBonus / 2);
				RewardSlot.GetComponent<Image>().sprite = RewardItem.icon;
				((Component)this).GetComponent<GlowEffect>().InitializeGlow(RewardItem.itemRarity);
				break;
			default:
				rewardType = RewardType.Gold;
				if (rarityBonus >= 24)
				{
					RewardGoldAmount = Random.Range(AudienceManager.instance.AudienceCount, AudienceManager.instance.AudienceCount * rarityBonus / 24);
				}
				else
				{
					RewardGoldAmount = AudienceManager.instance.AudienceCount;
				}
				RewardSlot.GetComponent<Image>().sprite = GoldSprite;
				((Component)this).GetComponent<GlowEffect>().InitializeGlow(Rarity.Common);
				break;
			}
			return;
		}
		int num = Random.Range(0, 100);
		if (num >= 100 - GlobalVariables.instance.rewardCharacterChance && RosterManager.instance.IsThereRoom())
		{
			rewardType = RewardType.Character;
			RewardCharacter = Object.Instantiate<CharacterTemplate>(DataTables.instance.GetRandomCharacter());
			RewardCharacter.Initialize(presetrarity, AI: false, rarityBonus / 2);
			RewardSlot.GetComponent<Image>().sprite = RewardCharacter.Sprite;
		}
		else if (num >= 100 - GlobalVariables.instance.rewardCharacterChance - GlobalVariables.instance.rewardEquipmentChance && InventoryManager.instance.IsThereRoom())
		{
			rewardType = RewardType.Equipment;
			RewardEquipment = Object.Instantiate<Equipment>(DataTables.instance.GetRandomEquipment());
			RewardEquipment.Initialize(presetrarity, rarityBonus / 2);
			RewardSlot.GetComponent<Image>().sprite = RewardEquipment.icon;
			((Component)this).GetComponent<GlowEffect>().InitializeGlow(RewardEquipment.itemRarity);
		}
		else if (num >= 100 - GlobalVariables.instance.rewardCharacterChance - GlobalVariables.instance.rewardEquipmentChance - GlobalVariables.instance.rewardItemChance && InventoryManager.instance.IsThereRoom())
		{
			switch (presetrarity)
			{
			case 5:
				presetrarity = 3;
				break;
			case 4:
				presetrarity = 2;
				break;
			case 3:
				presetrarity = 2;
				break;
			case 2:
				presetrarity = 1;
				break;
			}
			rewardType = RewardType.Item;
			RewardItem = Object.Instantiate<Item>(DataTables.instance.GetRandomItemNonEquip());
			RewardItem.Initialize(presetrarity, rarityBonus / 2);
			RewardSlot.GetComponent<Image>().sprite = RewardItem.icon;
		}
		else
		{
			rewardType = RewardType.Gold;
			if (rarityBonus >= 24)
			{
				RewardGoldAmount = Random.Range(AudienceManager.instance.AudienceCount, AudienceManager.instance.AudienceCount * rarityBonus / 24);
			}
			else
			{
				RewardGoldAmount = AudienceManager.instance.AudienceCount;
			}
			RewardSlot.GetComponent<Image>().sprite = GoldSprite;
		}
	}

	public void InitializeSpecificReward(int preset)
	{
		switch (preset)
		{
		case 1:
			rewardType = RewardType.Character;
			RewardCharacter = ProgressManager.instance.PresetCareerPrizeCharacter;
			RewardSlot.GetComponent<Image>().sprite = RewardCharacter.Sprite;
			((Component)this).GetComponent<GlowEffect>().InitializeGlow(RewardCharacter.characterRarity);
			return;
		case 2:
			rewardType = RewardType.Equipment;
			RewardEquipment = ProgressManager.instance.PresetCareerPrizeEquipment;
			RewardSlot.GetComponent<Image>().sprite = RewardEquipment.icon;
			((Component)this).GetComponent<GlowEffect>().InitializeGlow(RewardEquipment.itemRarity);
			return;
		case 3:
			rewardType = RewardType.Item;
			RewardItem = ProgressManager.instance.PresetCareerPrizeBook;
			RewardSlot.GetComponent<Image>().sprite = RewardItem.icon;
			((Component)this).GetComponent<GlowEffect>().InitializeGlow(RewardItem.itemRarity);
			return;
		}
		rewardType = RewardType.Gold;
		if (AudienceManager.instance.AudienceCount >= 24)
		{
			RewardGoldAmount = Random.Range(AudienceManager.instance.AudienceCount, AudienceManager.instance.AudienceCount * AudienceManager.instance.AudienceCount / 24);
		}
		else
		{
			RewardGoldAmount = AudienceManager.instance.AudienceCount;
		}
		RewardSlot.GetComponent<Image>().sprite = GoldSprite;
		((Component)this).GetComponent<GlowEffect>().InitializeGlow(Rarity.Common);
	}

	public void PickReward()
	{
		if (BattleProcessor.instance.EndRewardPicked)
		{
			return;
		}
		switch (rewardType)
		{
		case RewardType.Character:
			if (ProgressManager.instance.IsThereRoomInTeam())
			{
				ProgressManager.instance.AddToTeam(RewardCharacter);
				break;
			}
			if (RosterManager.instance.IsThereRoom())
			{
				RosterManager.instance.AddToRoster(RewardCharacter);
				break;
			}
			Debug.Log((object)"!!!This should not happen: Roster & Team full");
			return;
		case RewardType.Equipment:
			if (!InventoryManager.instance.IsThereRoom())
			{
				return;
			}
			InventoryManager.instance.AddToInventory(RewardEquipment);
			break;
		case RewardType.Item:
			if (!InventoryManager.instance.IsThereRoom())
			{
				return;
			}
			InventoryManager.instance.AddToInventory(RewardItem);
			break;
		case RewardType.Gold:
			ProgressManager.instance.ChangeGold(RewardGoldAmount);
			break;
		}
		BattleProcessor.instance.RewardPicked(this);
	}

	public IEnumerator FadeThis(float speed = 5f)
	{
		while (FadeCanvas.alpha > 0f)
		{
			CanvasGroup fadeCanvas = FadeCanvas;
			fadeCanvas.alpha -= Time.deltaTime * speed;
			yield return null;
		}
	}

	public string GetDescription()
	{
		switch (rewardType)
		{
			case RewardType.Character:
				return RewardCharacter.GetTooltip();
			case RewardType.Equipment:
				return RewardEquipment.GetTooltip();
			case RewardType.Item:
				return RewardItem.GetTooltip();
			case RewardType.Gold:
				return LocalizationManager.GetTranslation("UI.BATTLE/UI.BATTLE_rewardfullgold").Replace("<VALUE>", RewardGoldAmount.ToString());
			default:
				return "";
		}
	}

	public void OnPointerEnter(PointerEventData eventData)
	{
		//IL_0014: Unknown result type (might be due to invalid IL or missing references)
		//IL_0039: Unknown result type (might be due to invalid IL or missing references)
		//IL_009d: Unknown result type (might be due to invalid IL or missing references)
		//IL_007d: Unknown result type (might be due to invalid IL or missing references)
		if (rewardType == RewardType.Character)
		{
			UIManager.instance.ShowCharacterTooltip(((Component)this).transform.position, RewardCharacter);
		}
		else if (rewardType == RewardType.Equipment)
		{
			UIManager.instance.ShowTooltip(((Component)this).transform.position, this, RewardEquipment.givesSkill, RewardEquipment.givesPerk);
		}
		else if (rewardType == RewardType.Item)
		{
			Spellbook spellbook = (Spellbook)RewardItem;
			UIManager.instance.ShowTooltip(((Component)this).transform.position, this, spellbook.TeachesSkill, null, book: true);
		}
		else
		{
			UIManager.instance.ShowTooltip(((Component)this).transform.position, this);
		}
	}

	public void OnPointerExit(PointerEventData eventData)
	{
		UIManager.instance.HideTooltip();
	}
}
public enum RewardType
{
	Equipment,
	Item,
	Character,
	Gold
}
public class RosterManager : MonoBehaviour
{
	public List<CharacterTemplate> Roster = new List<CharacterTemplate>();

	public Transform RosterPanel;

	public GameObject RosterBar;

	public TextMeshProUGUI RosterSize;

	public static RosterManager instance;

	private void Awake()
	{
		if ((Object)(object)instance != (Object)null)
		{
			Object.Destroy((Object)(object)((Component)this).gameObject);
			return;
		}
		instance = this;
		Object.DontDestroyOnLoad((Object)(object)((Component)((Component)this).transform).gameObject);
	}

	private void Start()
	{
		if (SaveManager.instance.LoadActive)
		{
			SaveManager.instance.LoadComponent("RosterManager");
		}
	}

	public bool IsThereRoom()
	{
		if (Roster.Count < GlobalVariables.instance.RosterMaxSize)
		{
			return true;
		}
		return false;
	}

	public void AddToRoster(CharacterTemplate Character)
	{
		//IL_0014: Unknown result type (might be due to invalid IL or missing references)
		//IL_0019: Unknown result type (might be due to invalid IL or missing references)
		if (IsThereRoom())
		{
			Roster.Add(Character);
			Scene activeScene = SceneManager.GetActiveScene();
			if (activeScene.name == "Town")
			{
				RedrawRoster();
			}
		}
		else
		{
			UIManager.instance.ShowErrorMessage(LocalizationManager.GetTranslation("MESSAGE/MESSAGE_rosterfull"));
		}
	}

	public void RemoveFromRoster(CharacterTemplate Character)
	{
		//IL_000d: Unknown result type (might be due to invalid IL or missing references)
		//IL_0012: Unknown result type (might be due to invalid IL or missing references)
		Roster.Remove(Character);
		Scene activeScene = SceneManager.GetActiveScene();
		if (activeScene.name == "Town")
		{
			RedrawRoster();
		}
	}

	public void MoveToTeam(CharacterTemplate Character)
	{
		if (!ProgressManager.instance.IsThereRoomInTeam())
		{
			ProgressManager.instance.AddToTeam(Character);
			Roster.Remove(Character);
			RedrawRoster();
		}
	}

	public void RedrawRoster()
	{
		//IL_0014: Unknown result type (might be due to invalid IL or missing references)
		foreach (Transform item in RosterPanel)
		{
			Object.Destroy((Object)(object)((Component)item).gameObject);
		}
		foreach (CharacterTemplate item2 in Roster)
		{
			GameObject val = Object.Instantiate<GameObject>(RosterBar);
			val.GetComponent<DragHandlerCharacter>().Character = item2;
			val.GetComponent<DragHandlerCharacter>().AdjustBorders();
			val.transform.SetParent(RosterPanel, false);
			((Component)val.transform.Find("Character")).GetComponent<Image>().sprite = item2.Portrait;
			item2.UpdateHPMP();
			if (item2.InjuryCount > 0)
			{
				((Component)val.transform.Find("InjuryImage")).gameObject.SetActive(true);
				((TMP_Text)((Component)val.transform.Find("InjuryImage/InjuryCounter")).GetComponent<TextMeshProUGUI>()).text = item2.InjuryCount.ToString();
			}
			else
			{
				((Component)val.transform.Find("InjuryImage")).gameObject.SetActive(false);
			}
		}
		((TMP_Text)RosterSize).SetText(Roster.Count + " / " + GlobalVariables.instance.RosterMaxSize);
	}
}
public class SaveManager : MonoBehaviour
{
	public static SaveManager instance;

	public bool LoadActive;

	private int ComponentsStillLoading;

	public CanvasGroup LoadScreen;

	public bool FadeStarted;

	public bool SaveManagerInitialized;

	public bool StartupComplete;

	public int GameVersionNumber;

	private void Awake()
	{
		if ((Object)(object)instance != (Object)null)
		{
			Object.Destroy((Object)(object)((Component)this).gameObject);
			return;
		}
		instance = this;
		Object.DontDestroyOnLoad((Object)(object)((Component)((Component)this).transform).gameObject);
	}

	public void StartActions()
	{
		LoadProfile();
		LoadPreferences();
		MainMenuScript.instance.ActivatePresets();
		OptionsMenu.instance.ActivatePresets();
		PatchAdjustments();
		StartupComplete = true;
	}

	private void PatchAdjustments()
	{
		if (!KeyBindingManager.keyDict.ContainsKey(KeyAction.togglegrid))
		{
			KeyBindingManager.keyDict.Add(KeyAction.togglegrid, (KeyCode)116);
			ES3.Save<Dictionary<KeyAction, KeyCode>>("keyDict", KeyBindingManager.keyDict, "Preferences.es3");
		}
	}

	public void InitializePreferences()
	{
		KeyBindingManager.InitializeKeybindings();
		ProfileManager.instance.LatestResolution = 0;
		ProfileManager.instance.LatestFramerate = 2;
		ProfileManager.instance.LatestVSync = true;
		ProfileManager.instance.LatestSoundVolume = 0.5f;
		ProfileManager.instance.LatestMusicVolume = 0.5f;
		ProfileManager.instance.BloodEnabled = true;
		ProfileManager.instance.ScreenShakeEnabled = true;
		ProfileManager.instance.TurnIndicatorsEnabled = true;
