				ProfileManager.instance.LatestMusicVolume = ES3.Load("LatestMusicVolume", "Preferences.es3", 0.5f);
				ProfileManager.instance.BloodEnabled = ES3.Load("BloodEnabled", "Preferences.es3", defaultValue: true);
