				ProfileManager.instance.TurnIndicatorsEnabled = ES3.Load("TurnIndicatorsEnabled", "Preferences.es3", defaultValue: true);
				ProfileManager.instance.SkipBattleIntro = ES3.Load("SkipBattleIntro", "Preferences.es3", defaultValue: false);
