					ES3.Save<CareerTeamSaveHelper>("CareerTeam1Details", ProgressManager.instance.CurrentCareerEnemyTeamDetails);
					ES3.Save<Equipment>("CareerTeam1RewardEquipment", ProgressManager.instance.PresetCareerPrizeEquipment);
					ES3.Save<CharacterTemplate>("CareerTeam1RewardCharacter", ProgressManager.instance.PresetCareerPrizeCharacter);
					ES3.Save<Spellbook>("CareerTeam1RewardSkillbook", ProgressManager.instance.PresetCareerPrizeBook);
					num++;
				}
				else
				{
					ES3.Save<List<CharacterTemplate>>("CareerTeam1", ProgressManager.instance.ListOfCareerModeTeams[0].EnemyTeam);
					ES3.Save<CareerTeamSaveHelper>("CareerTeam1Details", ProgressManager.instance.ListOfCareerModeTeams[0].SaveTeamDetails());
					ES3.Save<Equipment>("CareerTeam1RewardEquipment", ProgressManager.instance.ListOfCareerModeTeams[0].RewardSlot.RewardEquipment);
					ES3.Save<CharacterTemplate>("CareerTeam1RewardCharacter", ProgressManager.instance.ListOfCareerModeTeams[0].RewardSlot.RewardCharacter);
					ES3.Save<Spellbook>("CareerTeam1RewardSkillbook", ProgressManager.instance.ListOfCareerModeTeams[0].RewardSlot.RewardSkillbook);
					num++;
					if (ProgressManager.instance.ListOfCareerModeTeams.Count == 2)
					{
						ES3.Save<List<CharacterTemplate>>("CareerTeam2", ProgressManager.instance.ListOfCareerModeTeams[1].EnemyTeam);
						ES3.Save<CareerTeamSaveHelper>("CareerTeam2Details", ProgressManager.instance.ListOfCareerModeTeams[1].SaveTeamDetails());
						ES3.Save<Equipment>("CareerTeam2RewardEquipment", ProgressManager.instance.ListOfCareerModeTeams[1].RewardSlot.RewardEquipment);
						ES3.Save<CharacterTemplate>("CareerTeam2RewardCharacter", ProgressManager.instance.ListOfCareerModeTeams[1].RewardSlot.RewardCharacter);
						ES3.Save<Spellbook>("CareerTeam2RewardSkillbook", ProgressManager.instance.ListOfCareerModeTeams[1].RewardSlot.RewardSkillbook);
						num++;
					}
					else if (ProgressManager.instance.ListOfCareerModeTeams.Count == 3)
					{
						ES3.Save<List<CharacterTemplate>>("CareerTeam2", ProgressManager.instance.ListOfCareerModeTeams[1].EnemyTeam);
						ES3.Save<CareerTeamSaveHelper>("CareerTeam2Details", ProgressManager.instance.ListOfCareerModeTeams[1].SaveTeamDetails());
						ES3.Save<Equipment>("CareerTeam2RewardEquipment", ProgressManager.instance.ListOfCareerModeTeams[1].RewardSlot.RewardEquipment);
						ES3.Save<CharacterTemplate>("CareerTeam2RewardCharacter", ProgressManager.instance.ListOfCareerModeTeams[1].RewardSlot.RewardCharacter);
						ES3.Save<Spellbook>("CareerTeam2RewardSkillbook", ProgressManager.instance.ListOfCareerModeTeams[1].RewardSlot.RewardSkillbook);
						num++;
						ES3.Save<List<CharacterTemplate>>("CareerTeam3", ProgressManager.instance.ListOfCareerModeTeams[2].EnemyTeam);
						ES3.Save<CareerTeamSaveHelper>("CareerTeam3Details", ProgressManager.instance.ListOfCareerModeTeams[2].SaveTeamDetails());
						ES3.Save<Equipment>("CareerTeam3RewardEquipment", ProgressManager.instance.ListOfCareerModeTeams[2].RewardSlot.RewardEquipment);
						ES3.Save<CharacterTemplate>("CareerTeam3RewardCharacter", ProgressManager.instance.ListOfCareerModeTeams[2].RewardSlot.RewardCharacter);
						ES3.Save<Spellbook>("CareerTeam3RewardSkillbook", ProgressManager.instance.ListOfCareerModeTeams[2].RewardSlot.RewardSkillbook);
						num++;
					}
				}
				ES3.Save<int>("numberofcareerteams", num);
			}
			Debug.Log((object)"---Saved run data---");
		}
		catch (Exception ex)
		{
			Debug.Log((object)("EXCEPTION SaveManager:Save: " + ex.StackTrace + " ||| MESSAGE: ||| " + ex.Message));
			UIManager.instance.ShowErrorMessage(LocalizationManager.GetTranslation("MESSAGE/MESSAGE_saveproblem"), 3f);
		}
	}

	public void Load()
	{
		//IL_0058: Unknown result type (might be due to invalid IL or missing references)
		//IL_005d: Unknown result type (might be due to invalid IL or missing references)
		//IL_008a: Unknown result type (might be due to invalid IL or missing references)
		//IL_008f: Unknown result type (might be due to invalid IL or missing references)
		try
		{
			if (!ES3.FileExists("Data.es3"))
			{
				Debug.LogWarning((object)"Trying to load data while it doesn't exist!");
				return;
			}
			LoadScreen.alpha = 1f;
			LoadScreen.blocksRaycasts = true;
			((MonoBehaviour)this).StartCoroutine(FadeOutLoadScreen(1.5f));
			Object.Destroy((Object)(object)GameObject.Find("GameManager"));
			Scene activeScene = SceneManager.GetActiveScene();
			_ = activeScene.name;
			LoadActive = true;
			ComponentsStillLoading = 6;
			SceneManager.LoadScene("Town", (LoadSceneMode)0);
			LoadComponent("GlobalVariables");
			activeScene = SceneManager.GetActiveScene();
			_ = activeScene.name == "Town";
		}
		catch (Exception ex)
		{
			Debug.Log((object)("EXCEPTION SaveManager:Load: " + ex.StackTrace + " ||| MESSAGE: ||| " + ex.Message));
			UIManager.instance.ShowErrorMessage(LocalizationManager.GetTranslation("MESSAGE/MESSAGE_loadproblem"), 3f);
		}
	}

	public void LoadComponent(string component)
	{
		try
		{
			if (ComponentsStillLoading <= 0)
			{
				Debug.LogWarning((object)"<color=red>TRYING TO LOAD EVEN THOUGH COMPONENTSSTILLOADING <= 0</color>");
			}
			switch (component)
			{
			case "ProgressManager":
				ProgressManager.instance.Gold = ES3.Load<int>("Gold");
				ProgressManager.instance.TotalWins = ES3.Load<int>("TotalWins");
				ProgressManager.instance.ProgressionLevel = ES3.Load<int>("ProgressionLevel");
				ProgressManager.instance.ProgressionLevelMax = ES3.Load<int>("ProgressionLevelMax");
				ProgressManager.instance.ProgressionLevelWins = ES3.Load<int>("ProgressionLevelWins");
				ProgressManager.instance.ProgressionLevelLosses = ES3.Load<int>("ProgressionLevelLosses");
				ProgressManager.instance.ProgressionLevelFightsRequired = ES3.Load<int>("ProgressionLevelFightsRequired");
				ProgressManager.instance.ProgressionLevelMaxLosses = ES3.Load<int>("ProgressionLevelMaxLosses");
				ProgressManager.instance.ProgressionList = ES3.Load<List<bool>>("ProgressionList");
				ProgressManager.instance.Team = ES3.Load<List<CharacterTemplate>>("Team");
				ProgressManager.instance.EnemyTeam = ES3.Load<List<CharacterTemplate>>("EnemyTeam");
				ProgressManager.instance.EnemyTeamName = ES3.Load<string>("EnemyTeamName");
				ProgressManager.instance.HeroTeamName = ES3.Load<string>("HeroTeamName");
				ProgressManager.instance.UnlockedSpecialEvents = ES3.Load<List<TownEvent>>("UnlockedSpecialEvents");
				ProgressManager.instance.difficultyLevel = ES3.Load<int>("difficultyLevel");
				ProgressManager.instance.NextEvent = ES3.Load<TownEvent>("NextEvent");
				ProgressManager.instance.CompletedEvents = ES3.Load<List<TownEvent>>("CompletedEvents");
				ProgressManager.instance.EmpDemand = ES3.Load<string>("EmpDemand");
				ProgressManager.instance.EmpDesire = ES3.Load<string>("EmpDesire");
				ProgressManager.instance.EventLuckBonusDefault = ES3.Load<int>("EventLuckBonusDefault");
				ProgressManager.instance.DeadHeroes = ES3.Load<List<CharacterTemplate>>("DeadHeroes");
				ProgressManager.instance.CurrentEvent = ES3.Load<TownEvent>("CurrentEvent");
				ProgressManager.instance.CurrentEventAffectedCharacter = ES3.Load<int>("CurrentEventAffectedCharacter");
				if (GlobalVariables.instance.CareerModeActivated)
				{
					ProgressManager.instance.CurrentCareerRank = ES3.Load<int>("CurrentCareerRank");
					ProgressManager.instance.CurrentTypeOfMatch = ES3.Load<int>("CurrentTypeOfMatch");
					ProgressManager.instance.NumberOfCareerProgressionStars = ES3.Load<int>("NumberOfCareerProgressionStars");
					ProgressManager.instance.NumberOfQualifierLosses = ES3.Load<int>("NumberOfQualifierLosses");
					ProgressManager.instance.CareerNextFights = ES3.Load<List<int>>("CareerNextFiveFights");
					ProgressManager.instance.LendingStatus = ES3.Load<int>("LendingStatus");
				}
				break;
			case "RosterManager":
				RosterManager.instance.Roster = ES3.Load<List<CharacterTemplate>>("Roster");
				RosterManager.instance.RedrawRoster();
				break;
			case "InventoryManager":
				InventoryManager.instance.InventoryList = ES3.Load<List<Item>>("InventoryList");
				InventoryManager.instance.RedrawInventory();
				break;
			case "EquipmentManager":
				EquipmentManager.instance.CreateLists();
				EquipmentManager.instance.Hero1Equipment = ES3.Load<List<Equipment>>("Hero1Equipment");
				EquipmentManager.instance.Hero2Equipment = ES3.Load<List<Equipment>>("Hero2Equipment");
				EquipmentManager.instance.Hero3Equipment = ES3.Load<List<Equipment>>("Hero3Equipment");
				EquipmentManager.instance.Hero4Equipment = ES3.Load<List<Equipment>>("Hero4Equipment");
				EquipmentManager.instance.Enemy1Equipment = ES3.Load<List<Equipment>>("Enemy1Equipment");
				EquipmentManager.instance.Enemy2Equipment = ES3.Load<List<Equipment>>("Enemy2Equipment");
				EquipmentManager.instance.Enemy3Equipment = ES3.Load<List<Equipment>>("Enemy3Equipment");
				EquipmentManager.instance.Enemy4Equipment = ES3.Load<List<Equipment>>("Enemy4Equipment");
				if (GlobalVariables.instance.CareerModeActivated)
				{
					EquipmentManager.instance.CareerTeam1Enemy1Equipment = ES3.Load<List<Equipment>>("CareerTeam1Enemy1Equipment");
					EquipmentManager.instance.CareerTeam1Enemy2Equipment = ES3.Load<List<Equipment>>("CareerTeam1Enemy2Equipment");
					EquipmentManager.instance.CareerTeam1Enemy3Equipment = ES3.Load<List<Equipment>>("CareerTeam1Enemy3Equipment");
					EquipmentManager.instance.CareerTeam1Enemy4Equipment = ES3.Load<List<Equipment>>("CareerTeam1Enemy4Equipment");
					EquipmentManager.instance.CareerTeam2Enemy1Equipment = ES3.Load<List<Equipment>>("CareerTeam2Enemy1Equipment");
					EquipmentManager.instance.CareerTeam2Enemy2Equipment = ES3.Load<List<Equipment>>("CareerTeam2Enemy2Equipment");
					EquipmentManager.instance.CareerTeam2Enemy3Equipment = ES3.Load<List<Equipment>>("CareerTeam2Enemy3Equipment");
					EquipmentManager.instance.CareerTeam2Enemy4Equipment = ES3.Load<List<Equipment>>("CareerTeam2Enemy4Equipment");
					EquipmentManager.instance.CareerTeam3Enemy1Equipment = ES3.Load<List<Equipment>>("CareerTeam3Enemy1Equipment");
					EquipmentManager.instance.CareerTeam3Enemy2Equipment = ES3.Load<List<Equipment>>("CareerTeam3Enemy2Equipment");
					EquipmentManager.instance.CareerTeam3Enemy3Equipment = ES3.Load<List<Equipment>>("CareerTeam3Enemy3Equipment");
					EquipmentManager.instance.CareerTeam3Enemy4Equipment = ES3.Load<List<Equipment>>("CareerTeam3Enemy4Equipment");
				}
				EquipmentManager.instance.RecalculateTeamModifiers();
				break;
			case "TownManager":
				TownManager.instance.RecruitableList = ES3.Load<List<CharacterTemplate>>("RecruitableList");
				TownManager.instance.ShopList = ES3.Load<List<Item>>("ShopList");
				TownManager.instance.EventStarted = ES3.Load("EventStarted", defaultValue: true);
				TownManager.instance.RedrawRecruits();
				TownManager.instance.RedrawShopItems();
				TownManager.instance.RedrawEmperorDemands();
				if (GlobalVariables.instance.CareerModeActivated)
				{
					TownManager.instance.NumberOfTeamsToLoad = ES3.Load<int>("numberofcareerteams");
				}
				break;
			case "GlobalVariables":
				GlobalVariables.instance.ChosenGameDifficulty = ES3.Load<int>("ChosenGameDifficulty");
				GlobalVariables.instance.GloryLevel = ES3.Load<int>("GloryLevel");
				GlobalVariables.instance.EndlessModeActivated = ES3.Load<bool>("EndlessModeActivated");
				GlobalVariables.instance.ChallengeNeedyEmperor = ES3.Load<bool>("ChallengeNeedyEmperor");
				GlobalVariables.instance.ChallengeBurlyEnemies = ES3.Load<bool>("ChallengeBurlyEnemies");
				GlobalVariables.instance.ChallengeDeadIsDead = ES3.Load<bool>("ChallengeDeadIsDead");
				GlobalVariables.instance.ChallengeLongTournament = ES3.Load<bool>("ChallengeLongTournament");
				GlobalVariables.instance.ChallengeNoDeaths = ES3.Load<bool>("ChallengeNoDeaths");
				GlobalVariables.instance.ChallengeNoLosses = ES3.Load<bool>("ChallengeNoLosses");
				GlobalVariables.instance.ChallengeRandomSkills = ES3.Load<bool>("ChallengeRandomSkills");
				GlobalVariables.instance.ChallengeSmallTeam = ES3.Load<bool>("ChallengeSmallTeam");
				GlobalVariables.instance.ChallengeLoneSurvivor = ES3.Load("ChallengeLoneSurvivor", defaultValue: false);
				GlobalVariables.instance.ChallengeBeastMode = ES3.Load("ChallengeBeastMode", defaultValue: false);
				GlobalVariables.instance.CareerModeActivated = ES3.Load("CareerModeActivated", "Data.es3", defaultValue: false);
				GlobalVariables.instance.CareerPrestigeLevel = ES3.Load("CareerPrestigeLevel", "Data.es3", 1);
				break;
			default:
				Debug.LogWarning((object)"<color=red>LOADCOMPONENT CALLED WITH INVALID PARAMETER</color>");
				return;
			case "BattleProcessor":
			case "MapManager":
				break;
			}
			ComponentsStillLoading--;
			if (ComponentsStillLoading <= 0)
			{
				LoadActive = false;
			}
			Debug.Log((object)("Component loaded: " + component + " (still loading: " + ComponentsStillLoading + ")"));
		}
		catch (Exception ex)
		{
			Debug.Log((object)("EXCEPTION SaveManager:LoadComponent: " + ex.StackTrace + " ||| MESSAGE: ||| " + ex.Message));
		}
	}

	public IEnumerator FadeOutLoadScreen(float speed)
	{
		if (!FadeStarted)
		{
			FadeStarted = true;
			yield return (object)new WaitForSeconds(1f);
			while (ComponentsStillLoading > 0)
			{
				yield return null;
			}
			while (LoadScreen.alpha > 0f)
			{
				CanvasGroup loadScreen = LoadScreen;
				loadScreen.alpha -= Time.deltaTime * speed;
				yield return null;
			}
			EquipmentManager.instance.RecheckEquipListOrder();
			LoadScreen.blocksRaycasts = false;
			FadeStarted = false;
		}
	}

