	public void SaveFinalScore(List<string> Details, bool Endless)
	{
		int result = 0;
		int.TryParse(Details[0], out result);
		int num = IsFinalScoreWorthy(result, Endless);
		if (num == 4)
		{
			try
			{
				ES3.Save<List<string>>("HighScoreEndless", Details, "Profile.es3");
				Debug.Log((object)("Final score saved (slot: " + num + ",score: " + result + ")"));
				return;
			}
			catch (Exception ex)
			{
				Debug.Log((object)("EXCEPTION SaveManager:SaveFinalScore: " + ex.StackTrace + " ||| MESSAGE: ||| " + ex.Message));
				UIManager.instance.ShowErrorMessage(LocalizationManager.GetTranslation("MESSAGE/MESSAGE_saveproblem"), 2f);
				return;
			}
		}
		if (num > 0)
		{
			try
			{
				ES3.Save<List<string>>("HighScore" + num, Details, "Profile.es3");
				Debug.Log((object)("Final score saved (slot: " + num + ",score: " + result + ")"));
			}
			catch (Exception ex2)
			{
				Debug.Log((object)("EXCEPTION SaveManager:SaveFinalScore: " + ex2.StackTrace + " ||| MESSAGE: ||| " + ex2.Message));
				UIManager.instance.ShowErrorMessage(LocalizationManager.GetTranslation("MESSAGE/MESSAGE_saveproblem"), 2f);
			}
		}
	}

	public int IsFinalScoreWorthy(int score, bool Endless)
	{
		List<int> list = CheckCurrentScores();
		int num = 0;
		if (!Endless)
		{
			if (list.Count < 3)
			{
				num = (ES3.KeyExists("HighScore2", "Profile.es3") ? 3 : ((!ES3.KeyExists("HighScore1", "Profile.es3")) ? 1 : 2));
			}
			else
			{
				int num2 = score;
				int num3 = 0;
				int num4 = 0;
				foreach (int item in list)
				{
					num3++;
					if (item < num2)
					{
						num2 = item;
						num4 = num3;
					}
				}
				if (num2 < score)
				{
					num = num4;
				}
			}
		}
		else if (CheckCurrentEndlessScore() < score)
		{
			num = 4;
		}
		Debug.Log((object)("Save score to slot: " + num));
		return num;
	}

	public List<int> CheckCurrentScores()
	{
		List<int> list = new List<int>();
		int result = 0;
		if (ES3.FileExists("Profile.es3"))
		{
			if (ES3.KeyExists("HighScore1", "Profile.es3"))
			{
				int.TryParse(ES3.Load<List<string>>("HighScore1", "Profile.es3")[0], out result);
				list.Add(result);
				result = 0;
			}
			if (ES3.KeyExists("HighScore2", "Profile.es3"))
			{
				int.TryParse(ES3.Load<List<string>>("HighScore2", "Profile.es3")[0], out result);
				list.Add(result);
				result = 0;
			}
			if (ES3.KeyExists("HighScore3", "Profile.es3"))
			{
				int.TryParse(ES3.Load<List<string>>("HighScore3", "Profile.es3")[0], out result);
				list.Add(result);
				result = 0;
			}
		}
		return list;
	}

	public int CheckCurrentEndlessScore()
	{
		int result = 0;
		if (ES3.FileExists("Profile.es3") && ES3.KeyExists("HighScoreEndless", "Profile.es3"))
		{
			int.TryParse(ES3.Load<List<string>>("HighScoreEndless", "Profile.es3")[0], out result);
		}
		return result;
	}
}
[CreateAssetMenu(fileName = "New Buff", menuName = "Buff")]
public class Buff : ScriptableObject
{
	public enum ActivationType
	{
		Once,
		EveryTurn,
		UponExpiry
	}

	public Sprite Icon;

	public bool IsItBuff;

	public string title;

	[TextArea]
	public string Description;

	public string BuffType;

	public int BuffValue;

	public int Duration;

	public ActivationType Activation;

	public string OnApplyText;

	public string OnApplyAnimation;

	public string OnApplySFX;

	public string GetTooltip()
	{
		string translation = LocalizationManager.GetTranslation("UI.BATTLE/UI.BATTLE_turns");
		translation = translation.Replace("{[TURNS]}", "<color=#FFCB37>{[TURNS]}</color>");
		GlobalVariables.instance.PluralHelper.SetParameterValue("TURNS", Duration.ToString());
		LocalizationManager.ApplyLocalizationParams(ref translation);
		if (BuffType == "Death")
		{
			return "<color=#FFCB37>" + GetTranslatedTitle() + "</color>\n" + LocalizationManager.GetTranslation("BUFF/BUFF_" + title + "_desc");
		}
		return "<color=#FFCB37>" + GetTranslatedTitle() + "</color>\n<color=#D9D9D9>" + LocalizationManager.GetTranslation("UI.BATTLE/UI.BATTLE_duration") + ":</color> " + translation + " \n" + GetTranslatedDescription();
	}

	public string GetTranslatedTitle()
	{
		return LocalizationManager.GetTranslation("BUFF/BUFF_" + title);
	}

	public string GetTranslatedDescription()
	{
		string text = LocalizationManager.GetTranslation("BUFF/BUFF_" + title + "_desc");
		if (BuffType == "DodgePenalty")
		{
			text = text.Replace("<VALUE>", Mathf.Abs(BuffValue).ToString());
		}
		return text;
	}
}
