	public override void Initialize(int initRarity = 0, int rarityBonus = 0, int maxRarity = 5)
	{
		if (initRarity > 5)
		{
			initRarity = 5;
		}
		else if (initRarity < 0)
		{
			initRarity = 0;
		}
		switch (initRarity)
		{
		case 5:
			SetRarity(1);
			break;
		case 4:
			SetRarity(8);
			break;
		case 3:
			SetRarity(20);
			break;
		case 2:
			SetRarity(40);
			break;
		case 1:
			SetRarity(99);
			break;
		case 0:
			SetRarity(0, rarityBonus, maxRarity);
			break;
		}
		itemLevel += raritylvlbuff;
		itemLevel--;
		StatPoints = itemLevel;
		int num = Random.Range(0, 100);
		if (num < skillGainChance / 2)
		{
			MaxAPmodifier = Random.Range(0, InitMaxAPmax);
			StatPoints -= 3 * MaxAPmodifier;
		}
		num = Random.Range(0, 100);
		if (Bow)
		{
			givesSkill = DataTables.instance.GetRandomBowSkill(skillGainRarity);
			StatPoints -= 2;
		}
		else if (num < skillGainChance && (Object)(object)givesSkill != (Object)null)
		{
			givesSkill = DataTables.instance.GetRandomSkill(0, skillGainRarity);
			StatPoints -= 2;
		}
		if (StatPoints <= 0)
		{
			StatPoints = 1;
		}
		List<string> list = new List<string>();
		list = FilterStat("STR", InitSTRmax, list);
		list = FilterStat("AGI", InitAGImax, list);
		list = FilterStat("WIS", InitWISmax, list);
		list = FilterStat("VIT", InitVITmax, list);
		list = FilterStat("ARM", InitARMORmax, list);
		list = FilterStat("PDMG", InitPhysicalDamagemax, list);
		list = FilterStat("KB", InitKnockbackChancemax, list);
		list = FilterStat("CRIT", InitCritChancemax, list);
		list = FilterStat("DODGE", InitDodgeChancemax, list);
		list = FilterStat("MP", InitMPmax, list);
		list = FilterStat("MDMG", InitMagicDamagemax, list);
		list = FilterStat("MDEF", InitMagicDefensemax, list);
		list = FilterStat("HP", InitHPmax, list);
		list = FilterStat("DRES", InitDebuffResistancemax, list);
		list = FilterStat("ADMG", InitArcheryDamagemax, list);
		list = FilterStat("KBRES", InitKnockbackResistancemax, list);
		list = FilterStat("DCHANCE", InitDebuffChancemax, list);
		if (ChosenSecondaryStats.Count > 0)
		{
			ChosenPrimaryStats.Add(ChosenSecondaryStats[0]);
		}
		for (int i = 0; i < 5; i++)
		{
			if (list.Count <= 0)
			{
				break;
			}
			int index = Random.Range(0, list.Count);
			ChosenPrimaryStats.Add(list[index]);
			list.RemoveAt(index);
		}
		float num2 = 0.35f;
		for (int j = 0; j < 5; j++)
		{
			if (StatPoints <= 0)
			{
				break;
			}
			FillModifier(ChosenPrimaryStats[j], num2);
			if (j < 2)
			{
				num2 -= 0.1f;
			}
			else if (j == 3)
			{
				num2 = 1f;
			}
		}
		if (StatPoints > 0)
		{
			Debug.LogWarning((object)("<color=red>" + ((Object)this).name + ": POINTS REMAINING: </color>" + StatPoints));
		}
		if (ProfileManager.instance.DLC_ContentEnabled && MainStat != "PDMG" && MainStat != "MDMG" && ArcheryDamagemodifier == 0 && equipSlot != EquipmentSlot.Weapon && Random.Range(0, 10) < 3)
		{
			if (PhysicalDamagemodifier > 0)
			{
				ArcheryDamagemodifier = PhysicalDamagemodifier;
				PhysicalDamagemodifier = 0;
			}
			else if (MagicDamagemodifier > 0)
			{
				ArcheryDamagemodifier = MagicDamagemodifier;
				MagicDamagemodifier = 0;
			}
		}
		if ((Object)(object)givesSkill != (Object)null)
		{
			itemValue += 5;
		}
		if ((Object)(object)givesPerk != (Object)null)
		{
			itemValue += 5;
		}
		itemValue = STRmodifier + AGImodifier + WISmodifier + VITmodifier + ARMORmodifier + PhysicalDamagemodifier + KnockbackChancemodifier / 2 + Mathf.RoundToInt((float)CritChancemodifier / 1.5f) + Mathf.RoundToInt((float)DodgeChancemodifier / 1.5f) + MPmodifier / 5 + MagicDamagemodifier + MagicDefensemodifier + HPmodifier / 5 + DebuffResistancemodifier / 2 + MaxAPmodifier * 5 + ArcheryDamagemodifier + DebuffChancemodifier / 2 + KnockbackResistancemodifier / 2;
		itemValue = Mathf.RoundToInt(4f * priceRarityModifier * (float)itemValue);
		shopValue = Mathf.RoundToInt(Random.Range((1f - GlobalVariables.instance.ShopItemVariance) * (float)itemValue, (1f + GlobalVariables.instance.ShopItemVariance) * (float)itemValue));
		if (itemRarity == Rarity.Legendary && LocalizationManager.CurrentLanguage == "English")
		{
			if (Bow)
			{
				title = DataTables.instance.GetRandomBowName();
			}
			else
			{
				title = DataTables.instance.GetRandomItemName(equipSlot);
			}
		}
	}

	private void SetRarity(int predetermined = 0, int rarityBonus = 0, int maxRarity = 5)
	{
		int num = Random.Range(0, 100) - rarityBonus;
		if (predetermined != 0)
		{
			num = predetermined;
		}
		int num2 = Random.Range(0, 100);
		skillGainRarity = 1;
		if (num < GlobalVariables.instance.EquipmentRarityLegendary && maxRarity >= 5)
		{
			itemRarity = Rarity.Legendary;
			skillGainChance = 30;
			raritylvlbuff = 30;
			raritystatmaxbonus = 10;
			priceRarityModifier = 2.5f;
			if (num2 > 70)
			{
				skillGainRarity = 3;
			}
			else if (num2 > 30)
			{
				skillGainRarity = 2;
			}
		}
		else if (num < GlobalVariables.instance.EquipmentRarityEpic && maxRarity >= 4)
		{
			itemRarity = Rarity.Epic;
			skillGainChance = 20;
			raritylvlbuff = 20;
			raritystatmaxbonus = 6;
			priceRarityModifier = 2f;
			if (num2 > 85)
			{
				skillGainRarity = 3;
			}
			else if (num2 > 45)
			{
				skillGainRarity = 2;
			}
		}
		else if (num < GlobalVariables.instance.EquipmentRarityRare && maxRarity >= 3)
		{
			itemRarity = Rarity.Rare;
			skillGainChance = 10;
			raritylvlbuff = 12;
			raritystatmaxbonus = 3;
			priceRarityModifier = 1.6f;
			if (num2 > 50)
			{
				skillGainRarity = 2;
			}
		}
		else if (num < GlobalVariables.instance.EquipmentRarityUncommon && maxRarity >= 2)
		{
			itemRarity = Rarity.Uncommon;
			skillGainChance = 5;
			raritylvlbuff = 6;
			raritystatmaxbonus = 1;
			priceRarityModifier = 1.3f;
			if (num2 > 65)
			{
				skillGainRarity = 2;
			}
		}
		else
		{
			itemRarity = Rarity.Common;
			skillGainChance = 1;
			raritylvlbuff = 0;
			raritystatmaxbonus = 0;
			priceRarityModifier = 1f;
			if (num2 > 90)
			{
				skillGainRarity = 2;
			}
		}
	}

	public List<string> FilterStat(string stat, int maxvalue, List<string> list)
	{
		if (MainStat == stat)
		{
			ChosenPrimaryStats.Add(stat);
		}
		else if (MainStat2 == stat)
		{
			ChosenSecondaryStats.Add(stat);
		}
		else if (maxvalue > 0)
		{
			list.Add(stat);
		}
		return list;
	}

	public void FillModifier(string stat, float minimumallocation)
	{
		int num = 0;
		int statPoints = StatPoints;
		int num2 = Mathf.RoundToInt(minimumallocation * (float)itemLevel);
		switch (stat)
		{
		case "STR":
		{
			int num3 = InitSTRmax - STRmodifier + raritystatmaxbonus;
			if (num3 <= num2)
			{
				num2 = num3;
			}
			num += Mathf.Clamp(Random.Range(num2, num3), 1, statPoints);
			STRmodifier += num;
			break;
		}
		case "AGI":
		{
			int num3 = InitAGImax - AGImodifier + raritystatmaxbonus;
			if (num3 <= num2)
			{
				num2 = num3;
			}
			num += Mathf.Clamp(Random.Range(num2, num3), 1, statPoints);
			AGImodifier += num;
			break;
		}
		case "WIS":
		{
			int num3 = InitWISmax - WISmodifier + raritystatmaxbonus;
			if (num3 <= num2)
			{
				num2 = num3;
			}
			num += Mathf.Clamp(Random.Range(num2, num3), 1, statPoints);
			WISmodifier += num;
			break;
		}
		case "VIT":
		{
			int num3 = InitVITmax - VITmodifier + raritystatmaxbonus;
			if (num3 <= num2)
			{
				num2 = num3;
			}
			num += Mathf.Clamp(Random.Range(num2, num3), 1, statPoints);
			VITmodifier += num;
			break;
		}
		case "ARM":
		{
			int num3 = InitARMORmax - ARMORmodifier + raritystatmaxbonus;
			if (num3 <= num2)
			{
				num2 = num3;
			}
			num += Mathf.Clamp(Random.Range(num2, num3), 1, Mathf.RoundToInt((float)statPoints * 0.7f));
			ARMORmodifier += num;
			break;
		}
		case "PDMG":
		{
			int num3 = InitPhysicalDamagemax - PhysicalDamagemodifier + raritystatmaxbonus;
			if (num3 <= num2)
			{
				num2 = num3;
			}
			num += Mathf.Clamp(Random.Range(num2, num3), 1, Mathf.RoundToInt((float)statPoints * 0.7f));
			PhysicalDamagemodifier += num;
			break;
		}
		case "KB":
		{
			int num3 = InitKnockbackChancemax - KnockbackChancemodifier + raritystatmaxbonus;
			if (num3 <= num2)
			{
				num2 = num3;
			}
			num += Mathf.Clamp(Random.Range(num2, num3 / 2), 1, statPoints);
			KnockbackChancemodifier += num * 2;
			break;
		}
		case "CRIT":
		{
			int num3 = InitCritChancemax - CritChancemodifier + raritystatmaxbonus;
			if (num3 <= num2)
			{
				num2 = num3;
			}
			num += Mathf.Clamp(Random.Range(num2, num3 / 2), 1, statPoints);
			CritChancemodifier += Mathf.RoundToInt((float)num * 1.5f);
			break;
		}
		case "DODGE":
		{
			int num3 = InitDodgeChancemax - DodgeChancemodifier + raritystatmaxbonus;
			if (num3 <= num2)
			{
				num2 = num3;
			}
			num += Mathf.Clamp(Random.Range(num2, num3 / 2), 1, statPoints);
			DodgeChancemodifier += Mathf.RoundToInt((float)num * 1.5f);
			break;
		}
		case "MP":
		{
			int num3 = InitMPmax - MPmodifier + raritystatmaxbonus;
			if (num3 <= num2)
			{
				num2 = num3;
			}
			num += Mathf.Clamp(Random.Range(num2, num3 / 4), 1, statPoints);
			MPmodifier += num * 4;
			break;
		}
		case "MDMG":
		{
			int num3 = InitMagicDamagemax - MagicDamagemodifier + raritystatmaxbonus;
			if (num3 <= num2)
			{
				num2 = num3;
			}
			num += Mathf.Clamp(Random.Range(num2, num3), 1, Mathf.RoundToInt((float)statPoints * 0.7f));
			MagicDamagemodifier += num;
			break;
		}
		case "MDEF":
		{
			int num3 = InitMagicDefensemax - MagicDefensemodifier + raritystatmaxbonus;
			if (num3 <= num2)
			{
				num2 = num3;
			}
			num += Mathf.Clamp(Random.Range(num2, num3), 1, statPoints);
			MagicDefensemodifier += num;
			break;
		}
		case "HP":
		{
			int num3 = InitHPmax - HPmodifier + raritystatmaxbonus;
			if (num3 <= num2)
			{
				num2 = num3;
			}
			num += Mathf.Clamp(Random.Range(num2, num3 / 4), 1, statPoints);
			HPmodifier += num * 4;
			break;
		}
		case "DRES":
		{
			int num3 = InitDebuffResistancemax - DebuffResistancemodifier + raritystatmaxbonus;
			if (num3 <= num2)
			{
				num2 = num3;
			}
			num += Mathf.Clamp(Random.Range(num2, num3 / 2), 1, statPoints);
			DebuffResistancemodifier += num * 2;
			break;
		}
		case "ADMG":
		{
			int num3 = InitArcheryDamagemax - ArcheryDamagemodifier + raritystatmaxbonus;
			if (num3 <= num2)
			{
				num2 = num3;
			}
			num += Mathf.Clamp(Random.Range(num2, num3), 1, Mathf.RoundToInt((float)statPoints * 0.7f));
			ArcheryDamagemodifier += num;
			break;
		}
		case "KBRES":
		{
			int num3 = InitKnockbackResistancemax - KnockbackResistancemodifier + raritystatmaxbonus;
			if (num3 <= num2)
			{
				num2 = num3;
			}
			num += Mathf.Clamp(Random.Range(num2, num3 / 2), 1, statPoints);
			KnockbackResistancemodifier += num * 2;
			break;
		}
		case "DCHANCE":
		{
			int num3 = InitDebuffChancemax - DebuffChancemodifier + raritystatmaxbonus;
			if (num3 <= num2)
			{
				num2 = num3;
			}
			num += Mathf.Clamp(Random.Range(num2, num3 / 2), 1, statPoints);
			DebuffChancemodifier += num * 2;
			break;
		}
		}
		StatPoints -= num;
	}

	public void ArcherizeEquipment()
	{
		if (PhysicalDamagemodifier > 0)
		{
			ArcheryDamagemodifier = PhysicalDamagemodifier;
			PhysicalDamagemodifier = 0;
		}
		else if (MagicDamagemodifier > 0)
		{
			ArcheryDamagemodifier = MagicDamagemodifier;
			MagicDamagemodifier = 0;
		}
	}

