[CreateAssetMenu(fileName = "New Item", menuName = "Inventory/Item")]
public class Item : ScriptableObject
{
	public Sprite icon;

	public string title;

	public Rarity itemRarity;

	public bool discounted;

	public virtual bool Use(CharacterTemplate User)
	{
		Debug.Log((object)("Used item: " + ((Object)this).name));
		return true;
	}

	public virtual void Initialize(int Rarity = 0, int rarityBonus = 0, int maxRarity = 5)
	{
		Debug.Log((object)"Trying to initialize Item, not Equipment");
	}

	public virtual int GetRealValue()
	{
		return 1;
	}

	public virtual int GetShopValue()
	{
		return 999;
	}

	public virtual void DiscountThis()
	{
	}

	public virtual string GetTooltip()
	{
		string arg = string.Empty;
		switch (itemRarity)
		{
		case Rarity.Common:
			arg = "#989898";
			break;
		case Rarity.Uncommon:
			arg = "#37D421";
			break;
		case Rarity.Rare:
			arg = "#2877FF";
			break;
		case Rarity.Epic:
			arg = "#AE39FF";
			break;
		case Rarity.Legendary:
			arg = "#FF4600";
			break;
		}
		string term = "ITEM/ITEM_" + title;
		if (itemRarity == Rarity.Legendary && LocalizationManager.CurrentLanguage == "English")
		{
			return $"<color={arg}>{title}</color>";
		}
		if (LocalizationManager.GetTermData(term) != null)
		{
			return $"<color={arg}>{LocalizationManager.GetTranslation(term)}</color>";
		}
		return $"<color={arg}>{title}</color>";
	}
}
