[CreateAssetMenu(fileName = "New Spellbook", menuName = "Inventory/Spellbook")]
public class Spellbook : Item
{
	public Skill TeachesSkill;

	public int itemValue;

	public int shopValue;

	public override void Initialize(int initRarity = 0, int rarityBonus = 0, int maxRarity = 5)
	{
		if (initRarity > 5)
		{
			initRarity = 5;
		}
		else if (initRarity < 0)
		{
			initRarity = 0;
		}
		if (ProfileManager.instance.DLC_ContentEnabled && Random.Range(0, 100) < 10)
		{
			TeachesSkill = DataTables.instance.GetRandomSkill(0, initRarity, AI: false, classType.Balanced, EpicsPossible: true, forcetype: false, ExactMatch: false, bowskill: true);
		}
		else if (initRarity != 0)
		{
			TeachesSkill = DataTables.instance.GetRandomSkill(0, initRarity);
		}
		else if (rarityBonus > 0)
		{
			TeachesSkill = DataTables.instance.GetRandomSkill(GlobalVariables.instance.SkillRarityRewardBonus);
		}
		else
		{
			TeachesSkill = DataTables.instance.GetRandomSkill();
		}
		classType bookCategory;
		try
		{
			bookCategory = TeachesSkill.BookCategory;
		}
		catch (Exception)
		{
			bookCategory = TeachesSkill.ClassType;
		}
		switch (bookCategory)
		{
		case classType.Mage:
			icon = UIManager.instance.MagicBook;
			break;
		case classType.Balanced:
			icon = UIManager.instance.MiscBook;
			break;
		case classType.Archer:
			icon = UIManager.instance.ArcheryBook;
			break;
		default:
			icon = UIManager.instance.PhysicalBook;
			break;
		}
		if (TeachesSkill.SkillRarity == Rarity.Epic)
		{
			itemValue = 240;
			itemRarity = Rarity.Epic;
		}
		else if (TeachesSkill.SkillRarity == Rarity.Rare)
		{
			itemValue = 120;
			itemRarity = Rarity.Rare;
		}
		else
		{
			itemRarity = Rarity.Uncommon;
			itemValue = 40;
		}
		shopValue = Mathf.RoundToInt(Random.Range((1f - GlobalVariables.instance.ShopItemVariance) * (float)itemValue, (1f + GlobalVariables.instance.ShopItemVariance) * (float)itemValue));
	}

	public override int GetRealValue()
	{
		return itemValue;
	}

	public override int GetShopValue()
	{
		return shopValue;
	}

	public override void DiscountThis()
	{
		shopValue = Mathf.RoundToInt(0.7f * (float)itemValue);
	}

	public override bool Use(CharacterTemplate User)
	{
		if (User.LearnSkill(TeachesSkill))
		{
			return true;
		}
		return false;
	}

	public override string GetTooltip()
	{
		return base.GetTooltip() + "\n" + LocalizationManager.GetTranslation("TOOLTIP/TOOLTIP_teachesskill") + "\n";
	}
}
