public class SellWindowManager : MonoBehaviour
{
	public static SellWindowManager instance;

	public List<Item> SellList = new List<Item>();

	public Transform SellWindowPanel;

	public TextMeshProUGUI SellPriceText;

	private int SellPrice;

	private void Awake()
	{
		if ((Object)(object)instance != (Object)null)
		{
			Object.Destroy((Object)(object)((Component)this).gameObject);
		}
		else
		{
			instance = this;
		}
	}

	public void AddToSellList(Item item)
	{
		SellList.Add(item);
		UpdatePrice();
	}

	public void RemoveFromSellList(Item item)
	{
		SellList.Remove(item);
		UpdatePrice();
	}

	public bool IsThisInSellWindow(Item item)
	{
		foreach (Item sell in SellList)
		{
			if ((Object)(object)item == (Object)(object)sell)
			{
				return true;
			}
		}
		return false;
	}

	public void UpdatePrice()
	{
		((TMP_Text)SellPriceText).SetText(CountSellPrice() + " G");
	}

	public int CountSellPrice()
	{
		SellPrice = 0;
		float sellVariable = ChangingVariables.instance.SellVariable;
		foreach (Item sell in SellList)
		{
			SellPrice += Mathf.RoundToInt((float)sell.GetShopValue() * sellVariable);
		}
		return SellPrice;
	}

	public void SellItems()
	{
		//IL_003c: Unknown result type (might be due to invalid IL or missing references)
		//IL_0042: Expected Obj, but got Unknown
		if (CountSellPrice() <= 0)
		{
			return;
		}
		AudioManager.instance.AudioEffect("Coin");
		ProgressManager.instance.ChangeGold(CountSellPrice());
		foreach (Transform item in SellWindowPanel)
		{
			Transform val = item;
			if (val.childCount > 0)
			{
				Object.Destroy((Object)(object)((Component)val.GetChild(0)).gameObject);
			}
		}
		SellList.Clear();
		UpdatePrice();
	}

	public Transform GetFirstFreeSlot()
	{
		//IL_0016: Unknown result type (might be due to invalid IL or missing references)
		//IL_001c: Expected Obj, but got Unknown
		Transform result = null;
		foreach (Transform item in SellWindowPanel)
		{
			Transform val = item;
			if (val.childCount == 0)
			{
				return val;
			}
		}
		return result;
	}

	public bool ReturnItems()
	{
		//IL_009b: Unknown result type (might be due to invalid IL or missing references)
		//IL_00a1: Expected Obj, but got Unknown
		RefreshSellWindow();
		if (SellList.Count == 0)
		{
			return true;
		}
		if (!InventoryManager.instance.IsThereRoom(SellList.Count))
		{
			UIManager.instance.ShowErrorMessage(LocalizationManager.GetTranslation("MESSAGE/MESSAGE_clearsell"));
			return false;
		}
		foreach (Item sell in SellList)
		{
			InventoryManager.instance.AddToInventory(sell);
		}
		foreach (Transform item in SellWindowPanel)
		{
			Transform val = item;
			if (val.childCount > 0)
			{
				Object.Destroy((Object)(object)((Component)val.GetChild(0)).gameObject);
			}
		}
		SellList.Clear();
		UpdatePrice();
		return true;
	}

	public void RefreshSellWindow()
	{
		//IL_0021: Unknown result type (might be due to invalid IL or missing references)
		//IL_0027: Expected Obj, but got Unknown
		int num = 0;
		SellList.Clear();
		foreach (Transform item in SellWindowPanel)
		{
			Transform val = item;
			if (val.childCount > 0)
			{
				AddToSellList(((Component)val.GetChild(0)).GetComponent<ItemDetails>().containeditem);
			}
			num++;
		}
		UpdatePrice();
	}
}
public class ShopSlot : MonoBehaviour
{
	public Button BuyButton;

	public GameObject SaleIcon;

	public GameObject GoldIcon;

	public TextMeshProUGUI GoldCost;

	public Transform ItemSlot;

	public ItemDetails Item;

	public void BuyItem()
	{
		if (!ProgressManager.instance.CanAfford(((Component)this).GetComponentInChildren<ItemDetails>().containeditem.GetShopValue()))
		{
			UIManager.instance.ShowErrorMessage(LocalizationManager.GetTranslation("MESSAGE/MESSAGE_nogold"));
			return;
		}
		if (!InventoryManager.instance.IsThereRoom())
		{
			UIManager.instance.ShowErrorMessage(LocalizationManager.GetTranslation("MESSAGE/MESSAGE_invfull"));
			return;
		}
		AudioManager.instance.AudioEffect("Buy");
		InventoryManager.instance.AddToInventory(((Component)this).GetComponentInChildren<ItemDetails>().containeditem);
		TownManager.instance.ShopList.Remove(((Component)this).GetComponentInChildren<ItemDetails>().containeditem);
		ProgressManager.instance.ChangeGold(-((Component)this).GetComponentInChildren<ItemDetails>().containeditem.GetShopValue());
		Object.Destroy((Object)(object)((Component)ItemSlot).gameObject);
		((Component)BuyButton).gameObject.SetActive(false);
		SaleIcon.gameObject.SetActive(false);
		GoldIcon.gameObject.SetActive(false);
		((Component)GoldCost).gameObject.SetActive(false);
	}
}
