	public void UseSkill(Skill skill, GameObject target, GameObject User)
	{
		if (CharacterWithTurn.ActionCooldown)
		{
			return;
		}
		BattleProcessor.instance.TurnHasRemainingTasks.Add(1);
		User.GetComponent<EnemyBattler>().LogEntryThisTurn = true;
		if (skill.MaxCooldown > 0)
		{
			if (User.GetComponent<EnemyBattler>().Controller == EnemyBattler.UnitController.AI)
			{
				User.GetComponent<EnemyBattler>().Cooldowns.Add(skill, skill.MaxCooldown + 1);
			}
			else
			{
				User.GetComponent<EnemyBattler>().Cooldowns.Add(skill, skill.MaxCooldown + 1);
				((TMP_Text)ActiveButton.CooldownTimer).SetText(skill.MaxCooldown.ToString());
				((Component)ActiveButton.CooldownTimer).gameObject.SetActive(true);
				((Selectable)((Component)ActiveButton).GetComponentInChildren<Button>()).interactable = false;
				ActiveButton = null;
			}
		}
		DeactivateTargeting();
		AttackDetails attackDetails = new AttackDetails();
		attackDetails.AttackSkill = skill.name;
		attackDetails.AttackerObject = User;
		attackDetails.TargetObject = target;
		attackDetails.Skill = skill.SkillType;
		attackDetails.ExtraDamage = skill.ExtraDamage;
		attackDetails.SkillNumberVariable = skill.SkillNumberVariable;
		attackDetails.ShowInLog = skill.ShowInLog;
		attackDetails.HitAnimation = skill.HitAnimation;
		attackDetails.HitSFX = skill.HitSFX;
		attackDetails.DamageType = skill.DamageType;
		attackDetails.CausesBuff = skill.CausesBuff;
		attackDetails.BuffChance = skill.BuffChance;
		if (skill.SkillType == SkillType.APBoostedMelee || skill.SkillType == SkillType.APBoostedSpell)
		{
			attackDetails.SpecialVariable = User.GetComponent<EnemyBattler>().RemainingMoves;
		}
		else if (skill.SkillType == SkillType.ManaBoostedSpell || skill.SkillType == SkillType.ManaBoostedSelfHeal || skill.SkillType == SkillType.ManaBoostedKnockback)
		{
			attackDetails.SpecialVariable = User.GetComponent<EnemyBattler>().ThisCharacter.CurrentMP;
		}
		else
		{
			attackDetails.SpecialVariable = skill.SpecialVariable;
		}
		if (skill.ManaCost != 0 && ProgressManager.instance.CareerSpecialRule != "Spiritual youth")
		{
			User.GetComponent<EnemyBattler>().ThisCharacter.CurrentMP -= skill.ManaCost;
			User.GetComponent<EnemyBattler>().UpdateBar();
		}
		if (skill.ConsumesTurns != 0)
		{
			User.GetComponent<EnemyBattler>().RemainingMoves -= skill.ConsumesTurns;
		}
		else if (skill.ManaCost > 0 && User.GetComponent<EnemyBattler>().Controller == EnemyBattler.UnitController.Player)
		{
			RecheckSkillAvailability(CharacterWithTurn.ThisCharacter);
		}
		BattleProcessor.instance.HandleAttack(attackDetails);
		BattleProcessor.instance.TurnHasRemainingTasks.Remove(1);
	}

