public class Slot : MonoBehaviour, IDropHandler, IEventSystemHandler
{
	public string SlotType;

	public void OnDrop(PointerEventData eventData)
	{
		//IL_00c5: Unknown result type (might be due to invalid IL or missing references)
		//IL_008a: Unknown result type (might be due to invalid IL or missing references)
		if (!Object.op_Implicit((Object)(object)eventData.pointerDrag.GetComponent<DragHandlerItem>()))
		{
			return;
		}
		if (((Component)this).transform.childCount > 0)
		{
			Transform startParent = eventData.pointerDrag.GetComponent<DragHandlerItem>().startParent;
			GameObject gameObject = ((Component)((Component)this).transform.GetChild(0)).gameObject;
			if (Object.op_Implicit((Object)(object)((Component)startParent).GetComponent<NewEquipmentSlot>()))
			{
				Item containeditem = gameObject.GetComponent<ItemDetails>().containeditem;
				if (!(containeditem is Equipment))
				{
					return;
				}
				Equipment obj = containeditem as Equipment;
				EquipmentSlot equipSlot = ((Component)startParent).GetComponent<NewEquipmentSlot>().equipSlot;
				if (obj.equipSlot != equipSlot)
				{
					return;
				}
			}
			gameObject.transform.position = startParent.position;
			gameObject.transform.SetParent(startParent);
		}
		DragHandlerItem.itemBeingDragged.transform.SetParent(((Component)this).transform);
		DragHandlerItem.itemBeingDragged.transform.position = ((Component)this).transform.position;
		InventoryManager.instance.RefreshInventory();
		if (((Component)TownManager.instance.SellWindow).gameObject.activeSelf)
		{
			SellWindowManager.instance.RefreshSellWindow();
		}
	}
}
[CreateAssetMenu(fileName = "New Character", menuName = "Character/Character")]
public class CharacterTemplate : ScriptableObject
{
	public string Charname;

	public CharacterRace Race;

	public classType RaceMainType;

	public Sprite Portrait;

	public Sprite Sprite;

	public int CharLevel;

	public int InitSTRmin;

	public int InitSTRmax;

	public int InitAGImin;

	public int InitAGImax;

	public int InitWISmin;

	public int InitWISmax;

	public int InitVITmin;

	public int InitVITmax;

	public int InitARMORmin;

	public int InitARMORmax;

	public Stat STR;

	public Stat AGI;

	public Stat WIS;

	public Stat VIT;

	public Stat ARMOR;

	public int InitPhysicalDamage;

	public int InitKnockbackChance;

	public int InitCritChance;

	public int InitDodgeChance;

	public int InitMaxAP;

	public int InitMP;

	public int InitMagicDamage;

	public int InitMagicDefense;

	public int InitHP;

	public int InitDebuffResistance;

	public int InitKnockbackResistance;

	public int InitDebuffChance;

	public int InitArcheryDamage;

	public Stat PhysicalDamage;

	public Stat KnockbackChance;

	public Stat CritChance;

	public Stat DodgeChance;

	public Stat MaxAP;

	public Stat MP;

	public Stat MagicDamage;

	public Stat MagicDefense;

	public Stat HP;

	public Stat DebuffResistance;

	public Stat KnockbackResistance;

	public Stat DebuffChance;

	public Stat ArcheryDamage;

