	public Perk Perk3;

	public Perk Perk4;

	public int characterValue;

	public int shopValue;

	public float priceRarityModifier;

	public Rarity characterRarity;

	private int skillGainChance;

	public bool Boss;

	public bool AIChar;

	public string Title;

	public Perk PerkFromTitle;

	public string StatGainFromTitle;

	public List<Skill> CharacterSkills = new List<Skill>();

	public List<Perk> CharacterPerks = new List<Perk>();

	public List<Skill> CharacterSkillsFromGear = new List<Skill>();

	public List<Perk> CharacterPerksFromGear = new List<Perk>();

	public List<Equipment> CharacterEquipList;

	public EnemyBattler BattleUnit;

	public int Wage;

	public float InherentWageScalingModifier;

	public int GamesSatInRoster;

	public virtual void Initialize(int initRarity = 0, bool AI = false, int rarityBonus = 0, int maxRarity = 5, float statmodifier = 0f, int minRarity = 1)
	{
		if (initRarity > 5)
		{
			initRarity = 5;
		}
		else if (initRarity < 0)
		{
			initRarity = 0;
		}
		switch (initRarity)
		{
		case 5:
			SetRarity(1);
			break;
		case 4:
			SetRarity(8);
			break;
		case 3:
			SetRarity(20);
			break;
		case 2:
			SetRarity(40);
			break;
		case 1:
			SetRarity(99);
			break;
		case 0:
			SetRarity(0, rarityBonus, maxRarity, minRarity);
			break;
		}
		Charname = DataTables.instance.GetRandomCharacterName(this);
		if (AI)
		{
			AIChar = true;
		}
		STR.InitializeStat(InitSTRmin, InitSTRmax);
		AGI.InitializeStat(InitAGImin, InitAGImax);
		WIS.InitializeStat(InitWISmin, InitWISmax);
		VIT.InitializeStat(InitVITmin, InitVITmax);
		ARMOR.InitializeStat(InitARMORmin, InitARMORmax);
		List<Stat> list = new List<Stat>();
		list.Add(STR);
		list.Add(AGI);
		list.Add(WIS);
		list.Add(VIT);
		list.Add(ARMOR);
		int num = Random.Range(0, 5);
		while (STR.GetBaseValue() + AGI.GetBaseValue() + WIS.GetBaseValue() + VIT.GetBaseValue() + ARMOR.GetBaseValue() < CharLevel)
		{
			list[num].IncreaseBaseValue(1);
			num++;
			if (num == 5)
			{
				num = 0;
			}
		}
		while (STR.GetBaseValue() + AGI.GetBaseValue() + WIS.GetBaseValue() + VIT.GetBaseValue() + ARMOR.GetBaseValue() > CharLevel)
		{
			list[num].DecreaseBaseValue(1);
			num++;
			if (num == 5)
			{
				num = 0;
			}
		}
		int num2 = 0;
		if (characterRarity == Rarity.Legendary)
		{
			num2 = 8;
		}
		else if (characterRarity == Rarity.Epic)
		{
			num2 = 5;
		}
		else if (characterRarity == Rarity.Rare)
		{
			num2 = 3;
		}
		else if (characterRarity == Rarity.Uncommon)
		{
			num2 = 2;
		}
		if (num2 > 0)
		{
			foreach (Stat item in list)
			{
				item.IncreaseBaseValue(num2);
			}
		}
		CharLevel += num2 * 5;
		if (statmodifier > 0f)
		{
			foreach (Stat item2 in list)
			{
				item2.IncreaseBaseValue(Mathf.RoundToInt((float)item2.GetBaseValue() * statmodifier));
			}
		}
		else if (statmodifier < 0f)
		{
			foreach (Stat item3 in list)
			{
				item3.DecreaseBaseValue(Mathf.RoundToInt((float)item3.GetBaseValue() * (0f - statmodifier)));
			}
		}
		DodgeChance.SetMaxValue(60);
		UpdateSecondaryStats();
		foreach (KeyValuePair<Stat, int> item4 in new Dictionary<Stat, int>
		{
			{ PhysicalDamage, InitPhysicalDamage },
			{ KnockbackChance, InitKnockbackChance },
			{ CritChance, InitCritChance },
			{ DodgeChance, InitDodgeChance },
			{ MaxAP, InitMaxAP },
			{ MagicDamage, InitMagicDamage },
			{ MagicDefense, InitMagicDefense },
			{ HP, InitHP },
			{ DebuffResistance, InitDebuffResistance },
			{ MP, InitMP },
			{ KnockbackResistance, InitKnockbackResistance },
			{ DebuffChance, InitDebuffChance },
			{ ArcheryDamage, InitArcheryDamage }
		})
		{
			if (item4.Value > 0)
			{
				item4.Key.AddRaceModifier(item4.Value);
			}
		}
		if (Boss)
		{
			ApplyCurrentPerkEffects();
		}
		if (!AI && RaceMainType == classType.Balanced)
		{
			if (Mathf.Abs(STR.GetBaseValue() - WIS.GetBaseValue()) <= 1)
			{
				RaceMainType = classType.Balanced;
			}
			else if (STR.GetBaseValue() < WIS.GetBaseValue())
			{
				RaceMainType = classType.Mage;
			}
			else
			{
				RaceMainType = classType.Warrior;
			}
		}
		if ((Object)(object)Skill1 == (Object)null)
		{
			if (AI)
			{
				Skill1 = DataTables.instance.GetRandomSkill(0, 0, AI: true, RaceMainType);
			}
			else if (RaceMainType == classType.Mage && GlobalVariables.instance.MagesAlwaysHaveSpell)
			{
				Skill1 = DataTables.instance.GetRandomSkill(0, 0, AI: false, RaceMainType, EpicsPossible: true, forcetype: true, ExactMatch: true);
			}
			else if (RaceMainType != classType.Balanced && Random.Range(0, 100) < GlobalVariables.instance.RecruitSkillMainTypeChance)
			{
				Skill1 = DataTables.instance.GetRandomSkill(0, 0, AI: false, RaceMainType, EpicsPossible: true, forcetype: true, ExactMatch: true);
			}
			else
			{
				Skill1 = DataTables.instance.GetRandomSkill();
			}
		}
		if ((Object)(object)Perk1 == (Object)null)
		{
			Perk1 = DataTables.instance.GetRandomPerk(0, 0, AIChar);
			ApplyPerkEffect(Perk1.PrimaryEffect, Perk1.PrimaryEffectValue);
			if (Perk1.SecondaryEffect != "")
			{
				ApplyPerkEffect(Perk1.SecondaryEffect, Perk1.SecondaryEffectValue);
			}
		}
		if (Random.Range(0, 100) < skillGainChance && (Object)(object)Skill2 == (Object)null)
		{
			do
			{
				if (AI)
				{
					Skill2 = DataTables.instance.GetRandomSkill(0, 0, AI: true, RaceMainType);
				}
				else if (RaceMainType == classType.Mage && GlobalVariables.instance.MagesAlwaysHaveSpell)
				{
					Skill2 = DataTables.instance.GetRandomSkill(0, 0, AI: false, RaceMainType, EpicsPossible: true, forcetype: true, ExactMatch: true);
				}
				else if (RaceMainType != classType.Balanced && Random.Range(0, 100) < GlobalVariables.instance.RecruitSkillMainTypeChance)
				{
					Skill2 = DataTables.instance.GetRandomSkill(0, 0, AI: false, RaceMainType, EpicsPossible: true, forcetype: true, ExactMatch: true);
				}
				else
				{
					Skill2 = DataTables.instance.GetRandomSkill();
				}
			}
			while (!(Skill1.name != Skill2.name));
		}
		if (Random.Range(0, 100) < skillGainChance / 3 && !Boss)
		{
			do
			{
				Perk2 = DataTables.instance.GetRandomPerk(0, 0, AIChar);
			}
			while (!(Perk1.name != Perk2.name));
			ApplyPerkEffect(Perk2.PrimaryEffect, Perk2.PrimaryEffectValue);
			if (Perk2.SecondaryEffect != "")
			{
				ApplyPerkEffect(Perk2.SecondaryEffect, Perk2.SecondaryEffectValue);
			}
		}
		if (Boss)
		{
			Skill randomSkill;
			do
			{
				randomSkill = DataTables.instance.GetRandomSkill(0, 99, AI: true, RaceMainType);
			}
			while (DoesCharHaveSkill(randomSkill));
			Skill3 = randomSkill;
			Skill randomSkill2;
			do
			{
				randomSkill2 = DataTables.instance.GetRandomSkill(0, 99, AI: true, RaceMainType);
			}
			while (DoesCharHaveSkill(randomSkill2));
			Skill4 = randomSkill2;
			Perk randomPerk;
			do
			{
				randomPerk = DataTables.instance.GetRandomPerk(0, 99, AIChar);
			}
			while (DoesCharHavePerk(randomPerk));
			Perk3 = randomPerk;
			ApplyPerkEffect(Perk3.PrimaryEffect, Perk3.PrimaryEffectValue);
			if (Perk3.SecondaryEffect != "")
			{
				ApplyPerkEffect(Perk3.SecondaryEffect, Perk3.SecondaryEffectValue);
			}
		}
		if (characterRarity == Rarity.Legendary || Boss)
		{
			GainTitle();
		}
		if ((Object)(object)Skill2 != (Object)null)
		{
			characterValue += 5;
		}
		if ((Object)(object)Perk2 != (Object)null)
		{
			characterValue += 5;
		}
		characterValue = STR.GetBaseValue() + AGI.GetBaseValue() + WIS.GetBaseValue() + VIT.GetBaseValue() + ARMOR.GetBaseValue();
		characterValue = Mathf.RoundToInt(4f * priceRarityModifier * (float)characterValue);
		if (Boss)
		{
			characterValue = Mathf.RoundToInt((float)characterValue * 1.2f);
		}
		UpdateHPMP();
		CreateListOfCharacterSkills();
		CreateListOfCharacterPerks();
		shopValue = Mathf.RoundToInt(Random.Range((1f - GlobalVariables.instance.ShopItemVariance) * (float)characterValue, (1f + GlobalVariables.instance.ShopItemVariance) * (float)characterValue));
		if (!AI)
		{
			InherentWageScalingModifier = Random.Range(0.85f, 1.15f);
			Wage = RecalculateWage();
		}
		else
		{
			InherentWageScalingModifier = 5f;
			Wage = 100;
		}
	}

	private void SetRarity(int predetermined = 0, int rarityBonus = 0, int maxRarity = 5, int minRarity = 1)
	{
		int num = Random.Range(0, 100) - rarityBonus;
		if (predetermined != 0)
		{
			num = predetermined;
		}
		if (num < GlobalVariables.instance.CharacterRarityLegendary && maxRarity >= 5)
		{
			characterRarity = Rarity.Legendary;
			skillGainChance = 100;
			priceRarityModifier = 2f;
		}
		else if ((num < GlobalVariables.instance.CharacterRarityEpic && maxRarity >= 4) || minRarity == 4)
		{
			characterRarity = Rarity.Epic;
			skillGainChance = 80;
			priceRarityModifier = 1.6f;
		}
		else if ((num < GlobalVariables.instance.CharacterRarityRare && maxRarity >= 3) || minRarity == 3)
		{
			characterRarity = Rarity.Rare;
			skillGainChance = 60;
			priceRarityModifier = 1.35f;
		}
		else if ((num < GlobalVariables.instance.CharacterRarityUncommon && maxRarity >= 2) || minRarity == 2)
		{
			characterRarity = Rarity.Uncommon;
			skillGainChance = 50;
			priceRarityModifier = 1.15f;
		}
		else
		{
			characterRarity = Rarity.Common;
			skillGainChance = 40;
			priceRarityModifier = 1f;
		}
	}

	public void UpdateSecondaryStats()
	{
		PhysicalDamage.SetStat(STR.GetValue());
		KnockbackChance.SetStat(STR.GetValue());
		CritChance.SetStat(AGI.GetValue());
		DodgeChance.SetStat(AGI.GetValue() / 2);
		MaxAP.SetStat(1 + AGI.GetValue() / 5);
		MagicDamage.SetStat(WIS.GetValue() / 2);
		MagicDefense.SetStat(WIS.GetValue() / 2);
		HP.SetStat(4 * VIT.GetValue());
		DebuffResistance.SetStat(VIT.GetValue());
		MP.SetStat(4 * WIS.GetValue());
		try
		{
			ArcheryDamage.SetStat(AGI.GetValue() / 3);
		}
		catch (Exception)
		{
		}
		if (!AIChar && HP.GetValue() >= 200)
		{
			SteamAchievements.instance.UnlockSteamAchievement("ACH_BigBones");
		}
	}

