	public void WageIncrease()
	{
		int num = RecalculateWage();
		if (num > Wage)
		{
			Wage = num;
		}
	}

	public int RecalculateWage()
	{
		float num = STR.GetBaseValue() + AGI.GetBaseValue() + WIS.GetBaseValue() + VIT.GetBaseValue() + ARMOR.GetBaseValue();
		float num2 = num / 5f;
		float num3 = 0.7f;
		float num4 = 0.45f;
		float num5 = 1f + ChangingVariables.instance.CareerWageModifier;
		float num6 = num + Mathf.Abs(((float)STR.GetBaseValue() - num2) * num3) + Mathf.Abs(((float)AGI.GetBaseValue() - num2) * num3) + Mathf.Abs(((float)WIS.GetBaseValue() - num2) * num3) + Mathf.Abs(((float)VIT.GetBaseValue() - num2) * num3) + Mathf.Abs(((float)ARMOR.GetBaseValue() - num2) * num3);
		float num7 = ((float)WinCount + (float)LossCount * 0.2f + 0.2f * (float)GamesSatInRoster + 0.75f * (float)KillCount) / 100f;
		int num8 = Mathf.RoundToInt(num7 * 20f);
		float num9 = 0f;
		if (characterRarity == Rarity.Uncommon)
		{
			num9 += 0.075f;
		}
		else if (characterRarity == Rarity.Rare)
		{
			num9 += 0.15f;
		}
		else if (characterRarity == Rarity.Epic)
		{
			num9 += 0.2f;
		}
		else if (characterRarity == Rarity.Legendary)
		{
			num9 += 0.3f;
		}
		float num10 = 0f;
		if (Boss)
		{
			num10 += 0.4f;
		}
		return Mathf.RoundToInt((num6 + (float)num8) * (InherentWageScalingModifier + num7 + num9 + num10) * num4 * num5);
	}

