	public string GainRandomStat(int amount = 1, int presetstat = 9)
	{
		string result = "";
		switch ((presetstat < 0 || presetstat > 4) ? Random.Range(0, 5) : presetstat)
		{
		case 0:
			STR.ChangeValue(amount);
			result = LocalizationManager.GetTranslation("STAT/STAT_strength");
			break;
		case 1:
			AGI.ChangeValue(amount);
			result = LocalizationManager.GetTranslation("STAT/STAT_agility");
			break;
		case 2:
			WIS.ChangeValue(amount);
			result = LocalizationManager.GetTranslation("STAT/STAT_wisdom");
			break;
		case 3:
			VIT.ChangeValue(amount);
			result = LocalizationManager.GetTranslation("STAT/STAT_vitality");
			break;
		case 4:
			ARMOR.ChangeValue(amount);
			result = LocalizationManager.GetTranslation("STAT/STAT_armor");
			break;
		}
		CharLevel += amount;
		UpdateSecondaryStats();
		return result;
	}

	public string LoseRandomStat(int amount = 1, int presetstat = 9)
	{
		string text = "";
		switch ((presetstat < 0 || presetstat > 4) ? Random.Range(0, 5) : presetstat)
		{
		case 0:
			amount = Mathf.Clamp(amount, -50, -1);
			STR.ChangeValue(amount);
			text = LocalizationManager.GetTranslation("STAT/STAT_strength");
			break;
		case 1:
			amount = Mathf.Clamp(amount, -50, -1);
			AGI.ChangeValue(amount);
			text = LocalizationManager.GetTranslation("STAT/STAT_agility");
			break;
		case 2:
			amount = Mathf.Clamp(amount, -50, -1);
			WIS.ChangeValue(amount);
			text = LocalizationManager.GetTranslation("STAT/STAT_wisdom");
			break;
		case 3:
			amount = Mathf.Clamp(amount, (VIT.GetBaseValue() - 1) * -1, 0);
			VIT.ChangeValue(amount);
			text = LocalizationManager.GetTranslation("STAT/STAT_vitality");
			break;
		default:
			amount = Mathf.Clamp(amount, -50, -1);
			ARMOR.ChangeValue(amount);
			text = LocalizationManager.GetTranslation("STAT/STAT_armor");
			break;
		}
		CharLevel -= amount;
		UpdateSecondaryStats();
		return text;
	}

	public void ShuffleMainStats(int bonus = 0)
	{
		CharLevel += bonus;
		STR.InitializeStat(InitSTRmin, InitSTRmax + 10);
		AGI.InitializeStat(InitAGImin, InitAGImax + 10);
		WIS.InitializeStat(InitWISmin, InitWISmax + 10);
		VIT.InitializeStat(InitVITmin, InitVITmax + 10);
		ARMOR.InitializeStat(InitARMORmin, InitARMORmax + 10);
		List<Stat> list = new List<Stat>();
		list.Add(STR);
		list.Add(AGI);
		list.Add(WIS);
		list.Add(VIT);
		list.Add(ARMOR);
		int num = Random.Range(0, 5);
		while (STR.GetBaseValue() + AGI.GetBaseValue() + WIS.GetBaseValue() + VIT.GetBaseValue() + ARMOR.GetBaseValue() < CharLevel)
		{
			list[num].IncreaseBaseValue(1);
			num++;
			if (num == 5)
			{
				num = 0;
			}
		}
		while (STR.GetBaseValue() + AGI.GetBaseValue() + WIS.GetBaseValue() + VIT.GetBaseValue() + ARMOR.GetBaseValue() > CharLevel)
		{
			list[num].DecreaseBaseValue(1);
			num++;
			if (num == 5)
			{
				num = 0;
			}
		}
		UpdateSecondaryStats();
		UpdateHPMP();
	}

	public void RandomizeSkills()
	{
		if ((Object)(object)Skill1 != (Object)null)
		{
			Skill1 = DataTables.instance.GetRandomSkill(0, 99);
		}
		if ((Object)(object)Skill2 != (Object)null)
		{
			do
			{
				Skill2 = DataTables.instance.GetRandomSkill(0, 99);
			}
			while (!((Object)(object)Skill1 != (Object)(object)Skill2));
		}
		if ((Object)(object)Skill3 != (Object)null)
		{
			do
			{
				Skill3 = DataTables.instance.GetRandomSkill(0, 99);
			}
			while (!((Object)(object)Skill3 != (Object)(object)Skill2) || !((Object)(object)Skill3 != (Object)(object)Skill1));
		}
		if ((Object)(object)Skill4 != (Object)null)
		{
			do
			{
				Skill4 = DataTables.instance.GetRandomSkill(0, 99);
			}
			while (!((Object)(object)Skill4 != (Object)(object)Skill3) || !((Object)(object)Skill4 != (Object)(object)Skill2) || !((Object)(object)Skill4 != (Object)(object)Skill1));
		}
		CreateListOfCharacterSkills();
	}

	public void SuperSkills()
	{
		Skill1 = DataTables.instance.GetRandomSkill(0, 3);
		Skill2 = DataTables.instance.GetRandomSkill(0, 3);
		Skill3 = DataTables.instance.GetRandomSkill(0, 3);
		Skill4 = DataTables.instance.GetRandomSkill(0, 3);
		CreateListOfCharacterSkills();
	}

	public void GainTitle(bool Random = true)
	{
		if (Title != "")
		{
			Debug.Log((object)"Character already has a title");
		}
		else if (Random)
		{
			Title = DataTables.instance.GetRandomTitle();
			switch (Random.Range(0, 5))
			{
			case 0:
				STR.AddTitleModifier(GlobalVariables.instance.StatgainFromTitle);
				StatGainFromTitle = "Strength";
				break;
			case 1:
				AGI.AddTitleModifier(GlobalVariables.instance.StatgainFromTitle);
				StatGainFromTitle = "Agility";
				break;
			case 2:
				WIS.AddTitleModifier(GlobalVariables.instance.StatgainFromTitle);
				StatGainFromTitle = "Wisdom";
				break;
			case 3:
				VIT.AddTitleModifier(GlobalVariables.instance.StatgainFromTitle);
				StatGainFromTitle = "Vitality";
				break;
			case 4:
				ARMOR.AddTitleModifier(GlobalVariables.instance.StatgainFromTitle);
				StatGainFromTitle = "Armor";
				break;
			}
			PerkFromTitle = GainPerk(50, PreventAmnesiac: true);
			UpdateSecondaryStats();
		}
	}

	public Perk GainPerk(int chancebonus = 0, bool PreventAmnesiac = false)
	{
		Perk perk = null;
		if (AIChar)
		{
			PreventAmnesiac = true;
		}
		if (IsThereRoomForPerk())
		{
			int num = 0;
			do
			{
				perk = DataTables.instance.GetRandomPerk(chancebonus, 0, PreventAmnesiac);
				if (!DoesCharHavePerk(perk))
				{
					break;
				}
				num++;
			}
			while (num <= 30);
			LearnPerk(perk);
		}
		return perk;
	}

	public string GetTranslatedTitleStatGain()
	{
		return LocalizationManager.GetTermTranslation("STAT/STAT_" + StatGainFromTitle.ToLower());
	}

	public string GetTranslatedPerkName()
	{
		if ((Object)(object)PerkFromTitle == (Object)null)
		{
			return "";
		}
		return LocalizationManager.GetTermTranslation("PERK/PERK_" + PerkFromTitle.name);
	}

	public void CauseInjuryInTown(int amount)
	{
		InjuryCount += amount;
		string text = "";
		if (InjuryCount > 9)
		{
			ProgressManager.instance.PermanentlyKillUnit(this);
			text = LocalizationManager.GetTranslation("MESSAGE/MESSAGE_chardied");
			text = text.Replace("<CHAR>", Charname);
			UIManager.instance.ShowErrorMessage(text, 0.5f);
		}
		else
		{
			UpdateHPMP();
			TownManager.instance.RedrawTeamBars();
			RosterManager.instance.RedrawRoster();
		}
	}

	public void HealInjury(int amount)
	{
		if (InjuryCount == 0)
		{
			return;
		}
		InjuryCount -= amount;
		foreach (Perk characterPerk in CharacterPerks)
		{
			if (characterPerk.name == "Persistent")
			{
				InjuryCount -= 2;
				InjuryCount = Mathf.Clamp(InjuryCount, 0, 9);
			}
		}
		UpdateHPMP();
	}

	public int FullRecovery()
	{
		int injuryCount = InjuryCount;
		InjuryCount = 0;
		UpdateHPMP();
		return injuryCount;
	}

	public void UpdateHPMP()
	{
		CurrentHP = Mathf.RoundToInt((10f - (float)InjuryCount) / 10f * (float)HP.GetValue());
		CurrentMP = Mathf.Clamp(MP.GetValue(), 0, int.MaxValue);
	}

	public int RegainHP(int amount)
	{
		if (ProgressManager.instance.EmpDemand == "Natural selection" && !AIChar)
		{
			BattleProcessor.instance.isEmperorAnnoyed = true;
		}
		int num = Mathf.Clamp(amount, 0, HP.GetValue() - CurrentHP);
		CurrentHP += num;
		return num;
	}

	public int ReduceHP(int amount, bool deathpossible = false)
	{
		int num = amount;
		if (!deathpossible)
		{
			num = Mathf.Clamp(amount, 0, CurrentHP - 1);
		}
		if (ProgressManager.instance.CareerSpecialRule == "Spirit of the Whale")
		{
			num = Mathf.RoundToInt((float)num / 2f);
		}
		CurrentHP -= num;
		return num;
	}

	public int RegainMP(int amount)
	{
		int num = Mathf.Clamp(amount, 0, MP.GetValue() - CurrentMP);
		CurrentMP += num;
		return num;
	}

	public int ReduceMP(int amount)
	{
		int num = Mathf.Clamp(amount, 0, CurrentMP);
		CurrentMP -= num;
		return num;
	}

	public int CalculateTrainingCost(int stat, int baseprice)
	{
		float num = 0f;
		int num2 = 5;
		float num3 = 1.7f;
		switch (stat)
		{
		case 1:
			num = ((float)STR.GetBaseValue() + num3 / (float)STR.GetBaseValue()) / (float)(InitSTRmax + num2);
			break;
		case 2:
			num = ((float)AGI.GetBaseValue() + num3 / (float)AGI.GetBaseValue()) / (float)(InitAGImax + num2);
			break;
		case 3:
			num = ((float)WIS.GetBaseValue() + num3 / (float)WIS.GetBaseValue()) / (float)(InitWISmax + num2);
			break;
		case 4:
			num = ((float)VIT.GetBaseValue() + num3 / (float)VIT.GetBaseValue()) / (float)(InitVITmax + num2);
			break;
		case 5:
			num = 1f;
			baseprice = Mathf.Clamp(10 * ProgressManager.instance.ProgressionLevel, 10, 50);
			break;
		}
		return Mathf.RoundToInt((float)baseprice * num);
	}

	public float EstimateCharacterQuality()
	{
		float num = 0f;
		if (characterRarity == Rarity.Legendary)
		{
			num += 1.2f;
		}
		else if (characterRarity == Rarity.Epic)
		{
			num++;
		}
		else if (characterRarity == Rarity.Rare)
		{
			num += 0.85f;
		}
		else
		{
			num = ((characterRarity != Rarity.Uncommon) ? (num + 0.65f) : (num + 0.75f));
		}
		foreach (Equipment characterEquip in CharacterEquipList)
		{
			if ((Object)(object)characterEquip != (Object)null)
			{
				if (characterEquip.itemRarity != Rarity.Legendary)
				{
					if (characterEquip.itemRarity != Rarity.Epic)
					{
						if (characterEquip.itemRarity != Rarity.Rare)
						{
							num = ((characterEquip.itemRarity != Rarity.Uncommon) ? (num + 0.1f) : (num + 0.15f));
						}
						else
						{
							num += 0.2f;
						}
					}
					else
					{
						num += 0.25f;
					}
				}
				else
				{
					num += 0.3f;
				}
			}
		}
		if (Boss && !GlobalVariables.instance.ChallengeBeastMode)
		{
			num *= 4f;
		}
		foreach (Perk characterPerk in CharacterPerks)
		{
			if (characterPerk.name == "Famous")
			{
				num *= 2f;
			}
		}
		num += 0.03f * (float)KillCount;
		num += 0.05f * (float)WinCount;
		if (Title != null)
		{
			num += 0.2f;
		}
		return num;
	}

	public bool DoesThisCharacterHaveABow()
	{
		bool result = false;
		foreach (Equipment characterEquip in CharacterEquipList)
		{
			if (characterEquip.Bow)
			{
				result = true;
				break;
			}
		}
		return result;
	}
}
