[Serializable]
public class Stat
{
	[SerializeField]
	private int baseValue;

	[SerializeField]
	private string description;

	[SerializeField]
	private List<int> modifiers = new List<int>();

	[SerializeField]
	private List<int> gearmodifiers = new List<int>();

	[SerializeField]
	private List<int> racemodifiers = new List<int>();

	[SerializeField]
	private List<int> perkmodifiers = new List<int>();

	[SerializeField]
	private List<int> buffmodifiers = new List<int>();

	[SerializeField]
	private List<int> titlemodifiers = new List<int>();

	[SerializeField]
	private int MaxValue = 1000;

	public void SetMaxValue(int value)
	{
		MaxValue = value;
	}

	public int GetValue()
	{
		int finalValue = baseValue;
		modifiers.ForEach((int x) =>
		{
			finalValue += x;
		});
		gearmodifiers.ForEach((int x) =>
		{
			finalValue += x;
		});
		titlemodifiers.ForEach((int x) =>
		{
			finalValue += x;
		});
		racemodifiers.ForEach((int x) =>
		{
			finalValue += x;
		});
		perkmodifiers.ForEach((int x) =>
		{
			finalValue += x;
		});
		finalValue = Mathf.Clamp(finalValue, int.MinValue, MaxValue);
		buffmodifiers.ForEach((int x) =>
		{
			finalValue += x;
		});
		finalValue = Mathf.Clamp(finalValue, int.MinValue, MaxValue);
		return finalValue;
	}

	public void ChangeValue(int modifier)
	{
		if (modifier != 0)
		{
			baseValue += modifier;
		}
	}

	public void AddModifier(int modifier)
	{
		if (modifier != 0)
		{
			modifiers.Add(modifier);
		}
	}

	public void RemoveModifier(int modifier)
	{
		if (modifier != 0)
		{
			modifiers.Remove(modifier);
		}
	}

	public void AddGearModifier(int modifier)
	{
		if (modifier != 0)
		{
			gearmodifiers.Add(modifier);
		}
	}

	public void RemoveGearModifier(int modifier)
	{
		if (modifier != 0)
		{
			gearmodifiers.Remove(modifier);
		}
	}

	public void AddTitleModifier(int modifier)
	{
		if (modifier != 0)
		{
			titlemodifiers.Add(modifier);
		}
	}

	public void RemoveTitleModifier(int modifier)
	{
		if (modifier != 0)
		{
			titlemodifiers.Remove(modifier);
		}
	}

	public void AddRaceModifier(int modifier)
	{
		if (modifier != 0)
		{
			racemodifiers.Add(modifier);
		}
	}

	public void RemoveRaceModifier(int modifier)
	{
		if (modifier != 0)
		{
			racemodifiers.Remove(modifier);
		}
	}

	public void AddPerkModifier(int modifier)
	{
		if (modifier != 0)
		{
			perkmodifiers.Add(modifier);
		}
	}

	public void RemovePerkModifier(int modifier)
	{
		if (modifier != 0)
		{
			perkmodifiers.Remove(modifier);
		}
	}

	public void AddBuffModifier(int modifier)
	{
		if (modifier != 0)
		{
			buffmodifiers.Add(modifier);
		}
	}

	public void RemoveBuffModifier(int modifier)
	{
		if (modifier != 0)
		{
			buffmodifiers.Remove(modifier);
		}
	}

	public void RemovePositiveBuffModifiers()
	{
		List<int> list = new List<int>();
		foreach (int buffmodifier in buffmodifiers)
		{
			if (buffmodifier > 0)
			{
				list.Add(buffmodifier);
			}
		}
		foreach (int item in list)
		{
			buffmodifiers.Remove(item);
		}
	}

	public void RemoveNegativeBuffModifiers()
	{
		List<int> list = new List<int>();
		foreach (int buffmodifier in buffmodifiers)
		{
			if (buffmodifier < 0)
			{
				list.Add(buffmodifier);
			}
		}
		foreach (int item in list)
		{
			buffmodifiers.Remove(item);
		}
	}

	public int GetBaseValue()
	{
		return baseValue;
	}

	public int GetGearModifiers()
	{
		int totalmodifiers = 0;
		gearmodifiers.ForEach((int x) =>
		{
			totalmodifiers += x;
		});
		return totalmodifiers;
	}

	public int GetTitleModifiers()
	{
		int totalmodifiers = 0;
		titlemodifiers.ForEach((int x) =>
		{
			totalmodifiers += x;
		});
		return totalmodifiers;
	}

	public int GetRaceModifiers()
	{
		int totalmodifiers = 0;
		racemodifiers.ForEach((int x) =>
		{
			totalmodifiers += x;
		});
		return totalmodifiers;
	}

	public int GetPerkModifiers()
	{
		int totalmodifiers = 0;
		perkmodifiers.ForEach((int x) =>
		{
			totalmodifiers += x;
		});
		return totalmodifiers;
	}

	public int GetBuffModifiers()
	{
		int totalmodifiers = 0;
		buffmodifiers.ForEach((int x) =>
		{
			totalmodifiers += x;
		});
		return totalmodifiers;
	}

	public int GetMiscModifiers()
	{
		int totalmodifiers = 0;
		modifiers.ForEach((int x) =>
		{
			totalmodifiers += x;
		});
		return totalmodifiers;
	}

	public int DoesItHaveModifiers()
	{
		int totalmodifiers = 0;
		modifiers.ForEach((int x) =>
		{
			totalmodifiers += x;
		});
		gearmodifiers.ForEach((int x) =>
		{
			totalmodifiers += x;
		});
		titlemodifiers.ForEach((int x) =>
		{
			totalmodifiers += x;
		});
		racemodifiers.ForEach((int x) =>
		{
			totalmodifiers += x;
		});
		perkmodifiers.ForEach((int x) =>
		{
			totalmodifiers += x;
		});
		buffmodifiers.ForEach((int x) =>
		{
			totalmodifiers += x;
		});
		if (totalmodifiers > 0)
		{
			return 1;
		}
		if (totalmodifiers < 0)
		{
			return -1;
		}
		return 0;
	}

	public void ClearGearModifiers()
	{
		gearmodifiers.Clear();
	}

	public void ClearPerkModifiers()
	{
		perkmodifiers.Clear();
	}

	public void ClearBuffModifiers()
	{
		buffmodifiers.Clear();
	}

	public void InitializeStat(int min, int max)
	{
		baseValue = Random.Range(min, max + 1);
	}

	public void SetStat(int Amount)
	{
		baseValue = Amount;
	}

	public void IncreaseBaseValue(int Amount)
	{
		if (Amount > 0)
		{
			baseValue += Amount;
		}
	}

	public void DecreaseBaseValue(int Amount)
	{
		if (baseValue > 1)
		{
			baseValue -= Amount;
		}
	}
}
public class TextLinkHandler : MonoBehaviour, IPointerClickHandler, IEventSystemHandler
{
	public TextMeshProUGUI text;

	public Canvas canvas;

	public Camera camera;

	public Vector3 TooltipPosition;

	public void OnPointerClick(PointerEventData eventData)
	{
		//IL_0006: Unknown result type (might be due to invalid IL or missing references)
		//IL_002c: Unknown result type (might be due to invalid IL or missing references)
		//IL_0031: Unknown result type (might be due to invalid IL or missing references)
		//IL_0078: Unknown result type (might be due to invalid IL or missing references)
		int num = TMP_TextUtilities.FindIntersectingLink((TMP_Text)(object)text, Input.mousePosition, camera);
		if (num == -1)
		{
			return;
		}
		TMP_LinkInfo val = ((TMP_Text)text).textInfo.linkInfo[num];
		string linkID = val.GetLinkID();
		if (linkID == "Char")
		{
			if (UIManager.instance.CharTooltip.activeSelf)
			{
				UIManager.instance.CloseAllTooltips();
			}
			else
			{
				UIManager.instance.ShowCharacterTooltip(new Vector3(150f, 150f, 0f), EventController.instance.AffectedCharacter, disablepivot: true);
			}
		}
	}
}
