	public string AddAdditionalChallengeInfo(int challengenumber)
	{
		string result = "";
		if (!MainMenuScript.instance.EndlessModeToggle.isOn && !MainMenuScript.instance.CareerModeToggle.isOn)
		{
			result = "<color=#8CFF75>\n" + LocalizationManager.GetTranslation("TOOLTIP/TOOLTIP_challengescore") + "</color>";
		}
		else if (MainMenuScript.instance.EndlessModeToggle.isOn)
		{
			if (challengenumber == 8 || challengenumber == 4)
			{
				result = "<color=#FF7A76>\n" + LocalizationManager.GetTranslation("TOOLTIP/TOOLTIP_challenge_noeffect") + "</color>";
			}
		}
		else if (MainMenuScript.instance.CareerModeToggle.isOn && challengenumber == 4)
		{
			result = "<color=#FF7A76>\n" + LocalizationManager.GetTranslation("TOOLTIP/TOOLTIP_challenge_noeffect") + "</color>";
		}
		if (MainMenuScript.instance.Challenge9Toggle.isOn && challengenumber == 6)
		{
			result = "<color=#FF7A76>\n" + LocalizationManager.GetTranslation("TOOLTIP/TOOLTIP_challengenoeffect2") + "</color>";
		}
		return result;
	}

	public string GetDemandDescription(string demand)
