	public void OnPointerEnter(PointerEventData eventData)
	{
		//IL_0019: Unknown result type (might be due to invalid IL or missing references)
		if ((Object)(object)perk != (Object)null)
		{
			UIManager.instance.ShowPerkTooltip(((Component)this).transform.position, perk);
		}
	}

	public void OnPointerExit(PointerEventData eventData)
	{
		if ((Object)(object)perk != (Object)null)
		{
			UIManager.instance.HideTooltip();
		}
	}
}
public class TooltipSkillLine : MonoBehaviour, IPointerEnterHandler, IEventSystemHandler, IPointerExitHandler
{
	public Skill skill;

	public void OnPointerEnter(PointerEventData eventData)
	{
		//IL_0285: Unknown result type (might be due to invalid IL or missing references)
		if ((Object)(object)skill != (Object)null)
		{
			string text = "";
			string text2 = "";
			if (skill.DamageType == DamageType.magic || skill.DamageType == DamageType.MagicHalfPiercing || skill.DamageType == DamageType.MagicPiercing)
			{
				text = "<color=#628FFF>" + LocalizationManager.GetTranslation("UI.GENERAL/UI.GENERAL_dmg_magic");
				text2 = "magic";
			}
			else if (skill.DamageType == DamageType.NoDamage)
			{
				text = LocalizationManager.GetTranslation("UI.GENERAL/UI.GENERAL_dmg_none");
				text2 = "none";
			}
			else if (skill.DamageType == DamageType.piercing && skill.ClassType == classType.Mage)
			{
				text = "<color=#628FFF>" + LocalizationManager.GetTranslation("UI.GENERAL/UI.GENERAL_dmg_magic");
				text2 = "magic";
			}
			else if (skill.DamageType == DamageType.piercing && skill.ClassType == classType.Warrior)
			{
				text = "<color=#FF6A62>" + LocalizationManager.GetTranslation("UI.GENERAL/UI.GENERAL_dmg_physical");
				text2 = "physical";
			}
			else if (skill.ClassType == classType.Archer)
			{
				text = "<color=#7DFF78>" + LocalizationManager.GetTranslation("UI.GENERAL/UI.GENERAL_dmg_archery");
				text2 = "physical";
			}
			else
			{
				text = "<color=#FF6A62>" + LocalizationManager.GetTranslation("UI.GENERAL/UI.GENERAL_dmg_physical");
				text2 = "physical";
			}
			if (skill.SkillType == SkillType.RangedPotion && skill.ExtraDamage != 0)
			{
				text = skill.ExtraDamage.ToString();
				text2 = "static";
			}
			else if (skill.SkillType == SkillType.Obliteration || skill.SkillType == SkillType.MagicPercentual || skill.Id == 14)
			{
				text = LocalizationManager.GetTranslation("UI.GENERAL/UI.GENERAL_dmg_static");
				text2 = "static";
			}
			else if (text2 != "none" && skill.ExtraDamage >= 0)
			{
				text = text + " + " + skill.ExtraDamage;
			}
			else if (text2 != "none" && skill.ExtraDamage < 0)
			{
				string text3 = skill.ExtraDamage.ToString().Replace("-", " - ");
				text += text3;
			}
			text += "</color>";
			string buffText = skill.GetBuffText();
			UIManager.instance.ShowSkillTooltip(((Component)this).transform.position, skill.name, skill.Description, text, skill.Range, skill.MaxCooldown, skill.ManaCost, buffText, text2);
		}
	}

	public void OnPointerExit(PointerEventData eventData)
	{
		if ((Object)(object)skill != (Object)null)
		{
			UIManager.instance.HideTooltip();
		}
	}
}
