	private void Awake()
	{
		if ((Object)(object)instance != (Object)null)
		{
			Debug.LogWarning((object)"More than one instance of TownManager found!");
			Object.Destroy((Object)(object)((Component)this).gameObject);
		}
		else
		{
			instance = this;
		}
	}

	private void Start()
	{
		NewRewards.Clear();
		AudioManager.instance.StopAudienceSounds();
		if (SaveManager.instance.LoadActive)
		{
			SaveManager.instance.LoadComponent("TownManager");
			ProgressManager.instance.ReCheckLuckBonus();
			if (GlobalVariables.instance.CareerModeActivated)
			{
				RedrawCareerTeams();
				VisualizeCareerRank();
				VisualizeCareerNextFights();
				((TMP_Text)PrestigeLevel).SetText(LocalizationManager.GetTranslation("UI.NEWGAME/UI.NEWGAME_setting_careerprestigelevel") + ": " + GlobalVariables.instance.CareerPrestigeLevel);
				((Component)PrestigeLevel).gameObject.SetActive(true);
			}
			if (GlobalVariables.instance.GloryLevel > 0)
			{
				((TMP_Text)GloryLevel).SetText(LocalizationManager.GetTranslation("UI.NEWGAME/UI.NEWGAME_setting_glorytitle") + ": " + GlobalVariables.instance.GloryLevel);
				((Component)GloryLevel).gameObject.SetActive(true);
			}
			if (GlobalVariables.instance.CountChallenges() > 0)
			{
				((TMP_Text)Challenges).SetText(LocalizationManager.GetTranslation("UI.NEWGAME/UI.NEWGAME_setting_challenges") + ": " + GlobalVariables.instance.CountChallenges());
				((Component)Challenges).gameObject.SetActive(true);
			}
			if (GlobalVariables.instance.ChosenGameDifficulty == 2)
			{
				((TMP_Text)Difficulty).SetText(LocalizationManager.GetTranslation("UI.NEWGAME/UI.NEWGAME_normal"));
			}
			else
			{
				((TMP_Text)Difficulty).SetText(LocalizationManager.GetTranslation("UI.NEWGAME/UI.NEWGAME_relaxed"));
			}
			if (ProgressManager.instance.CurrentEvent != null)
			{
				EventController.instance.StartEvent();
			}
			else
			{
				AudioManager.instance.PlayMusic("Town");
			}
		}
		else
		{
			ProgressManager.instance.ReCheckLuckBonus();
			ProgressManager.instance.CheckProgressionStatus();
			InitiateShop();
			InitiateRecruits();
			if (GlobalVariables.instance.GloryLevel > 0)
			{
				((TMP_Text)GloryLevel).SetText(LocalizationManager.GetTranslation("UI.NEWGAME/UI.NEWGAME_setting_glorytitle") + ": " + GlobalVariables.instance.GloryLevel);
				((Component)GloryLevel).gameObject.SetActive(true);
			}
			if (GlobalVariables.instance.CountChallenges() > 0)
			{
				((TMP_Text)Challenges).SetText(LocalizationManager.GetTranslation("UI.NEWGAME/UI.NEWGAME_setting_challenges") + ": " + GlobalVariables.instance.CountChallenges());
				((Component)Challenges).gameObject.SetActive(true);
			}
			if (GlobalVariables.instance.ChosenGameDifficulty == 2)
			{
				((TMP_Text)Difficulty).SetText(LocalizationManager.GetTranslation("UI.NEWGAME/UI.NEWGAME_normal"));
			}
			else
			{
				((TMP_Text)Difficulty).SetText(LocalizationManager.GetTranslation("UI.NEWGAME/UI.NEWGAME_relaxed"));
			}
			if (ProgressManager.instance.GameHasEnded)
			{
				RedrawTeamBars();
				ReconnectBars();
				EquipmentManager.instance.RedrawGear();
				UpdateGold();
				return;
			}
			if (GlobalVariables.instance.CareerModeActivated)
			{
				CreateCareerEnemyTeams();
				VisualizeCareerRank();
				VisualizeCareerNextFights();
				if (ProgressManager.instance.LendingStatus == 1)
				{
					ProgressManager.instance.LendingStatus = 2;
				}
				else if (ProgressManager.instance.LendingStatus == 2)
				{
					ProgressManager.instance.LendingStatus = 0;
				}
				((TMP_Text)PrestigeLevel).SetText(LocalizationManager.GetTranslation("UI.NEWGAME/UI.NEWGAME_setting_careerprestigelevel") + ": " + GlobalVariables.instance.CareerPrestigeLevel);
				((Component)PrestigeLevel).gameObject.SetActive(true);
			}
			else
			{
				ProgressManager.instance.CreateEmperorDemands();
				ProgressManager.instance.CreateEnemyTeam(ChangingVariables.instance.EnemyTeamRarity, ChangingVariables.instance.EnemyTeamRarityPoints, ChangingVariables.instance.EnemyItemRarityPoints);
			}
			foreach (CharacterTemplate item in ProgressManager.instance.Team)
			{
				if ((Object)(object)item != (Object)null && item.CheckTitleValidity())
				{
					string translation = LocalizationManager.GetTranslation("Z.ADDITIONAL/Z.ADDITIONAL_earnedtitle");
					translation = translation.Replace("<CHAR>", item.Charname);
					translation = translation.Replace("<TITLE>", "\n<color=#F69696>" + LocalizationManager.GetTranslation("TITLE/TITLE_" + item.Title) + "</color><color=#64E632>\n+3 ");
					NewRewards.Add(translation + item.GetTranslatedTitleStatGain() + "\n" + LocalizationManager.GetTranslation("UI.GENERAL/UI.GENERAL_perk") + ": " + item.GetTranslatedPerkName() + "</color>", item.Sprite);
				}
			}
			if (ProgressManager.instance.ProgressionList.Count > 0)
			{
				if (GlobalVariables.instance.CareerModeActivated)
				{
					if (ShouldCareerEventBeShown())
					{
						EventController.instance.PrepareEvent();
					}
					else
					{
						((MonoBehaviour)this).StartCoroutine(OptionsMenu.instance.FadeFromBlack(0f, 0.8f, "EnterTown"));
					}
				}
				else
				{
					EventController.instance.PrepareEvent();
				}
				SaveManager.instance.Save();
			}
			else if (GlobalVariables.instance.ChallengeBeastMode)
			{
				AddBeastToFirstSlot();
			}
			if (NewRewards.Count > 0)
			{
				((MonoBehaviour)this).StartCoroutine(ShowReward(NewRewards, 2.5f));
			}
			if (!InfotextActive && !RewardActive && !ShowInfotext && ProgressManager.instance.ProgressionList.Count > 0 && !ProgressManager.instance.GameHasEnded)
			{
				if (GlobalVariables.instance.CareerModeActivated)
				{
					if (ShouldCareerEventBeShown())
					{
						EventController.instance.StartEvent();
					}
				}
				else
				{
					EventController.instance.StartEvent();
				}
			}
			if (ProgressManager.instance.ProgressionList.Count == 0)
			{
				StoredInfoText = LocalizationManager.GetTranslation("UI.TOWN/UI.TOWN_managermsg1");
				((MonoBehaviour)this).StartCoroutine(ShowInfo());
				FirstTimeRecruitText.SetActive(true);
			}
		}
		((TMP_Text)EnemyTeamName).SetText(ProgressManager.instance.EnemyTeamName);
		RedrawTeamBars();
		ReconnectBars();
		RosterManager.instance.RedrawRoster();
		InventoryManager.instance.RedrawInventory();
		EquipmentManager.instance.RedrawGear();
		EquipmentManager.instance.RecheckGear();
		UpdateGold();
		foreach (CharacterTemplate item2 in ProgressManager.instance.Team)
		{
			if ((Object)(object)item2 != (Object)null)
			{
				item2.CurrentHP = Mathf.RoundToInt((10f - (float)item2.InjuryCount) / 10f * (float)item2.HP.GetValue());
				item2.CurrentMP = Mathf.Clamp(item2.MP.GetValue(), 0, int.MaxValue);
			}
		}
		if (GlobalVariables.instance.EndlessModeActivated)
		{
			((Component)ProgressionWindow).gameObject.SetActive(false);
			((Component)EndlessWindow).gameObject.SetActive(true);
			((TMP_Text)EndlessCounter).SetText(ProgressManager.instance.TotalWins.ToString());
		}
		else if (GlobalVariables.instance.CareerModeActivated)
		{
			WagesBar.SetActive(true);
		}
		else
		{
			UpdateProgressionChart();
		}
		if (ProgressManager.instance.FirstTimeInjury || ProfileManager.instance.TotalGameWins != 0)
		{
			return;
		}
		foreach (CharacterTemplate item3 in ProgressManager.instance.Team)
		{
			if ((Object)(object)item3 != (Object)null && item3.InjuryCount > 0)
			{
				FirstTimeInjuryText.SetActive(true);
				ProgressManager.instance.FirstTimeInjury = true;
				break;
			}
		}
	}

