	public void UpdateProgressionChart()
	{
		//IL_022a: Unknown result type (might be due to invalid IL or missing references)
		//IL_022f: Unknown result type (might be due to invalid IL or missing references)
		//IL_01d3: Unknown result type (might be due to invalid IL or missing references)
		//IL_01d8: Unknown result type (might be due to invalid IL or missing references)
		//IL_02f6: Unknown result type (might be due to invalid IL or missing references)
		//IL_02fb: Unknown result type (might be due to invalid IL or missing references)
		if (ProgressManager.instance.ProgressionLevel > 4)
		{
			ProgressionL1Canvas.alpha = 1f;
		}
		if (ProgressManager.instance.ProgressionLevel > 3)
		{
			ProgressionL2Canvas.alpha = 1f;
		}
		if (ProgressManager.instance.ProgressionLevel > 2)
		{
			ProgressionL3Canvas.alpha = 1f;
		}
		if (ProgressManager.instance.ProgressionLevel > 1)
		{
			ProgressionL4Canvas.alpha = 1f;
		}
		if (ProgressManager.instance.ProgressionLevel > 0)
		{
			ProgressionL5Canvas.alpha = 1f;
		}
		ProgressionLevelPanels.Clear();
		ProgressionLevelPanels.Add(ProgressionLevel1FightPanel);
		ProgressionLevelPanels.Add(ProgressionLevel2FightPanel);
		ProgressionLevelPanels.Add(ProgressionLevel3FightPanel);
		ProgressionLevelPanels.Add(ProgressionLevel4FightPanel);
		ProgressionLevelPanels.Add(ProgressionLevel5FightPanel);
		if (ProgressManager.instance.ProgressionLevelFightsRequired > 3)
		{
			int num = ProgressManager.instance.ProgressionLevelFightsRequired - 3;
			foreach (Transform progressionLevelPanel in ProgressionLevelPanels)
			{
				for (int i = 0; i < num; i++)
				{
					Object.Instantiate<GameObject>(ProgressionEmptySlot).transform.SetParent(progressionLevelPanel, false);
				}
			}
		}
		int num2 = 0;
		int num3 = 0;
		foreach (bool progression in ProgressManager.instance.ProgressionList)
		{
			if (progression)
			{
				((Component)ProgressionLevelPanels[num2].GetChild(num3)).GetComponent<Image>().sprite = ProgressionVictory;
				((Graphic)((Component)ProgressionLevelPanels[num2].GetChild(num3)).GetComponent<Image>()).color = Color32.op_Implicit(new Color32(byte.MaxValue, (byte)225, byte.MaxValue, byte.MaxValue));
			}
			else
			{
				((Component)ProgressionLevelPanels[num2].GetChild(num3)).GetComponent<Image>().sprite = ProgressionLoss;
				((Graphic)((Component)ProgressionLevelPanels[num2].GetChild(num3)).GetComponent<Image>()).color = Color32.op_Implicit(new Color32((byte)225, (byte)25, (byte)0, byte.MaxValue));
			}
			num3++;
			if (num3 % ProgressManager.instance.ProgressionLevelFightsRequired == 0)
			{
				num2++;
				num3 = 0;
			}
		}
		if (ProgressManager.instance.ProgressionLevelFightsRequired * ProgressManager.instance.ProgressionLevelMax > ProgressManager.instance.ProgressionList.Count)
		{
			((Component)ProgressionLevelPanels[num2].GetChild(num3)).GetComponent<Image>().sprite = ProgressionNextFight;
		}
		else if (ProgressManager.instance.ProgressionLevelFightsRequired * ProgressManager.instance.ProgressionLevelMax <= ProgressManager.instance.ProgressionList.Count)
		{
			((Graphic)ProgressionTrophy).color = Color32.op_Implicit(new Color32(byte.MaxValue, byte.MaxValue, byte.MaxValue, byte.MaxValue));
			((Component)ProgressionTroplyGlow).gameObject.SetActive(true);
		}
	}

