			}
			else
			{
				item = Object.Instantiate<Item>(DataTables.instance.GetRandomItemNonEquip());
				item.Initialize(1);
			}
			ShopList.Add(item);
			GameObject val = Object.Instantiate<GameObject>(ShopSlot);
			val.transform.SetParent(ShopPanel, false);
