	public void ShowEnemyTeam()
	{
		if (LobbyEnemyTeamPanel.childCount != 0)
		{
			return;
		}
		foreach (CharacterTemplate item in ProgressManager.instance.EnemyTeam)
		{
			GameObject val = Object.Instantiate<GameObject>(LobbyEnemyTeamSlot);
			val.transform.SetParent(LobbyEnemyTeamPanel, false);
			val.GetComponent<EnemyTeamSlot>().Character = item;
			((Component)val.transform.Find("Character")).GetComponent<Image>().sprite = item.Portrait;
			switch (item.characterRarity)
			{
			case Rarity.Common:
				((Component)val.transform.Find("Borders")).GetComponent<Image>().sprite = UIManager.instance.BorderCommon;
				break;
			case Rarity.Uncommon:
				((Component)val.transform.Find("Borders")).GetComponent<Image>().sprite = UIManager.instance.BorderUncommon;
				break;
			case Rarity.Rare:
				((Component)val.transform.Find("Borders")).GetComponent<Image>().sprite = UIManager.instance.BorderRare;
				break;
			case Rarity.Epic:
				((Component)val.transform.Find("Borders")).GetComponent<Image>().sprite = UIManager.instance.BorderEpic;
				break;
			case Rarity.Legendary:
				((Component)val.transform.Find("Borders")).GetComponent<Image>().sprite = UIManager.instance.BorderLegendary;
				break;
			}
			if (item.InjuryCount > 0)
			{
				((Component)val.transform.Find("InjuryImage")).gameObject.SetActive(true);
				((TMP_Text)((Component)val.transform.Find("InjuryImage/InjuryCounter")).GetComponent<TextMeshProUGUI>()).text = item.InjuryCount.ToString();
			}
			else
			{
				((Component)val.transform.Find("InjuryImage")).gameObject.SetActive(false);
			}
		}
	}

	public IEnumerator FadeOutEventBackground()
	{
		while (EventPanelCanvas.alpha > 0f)
		{
			CanvasGroup eventPanelCanvas = EventPanelCanvas;
			eventPanelCanvas.alpha -= Time.deltaTime * 2f;
			yield return null;
		}
		((Component)EventPanel).gameObject.SetActive(false);
	}

	public IEnumerator ShowReward(Dictionary<string, Sprite> Rewards, float duration = 3f)
	{
		if (RewardActive)
		{
			yield break;
		}
		if (!ProgressManager.instance.GameHasEnded)
		{
			((Component)EventPanel).gameObject.SetActive(true);
		}
		RewardActive = true;
		foreach (KeyValuePair<string, Sprite> Reward in Rewards)
		{
			if (GlobalVariables.instance.CareerModeActivated)
			{
				if (Reward.Key == "Demotion")
				{
					((TMP_Text)RewardPopUpText).SetText(LocalizationManager.GetTranslation("UI.TOWN/UI.TOWN_careerdemotion"));
					AudioManager.instance.AudioEffect("CareerNotificationDemotion");
				}
				else if (Reward.Key == "StayAtRank")
				{
					((TMP_Text)RewardPopUpText).SetText(LocalizationManager.GetTranslation("UI.TOWN/UI.TOWN_careersamerank"));
					AudioManager.instance.AudioEffect("CareerNotificationStayAtRank");
				}
				else
				{
					((TMP_Text)RewardPopUpText).SetText(Reward.Key);
					AudioManager.instance.AudioEffect("Congratulations");
				}
			}
			else
			{
				((TMP_Text)RewardPopUpText).SetText(Reward.Key);
				AudioManager.instance.AudioEffect("Congratulations");
			}
			RewardPopUpImage.sprite = Reward.Value;
			while (RewardPopUpCanvas.alpha < 1f)
			{
				CanvasGroup rewardPopUpCanvas = RewardPopUpCanvas;
				rewardPopUpCanvas.alpha += Time.deltaTime * 2f;
				yield return null;
			}
			yield return (object)new WaitForSeconds(duration);
			while (RewardPopUpCanvas.alpha > 0f)
			{
				CanvasGroup rewardPopUpCanvas2 = RewardPopUpCanvas;
				rewardPopUpCanvas2.alpha -= Time.deltaTime * 2f;
				yield return null;
			}
			yield return (object)new WaitForSeconds(0.2f);
		}
		RewardActive = false;
		if (ProgressManager.instance.GameHasEnded)
		{
			yield break;
		}
		if (ShowInfotext)
		{
			((MonoBehaviour)this).StartCoroutine(ShowInfo());
		}
		else if (!EventStarted)
		{
			if (GlobalVariables.instance.CareerModeActivated)
			{
				if (ShouldCareerEventBeShown())
				{
					EventController.instance.StartEvent();
				}
				else
				{
					((MonoBehaviour)this).StartCoroutine(FadeOutEventBackground());
				}
			}
			else
			{
				EventController.instance.StartEvent();
			}
		}
		else
		{
			((Component)EventPanel).gameObject.SetActive(false);
		}
	}

	public IEnumerator ShowInfo(int soundeffect = 0)
	{
		ShowInfotext = true;
		yield return (object)new WaitForSeconds(0.2f);
		if (!InfotextActive && !RewardActive)
		{
			InfotextActive = true;
			((TMP_Text)InfoScreenText).SetText(StoredInfoText);
			InfoScreenBackground.SetActive(true);
			yield return (object)new WaitForSeconds(0.3f);
			switch (soundeffect)
			{
			case 0:
				AudioManager.instance.AudioEffect("InfoScreen");
				break;
			case 1:
				AudioManager.instance.AudioEffect("GoblinAccountant");
				break;
			}
			while (InfoScreenCanvas.alpha < 1f)
			{
				CanvasGroup infoScreenCanvas = InfoScreenCanvas;
				infoScreenCanvas.alpha += Time.deltaTime * 2.5f;
				yield return null;
			}
			InfotextActive = false;
		}
	}

	public IEnumerator VictoryAnimation()
	{
		if (!VictoryAnimationActive)
		{
			VictoryAnimationActive = true;
			AudioManager.instance.AudioEffect("GameVictory");
			VictoryAnimationTrophy.SetActive(true);
			VictoryAnimationGlow.SetActive(true);
			yield return (object)new WaitForSeconds(6f);
			ShowGameEnd(Victory: true);
			VictoryAnimationTrophy.SetActive(false);
			VictoryAnimationGlow.SetActive(false);
		}
	}

	public void CloseInfo()
	{
		InfoScreenCanvas.alpha = 0f;
		AudioManager.instance.AudioEffect("DialogueOK");
		InfoScreenBackground.SetActive(false);
		if (EventStarted || ProgressManager.instance.ProgressionList.Count <= 0)
		{
			return;
		}
		if (GlobalVariables.instance.CareerModeActivated)
		{
			if (!CareerLobbyWindow.activeSelf && ShouldCareerEventBeShown())
			{
				EventController.instance.StartEvent();
			}
			else
			{
				((MonoBehaviour)this).StartCoroutine(FadeOutEventBackground());
			}
		}
		else
		{
			EventController.instance.StartEvent();
		}
	}

	private void RewardCheck()
	{
		if (ProgressManager.instance.difficultyLevel == 1)
		{
			RewardText += "Rewards: ";
		}
		else
		{
			RewardText += "Re";
		}
		if (GlobalVariables.instance.InventoryMaxSize > 100)
		{
			RewardText += "Unlocked: ";
		}
		if (RosterManager.instance.Roster.Count == 3)
		{
			RewardText += "dbe";
		}
		if (GlobalVariables.instance.EndlessModeActivated)
		{
			RewardText += "ak";
		}
		if (ProgressManager.instance.GetGold() > 5)
		{
			RewardText += "Gold";
		}
		if (RewardText.Length == 7)
		{
			UIManager.instance.ShowErrorMessage(RewardText, 0.5f);
		}
	}

