	public void ShowGameEnd(bool Victory)
	{
		//IL_00e3: Unknown result type (might be due to invalid IL or missing references)
		//IL_00ed: Expected Obj, but got Unknown
		//IL_02b4: Unknown result type (might be due to invalid IL or missing references)
		//IL_02be: Expected Obj, but got Unknown
		//IL_01e9: Unknown result type (might be due to invalid IL or missing references)
		//IL_01f3: Expected Obj, but got Unknown
		//IL_01cb: Unknown result type (might be due to invalid IL or missing references)
		//IL_01d5: Expected Obj, but got Unknown
		EndScreenPanel.SetActive(true);
		if (GlobalVariables.instance.EndlessModeActivated)
		{
			AudioManager.instance.AudioEffect("GameLoss");
			((TMP_Text)EndScreenTitle).SetText("<color=#FF4040>" + LocalizationManager.GetTranslation("UI.ENDSCREEN/UI.ENDSCREEN_defeat") + "</color>");
			((TMP_Text)EndScreenDescription1).SetText(LocalizationManager.GetTranslation("UI.ENDSCREEN/UI.ENDSCREEN_defeatdescendless").Replace("<ENDLESSWINS>", "<color=#66FF4A><size=36>" + ProgressManager.instance.TotalWins + "</size></color>"));
			((Component)EndScreenTeamName).gameObject.SetActive(false);
			((Component)EndScreenDescription2).gameObject.SetActive(false);
			EndScreenLaurel.SetActive(false);
			EndScreenThorns.SetActive(true);
			((UnityEvent)EndScreenMainMenuButton.onClick).AddListener((UnityAction)(() =>
			{
				BackToMainMenu();
			}));
			((TMP_Text)EndScreenDetails).SetText(EndScreenGameDetails(victory: false));
		}
		else if (Victory)
		{
			UnlockRewards();
			AudioManager.instance.AudioEffect("Treasure");
			((TMP_Text)EndScreenTitle).SetText("<color=#FFF475>" + LocalizationManager.GetTranslation("UI.ENDSCREEN/UI.ENDSCREEN_victory") + "</color>");
			((TMP_Text)EndScreenDescription1).SetText(LocalizationManager.GetTranslation("UI.ENDSCREEN/UI.ENDSCREEN_victorydesc1"));
			((TMP_Text)EndScreenTeamName).SetText(ProgressManager.instance.HeroTeamName);
			((TMP_Text)EndScreenDescription2).SetText(LocalizationManager.GetTranslation("UI.ENDSCREEN/UI.ENDSCREEN_victorydesc2"));
			EndScreenLaurel.SetActive(true);
			EndScreenThorns.SetActive(false);
			if (ProfileManager.instance.TotalGameWins == 1)
			{
				((UnityEvent)EndScreenMainMenuButton.onClick).AddListener((UnityAction)(() =>
				{
					OpenFirstTimeCongratulationText();
				}));
			}
			else
			{
				((UnityEvent)EndScreenMainMenuButton.onClick).AddListener((UnityAction)(() =>
				{
					BackToMainMenu();
				}));
			}
			((TMP_Text)EndScreenDetails).SetText(EndScreenGameDetails(victory: true));
		}
		else
		{
			AudioManager.instance.AudioEffect("GameLoss");
			((TMP_Text)EndScreenTitle).SetText("<color=#FF4040>" + LocalizationManager.GetTranslation("UI.ENDSCREEN/UI.ENDSCREEN_defeat") + "</color>");
			((TMP_Text)EndScreenDescription1).SetText("\n" + LocalizationManager.GetTranslation("UI.ENDSCREEN/UI.ENDSCREEN_defeatdesc1"));
			((Component)EndScreenTeamName).gameObject.SetActive(false);
			((Component)EndScreenDescription2).gameObject.SetActive(false);
			EndScreenLaurel.SetActive(false);
			EndScreenThorns.SetActive(true);
			((UnityEvent)EndScreenMainMenuButton.onClick).AddListener((UnityAction)(() =>
			{
				BackToMainMenu();
			}));
			((TMP_Text)EndScreenDetails).SetText(EndScreenGameDetails(victory: false));
		}
		AudioManager.instance.PlayMusic("Event");
	}

