	public void UnlockRewards()
	{
		switch (ProfileManager.instance.TotalGameWins)
		{
		case 1:
			NewRewards.Add("<size=24>" + LocalizationManager.GetTranslation("UI.ENDSCREEN/UI.ENDSCREEN_unlockedpopup") + "\n" + LocalizationManager.GetTranslation("UI.NEWGAME/UI.NEWGAME_setting_challenges") + "!</size>", Unlock1);
			break;
		case 2:
			NewRewards.Add("<size=24>" + LocalizationManager.GetTranslation("UI.ENDSCREEN/UI.ENDSCREEN_unlockedpopup") + "\n" + LocalizationManager.GetTranslation("UI.NEWGAME/UI.NEWGAME_setting_glory") + "!</size>", Unlock2);
			break;
