			NewRewards.Add("<size=24>" + LocalizationManager.GetTranslation("UI.ENDSCREEN/UI.ENDSCREEN_unlockedpopup") + "\n" + LocalizationManager.GetTranslation("UI.NEWGAME/UI.NEWGAME_setting_endless") + "!</size>", Unlock3);
