	public string EndScreenGameDetails(bool victory)
	{
		string text = "";
		if (GlobalVariables.instance.CareerModeActivated)
		{
			text = text + "<size=26>" + LocalizationManager.GetTranslation("UI.NEWGAME/UI.NEWGAME_setting_careerprestigelevel") + ": <color=#66FF4A>" + GlobalVariables.instance.CareerPrestigeLevel + "</color></size>\n";
		}
		else if (victory)
		{
			text = text + "<size=26>" + LocalizationManager.GetTranslation("UI.ENDSCREEN/UI.ENDSCREEN_score") + ": <color=#66FF4A>" + ProgressManager.instance.CalculateFinalScore(Endless: false) + "</color></size>\n";
		}
		text = ((GlobalVariables.instance.ChosenGameDifficulty != 2) ? (text + LocalizationManager.GetTranslation("UI.ENDSCREEN/UI.ENDSCREEN_difficulty") + ": " + LocalizationManager.GetTranslation("UI.NEWGAME/UI.NEWGAME_relaxed")) : (text + LocalizationManager.GetTranslation("UI.ENDSCREEN/UI.ENDSCREEN_difficulty") + ": " + LocalizationManager.GetTranslation("UI.NEWGAME/UI.NEWGAME_normal")));
		if (GlobalVariables.instance.EndlessModeActivated)
		{
			text = text + "\n" + LocalizationManager.GetTranslation("UI.NEWGAME/UI.NEWGAME_setting_endless");
		}
		if (GlobalVariables.instance.GloryLevel > 0)
		{
			text = text + "\n" + LocalizationManager.GetTranslation("UI.NEWGAME/UI.NEWGAME_setting_glorytitle") + ": " + GlobalVariables.instance.GloryLevel;
		}
		if (GlobalVariables.instance.CountChallenges() > 0)
		{
			text = text + "\n" + LocalizationManager.GetTranslation("UI.NEWGAME/UI.NEWGAME_setting_challenges") + ": " + GlobalVariables.instance.CountChallenges();
		}
		if (ProfileManager.instance.TotalGameWins < 3)
		{
			text = text + "\n" + LocalizationManager.GetTranslation("UI.ENDSCREEN/UI.ENDSCREEN_unlocks") + ": " + ProfileManager.instance.TotalGameWins + " / 3";
		}
		return text;
	}

