		TotalWages = num;
		((TMP_Text)TotalWagesText).SetText(TotalWages.ToString());
	}

	public void CreateCareerEnemyTeams()
	{
		int num = 3;
		if (ProgressManager.instance.CareerNextFights[0] == 19 || ProgressManager.instance.CareerNextFights[0] == 20)
		{
			num = 1;
		}
		EquipmentManager.instance.ClearCareerEnemyGear();
		for (int i = 0; i < num; i++)
		{
			GameObject val = Object.Instantiate<GameObject>(CareerEnemyChoicePrefab);
			val.transform.SetParent(CareerEnemyChoicesParent, false);
			val.GetComponent<CareerModeEnemyTeam>().InitializeTeam(ProgressManager.instance.CareerNextFights[0]);
		}
	}

	public void CareerStartRankAnimation()
	{
		if (ProgressManager.instance.CareerAnimateStatus > 0)
		{
			switch (ProgressManager.instance.CareerAnimateStatus)
			{
			case 1:
				((MonoBehaviour)this).StartCoroutine(CareerAnimationController(1));
				break;
			case 2:
				((MonoBehaviour)this).StartCoroutine(CareerAnimationController(2));
				break;
			case 3:
				((MonoBehaviour)this).StartCoroutine(CareerAnimationController(3));
				break;
			case 10:
				((MonoBehaviour)this).StartCoroutine(CareerAnimationController(0, 1, ProgressManager.instance.CurrentCareerRank, dimstars: true));
				break;
			case 11:
				((MonoBehaviour)this).StartCoroutine(CareerAnimationController(1, 1, ProgressManager.instance.CurrentCareerRank, dimstars: true));
				break;
			case 12:
				((MonoBehaviour)this).StartCoroutine(CareerAnimationController(2, 1, ProgressManager.instance.CurrentCareerRank, dimstars: true));
				break;
			case 13:
				((MonoBehaviour)this).StartCoroutine(CareerAnimationController(3, 1, ProgressManager.instance.CurrentCareerRank, dimstars: true));
				break;
			case 20:
				((MonoBehaviour)this).StartCoroutine(CareerAnimationController(0, 2, ProgressManager.instance.CurrentCareerRank, dimstars: true));
				break;
			case 21:
				((MonoBehaviour)this).StartCoroutine(CareerAnimationController(1, 2, ProgressManager.instance.CurrentCareerRank, dimstars: true));
				break;
			case 22:
				((MonoBehaviour)this).StartCoroutine(CareerAnimationController(2, 2, ProgressManager.instance.CurrentCareerRank, dimstars: true));
				break;
			case 23:
				((MonoBehaviour)this).StartCoroutine(CareerAnimationController(3, 2, ProgressManager.instance.CurrentCareerRank, dimstars: true));
				break;
			case 30:
				((MonoBehaviour)this).StartCoroutine(CareerAnimationController(0, 3, 0, dimstars: true));
				break;
			case 31:
				((MonoBehaviour)this).StartCoroutine(CareerAnimationController(1, 3, 0, dimstars: true));
				break;
			case 32:
				((MonoBehaviour)this).StartCoroutine(CareerAnimationController(2, 3, 0, dimstars: true));
				break;
			case 33:
				((MonoBehaviour)this).StartCoroutine(CareerAnimationController(3, 3, 0, dimstars: true));
				break;
			}
		}
		ProgressManager.instance.CareerAnimateStatus = 0;
	}

