	public IEnumerator CareerAnimationController(int StarToLight = 0, int DemotePromote = 0, int newrank = 0, bool dimstars = false)
	{
		yield return (object)new WaitForSeconds(0.2f);
		if (StarToLight > 0)
		{
			switch (StarToLight)
			{
			case 1:
				((MonoBehaviour)this).StartCoroutine(TransitionSpriteColor(new Color32(byte.MaxValue, byte.MaxValue, byte.MaxValue, byte.MaxValue), ((Component)CareerLadderStarPanel.GetChild(0)).GetComponent<Image>(), null, "CareerGainStar"));
				break;
			case 2:
				((MonoBehaviour)this).StartCoroutine(TransitionSpriteColor(new Color32(byte.MaxValue, byte.MaxValue, byte.MaxValue, byte.MaxValue), ((Component)CareerLadderStarPanel.GetChild(1)).GetComponent<Image>(), null, "CareerGainStar"));
				break;
			case 3:
				((MonoBehaviour)this).StartCoroutine(TransitionSpriteColor(new Color32(byte.MaxValue, byte.MaxValue, byte.MaxValue, byte.MaxValue), ((Component)CareerLadderStarPanel.GetChild(2)).GetComponent<Image>(), null, "CareerGainStar"));
				break;
			}
			yield return (object)new WaitForSeconds(0.7f);
		}
		if (dimstars)
		{
			if (((Graphic)((Component)CareerLadderStarPanel.GetChild(0)).GetComponent<Image>()).color != Color32.op_Implicit(new Color32((byte)22, (byte)22, (byte)22, (byte)95)))
			{
				AudioManager.instance.AudioEffect("CareerDimStars");
			}
			((MonoBehaviour)this).StartCoroutine(TransitionSpriteColor(new Color32((byte)22, (byte)22, (byte)22, (byte)95), ((Component)CareerLadderStarPanel.GetChild(0)).GetComponent<Image>(), null, null, 0.4f));
			((MonoBehaviour)this).StartCoroutine(TransitionSpriteColor(new Color32((byte)22, (byte)22, (byte)22, (byte)95), ((Component)CareerLadderStarPanel.GetChild(1)).GetComponent<Image>(), null, null, 0.55f));
			((MonoBehaviour)this).StartCoroutine(TransitionSpriteColor(new Color32((byte)22, (byte)22, (byte)22, (byte)95), ((Component)CareerLadderStarPanel.GetChild(2)).GetComponent<Image>(), null, null, 0.7f));
			yield return (object)new WaitForSeconds(0.5f);
		}
		if (newrank > 0)
		{
			Sprite newSprite = null;
			string soundeffect;
			switch (DemotePromote)
			{
				case 1:
					soundeffect = "CareerDemotion";
					break;
				case 3:
					soundeffect = "CareerStayAtRank";
					break;
				default:
					soundeffect = "CareerPromotion";
					break;
			}
			switch (newrank)
			{
			case 1:
				newSprite = CareerLevel1Icon;
				break;
			case 2:
				newSprite = CareerLevel2Icon;
				break;
			case 3:
				newSprite = CareerLevel3Icon;
				break;
			case 4:
				newSprite = CareerLevel4Icon;
				break;
			case 5:
				newSprite = CareerLevel5Icon;
				break;
			}
			((MonoBehaviour)this).StartCoroutine(TransitionSpriteColor(new Color32(byte.MaxValue, byte.MaxValue, byte.MaxValue, byte.MaxValue), CareerRankIcon, newSprite, soundeffect));
			((MonoBehaviour)this).StartCoroutine(TransitionText(CareerRankNumber, ProgressManager.instance.CurrentCareerRank.ToString()));
			yield return (object)new WaitForSeconds(1.2f);
		}
		VisualizeCareerRank();
	}

	public IEnumerator TransitionText(TextMeshProUGUI text, string newtext)
	{
		Color32 OriginalColor = Color32.op_Implicit(((Graphic)text).color);
		for (float t = 0f; t < 1f; t += Time.deltaTime * 3.5f)
		{
			((Graphic)text).color = Color32.op_Implicit(Color32.Lerp(OriginalColor, new Color32(OriginalColor.r, OriginalColor.g, OriginalColor.b, (byte)0), t));
			yield return null;
		}
		Color32 TempColor = Color32.op_Implicit(((Graphic)text).color);
		((TMP_Text)text).SetText(newtext);
		yield return (object)new WaitForSeconds(0.3f);
		for (float t = 0f; t < 1f; t += Time.deltaTime * 2.5f)
		{
			((Graphic)text).color = Color32.op_Implicit(Color32.Lerp(TempColor, OriginalColor, t));
			yield return null;
		}
	}

	public IEnumerator TransitionSpriteColor(Color32 ResultColor, Image OldSprite, Sprite NewSprite = null, string soundeffect = null, float speedadjustment = 1f)
	{
		//IL_0007: Unknown result type (might be due to invalid IL or missing references)
		//IL_0008: Unknown result type (might be due to invalid IL or missing references)
		Color32 OriginalColor = Color32.op_Implicit(((Graphic)OldSprite).color);
		if ((Object)(object)NewSprite != (Object)null)
		{
			for (float t = 0f; t < 1f; t += Time.deltaTime * 3.5f)
			{
				((Graphic)OldSprite).color = Color32.op_Implicit(Color32.Lerp(OriginalColor, new Color32(OriginalColor.r, OriginalColor.g, OriginalColor.b, (byte)0), t));
				yield return null;
			}
			OldSprite.sprite = NewSprite;
			OriginalColor = Color32.op_Implicit(((Graphic)OldSprite).color);
			yield return (object)new WaitForSeconds(0.3f);
		}
		if (soundeffect != null)
		{
			AudioManager.instance.AudioEffect(soundeffect);
		}
		for (float t = 0f; t < 1f; t += Time.deltaTime * 2.5f * speedadjustment)
		{
			((Graphic)OldSprite).color = Color32.op_Implicit(Color32.Lerp(OriginalColor, ResultColor, t));
			yield return null;
		}
	}

