	public void ActivateStat(int stat)
	{
		SelectedStat = stat;
		((Selectable)STRButton).interactable = true;
		((Selectable)AGIButton).interactable = true;
		((Selectable)WISButton).interactable = true;
		((Selectable)VITButton).interactable = true;
		((Selectable)HealButton).interactable = true;
		STRCanvas.alpha = 0.3f;
		AGICanvas.alpha = 0.3f;
		WISCanvas.alpha = 0.3f;
		VITCanvas.alpha = 0.3f;
		HealCanvas.alpha = 0.3f;
		switch (stat)
		{
		case 1:
			((Selectable)STRButton).interactable = false;
			STRCanvas.alpha = 1f;
			((TMP_Text)TrainButtonText).SetText(LocalizationManager.GetTranslation("TRAINER/TRAINER_trainstr"));
			break;
		case 2:
			((Selectable)AGIButton).interactable = false;
			AGICanvas.alpha = 1f;
			((TMP_Text)TrainButtonText).SetText(LocalizationManager.GetTranslation("TRAINER/TRAINER_trainagi"));
			break;
		case 3:
			((Selectable)WISButton).interactable = false;
			WISCanvas.alpha = 1f;
			((TMP_Text)TrainButtonText).SetText(LocalizationManager.GetTranslation("TRAINER/TRAINER_trainwis"));
			break;
		case 4:
			((Selectable)VITButton).interactable = false;
			VITCanvas.alpha = 1f;
			((TMP_Text)TrainButtonText).SetText(LocalizationManager.GetTranslation("TRAINER/TRAINER_trainvit"));
			break;
		case 5:
			((Selectable)HealButton).interactable = false;
			HealCanvas.alpha = 1f;
			((TMP_Text)TrainButtonText).SetText(LocalizationManager.GetTranslation("TRAINER/TRAINER_heal"));
			break;
		}
		if (GlobalVariables.instance.CareerModeActivated)
		{
			GoldCost = Character.CalculateTrainingCost(stat, 50);
		}
		else
		{
			GoldCost = Character.CalculateTrainingCost(stat, 60);
		}
		((TMP_Text)GoldCostText).SetText(GoldCost.ToString());
		if (GoldCost > ProgressManager.instance.GetGold() || (stat == 5 && Character.InjuryCount <= 0))
		{
			((Selectable)TrainButton).interactable = false;
		}
		else
		{
			((Selectable)TrainButton).interactable = true;
		}
		((Component)TrainButton).gameObject.SetActive(true);
	}

