			((TMP_Text)Name).SetText(Character.Charname);
			((Component)TrainBar.Find("PortraitPicture")).GetComponent<DragHandlerCharacter>().AdjustBorders();
			if (Character.InjuryCount > 0)
			{
				((Component)TrainBar.Find("PortraitPicture/InjuryImage")).gameObject.SetActive(true);
				((TMP_Text)((Component)TrainBar.Find("PortraitPicture/InjuryImage/InjuryCounter")).GetComponent<TextMeshProUGUI>()).text = Character.InjuryCount.ToString();
			}
			else
			{
				((Component)TrainBar.Find("PortraitPicture/InjuryImage")).gameObject.SetActive(false);
			}
			foreach (KeyValuePair<TextMeshProUGUI, Stat> item in new Dictionary<TextMeshProUGUI, Stat>
			{
				{ STR, Character.STR },
				{ AGI, Character.AGI },
				{ WIS, Character.WIS },
				{ VIT, Character.VIT }
			})
			{
				((TMP_Text)item.Key).SetText(item.Value.GetValue().ToString());
				float num = Mathf.Clamp((float)item.Value.GetValue() / 10f, 0f, 1f);
				if (num > 0.5f)
				{
					((Graphic)item.Key).color = Color32.op_Implicit(Color32.Lerp(new Color32(byte.MaxValue, byte.MaxValue, (byte)0, byte.MaxValue), new Color32((byte)0, byte.MaxValue, (byte)0, byte.MaxValue), (num - 0.5f) * 2f));
				}
				else
				{
					((Graphic)item.Key).color = Color32.op_Implicit(Color32.Lerp(new Color32(byte.MaxValue, (byte)0, (byte)0, byte.MaxValue), new Color32(byte.MaxValue, byte.MaxValue, (byte)0, byte.MaxValue), num * 2f));
				}
			}
			((TMP_Text)Heal).SetText(Character.InjuryCount.ToString());
			if (SelectedStat != 0)
			{
				ActivateStat(SelectedStat);
			}
		}
		else
		{
			((Selectable)STRButton).interactable = false;
			((Selectable)AGIButton).interactable = false;
			((Selectable)WISButton).interactable = false;
			((Selectable)VITButton).interactable = false;
			((Selectable)HealButton).interactable = false;
			STRCanvas.alpha = 0.2f;
			AGICanvas.alpha = 0.2f;
			WISCanvas.alpha = 0.2f;
			VITCanvas.alpha = 0.2f;
			HealCanvas.alpha = 0.2f;
			SelectedStat = 0;
			((TMP_Text)Name).SetText("");
			((Component)TrainBar.Find("PortraitPicture")).GetComponent<DragHandlerCharacter>().Character = null;
			((Component)TrainBar.Find("PortraitPicture")).gameObject.SetActive(false);
			((TMP_Text)STR).SetText("");
			((TMP_Text)AGI).SetText("");
			((TMP_Text)WIS).SetText("");
			((TMP_Text)VIT).SetText("");
			((TMP_Text)Heal).SetText("");
			((Component)TrainButton).gameObject.SetActive(false);
		}
	}

	public void RemoveCharacterFromSeat()
	{
		if (ProgressManager.instance.IsThereRoomInTeam())
		{
			ProgressManager.instance.AddToTeam(Character);
		}
		else if (RosterManager.instance.IsThereRoom())
		{
			RosterManager.instance.AddToRoster(Character);
		}
		Character = null;
		UpdateVisuals();
	}

	public void CharacterRemovedByDragging()
	{
		Character = null;
		UpdateVisuals();
	}

	public void TrainCharacter()
	{
		if (!Cooldown && SelectedStat != 0)
		{
			if (SelectedStat < 5)
			{
				Character.GainRandomStat(1, SelectedStat - 1);
			}
			else if (SelectedStat == 5)
			{
				Character.HealInjury(1);
			}
			ProgressManager.instance.ChangeGold(-GoldCost);
			AudioManager.instance.AudioEffect("Coin");
			UpdateVisuals();
			ActivateStat(SelectedStat);
			((MonoBehaviour)this).StartCoroutine(ButtonCooldown(0.2f));
		}
	}

	public IEnumerator ButtonCooldown(float duration)
	{
		if (!Cooldown)
		{
			Cooldown = true;
			yield return (object)new WaitForSeconds(duration);
			Cooldown = false;
		}
	}
}
