	public void UpdateSkillsOnTooltip()
	{
		//IL_0014: Unknown result type (might be due to invalid IL or missing references)
		//IL_009f: Unknown result type (might be due to invalid IL or missing references)
		//IL_00a4: Unknown result type (might be due to invalid IL or missing references)
		foreach (Transform item in SkillPanel)
		{
			Object.Destroy((Object)(object)((Component)item).gameObject);
		}
		ActiveCharacter.CreateListOfCharacterSkills();
		foreach (Skill characterSkill in ActiveCharacter.CharacterSkills)
		{
			if (!((Object)(object)characterSkill != (Object)null))
			{
				continue;
			}
			GameObject val = Object.Instantiate<GameObject>(SkillSlotPrefab);
			val.transform.SetParent(SkillPanel, false);
			SkillButton componentInChildren = val.GetComponentInChildren<SkillButton>();
			componentInChildren.skill = characterSkill;
			Scene activeScene = SceneManager.GetActiveScene();
			if (activeScene.name == "GladGBattle" && !BattleProcessor.instance.GameIsOver)
			{
				int num = 0;
				if (ActiveCharacter.BattleUnit.Cooldowns.TryGetValue(characterSkill, out var value))
				{
					num = value;
				}
				if (num > 0)
				{
					((TMP_Text)componentInChildren.CooldownTimer).SetText(value.ToString());
					((Component)componentInChildren.CooldownTimer).gameObject.SetActive(true);
				}
				else
				{
					((Component)componentInChildren.CooldownTimer).gameObject.SetActive(false);
				}
			}
		}
		((TMP_Text)SkillsText).SetText(LocalizationManager.GetTranslation("TOOLTIP/TOOLTIP_character_skills") + " " + ActiveCharacter.HowManySkills() + " / 4");
	}

	public void HideTooltip()
	{
		TooltipBuff.SetActive(false);
		if (MouseOverThirdTooltippable)
		{
			MouseOverThirdTooltippable = false;
			TooltipSkill.SetActive(false);
			TooltipPerk.SetActive(false);
		}
		else if (MouseOverSecondTooltippable)
		{
			MouseOverSecondTooltippable = false;
			MouseOverSecondTooltip = false;
			if (TooltipSkill.activeSelf || TooltipPerk.activeSelf)
			{
				TooltipSkill.SetActive(false);
				TooltipPerk.SetActive(false);
			}
		}
		else if (MouseOverSecondTooltip)
		{
			MouseOverSecondTooltip = false;
			Tooltip.SetActive(false);
		}
		else if (MouseOverTooltip && !CharTooltip.activeSelf)
		{
			MouseOverTooltip = false;
		}
		else if (MouseOverTooltip && CharTooltip.activeSelf && !Tooltip.activeSelf)
		{
			MouseOverTooltip = false;
		}
		else
		{
			MouseOverTooltippable = false;
		}
		((MonoBehaviour)this).StartCoroutine(ClosingTimer());
	}

	public IEnumerator ClosingTimer()
	{
		if (!FadeStarted)
		{
			FadeStarted = true;
			yield return (object)new WaitForSeconds(0.2f);
			FadeStarted = false;
			if (!MouseOverTooltip && !MouseOverTooltippable && !MouseOverSecondTooltip && !MouseOverSecondTooltippable && !MouseOverThirdTooltippable)
			{
				CloseAllTooltips();
			}
			else if (CharTooltip.activeSelf && !MouseOverSecondTooltip && !MouseOverSecondTooltippable)
			{
				CloseAllTooltips(1);
			}
			else if (CharTooltip.activeSelf && !Tooltip.activeSelf && !TooltipSkill.activeSelf && !TooltipPerk.activeSelf)
			{
				CloseAllTooltips();
			}
		}
	}

	public void CloseAllTooltips(int scale = 3)
	{
		//IL_0044: Unknown result type (might be due to invalid IL or missing references)
		//IL_0049: Unknown result type (might be due to invalid IL or missing references)
		//IL_0073: Unknown result type (might be due to invalid IL or missing references)
		//IL_0078: Unknown result type (might be due to invalid IL or missing references)
		Tooltip.SetActive(false);
		TooltipBuff.SetActive(false);
		if (!MouseOverCharTooltip.MouseOverthis && !MouseOverTooltippable)
		{
			scale = 3;
		}
		if (scale <= 2)
		{
			return;
		}
		if (CharTooltip.activeSelf)
		{
			Scene activeScene = SceneManager.GetActiveScene();
			if (!(activeScene.name == "GladGBattle") || !((Component)BattleProcessor.instance.RewardScreen).gameObject.activeSelf)
			{
				activeScene = SceneManager.GetActiveScene();
				if (activeScene.name == "GladGBattle")
				{
					((MonoBehaviour)this).StartCoroutine(TooltipPreventionWindow());
				}
			}
		}
		CharTooltip.SetActive(false);
		TooltipSpellbook.SetActive(false);
		TooltipSkill.SetActive(false);
		TooltipPerk.SetActive(false);
		MouseOverTooltip = false;
		MouseOverTooltippable = false;
		MouseOverSecondTooltip = false;
		MouseOverSecondTooltippable = false;
		MouseOverThirdTooltippable = false;
		((Component)SpellbookUnitSelectionPanel).gameObject.SetActive(false);
		ItemInUse = null;
		SpellbookInUse = null;
		if (SettingsPanel.activeSelf)
		{
			ToggleCharSettings();
		}
	}

