		AudioManager.instance.AudioEffect("ButtonClick");
		foreach (Transform item in SpellbookUnitSelectionPanel)
		{
			Object.Destroy((Object)(object)((Component)item).gameObject);
		}
		int num = 0;
		foreach (CharacterTemplate Character in ProgressManager.instance.Team)
		{
			if ((Object)(object)Character != (Object)null)
			{
				GameObject val = Object.Instantiate<GameObject>(UnitSelectionButton);
				((TMP_Text)val.GetComponentInChildren<TextMeshProUGUI>()).text = Character.Charname;
				val.transform.SetParent(SpellbookUnitSelectionPanel, false);
				((UnityEvent)val.GetComponent<Button>().onClick).AddListener((UnityAction)(() =>
				{
					LearnSpell(Character);
				}));
				num++;
			}
		}
		foreach (CharacterTemplate Character2 in RosterManager.instance.Roster)
		{
			if ((Object)(object)Character2 != (Object)null)
			{
				GameObject val2 = Object.Instantiate<GameObject>(UnitSelectionButton);
				((TMP_Text)val2.GetComponentInChildren<TextMeshProUGUI>()).text = Character2.Charname;
				val2.transform.SetParent(SpellbookUnitSelectionPanel, false);
				((UnityEvent)val2.GetComponent<Button>().onClick).AddListener((UnityAction)(() =>
				{
					LearnSpell(Character2);
				}));
				num++;
			}
		}
		if (num > 0)
		{
			((Component)SpellbookUnitSelectionPanel).gameObject.SetActive(true);
		}
		else
		{
			ShowErrorMessage(LocalizationManager.GetTranslation("MESSAGE/MESSAGE_nocharsinteam"));
		}
	}

	public void LearnSpell(CharacterTemplate Character)
	{
		if (ItemInUse.Use(Character))
		{
			Object.Destroy((Object)(object)SpellbookInUse);
			InventoryManager.instance.RemoveFromInventory(ItemInUse);
			AudioManager.instance.AudioEffect("Learn");
			CloseAllTooltips();
		}
	}

	public void ShowNotificationMessage(string text, int textSize, string color, Vector3 position, float fadeSpeed = 1f)
	{
		//IL_001a: Unknown result type (might be due to invalid IL or missing references)
		AudioManager.instance.AudioEffect("Notification");
		((Component)NotificationMessage).transform.localPosition = position;
		((TMP_Text)NotificationMessageText).SetText("<size=" + textSize + "><color=" + color + ">" + text);
		NotificationMessage.alpha = 1f;
		((MonoBehaviour)this).StartCoroutine(FadeOutNotification(fadeSpeed));
	}

	public IEnumerator FadeOutNotification(float speed)
	{
		if (!NotificationFadeStarted)
		{
			NotificationFadeStarted = true;
			while (NotificationMessage.alpha > 0f)
			{
				CanvasGroup notificationMessage = NotificationMessage;
				notificationMessage.alpha -= Time.deltaTime * speed;
				Transform transform = ((Component)NotificationMessage).transform;
				transform.localPosition += Vector3.up * speed / 2f;
				yield return null;
			}
			NotificationFadeStarted = false;
		}
	}

