	public IEnumerator TooltipPreventionWindow()
	{
		if (!PreventionWindowActive)
		{
			PreventionWindowActive = true;
			yield return (object)new WaitForSeconds(0.001f);
			PreventionWindowActive = false;
		}
	}

	public void ShowCongratulationMessage(string text, float fadeSpeed = 0.5f)
	{
		AudioManager.instance.AudioEffect("Congratulations");
		((TMP_Text)CongratulationMessageText).SetText(text);
		CongratulationMessage.alpha = 1f;
		((MonoBehaviour)this).StartCoroutine(FadeOutCongratulations(fadeSpeed));
	}

	public IEnumerator FadeOutCongratulations(float speed)
	{
		if (!CongratulationFadeStarted)
		{
			CongratulationFadeStarted = true;
			yield return (object)new WaitForSeconds(1f);
			while (CongratulationMessage.alpha > 0f)
			{
				CanvasGroup congratulationMessage = CongratulationMessage;
				congratulationMessage.alpha -= Time.deltaTime * speed;
				yield return null;
			}
			CongratulationFadeStarted = false;
		}
	}

	public void ToggleCharSettings()
	{
		if (SettingsPanel.activeSelf)
		{
			if (CharTooltip.activeSelf)
			{
				AudioManager.instance.AudioEffect("Back");
			}
			SettingsPanel.SetActive(false);
			RenameWindow.SetActive(false);
			HideForgetbuttons();
			RetireConfirmButton.SetActive(false);
			ExtraStatsPanel.SetActive(false);
		}
		else
		{
			AudioManager.instance.AudioEffect("Options");
			SettingsPanel.SetActive(true);
			ExtraStatsPanel.SetActive(true);
			if (GlobalVariables.instance.RetireGivesMoney > 0f)
			{
				((TMP_Text)RetireButtonText).SetText(LocalizationManager.GetTermTranslation("TOOLTIP/TOOLTIP_character_retire") + " <color=#FFE63B>+" + Mathf.RoundToInt((float)ActiveCharacter.characterValue * GlobalVariables.instance.RetireGivesMoney) + "<sprite=\"GoldInText\" index=0>   \u00a0");
			}
		}
	}

	public void ToggleExtraStatsInBattle(bool forceclose = false)
	{
		if (ExtraStatsPanel.activeSelf | forceclose)
		{
			ExtraStatsPanel.SetActive(false);
		}
		else
		{
			ExtraStatsPanel.SetActive(true);
		}
	}

