	public void ForgetSkill(int index)
	{
		AudioManager.instance.AudioEffect("ButtonClick");
		ActiveCharacter.ForgetSkill(index);
		HideForgetbuttons();
		UpdateSkillsOnTooltip();
	}

	public void HideForgetbuttons()
	{
		((Component)ForgetSkill1Button).gameObject.SetActive(false);
		((Component)ForgetSkill2Button).gameObject.SetActive(false);
		((Component)ForgetSkill3Button).gameObject.SetActive(false);
		((Component)ForgetSkill4Button).gameObject.SetActive(false);
	}

	public void CharSettingsActivateRename()
	{
		NewNameField.text = ActiveCharacter.Charname;
		RenameWindow.SetActive(!RenameWindow.activeSelf);
	}

	public void CharSettingsSetNewName()
	{
		if (!(NewNameField.text == ""))
		{
			ActiveCharacter.Charname = NewNameField.text;
			string text = "#FFFFFF";
			switch (ActiveCharacter.characterRarity)
			{
			case Rarity.Common:
				text = "#B0B0B0";
				break;
			case Rarity.Uncommon:
				text = "#35BA23";
				break;
			case Rarity.Rare:
				text = "#0077FF";
				break;
			case Rarity.Epic:
				text = "#9400FF";
				break;
			case Rarity.Legendary:
				text = "#FF4000";
				break;
			}
			((TMP_Text)CharacterName).SetText("<color=" + text + ">" + ActiveCharacter.Charname + "</color>");
			TownManager.instance.RedrawTeamBars();
		}
		RenameWindow.SetActive(false);
	}

	public void CharSettingsRetireClicked()
	{
		AudioManager.instance.AudioEffect("ButtonClick");
		RetireConfirmButton.SetActive(true);
	}

	public void CharSettingsConfirmRetire()
	{
		AudioManager.instance.AudioEffect("ButtonClickSpecial");
		ProgressManager.instance.PermanentlyKillUnit(ActiveCharacter, DestroyGear: false, Retired: true);
		CloseAllTooltips();
	}

	public void DebugMenuOperations(int number)
	{
		switch (number)
		{
		case 1:
			BattleProcessor.instance.DebugWin();
			break;
		case 2:
			BattleProcessor.instance.DebugLose();
			break;
		case 3:
			TownManager.instance.DebugTranslatorHelper(7);
			break;
		case 4:
			TownManager.instance.DebugTranslatorHelper(8);
			break;
		case 5:
			ProgressManager.instance.ListOfCareerModeTeams[0].DoorChosen();
			break;
		}
	}
}
